\begin{proposition}
\label{prop:1.4}
 For any $p \ge 0$ with $p \neq 1$, the following asymptotic estimate holds as $r \to \infty$:
 \[
 \mathbb{P}\bigg[\, n_{F_\beta}(r) = \Big\lfloor \frac{\beta p}{2} r^{\beta} \Big\rfloor \,\bigg]
 = \exp\bigg( -\frac{\beta Z_p}{2} r^{2\beta} + O\big( r^{\beta} \log^{2} r \big) \bigg),
 \]
 where $Z_p$ is defined by
 \[
 Z_p = 
 \begin{cases}
 \displaystyle 
 \frac{e^2}{4}, & p=0, \\[10pt]
 \Bigl| \frac{1}{4} \bigl( q^{2}(2\log q-1) - p^{2}(2\log p-1) \bigr) \Bigr|, & 0 \le p < e,\; p \neq 1, \\[10pt]
