\begin{proofof}{Corollary~\ref{cor:1.2}}
By the definition of $X_{\phi,\beta}(r)$, it suffices to show that for any continuous and compactly supported function $f$ on $\mathbb{C}$,
$$\frac{X_{f,\beta}(r)}{r^\beta}\longrightarrow \int_{\mathbb{C}}f(z)\,d\mu_{0}^{\beta}(z)
$$ 
in distribution as $r\rightarrow \infty$. Assume $\text{supp }f\subset D(0,B)$. For any $\delta>0$, we can choose a smooth function $g$ with compact support in $D(0,B+1)$ such that $|f(z)-g(z)|\leq \delta$ for all $z\in\mathbb{C}$. Then
\begin{align*}
 |X_{f,\beta}(r)-X_{g,\beta}(r)|&\leq\sum_{F_\beta(z)=0}\Big|f\Big(\frac{z}{r}\Big)-g\Big(\frac{z}{r}\Big)\Big|\leq n_{F_\beta}\big(r(B+1)\big)\delta,\\
 \bigg|\int_{\mathbb{C}}f(z)\,d\mu_{0}^{\beta}(z)-\int_{\mathbb{C}}g(z)\,d\mu_{0}^{\beta}(z)\bigg|&\leq\int_{D(0,B+1)}|f(z)-g(z)|\,d\mu_{0}^{\beta}(z)\leq \frac{\beta}{2}\delta(B+1)^\beta.
\end{align*}
Therefore,
\begin{align*}
 \bigg|\frac{X_{f,\beta}(r)}{r^\beta}- \int_{\mathbb{C}}f(z)\,d\mu_{0}^{\beta}(z)\bigg|&\leq\bigg|\frac{X_{f,\beta}(r)}{r^\beta}- \frac{X_{g,\beta}(r)}{r^\beta}\bigg|+\bigg|\frac{X_{g,\beta}(r)}{r^\beta}- \int_{\mathbb{C}}g(z)\,d\mu_{0}^{\beta}(z)\bigg|\\
 &\qquad+\bigg|\int_{\mathbb{C}}g(z)\,d\mu_{0}^{\beta}(z)- \int_{\mathbb{C}}f(z)\,d\mu_{0}^{\beta}(z)\bigg|\\
 &\leq\bigg|\frac{X_{f,\beta}(r)}{r^\beta}- \frac{X_{g,\beta}(r)}{r^\beta}\bigg|+\bigg|\frac{X_{g,\beta}(r)}{r^\beta}- \int_{\mathbb{C}}g(z)\,d\mu_{0}^{\beta}(z)\bigg|+\frac{\beta}{2}\delta(B+1)^\beta.
\end{align*}
For any $\epsilon\in(0,1)$, choose $\delta=\frac{2\epsilon^2}{\beta(B+1)^\beta}$, then one has:
\begin{align*}
 \mathbb{P}\bigg[\bigg|\frac{X_{f,\beta}(r)}{r^\beta}- \int_{\mathbb{C}}f(z)\,d\mu_{0}^{\beta}(z)\bigg|>\epsilon\bigg]&\leq\mathbb{P}\bigg[\bigg|\frac{X_{f,\beta}(r)}{r^\beta}- \frac{X_{g,\beta}(r)}{r^\beta}\bigg|>\epsilon\bigg]\\ &\qquad+\mathbb{P}\bigg[\bigg|\frac{X_{g,\beta}(r)}{r^\beta}- \int_{\mathbb{C}}g(z)\,d\mu_{0}^{\beta}(z)\bigg|>\epsilon-\frac{\beta}{2}\delta(B+1)^\beta\bigg]\\
 &\leq\mathbb{P}\bigg[|n_{F_\beta}\big(r(B+1)\big)|>\frac{\beta}{2\epsilon}\big(r(B+1)\big)^\beta\,\big|\,n_{F_\beta}(r)=0\bigg]\\
 &\qquad+\mathbb{P}\bigg[\bigg|\frac{X_{g,\beta}(r)}{r^\beta}- \int_{\mathbb{C}}g(z)\,d\mu_{0}^{\beta}(z)\bigg|>\epsilon-\epsilon^2\bigg].
\end{align*}

ref_dict.ergodic-th:
\begin{theorem}
\label{ergodic-th}
If Assumption B holds, then $\{u(t,x)\}_{x\in \bR}$ is ergodic, for any $t>0$. Consequently, by the mean ergodic theorem,
\[
\frac{1}{R}F_R(t) \to 0 \quad \mbox{a.s and in $L^2(\Omega)$}, \quad \mbox{as $R \to \infty$}.
\]
\end{theorem}

ref_dict.cov-th:
\begin{theorem}[Limiting covariance]
\label{cov-th}
If Assumption B holds, then
for any $t,s>0$,
\[
\lim_{R \to \infty}\frac{1}{R^{\beta}}\bE[F_R(t) F_R(s)]=K(t,s) \quad \mbox{is finite},
\] 
where 
\begin{equation}
\label{def-beta}
\beta:=\left\{
\begin{array}{ll} 1 & \mbox{if $\k \in L^1(\bR)$,} \\
\alpha+1 & \mbox{if $\k=R_{1,\alpha/2}$ for some $\alpha \in (0,1)$. }
\end{array} \right.
\end{equation}
In particular, $R^{-\beta} \sigma_R^2(t) \to K(t,t)$ as $R \to \infty$, for any $t>0$.
\end{theorem}

ref_dict.QCLT:
\begin{theorem}[Quantitative Central Limit Theorem]
\label{QCLT}
Suppose that Assumption B holds, and there exists $p \in (1,2]$ such that 
\begin{equation}
\label{mp-m2p}
m_{p}<\infty \quad \mbox{and} \quad m_{2p}<\infty.
\end{equation}

If $\k \in L^1(\bR)$, then
for any $t>0$,
\[
{\rm dist}\left( \frac{F_R(t)}{\sigma_R(t)},Z\right) \leq  C_t R^{-(1-\frac{1}{p})}
\]

If $\k=R_{1,\alpha/2}$ for some $\alpha \in (0,1)$, and $p>\frac{2}{2-\alpha}$, then
\[
{\rm dist}\left( \frac{F_R(t)}{\sigma_R(t)},Z\right) \leq
C_t R^{-\e}  \quad \mbox{for any $\varepsilon \in \big(0, 1-\frac{1}{p}-\frac{\alpha}{2}\big)$}.
\]

Here $C_t>0$ is a constant depending on $t$, and ${\rm dist}$ is the Fortet-Mourier distance, the 1-Wasserstein distance, or the Kolmogorov distance.
\end{theorem}

