In particular, in the case when $m=n$, our arguments are different from those in \cite{Wang}, so we obtain a new proof of that case. For general $m$, our proof follows a strategy introduced in \cite{LT}, where a key input is Perelman's monotonicity of the reduced volume, viewed as a parabolic analogue of the Bishop-Gromov volume comparison for Riemannian metrics with Ricci curvature bounded below. This allows for some control over how much time minimizing $\mathcal{L}$-geodesics spend in a neighborhood of the ``bad region'' $X\backslash X^\circ=f^{-1}(D)$. However, to push this strategy to the end, \cite{LT} had to use a result from \cite{GTZ2} which shows that when $Y$ is smooth and the divisorial components of $D$ have simple normal crossings, $\omega_{\rm can}$ is quasi-isometric to a {\em conical K\"ahler metric} near these components, up to a small logarithmic error.

\subsection{Reduction to an upper of $d_{\can}$ by $d_t$}In the following, let $d_t$ denote the distance function on $X$ defined by the metric $\omega(t)$. To prove Theorem \ref{main} we need to show that $(X,d_t)$ converges in the Gromov-Hausdorff topology to $(Y,d_{\rm can})$. Recall that we have the analytic subvariety $D\subset Y$ so that $Y^\circ=Y\backslash D$ is smooth and $f$ is a submersion over $Y^\circ$. Given $\ve>0$ we define
\begin{equation}
 V_{\epsilon}:=\{y\in Y\mid d_{\can}(D,y)<\epsilon\}, \quad \tilde V_{\epsilon}:=f^{-1}(V_{\epsilon}).
\end{equation}and let $(Y\setminus V_{\epsilon},d_{\can})$ denote the restriction of the metric $d_{\can}$ from $Y$ to $Y\setminus V_{\epsilon}$, and similarly let $(X\setminus \tilde V_{\epsilon},d_t)$ be restriction of $d_t$ from $X$ to $X\setminus \tilde V_{\epsilon}$.

\begin{lemma}\label{lem--dcan bound by dt}
 Suppose the following is true: given any small $\ve>0$ and two points $p, q\in X\setminus \tilde V_{\epsilon}$, we have
 \begin{equation}\label{eq--to prove}
 d_{\can}(f(p),f(q))\leq d_t(p,q)+\Psi(t^{-1}|\epsilon).
\end{equation}
In this case, we then have
\begin{equation}\label{agogna}
 \lim_{t\rightarrow\infty}d_{\gh}((X,d_t),(Y,d_{\can}))=0
\end{equation}
\end{lemma}
\begin{proof}
 Thanks to Lemma \ref{lem--gh close for smooth exhaustion}, to prove \eqref{agogna} is enough to show that
 \begin{equation}\label{eq--intermediate}
 d_{\gh}((X\setminus \tilde V_{\epsilon},d_t), (Y\setminus V_{\epsilon},d_{\can}))=\Psi(t^{-1}| \epsilon).
 \end{equation} To show this, we will show that the fibration map
 \begin{equation}
 f:X\setminus \tilde V_{\epsilon}\rightarrow Y\setminus V_{\epsilon}
 \end{equation}is the Gromov-Hausdorff approximation that we want.
Indeed, by Lemma \ref{lem--convexity on y}, and the $C^0_{\loc}$-convergence of $\omega(t)$ to $\omega_{\can}$ on $f^{-1}(Y^{\circ})$ in \eqref{conv}, we know that for any $p,q\in X\setminus \tilde V_{\epsilon}$, we have
 \begin{equation}
 d_t(p,q)\leq d_{\can}(f(p),f(q))+\Psi(t^{-1}|\epsilon).
 \end{equation}
Combining this with \eqref{eq--to prove} then gives
 \begin{equation}
 \left|d_t(p,q)-d_{\can}(f(p),f(q))\right|=\Psi(t^{-1}|\epsilon),
 \end{equation}
and since clearly $f$ is surjective, we obtain the desired Gromov-Hausdorff approximation, which shows \eqref{eq--intermediate}.
\end{proof}

