 \begin{equation}
 \label{eq:param-all}
 |\zeta'(t)| + \Big|\frac{\mu'(t)}{\mu(t)}\Big| + |\theta'(t)| + \Big|\frac{\lambda'(t)}{\lambda(t)}\Big| \lesssim |t|^{-1},
 \end{equation}
 (for the last term, this bound is sharp).
 \end{remark}
 \subsection{Control of the stable and unstable component}
 An important step is to control
 the stable and unstable components $a_1^\pm(t) = \la \alpha_{\zeta(t), \mu(t)}^\pm, g(t)\ra$ and $a_2^\pm(t)= \la \alpha_{\theta(t), \lambda(t)}^\pm, g(t)\ra$. Recall that $\nu > 0$ is the positive eigenvalue of the linearized flow, see \eqref{eq:Y1Y2}.
 \begin{lemma}
 \label{lem:proper}
 Under assumptions of Lemma~\ref{lem:mod}, for $t \in [T, T_1]$ there holds
 \begin{align}
 \big| \dd t a_1^+(t) - \frac{\nu}{\mu(t)^2}a_1^+(t)\big| &\leq \frac{c}{\mu(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-1p} \\
 \big| \dd t a_1^-(t) + \frac{\nu}{\mu(t)^2}a_1^-(t)\big| &\leq \frac{c}{\mu(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-1m} \\
 \big| \dd t a_2^+(t) - \frac{\nu}{\lambda(t)^2}a_2^+(t)\big| &\leq \frac{c}{\lambda(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-2p} \\
 \big| \dd t a_2^-(t) + \frac{\nu}{\lambda(t)^2}a_2^-(t)\big| &\leq \frac{c}{\lambda(t)^2}|t|^{-\frac{N}{2(N-6)}}, \label{eq:proper-2m}
 \end{align}
 with $c \to 0$ as $|T_0| \to +\infty$.
 \end{lemma}
 \begin{proof}
 The proof is analogous to that of Lemma $3.4$ in \cite{Jacek:nls}, so we omit the proof.
 \end{proof}

\section{Bootstrap argument}
 \label{sec:boot}
 We turn to the heart of the proof, which consists in establishing bootstrap estimates.
 We consider a solution $u(t)$, decomposed according to \eqref{eq:decompose}, \eqref{eq:param-rough} and \eqref{eq:orth}.
 The initial data at time $T \leq T_0$ is chosen as follows. 
 \begin{lemma}
 \label{lem:initial}
 There exists $T_0 < 0$ such that for all $T \leq T_0$ and for all $\lambda^0$, $a_1^0$, $a_2^0$
 satisfying
 \begin{equation}
 \label{eq:initial-assum}
 \big|\lambda^0 -\kappa T^{-\frac{2}{N-6}}\big| \leq \frac 12 |T|^{-\frac{5}{2(N-6)}},\qquad |a_1^0| \leq \frac 12 |T|^{-\frac{N}{2(N-6)}},\qquad |a_2^0| \leq \frac 12 |T|^{-\frac{N}{2(N-6)}},
 \end{equation}
 there exists $g^0 \in X^1$ satisfying
 \begin{gather}
 \label{eq:initial-orth}
 \la \Lambda W, g^0\ra = \la iW, g^0\ra = \la i\Lambda W_{\lambda^0}, g^0\ra = \la {-}W_{\lambda^0}, g^0\ra = 0, \\
 \label{eq:initial-unstable}
 \la \alpha_{-\frac{\pi}{2},1}^-, g^0\ra = 0,\quad \la \alpha_{-\frac{\pi}{2},1}^+, g^0\ra = a_1^0,\quad 
 \la \alpha_{0,\lambda^0}^-, g^0\ra = 0,\quad \la \alpha_{0, \lambda^0}^+, g^0\ra = a_2^0, \\
 \label{eq:initial-size}
 \|g^0\|_{\cE} \lesssim |T|^{-\frac{N}{2(N-6)}}.
 \end{gather}
 This $g^0$ is continuous for the $X^1$ topology with respect to $\lambda^0$, $a_1^0$ and $a_2^0$.
 \end{lemma}
 \begin{remark}
 For the continuity, we just claim that the function $g^0$ constructed in the proof
 is continuous with respect to $\lambda^0$, $a_1^0$ and $a_2^0$.
 Clearly, $g^0$ is not uniquely determined by \eqref{eq:initial-orth}, \eqref{eq:initial-unstable} and \eqref{eq:initial-size}.
 \end{remark}
 \begin{remark}
 Condition \eqref{eq:initial-orth} is exactly \eqref{eq:orth} with $\big(\zeta, \mu, \theta, \lambda\big) = \big(-\frac{\pi}{2}, 1, 0, \lambda^0\big)$.
 Hence, if we consider the solution $u(t)$ of \eqref{har} with initial data $u(T) = -iW + W_{\lambda^0} + g^0$
 and decompose it according to \eqref{eq:decompose}, then $g(T) = g^0$ and the initial values of the modulation parameters are
 $\big(\zeta(T), \mu(T), \theta(T), \lambda(T)\big) = \big({-}\frac{\pi}{2}, 1, 0, \lambda^0\big)$.
 \end{remark}
 \begin{proof}
 The proof is same with \cite[Lemma 4.1]{Jacek:nls}, which mainly use implicit function theorem to obtain the orthogonal decomposition. Here we omit.
 \end{proof}
 In the remaining part of this section, we will analyze solutions $u(t)$ of \eqref{har}
 with the initial data $u(T) = -iW + W_{\lambda^0} + g^0$,
 where $g^0$ is given by the previous lemma.

\begin{proposition}
 \label{prop:shooting}
 Let $|T_0|$ be large enough. For all $T < T_0$ there exist $\lambda^0, a_1^0, a_2^0$ satisfying \eqref{eq:initial-assum}
 such that the solution $u(t)$ with the initial data $u(T) = -iW + W_{\lambda^0} + g^0$ exists on the time interval $[T, T_0]$
 and for $t\in[T, T_0]$ the bounds \eqref{eq:bootstrap-better-zeta}, \eqref{eq:bootstrap-better-mu}, \eqref{eq:bootstrap-better-theta}, \eqref{eq:bootstrap-better-g},
 \begin{align}
 \big|\lambda(t) - \kappa|t|^{-\frac{2}{N-6}}\big| &\leq \frac 12 |t|^{-\frac{5}{2(N-6)}}, \label{eq:bootstrap-better-lambda} \\
 |a_1^+(t)| &\leq \frac 12 |t|^{-\frac{N}{2(N-6)}}, \label{eq:bootstrap-better-a1p} \\
 |a_2^+(t)| &\leq \frac 12 |t|^{-\frac{N}{2(N-6)}} \label{eq:bootstrap-better-a2p},
 \end{align}
 hold.
 \end{proposition}
 \begin{proof}
 The proof is similarly to \cite[Proposition 4.8]{Jacek:nls}, thus we omit.
 \end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:deux-bulles}]
 Let $T_0 < 0$ be given by Proposition~\ref{prop:shooting} and let $T_0, T_1, T_2, \ldots$
 be a decreasing sequence tending to $-\infty$.
 For $n \geq 1$, let $u_n$ be the solution given by Proposition~\ref{prop:shooting}.
 Inequalities \eqref{eq:bootstrap-better-zeta}, \eqref{eq:bootstrap-better-mu}, \eqref{eq:bootstrap-better-theta},
 \eqref{eq:bootstrap-better-lambda} and \eqref{eq:bootstrap-better-g} yield
 \begin{equation}
 \label{eq:uniform}
 \Big\|u_n(t) - \Big({-}iW + W_{\kappa|t|^{-\frac{2}{N-6}}}\Big)\Big\|_\cE \lesssim |t|^{-\frac{1}{2(N-6)}},
 \end{equation}
 for all $t \in [T_n, T_0]$ and with a constant independent of $n$.
 Upon passing to a subsequence, we can assume that $u_n(T_0) \wto u_0 \in \cE$.
 Let $u$ be the solution of \eqref{har} with the initial condition $u(T_0) = u_0$.
 The weak stability Lemma~\ref{cor:weak-cont} implies that $u$ exists on the time interval $({-}\infty, T_0]$
 and for all $t \in ({-}\infty, T_0]$ there holds $u_n(t) \wto u(t)$.
 Passing to the weak limit in \eqref{eq:uniform} finishes the proof.
 \end{proof}

post_theorem_intro_text:
\begin{remark}
		More precisely, we will prove that
		\begin{equation*}
			\Big\|u(t) - \Big({-}iW + W_{\kappa|t|^{-\frac{2}{N-6}}}\Big)\Big\|_\mathcal{E} \leq C_0|t|^{-\frac{1}{2(N-6)}},
		\end{equation*}
		for some constant $C_0 > 0$.
	\end{remark}
	\begin{remark}
		We construct here \emph{pure} two-bubble, that is the solution approaches a superposition of two ground states, with no energy transformed into radiation.
		By the conservation of energy and the decoupling of the two bubbles, we necessarily have $E(u(t)) = 2E(W)$.
	\end{remark}
	\begin{remark}
		For energy-critical wave and NLS equations, similar objects were constructed by the first author in \cite{Jacek:wave} and \cite{Jacek:nls}. In the following work, we will consider dimension $N = 6$ and we expect an analogous result, with an exponential concentration rate. 
	\end{remark}
	\begin{remark}
	Solutions of similar kind for the energy-critical heat equation were constructed in \cite{dPMW, SWZ}.
	\end{remark}
		\begin{remark}
		Two-bubble solutions of a different kind were recently constructed in \cite{JK:wmaptwobub} for the energy-critical wave maps equation: the solution blows up in finite time, with the scales of both bubbles converging to zero simultaneously.
	\end{remark}

	\subsection{Outline of the proof}
	The overall structure is similar to the earlier work of the first author on the energy-critical NLS equations \cite{Jacek:nls}. The difference between Hartree equation here with NLS in \cite{Jacek:nls}  is the nonlocal interaction, which is more complex to analyze. The main tools are the modulation analysis, bootstrap argument and topological argument. 

	The paper is organized as follows. We study solutions of \eqref{har} close to a sum of two bubbles:
	\begin{equation}
		u(t) = \mathrm e^{i\zeta(t)}W_{\mu(t)} + \mathrm e^{i\theta(t)}W_{\lambda(t)} + g(t).
	\end{equation}
	One should think of $\zeta(t)$ as being close to $-\frac{\pi}{2}$, $\mu(t) \simeq 1$,
	$\theta(t) \sim 0$, $\lambda(t) \ll 1$ and $\|g(t)\|_\mathcal{E} \ll 1$. 

	In Section \ref{sec:variational}, we first recall some useful lemmas. We also state the spectral properties  of the linearized operator $Z_{\theta, \lambda}$ around $\mathrm e^{i\theta}W_\lambda$ and coercivity of the energy near a two-bubble. These are very important to estimate $g$, which is the infinite-dimensional part. We will use the energy conservation to deal with this.

	In Section \ref{sec:mod}, we estimate the modulation parameters. For this reason, we impose the orthogonality conditions which make the terms linear in $g$ in the modulation equations disappeared. There is essentially a unique choice of such orthogonality conditions. In Lemma~\ref{lem:mod} we establish bounds on the evolution of the modulation parameters under some bootstrap assumptions. The goal is to improve these bounds, thus closing the bootstrap. In order to improve the bound on $\|g\|_\mathcal{E}$ to close the bootstrap, we establish Lemma \ref{lem:proper} to control the unstable components.

	In Section \ref{sec:boot}, we establish the bootstrap estimates and prove the main result Theorem \ref{thm:deux-bulles}. First, we use implicit function theorem to obtain the modulation decomposition. Next, combining with virial correction, which is used to improve the bound \eqref{eq:bootstrap-theta} on $\theta(t)$, we can close the bootstrap of modulation parameters. Adding the virial correction allows us to gain a small constant on the right hand side of \eqref{eq:mod-th}, which is decisive for closing the bootstrap. The linear instabilities of the flow can be handled by using a classical topological argument based on the Brouwer fixed point theorem. Finally, we prove Theorem \ref{thm:deux-bulles}.

	\subsection{Acknowledgments}
