\begin{theorem}\label{main_thm}
Let $\H\in (\frac{1}{3},1)$, and let the initial data $u_0^{\epsilon},v_0^\epsilon $ be divergence-free, of zero mean, and such that
\begin{align*}
   \sup_{\epsilon\in (0,1)} \|u_0^{\epsilon}\|_{L^2_x}+\|\sqrt{\epsilon}v_0^{\epsilon}\|_{L^2_x}<+\infty.
\end{align*}
Assume that the operators $Q$ and $C$ satisfy the conditions stated in \autoref{sec_hp_noise}. Then there exist probabilistically weak rough path solutions $(u^{\epsilon},(-C)^{-1}dW^{\H,\epsilon})$ to \eqref{system_prelimit} that converge in law to a probabilistically weak rough path solution of \eqref{eq_Hgreat12} in the case $\alpha=1$ and $\H>\tfrac{1}{2}$, and to a probabilistically weak rough path solution of \eqref{eq_Hsmall12} in the case $\H<\tfrac{1}{2}$ and $\alpha=\tfrac{1}{2}+\H$. 
\end{theorem}

