\section{Preliminaries}\label{sec:2}
\subsection{Auxiliary Analysis Tools}\label{sec:2.1}
In this subsection, we introduce two key lemmas needed later. The first one is
\begin{lemma}\cite{nonuniform-2010-cmp-himonas}\label{phi-cmp-2010}
 Let $\sigma \geq 0, \delta\geq 0, a\in \mr$ and $\lambda\gg 1$. For any Schwartz function $\psi\in \mathcal{S}(\mr)$, it holds that
 \begin{align*}
 \lambda^{\delta/2}\left\|\psi\right\|_{L^2(\mathbb{R})}\leq\left\|\psi\left(\frac{\cdot}{\lambda^\delta}\right)\right\|_{H^\sigma(\mathbb{R})}\leq\lambda^{\delta/2}\left\|\psi\right\|_{H^\sigma(\mathbb{R})},
 \end{align*}
and \begin{align}\label{622}
 \left\|\psi\left(\frac{\cdot}{\lambda^\delta}\right)\cos(\lambda\cdot-a)\right\|_{H^\sigma(\mathbb{R})}\simeq\lambda^{\sigma+\delta/2}\|\psi\|_{L^2(\mathbb{R})}.
\end{align}
Moreover, \eqref{622} holds true if $\cos(\lambda \cdot-a)$ is replaced by $\sin(\lambda \cdot-a)$.
\end{lemma}

\subsection{Approximate Solutions Scheme}\label{sec:3.1}
We begin by constructing two sequences of approximate solutions $b^{w,\lambda}$ and $u^{w,\lambda}$ with $w=\pm 1$, where $b^{w,\lambda}$ contains low frequencies only and $u^{w,\lambda}$ contain both high and low frequencies. More precisely, we set
\begin{align}\label{u-low+high}
 u^{w,\lambda}(x,t)=u^{l,w,\lambda}(x,t)+u^{h,w,\lambda}(x,t).
\end{align}
The high-frequency components $u^{h,w,\lambda}$ are constructed as
\begin{align}\label{u-high}
 u^{h,w,\lambda}(x,t)=\begin{cases}
 \nabla^\perp \phi^{h,w,\lambda}(x,t)=(\partial_{x_2}\phi^{h,w,\lambda}(x,t),-\partial_{x_1}\phi^{h,w,\lambda}(x,t)), &~d=2,\\[3mm]
 \left(\nabla^\perp \phi^{h,w,\lambda}(x,t),0 \right)=(\partial_{x_2}\phi^{h,w,\lambda}(x,t),-\partial_{x_1}\phi^{h,w,\lambda}(x,t),0), &~d=3.
 \end{cases}
\end{align}
In \eqref{u-high}, the function $\phi^{h,w,\lambda}(x,t)$ is defined as
\begin{align}\label{phi-high}
 \phi^{h,w,\lambda}(x,t)=\begin{cases}
 \lambda^{-s-\delta-1}\phi(\dfrac{x_1}{\lambda^\delta})\phi(\dfrac{x_2}{\lambda^\delta})\sin (\lambda x_2-wt),&~d=2,\\[3mm]
 \lambda^{-s-\delta-1}\phi(\dfrac{x_1}{\lambda^\delta})\phi(\dfrac{x_2}{\lambda^\delta})\sin (\lambda x_2-wt)\phi(x_3),&~d=3,
 \end{cases}
\end{align}
where $s > 0, \lambda>0, w=\pm 1$, the parameter $\delta > 0$ is to be specified later and the smooth function $\phi \in C_c^\infty(\mathbb{R})$ satisfies $\text{supp}\,\phi \subset [-2,2]$ and $\phi(x) \equiv 1$ on $|x| < 1$.

Following similar estimates established in \eqref{u,b-low-t-local-bound} and \eqref{u-high-bound}, we can obtain
\begin{align}\label{4.5}
 \|\bar{u}^{l,w,\lambda}(t)\|_{H^m} + \|\bar{b}^{w,\lambda}(t)\|_{H^{m}}
 \leq C\lambda^{-1+\delta},
\end{align}
and
\begin{align}\label{4.6}
 \|\bar{u}^{h,w,\lambda}(t)\|_{H^r}\leq C\lambda^{r-s},\quad \|\bar{u}^{h,w,\lambda}(t)\|_{L^\infty}\leq C\lambda^{-s-\delta},\quad \|\nabla \bar{u}^{h,w,\lambda}(t)\|_{L^\infty}\leq C\lambda^{-s+1-\delta}
\end{align}
for any $0 \leq t \leq T\leq 1$, where $[0,T]$ denotes the existence interval of the solution guaranteed by Lemma~\ref{local-well-pri}.
\subsection{Error Estimates for the Approximate Solutions}\label{sec:4.2}
Following the approach in subsection \ref{sec:3.2} and based on system \eqref{mhd-B}, we construct a perturbed system as follows
\begin{align}\label{4.9}
 \begin{cases}
 \partial_t \bar{u}^{w,\lambda}+\bar{u}^{w,\lambda} \cdot \nabla \bar{u}^{w,\lambda}+\nabla p^{w,\lambda}=\bar{b}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{b}^{w,\lambda}+E_1^{w,\lambda},\\[1mm]
 \partial_t \bar{b}^{w,\lambda}-\Delta \bar{b}^{w,\lambda}+\bar{u}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}=\bar{b}^{w,\lambda}\cdot\nabla \bar{u}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{u}^{w,\lambda}+F_1^{w,\lambda}, \\[1mm]
 \diver\, \bar{u}^{w,\lambda}=\diver\, \bar{b}^{w,\lambda}=0,
 \end{cases}
\end{align}
where
\begin{align*}
 E_1^{w,\lambda}&=\partial_t \bar{u}^{h,w,\lambda}+\bar{u}^{l,w,\lambda}\cdot\nabla \bar{u}^{h,w,\lambda}+\bar{u}^{h,w,\lambda}\cdot\nabla \bar{u}^{h,w,\lambda}+\bar{u}^{h,w,\lambda}\cdot\nabla \bar{u}^{l,w,\lambda},\\\nonumber
 F_1^{w,\lambda}&=\bar{u}^{h,w,\lambda}\cdot\nabla \bar{b}^{w,\lambda}-\bar{b}^{w,\lambda}\cdot\nabla \bar{u}^{h,w,\lambda}-{\bf B_0}\cdot \nabla \bar{u}^{h,w,\lambda}\\
 &\define\diver \tilde{F}_1^{w,\lambda}-{\bf B_0}\cdot \nabla \bar{u}^{h,w,\lambda}.
\end{align*}
The perturbed system \eqref{4.9} is analogous to \eqref{mhd-low+high}. The directional derivative of the high-frequency component along the background magnetic field ${\bf B_0} = (B_1, B_2)$ is
\begin{align*}
 {\bf B_0} \cdot \nabla \bar{u}^{h,w,\lambda} = B_1\partial_{x_1}\bar{u}^{h,w,\lambda} + B_2\partial_{x_2}\bar{u}^{h,w,\lambda}.
\end{align*}
Remarkably, we observe that the oscillatory part in $\bar{u}^{h,w,\lambda}$ satisfies
\begin{align*}
 {\bf B_0} \cdot \nabla \left[\phi\left(\frac{B_1x_2 - B_2x_1}{\lambda^\delta}\right) \cos\left(\lambda(B_1x_2 - B_2x_1) - wt\right)\right] = 0,
\end{align*}
which leads to the following simplified expression
\begin{align*}
 & {\bf B_0}\cdot \nabla \left(\lambda^{-s-\delta}\phi\left(\dfrac{x_1}{\lambda^\delta}\right)
 \phi\left(\dfrac{B_1x_2-B_2x_1}{\lambda^\delta}\right)\cos \left(\lambda \left(B_1x_2-B_2x_1\right)-wt\right)\right)\\
 &=B_1\lambda^{-s-2\delta}\phi'\left(\frac{x_1}{\lambda^{\delta}}\right) \phi\left(\dfrac{B_1x_2-B_2x_1}{\lambda^\delta}\right)\cos \left(\lambda \left(B_1x_2-B_2x_1\right)-wt\right)
\end{align*}
Therefore, following analogous arguments as \eqref{4.3}, we can obtain
\begin{align}\label{4.7}
 \left\| {\bf B_0}\cdot\nabla \bar{u}^{h,w,\lambda}\right\|_{L^2}\leq C\lambda^{-s-\delta}.
\end{align}
Combining the estimates \eqref{4.5}, \eqref{4.6} with Lemma \ref{E,F-error-estimate}, we deduce that
\begin{align}\label{4.8}
 \|E_1^{w,\lambda}(t)\|_{L^2}\leq C\lambda^{-\sigma_{s,\delta}},\quad \|\tilde{F}_1^{w,\lambda}(t)\|_{L^2}\leq C\lambda^{-s-1},
\end{align}
where \begin{align*}
 \sigma_{s,\delta}=\min\{s+1-\delta,2s-1+\delta\}.
\end{align*}
\subsection{Exact Solutions}\label{sec:4.3}
Let $(\bar{u}_{w,\lambda},\bar{b}_{w,\lambda})$ be the unique solution to system \eqref{mhd-B} with the initial data $\left(\bar{u}^{w,\lambda}(x,0),\bar{b}^{w,\lambda}(x,0)\right)$, satisfying
\begin{align*}
 \begin{cases}
 \partial_t \bar{u}_{w,\lambda}+\bar{u}_{w,\lambda} \cdot \nabla \bar{u}_{w,\lambda}+\nabla p_{w,\lambda}=\bar{b}_{w,\lambda}\cdot \nabla \bar{b}_{w,\lambda}+{\bf B_0}\cdot \nabla \bar{b}_{w,\lambda},\\[1mm]
 \partial_t \bar{b}_{w,\lambda}-\Delta \bar{b}_{w,\lambda}+\bar{u}_{w,\lambda}\cdot \nabla \bar{b}_{w,\lambda}=\bar{b}_{w,\lambda}\cdot\nabla \bar{u}_{w,\lambda}+{\bf B_0}\cdot \nabla \bar{u}_{w,\lambda}, \\[1mm]
 \diver\, \bar{u}_{w,\lambda}=\diver\, \bar{b}_{w,\lambda}=0,
 \end{cases}
\end{align*}
It follows from \eqref{4.9} that
\begin{align*}
 \begin{cases}
 \partial_t \bar{u}^{w,\lambda}+\bar{u}^{w,\lambda} \cdot \nabla \bar{u}^{w,\lambda}+\nabla p^{w,\lambda}=\bar{b}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{b}^{w,\lambda}+E_1^{w,\lambda},\\[1mm]
 \partial_t \bar{b}^{w,\lambda}-\Delta \bar{b}^{w,\lambda}+\bar{u}^{w,\lambda}\cdot \nabla \bar{b}^{w,\lambda}=\bar{b}^{w,\lambda}\cdot\nabla \bar{u}^{w,\lambda}+{\bf B_0}\cdot\nabla \bar{u}^{w,\lambda}+\diver \tilde{F}_1^{w,\lambda}-{\bf B_0}\cdot \nabla \bar{u}^{h,w,\lambda}, \\[1mm]
 \diver\, \bar{u}^{w,\lambda}=\diver\, \bar{b}^{w,\lambda}=0.
\end{cases}
\end{align*}
The two systems share same initial conditions, which are
\begin{align*}
