Throughout this paper, we use $G(n,p)$ to denote the Erdős–Rényi random graph with vertex set $[n]$ and edge probability $p$.
Recent progress in the study of random \( F \)-graphs enables us to extend this relation to more complex substructures, by analyzing the minimum number of monochromatic \( F \)-subgraphs over all bipartitions of Erdős–Rényi random graphs, where \( F \) is a strictly 1-balanced graph~\cite{burghart2024sharp}. 
\begin{theorem}\label{thm-convergence}
 Let $F$ be a strictly 1-balanced graph with $s>0$ edges on $r \geq 2$ vertices. For $c>0$, let $p= cn^{-1/\rd_1(F)}$ and $q=p^s=c^sn^{1-r}$. Let $\Min(F,n,p)$ be the minimum number of monochromatic \( F \)-subgraphs over all bipartitions of the Erdős–Rényi random graph $G(n,p)$. Let $\Max(F,n,q)$ be the size of max-cut in the random $F$-graph $R_F(n,q)$. Then, there exists $m(F,p)$ such that
 \begin{align*}
 \frac{\Min(F,n,p)}{n}\xlongrightarrow{\text{p}}m(F,p),
 \end{align*}
 and
 \begin{align*}
 \frac{\Max(F,n,q)}{n}\xlongrightarrow{\text{p}}\frac{c^s}{\aut(F)}-m(F,p).
 \end{align*}
\end{theorem}

We further illustrate how this minimum evolves as the host graph becomes denser, and we estimate its limiting behavior as the number of vertices in $F$ tends to infinity.
For any integer \( k \geq 0 \), any positive function \( f = f(a_1, \ldots, a_k) \), and any function \( g = g(a_1, \ldots, a_k) \), we write \( g = o_{a_1,\ldots,a_k}(f) \) if
\[
\limsup_{a_k \to \infty} \cdots \limsup_{a_1 \to \infty} \left| \frac{g}{f} \right| = 0;
\]
we write \( g = O_{a_1,\ldots,a_k}(f) \) if there exists a positive constant \( M \) such that
\[
\limsup_{a_k \to \infty} \cdots \limsup_{a_1 \to \infty} \left| \frac{g}{f} \right| \leq M.
\]
\begin{theorem}\label{thm-limit}
 With the notion in \Cref{thm-convergence}, for sufficently large $r$,
 \begin{align*}
 m(F,p)=(1+o_r(1))\sqrt{\frac{\log2}{2^{r-2}\aut(F)}c^s }+\frac{c^s}{2^{r-1}\aut(F)}+o_{c^s}(c^{s/2}).
 \end{align*}
\end{theorem}

