\begin{definition}\label{Def-homog}
{\rm
Let $\Ga=(V,E)$ be a graph, $G\leqslant\Aut(\Ga)$, and  $k$ a positive integer.
\begin{itemize}
\item[(1)] If each isomorphism between any pair of isomorphic induced subgraphs of $\Ga$ of order at most $k$
extends to an automorphism of $\Ga$ { contained} in $G$, then $\Ga$ is called a {\it $(G, k)$-homogeneous} graph.
(The {\it order} of a graph is the number of vertices.)

\item[(2)] If any two isomorphic induced subgraphs of $\Ga$ of order at most $k$ are equivalent under $G$, then $\Ga$ is called a {\it $(G,k)$-set-homogeneous} graph.

\item[(3)] {When $G=\Aut(\Ga)$, a $(G, k)$-homogeneous or $(G, k)$-set-homogeneous graph is simply called {\em $k$-homogeneous} or {\em $k$-set-homogeneous}, respectively.}
\end{itemize}
}
\end{definition}

