\begin{theorem}\label{thm: dream}
Let $F:\bU\to\R^n$ be nondegenerate, $\bU$ be an open subset of $\R^d$, $\psi_1,\dots,\psi_n:\Rp\to(0,1)$ be non-increasing. Then \begin{equation}
 \mu_d\left(F^{-1}\mathcal{S}_n(\psi_1,\dots, \psi_n)\right)=\left\{\begin{aligned}
 & 0 &\text{ if } &\textstyle\sum\psi_1(q)\cdots \psi_n(q)<\infty\,,\\[1ex]
 & \mu_d(\bU) &\text{ if } &\textstyle\sum \psi_1(q)\cdots \psi_n(q)=\infty\,.
 \end{aligned}\right.
 \end{equation}
\end{theorem}

With this proposition at hand, justifying \eqref{eq: prod is greater than} becomes simple. We take $\Phi(q)=q^{-1-\mathfrak{c}}$ and define $\psi'_i$ from the proposition. Then
\begin{equation}\label{eq2.13}
\sum_{q=1}^\infty \psi'_{1}(q)\cdots\psi'_{n}(q)
\leq \sum_{q=1}^\infty \psi_{1}(q)\cdots\psi_{n}(q)
+\sum_{q=1}^\infty q^{-1-\mathfrak{c}}
<\infty
\end{equation}
and
$$
\mathcal{S}_n(\psi_1,\dots,\psi_n)
\subset \mathcal{S}_n(\psi_1',\dots,\psi_n').
$$
Hence we may work with the set
$\mathcal{S}_n(\psi_1',\dots,\psi_n')$
instead of $\mathcal{S}_n(\psi_1,\dots,\psi_n)$,
or equivalently we may assume \eqref{eq: prod is greater than}.

Let $\psi_1,\dots,\psi_n$ be approximation functions satisfying the divergence sum condition in Theorem~\ref{thm: dream}. Then
\begin{equation}\label{eq3.20}
\sum_{t=1}^\infty 2^t\psi_1(2^t)\cdots\psi_n(2^t)=\infty.
\end{equation}
As explained in \S \ref{sec: con on psi div}, we assume $\psi_i$ satisfy \eqref{eq: psi chain}, without loss of generality.

Fix any $0<s'<\frac{1}{n-1}$. Then, by \eqref{eq3.20}, there exists a strictly increasing sequence of positive integers $(t_k)_{k\in\N}$ such that
\begin{equation}\label{eq:lower bound on prod} 
\psi_{1}(q)\cdots \psi_{n}(q) q>q^{-\left(\frac{1}{n-1}-s'\right)}\qquad\text{for each } q=2^{t_k}
\end{equation}
and 
\begin{equation}\label{eq3.22}
\sum_{k=1}^\infty 2^{t_k}\psi_1(2^{t_k})\cdots \psi_n(2^{t_k})=\infty.
\end{equation}
In particular, we have that for all $k\in\N$
\begin{equation}\label{eq: standing 2 in 2^t}
2^{t_k}\psi_{2}(2^{t_k})\cdots \psi_n(2^{t_k})>2^{st_k},\qquad s:=\frac{n-1}{n}s'.
\end{equation}
Define $\mathcal{T}:=\{t_k:k\in\N\}$, which is thus an infinite collection. Split $\mathcal{T}$ into two sub-collections:
$$\mathcal{T}_1:=\{t\in\mathcal{T}: 
2^{t}\psi_{1}(2^{t})\cdots \psi_n(2^{t})<1\}\qquad\text{and}\qquad 
\mathcal{T}_2=\mathcal{T}\setminus \mathcal{T}_1.
$$

From Lemma \ref{lem: ubiqui is enough}, it is enough to show that one of the sets on the left side of \eqref{eq: enough} has \textit{full} measure. In what follows $\brho=(\rho_i)_{i=1}^d\Rp^d\to\Rp$.
By the definition of $\Delta$ in \eqref{def: Delta},
$$\begin{aligned}\Delta(2^t, \tfrac12(\psi_{d+j}(2^t))_{j=1}^m, B, \brho(2^t)):=\bigcup_{(q,\ba,\bb)\in \mathcal{R}(2^t, (\psi_{d+j}(2^t))_{j=1}^m, B)} \tDelta(\vv a/q,\brho(2^t)),
\end{aligned}
$$ 
for any ball $B\subset B_0,$ where $B_0$ be as in Proposition \ref{thm: ubiq main}. 
Now note that $$\begin{aligned}
 \bigcup_{(q,\ba,\bb)\in \mathcal{R}(2^t, (\psi_{d+j}(2^t))_{j=1}^m, B)} \tDelta(\vv a/q,\brho(2^t))\cap B
 \subset \bigcup_{2^{t-1}\leq q\leq 2^{t}, (q,\ba)\in J }\tDelta(\vv a/q,\brho(2^t))\cap B.\end{aligned}$$
By \eqref{eq3.22}, there is $i\in\{1,2\}$ such that
\begin{equation}\label{eq3.25}
\sum_{t\in \mathcal{T}_i} 2^t \psi_1(2^t)\cdots\psi_n(2^t)=\infty,
\end{equation}

\begin{equation}\label{mainsum}
\sum_{q=1}^\infty\psi_1(q)\cdots \psi_n(q)
\end{equation}

