ref_dict.th:3sethomo:
\begin{theorem}\label{th:3sethomo}
Let $\Ga=(V,E)$ be a finite $3$-set-homogeneous graph. Then, up to complement, $\Ga$ is isomorphic either to one of the graphs: $\C_5$, $\K_n$, $\K_{m[b]}$, $\K_n\square\K_n$, or to one of the following graphs:
\begin{itemize}
\item[{\rm(1)}] the affine polar graph $\mathrm{VO}_{2m}^{\epsilon}(2)$ with $m\geq 1$ and $\epsilon \in \{+,-\}$;

\item[{\rm(2)}]  the elliptic orthogonal graph $\mathrm{\Gamma}(\mathrm{O}^-_6(q))$ with $q$ a prime power;

\item[{\rm(3)}] an orbital graph of the Higman-Sims group $\mathrm{HS}$ acting on $100$ points;

\item[{\rm(4)}] an orbital graph of the McLaughlin group $\mathrm{McL}$ acting on $275$ points.
\end{itemize}
In particular, all $3$-set-homogeneous graphs are $3$-homogeneous.
\end{theorem}

ref_dict.trans-rank-4:
\begin{theorem}\label{trans-rank-4}
Let $G$ be a primitive permutation group of rank $4$. Then either all orbitals of $G$ are self-paired, or $G=\PSU_3(3)$ acting on $36$ points.
\end{theorem}

ref_dict.Def-homog:
\begin{definition}\label{Def-homog}
{\rm
Let $\Ga=(V,E)$ be a graph, $G\leqslant\Aut(\Ga)$, and  $k$ a positive integer.
\begin{itemize}
\item[(1)] If each isomorphism between any pair of isomorphic induced subgraphs of $\Ga$ of order at most $k$
extends to an automorphism of $\Ga$ { contained} in $G$, then $\Ga$ is called a {\it $(G, k)$-homogeneous} graph.
(The {\it order} of a graph is the number of vertices.)

\item[(2)] If any two isomorphic induced subgraphs of $\Ga$ of order at most $k$ are equivalent under $G$, then $\Ga$ is called a {\it $(G,k)$-set-homogeneous} graph.

\item[(3)] {When $G=\Aut(\Ga)$, a $(G, k)$-homogeneous or $(G, k)$-set-homogeneous graph is simply called {\em $k$-homogeneous} or {\em $k$-set-homogeneous}, respectively.}
\end{itemize}
}
\end{definition}

