The systematic study of multiple zeta values (MZVs) started
in the early 1990s with the work of Hoffman \cite{[H-PJM]}
and Zagier \cite{[Z-FECM]}. Let $r\ge 1$ be an integer. For any multiple index
$\mathbf{s}=(s_1,s_2,\cdots,s_r)\in \mathbb{Z}_{\geq 1}^r$ with
$s_r\textgreater 1$, the {\it multiple zeta value (MZV for short)}
is defined by
\begin{align*}
\zeta(s_1,s_2,\cdots,s_r):=\sum_{1\leq k_1<k_2<\cdots<k_r}
\frac{1}{k_1^{s_1}k_2^{s_2}\cdots k_r^{s_r}}.
\end{align*}
The {\it weight} of MZV is defined to be the number
$|\mathbf{s}|:=s_1+\cdots+s_r$, and its {\it depth} is defined
by $l(\mathbf{s}):=r$. For brevity, we let $\{a_1,\cdots,a_k\}^d$
denote the sequence formed by repeating the sequence
$\{a_1,\cdots,a_k\}$ exactly $d$ times. The simplest precise
evaluations of MZVs and MZSVs are given by
\begin{eqnarray*}
\zeta(\{2\}^d)=\frac{\pi^{2d}}{(2d+1)!}.
\end{eqnarray*}

A central problem in MZV is to investigate the algebraic structure
of the $\mathbb{Q}$-vector space $\mathfrak{Z}_k$ spanned by MZVs
of weight $k$. In this direction, Hoffman \cite{[H-JA]} proposed a
conjecture that stats that every MZV of weight $k$ can be expressed as a
$\mathbb{Q}$-linear combination of those MZVs whose entries are only
$2$'s and $3$'s. This conjecture was proved by Brown \cite{[B-ANN]}
using motivic method. In particular, Brown showed that
$H(a,b):=\zeta(\{2\}^a,3,\{2\}^b)$ can be expressed as a $\mathbb{Q}$-linear
combination of the products $\pi^{2m}\zeta(2n+1)$ with $m+n=a+b+1$.
In 2012, Zagier \cite{[Z-AM]} found surprisingly an elegant and explicit
formula as follows.

\section{Introduction}
The systematic study of multiple zeta values (MZVs) started
in the early 1990s with the work of Hoffman \cite{[H-PJM]}
and Zagier \cite{[Z-FECM]}. Let $r\ge 1$ be an integer. For any multiple index
$\mathbf{s}=(s_1,s_2,\cdots,s_r)\in \mathbb{Z}_{\geq 1}^r$ with
$s_r\textgreater 1$, the {\it multiple zeta value (MZV for short)}
is defined by
\begin{align*}
\zeta(s_1,s_2,\cdots,s_r):=\sum_{1\leq k_1<k_2<\cdots<k_r}
\frac{1}{k_1^{s_1}k_2^{s_2}\cdots k_r^{s_r}}.
\end{align*}
The {\it weight} of MZV is defined to be the number
$|\mathbf{s}|:=s_1+\cdots+s_r$, and its {\it depth} is defined
by $l(\mathbf{s}):=r$. For brevity, we let $\{a_1,\cdots,a_k\}^d$
denote the sequence formed by repeating the sequence
$\{a_1,\cdots,a_k\}$ exactly $d$ times. The simplest precise
evaluations of MZVs and MZSVs are given by
\begin{eqnarray*}
\zeta(\{2\}^d)=\frac{\pi^{2d}}{(2d+1)!}.
\end{eqnarray*}

A central problem in MZV is to investigate the algebraic structure
of the $\mathbb{Q}$-vector space $\mathfrak{Z}_k$ spanned by MZVs
of weight $k$. In this direction, Hoffman \cite{[H-JA]} proposed a
conjecture that stats that every MZV of weight $k$ can be expressed as a
$\mathbb{Q}$-linear combination of those MZVs whose entries are only
$2$'s and $3$'s. This conjecture was proved by Brown \cite{[B-ANN]}
using motivic method. In particular, Brown showed that
$H(a,b):=\zeta(\{2\}^a,3,\{2\}^b)$ can be expressed as a $\mathbb{Q}$-linear
combination of the products $\pi^{2m}\zeta(2n+1)$ with $m+n=a+b+1$.
In 2012, Zagier \cite{[Z-AM]} found surprisingly an elegant and explicit
formula as follows.

In a similar way, Hoffman \cite{[H-CNTP]} defined the multiple
$t$-values (``odd variant'' of MZVs). For any multiple index
$\mathbf{s}=(s_1,s_2,...,s_r)\in \mathbb{Z}_{\geq 1}^r$, the
{\it multiple $t$-value } is defined by
\begin{align*}
t(s_1,s_2,...,s_r):=\sum_{1\leq k_1<k_2<...<k_r}
\frac{1}{(2k_1-1)^{s_1}(2k_2-1)^{s_2}...(2k_r-1)^{s_r}},
\end{align*}
where if the index is empty, then we define the value $t(\emptyset):=1$.
As we stated above, first let us recall the the analogue formula
for the simplest multiple zeta value (\cite{[MK-PSPM]},\cite{[Z-FM]})
\begin{align*}
t(\mathop{\underbrace{2,2,...,2}}_{n})=\frac{\pi^{2n}}{2^{2n}(2n)!}.
\end{align*}

By the method of establishing the generating functions, Murakami \cite{[M-MA]}
obtained an equivalent version of Theorem \ref{theorem1.01}. Define
$$\widetilde{t}(k_1,k_2,...,k_r):=2^{|k|}t(k_1,k_2,...,k_r)$$
and set
$$K(a,b):=\widetilde{t}(\{2\}^a,3,\{2\}^b),K(n)=\widetilde{t}(\{2\}^n)$$
for any $a,b,n\in \mathbb{N}_{\geq 0}$. Then for all integers $a,b\geq 0$,
Murakami \cite{[M-MA]} provided the following formula
\begin{align}\label{eq1.1}
K(a,b)=\sum_{k=1}^{a+b+1}(-1)^{k-1}d_{a,b}K(a+b-k+1)\zeta(2k+1),
\end{align}
where
$$d_{a,b}:=\binom{2k}{2a+1}+\binom{2k}{2b+1}\Big(1-\frac{1}{2^{2k}}\Big).$$
Moreover, let $T(a,b):=t(\{2\}^a,3,\{2\}^b)$. Then \eqref{eq1.1} is equivalent to
\begin{align}
T(a,b)=2\sum_{k=1}^{r+s+1}(-1)^{k-1}d_{a,b}\frac{1}{2^{2k}}\zeta(2k+1)
t(\{2\}^{a+b-k+1}),
\end{align}

\begin{conjecture}\label{con2}
For nonnegative integers $a$ and $b$, we have
\begin{align}
T(a,b)=\frac{-2}{(2a+1)!}\left(\frac{\pi}{2}\right)^{2a+2b+2}
\sum_{n=0}^{\infty}\frac{\zeta(2n)}{(2n+2a+1)(2n+2a+2)\cdots(2n+2a+2b+2)2^{2n}}.
\end{align}
\end{conjecture}
\noindent Notice that Conjectures 1.2 and 1.3 are shown in \cite{[L-MZ]}
to be true when $b=0$. But for the general case $b>0$, these two conjectures
are still kept open so far.

\begin{theorem}\label{theorem1.1}
For nonnegative integers $a$ and $b$, we have $H(a,b)=L(a,b)$, where
\begin{align*}
L(a,b):=\frac{-4\pi^{2a+2b+2}}{(2a+2)!}\sum_{n=0}^{\infty}
\frac{\zeta(2n)}{(2n+2a+2)(2n+2a+3)\cdots(2n+2a+2b+3)2^{2n}}.
\end{align*}
\end{theorem}

\begin{theorem}\label{theorem1.2}
For nonnegative integers $a$ and $b$, we have $T(a,b)=\hat L(a,b)$, where
\begin{align*}
\hat L(a,b):=\frac{-2}{(2a+1)!}\left(\frac{\pi}{2}\right)^{2a+2b+2}
\sum_{n=0}^{\infty}\frac{\zeta(2n)}{(2n+2a+1)(2n+2a+2)\cdots(2n+2a+2b+2)2^{2n}}.
\end{align*}
\end{theorem}

First, we consider the integral
$$\int_{0}^{\frac{\pi}{2}} x^{2a + 2}\left(1 - \frac{2}{\pi} x\right)^{2b + 1} \cot(x)\mathrm{d}x.$$
By using the well-known identity (see, for example, Theorem 1.2.4 of \cite{[AAR]})
\begin{align}\label{eq3.1'}
x\cot(x)=-2\sum_{n=0}^{\infty}\frac{\zeta(2n)}{\pi^{2n}}x^{2n},
\end{align}
we derive that
\begin{align}\label{eq3.2}
&\int_{0}^{\frac{\pi}{2}}x^{2a+2}\Big(1-\frac{2}{\pi} x\Big)^{2b+1}
\cot(x)\mathrm{d}x\nonumber\\
=&-2\int_{0}^{\frac{\pi}{2}}x^{2a+1}\Big(1-\frac{2}{\pi} x\Big)^{2b+1}
\sum_{n=0}^{\infty}\frac{\zeta(2n)}{\pi^{2n}}x^{2n} \mathrm{d}x \nonumber\\
=&-2\sum_{n=0}^{\infty}\frac{\zeta(2n)}{\pi^{2n}}
\int_{0}^{\frac{\pi}{2}}x^{2n+2a+1}\Big(1-\frac{2}{\pi} x\Big)^{2b+1}\mathrm{d}x.
\end{align}

\begin{theorem}\label{theorem1.01}
(Zagier \cite{[Z-AM]}) For non-negative integers $a$ and $b$,
\begin{align}
H(a,b)=2\sum_{k=1}^{a+b+1}(-1)^kc_{a,b}\zeta(2k+1)
\zeta(\{2\}^{a+b+1-k}),
\end{align}
where
$$c_{a,b}:=\binom{2k}{2a+2}-\Big(1-\frac{1}{2^{2k}}\Big)\binom{2k}{2b+1}.$$
\end{theorem}

