 \begin{align}\label{R.E1}
 - S_e - 2\pi^2-\log\left(2\kappa\right) \le \log(\Psi(e)) \le -S_e,
 \end{align}
in which we set $$S_e:=\sum_{v\in\mathcal{P}_e, |v|\ge 3}\frac{C_v}{|v|}.$$ 
