\begin{proposition}\label{Penrose-prop}
Let $g$ be a Lorentzian metric, and let $\gamma$ be a null geodesic. Let $g_\sigma := e^\sigma g$ be a conformal change of $g$ (up to reparametrization, $\gamma$ is also a null geodesic of $g_\sigma$). Let $\mathrm{PL}_g$ (resp.\ $\mathrm{PL}_{g_\sigma}$) denote the Penrose limit of $g$ (resp.\ of $g_\sigma$) along $\gamma$. Then there exists a conformal diffeomorphism
$ \mathrm{PL}_g \to \mathrm{PL}_{g_\sigma}.$
\end{proposition}

ref_dict.maintheo:
\begin{theorem}\label{maintheo}Let $(M, g)$ be a Lorentzian manifold of dimension at least $3$ and let $\bf P$ be its pseudo-group of local conformal transformations, that is the collection 
 of all conformal diffeomorphisms between open subsets of $M$. We assume $M$ locally conformally homogeneous, i.e.~$M$ is an orbit of $\bf P$. Then one of the following possibilities holds:

 \begin{enumerate}

 \item $\bf P$ preserves a Lorentzian metric in the $g$-conformal class.

 \item $(M, g)$ is conformally flat. 

 \item $(M, g)$ is locally conformally equivalent to a plane wave that is isometrically locally homogeneous.  More precisely, there exists a homogeneous plane wave $X$, such that 
 $(M, [g])$ is modeled on $(\Conf(X), X)$.
 \end{enumerate}
 \end{theorem}

