 \end{equation}
 Then $\bar g$ is the unique solution to \eqref{eq:Ch}.
 \end{pro}
 \begin{proof}
 Let $\hat g \in \mathcal{C}$ be such that
 \begin{equation}
 \label{eq:51}
 \|f-\hat g\|_\infty \le \|f - \bar g\|_\infty.
 \end{equation}
 If we can prove that from this follows $\hat g = \bar g$ then obviously $\bar g$ is a solution to \eqref{eq:Ch} and, moreover, unique.

Assume that
 \begin{equation}
 \label{eq:71}
 \bar g \neq \hat g.
 \end{equation} 
 Let $h := \bar g - \hat g$. We can write $h(\varphi_i) = (f-\hat g) (\varphi_i) - (f-\bar g) (\varphi_i)$. By \eqref{eq:alternance-pts-values-2} we have $(f-\bar g)(\varphi_i) = \|f-\bar g\|_\infty$, so $h(\varphi_i) = (f-\hat g)(\varphi_i) - \|f-\bar g\|_\infty \le \|f-\hat g\|_\infty - \|f-\bar g\|_\infty \le 0$ by \eqref{eq:51}. Thus $h(\varphi_i) \le 0$.
 Similarly, $h(\psi_i) = (f-\hat g)(\psi_i) + (\bar g -f)(\psi_i) = (f-\hat g)(\psi_i) + \|f-\bar g\|_\infty \ge \|f-\bar g\|_\infty - \|f-\hat g\|_\infty \ge 0$. We have shown that
 \begin{equation}
 \label{eq:72}
 h(\varphi_i) \le 0 \le h(\psi_i),\quad i=1,2.
 \end{equation}
