ref_dict.thm:main:
\begin{thm}\label{thm:main}
    For any $0<\alpha<1$, there exists a constant $C_\alpha>0$ such that the following holds. Let $p$ be a prime and let $S\subseteq \mathbb{Z}_p \setminus \{0\}$ be a subset with $C_\alpha\le |S|\le p^{1-\alpha}$. Then there exists a valid ordering of $S$, i.e.\ there is an ordering $s_1,s_2,\dots,s_{|S|}$ of the elements of $S$ such that all partial sums $s_1,s_1+s_2,\dots,s_1+s_2+\dots+s_{|S|}$ are distinct.  
\end{thm}

full_context:
Given an abelian group $G$ and a subset $S\subseteq G$, a \emph{valid ordering} of $S$ is an ordering $s_1,s_2,\dots,s_{|S|}$ of the elements of $S$ such that all partial sums $s_1,s_1+s_2,\dots,s_1+s_2+\dots+s_{|S|}$ are distinct. 
Valid orderings have been a subject of a number of works in combinatorics and group theory. The main subject of this paper is the a conjecture, called Graham's rearrangement conjecture, which was posed by Graham \cite[p. 36]{G} in 1971 and later reiterated by Erd\H{o}s and Graham \cite[p. 95]{EG}. 
\begin{conj}
 Any subset $S\subseteq \mathbb{Z}_p\setminus \{0\}$ admits a valid ordering. 
\end{conj}

Graham's rearrangement conjecture has attracted a lot of interest over the past few years. Bedert and Kravitz \cite{BK} showed that the conjecture holds true for small sets $S$, namely for $|S| \le \exp((\log p)^{1/4})$, improving an earlier result of Kravitz \cite{Kr} and an observation of Sawin \cite{Sa}. M\"uyesser and Pokrovskiy \cite{MP} showed that the conjecture holds for very large $S$ of size $|S|\ge (1-o(1))p$. Buci\'c, Frederickson, M\"uyesser, Pokrovskiy and Yepremyan \cite{BFMPY} showed an approximate version of the conjecture, where all but $o(|S|)$ many partial sums are guaranteed to be distinct. Recently, Bedert, Buci\'c, Kravitz, Montgomery and M\"uyesser \cite{BBKMM} showed that the conjecture holds true for large sets $S$, namely for $|S| \ge p^{1-c}$ for a small positive constant $c$.

The main result of this paper is the following theorem, which shows that Graham's rearrangement conjecture holds for all $S\subseteq \mathbb{Z}_p\setminus \{0\}$ with $C_\alpha\le |S|\le p^{1-\alpha}$, for any $\alpha>0$ (with a suitable constant $C_\alpha>0$ depending on $\alpha$).

\abstract{Graham conjectured in 1971 that for any prime $p$, any subset $S\subseteq \mathbb{Z}_p\setminus \{0\}$ admits an ordering $s_1,s_2,\dots,s_{|S|}$ where all partial sums $s_1, s_1+s_2,\dots,s_1+s_2+\dots+s_{|S|}$ are distinct. We prove this conjecture for all subsets $S\subseteq \mathbb{Z}_p\setminus \{0\}$ with $|S|\le p^{1-\alpha}$ and $|S|$ sufficiently large with respect to $\alpha$, for any $\alpha \in (0,1)$. Combined with earlier results, this gives a complete resolution of Graham's rearrangement conjecture for all sufficiently large primes $p$.}

Given an abelian group $G$ and a subset $S\su G$, a \emph{valid ordering} of $S$ is an ordering $s_1,s_2,\dots,s_{|S|}$ of the elements of $S$ such that all partial sums $s_1,s_1+s_2,\dots,s_1+s_2+\dots+s_{|S|}$ are distinct. 
Valid orderings have been a subject of a number of works in combinatorics and group theory. The main subject of this paper is the a conjecture, called Graham's rearrangement conjecture, which was posed by Graham \cite[p. 36]{G} in 1971 and later reiterated by Erd\H{o}s and Graham \cite[p. 95]{EG}. 
\begin{conj}
 Any subset $S\su \mathbb{Z}_p\setminus \{0\}$ admits a valid ordering. 
\end{conj}

The main result of this paper is the following theorem, which shows that Graham's rearrangement conjecture holds for all $S\su \mathbb{Z}_p\setminus \{0\}$ with $C_\alpha\le |S|\le p^{1-\alpha}$, for any $\alpha>0$ (with a suitable constant $C_\alpha>0$ depending on $\alpha$).

Together with the earlier results discussed above, this completely settles Graham's rearrangement conjecture for all sufficiently large primes $p$.

\begin{thm}\label{thm:anticonc}
 There exists an absolute constant $C>0$ such that the following holds. Let $p$ be a prime, let $S\subseteq \mathbb{Z}_p$ be a subset of size $|S|\ge 2$, and let $m$ be an integer with $C\log |S|\le m\le 10^{-3}|S|/\log |S|$. Now, let $R\su S$ be a uniformly random subset of $S$ of size $m$, and let $\Sigma(R) = \sum_{x\in R}x\in \mathbb{Z}_p$ be the sum of the elements of $R$. Then 
 \[
 \max_{z\in \mathbb{Z}_p} \mathbb{P}[\Sigma(R)=z] \le \frac{1}{p} + \frac{C}{|S|\sqrt{m}}.
 \]
\end{thm}

\begin{cor}\label{coro:anticonc}
 For any $0<\eps<1$ There exists a constant $C'_\eps>0$ such that the following holds. Let $p$ be a prime, let $S\subseteq \mathbb{Z}_p$ be a subset of size $|S|\ge 2$, and consider a positive integer $m\le (1-\eps)|S|$. Now, let $R\su S$ be a uniformly random subset of $S$ of size $m$, and let $\Sigma(R) = \sum_{x\in R}x\in \mathbb{Z}_p$ be the sum of the elements of $R$. Then 
 \[
 \max_{z\in \mathbb{Z}_p} \mathbb{P}[\Sigma(R)=z] \le \frac{1}{p} + \frac{C'_\eps\sqrt{\log |S|}}{|S|\sqrt{m}}.
 \]
\end{cor}

\begin{cor}\label{coro:anticonc-chain}
 For every positive integer $k$, there exists a constant $C_k>0$ such that the following holds. Let $p$ be a prime, let $S\subseteq \mathbb{Z}_p$ be a subset of size $|S|\ge 2$, and consider integers $1\le m_1<\dots<m_k< |S|$. Now, let $R_1\su \dots\su R_k\su S$ be a uniformly random chain of subsets of $S$ satisfying $|R_i|=m_i$ for $i=1,\dots,k$. Then for any $z_1,\dots,z_k\in \mathbb{Z}_p$, we have
 \[
 \mathbb{P}[\Sigma(R_i)=z_i \text{ for }i=1,\dots,k] \le \sum_{j=0}^k \, \prod_{i\in \{0,\dots,k\}\setminus\{j\}}\Bigg(\frac{1}{p} + \frac{C_k\sqrt{\log |S|}}{|S|\sqrt{m_{i+1}-m_i}}\Bigg),
 \]
 where we set $m_0=0$ and $m_{k+1}=|S|$.
\end{cor}
\begin{proof}
 Let $\eps=1/(k+1)$, and let us define $C_k=C'_\eps/\eps$ for the constant $C'_\eps$ in Corollary \ref{coro:anticonc}. Also let $z_1,\dots,z_k\in \mathbb{Z}_p$.

\begin{proof}
 It suffices to show that for any $b\in\{1,\dots,|S|-30D\}$ and any two distinct subsets $J,J'\su \{b,b+1,\dots,b+20D\}$ we have
 \begin{equation}\mathbb{P}[b\in B(\sigma)\text{ and }\Sigma(\sigma(J))=\Sigma(\sigma(J'))]\le \frac{8}{|S|^{1+\alpha}}.\label{eq:prob-1}\end{equation}
 Indeed, given (\ref{eq:prob-1}), taking a union bound over the at most $(|S|-30D)\cdot 2^{20D+1}\cdot 2^{20D+1}\le |S|\cdot 2^{40D+2}$ possibilities for $b$, $J$ and $J'$ gives
 \[\mathbb{P}[\mathcal{B}_0]\le |S|\cdot 2^{40D+2}\cdot \frac{8}{|S|^{1+\alpha}}= \frac{2^{40D+5}}{|S|^{\alpha}}\le \frac{2^{40D+5}}{(C_\alpha)^{\alpha}}\le \frac{1}{100}.\]
 So let $b\in\{1,\dots,|S|-30D\}$, and consider distinct subsets $J,J'\su \{b,b+1,\dots,b+20D\}$. Note that the event $\Sigma(\sigma(J))=\Sigma(\sigma(J'))$ (i.e.\ the event $\sum_{j\in J}\sigma(j)=\sum_{j'\in J'}\sigma(j')$) is determined by the outcomes of $\sigma(b),\dots, \sigma(b+20D)$. Furthermore, choosing an index $i\in J\Delta J'$ and conditioning on any outcomes of $\sigma(b),\dots, \sigma(i-1), \sigma(i+1),\dots,\sigma(b+20D)$, we can see that there is at most one outcome for $\sigma(i)$ (among the $|S|-20D$ remaining elements in $S$) such that $\Sigma(\sigma(J))=\Sigma(\sigma(J'))$ is satisfied. Thus, we can conclude
 \[\mathbb{P}[\Sigma(\sigma(J))=\Sigma(\sigma(J'))]\le \frac{1}{|S|-20D
 }\le \frac{2}{|S|},\]
 since $|S|\ge C_\alpha\ge 50D$. Now, conditioning on any fixed outcomes of $\sigma(b),\dots, \sigma(b+20D)$ such that $\Sigma(\sigma(J))=\Sigma(\sigma(J'))$ holds, we have
 \begin{align*}
 &\mathbb{P}[b\in B(\sigma)\mid \sigma(b),\dots, \sigma(b+20D)]\\
 &\qquad\le \sum_{a=2}^{b-1}\mathbb{P}[\Sigma(\sigma,[a,b])=0\mid \sigma(b),\dots, \sigma(b+20D)]\\
 &\qquad=\sum_{a=2}^{b-1}\mathbb{P}[\sigma(a)+\dots+\sigma(b-1)=-\sigma(b)\mid \sigma(b),\dots, \sigma(b+20D)]\\
 &\qquad\le \sum_{a=2}^{b-1} \Bigg(\frac{1}{p} + \frac{C_1\sqrt{\log (|S|-20D-1)}}{(|S|-20D-1)\sqrt{b-a}}+\frac{1}{p} + \frac{C_1\sqrt{\log (|S|-20D-1)}}{(|S|-20D-1)\sqrt{|S|-20D-1-b+a}}\Bigg),
 \end{align*}
 where in the last step we applied Corollary \ref{coro:anticonc-chain} with $k=1$, noting that conditional on our fixed outcomes of $\sigma(b),\dots, \sigma(b+20D)$, the set $\{\sigma(a),\dots,\sigma(b-1)\}$ is a uniformly random subset of size $b-a$ in $S\setminus\{\sigma(b),\dots, \sigma(b+20D)\}$. Therefore we can conclude (recalling that $|S|\ge C_\alpha\ge 50D$ as well as $|S|/p\le |S|^{1-\alpha}$ and $4C_1\sqrt{\log |S|}/|S|^{1/2}\le |S|^{-\alpha}$)
 \[\mathbb{P}[b\in B(\sigma)\mid \sigma(b),\dots, \sigma(b+20D)]\le\frac{2|S|}{p}+2\cdot \frac{C_1\sqrt{\log |S|}}{(|S|/2)}\sum_{i=1}^{|S|}\frac{1}{\sqrt{i}}\le 2|S|^{-\alpha}+\frac{8C_1\sqrt{\log |S|}}{|S|^{1/2}}\le 4|S|^{-\alpha}\]
 for any fixed outcomes of $\sigma(b),\dots, \sigma(b+20D)$. Thus, overall we indeed obtain
 \[\mathbb{P}[b\in B(\sigma)\text{ and }\Sigma(\sigma(J))=\Sigma(\sigma(J'))]\le \frac{2}{|S|}\cdot 4|S|^{-\alpha}=\frac{8}{|S|^{1+\alpha}},\]
 proving \eqref{eq:prob-1}
\end{proof}

