\begin{definition}
 \label{def:kqdefineskd} Let $\oslash$ be a Kronecker quotient. The Kronecker difference $\ominus$ induced by $\oslash$ is the
 Kronecker difference given by
 \begin{equation*}
  M\ominus B := (M-I_m\otimes B)\oslash I_n
 \end{equation*}
 for all $M\in\mathbb{F}_{mn}$, $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$.
\end{definition}

ref_dict.rem:kqdefineskd:
\begin{remark}
 \label{rem:kqdefineskd} It is easily verified that this expression satisfies the condition for a
 Kronecker difference, i.e. for every $A\in\mathbb{F}_m$, $B\in\mathbb{F}_n$ and $m,n\in\mathbb{N}$,
 \begin{align*}
  (A\oplus B)\ominus B
   &= (A\otimes I_n + I_m\otimes B)\ominus B \\
   &= (A\otimes I_n + I_m\otimes B - I_m\otimes B)\oslash I_n \\
   &= (A\otimes I_n)\oslash I_n \\
   &= A.
 \end{align*}
\end{remark}

ref_dict.def:kquniform:
\begin{definition}
 \label{def:kquniform} A Kronecker quotient $\oslash$ is a uniform Kronecker quotient if
 \begin{equation*}
  (A\otimes C)\oslash B = A\otimes (C\oslash B)
 \end{equation*}
 for all matrices $A\in\mathbb{F}_{m}$, $B\in\mathbb{F}_n$, $C\in\mathbb{F}_p\otimes\mathbb{F}_n$ and $m,n,p\in\mathbb{N}$,
 and
 \begin{equation*}
  (A+B)\oslash C = (A\oslash C)+(B\oslash C), \qquad
  (kA)\oslash C = k(A\oslash C)
 \end{equation*}
 for all matrices $A$, $B$ and $C$, and scalars $k\in\mathbb{F}$ whenever the operations are defined.
\end{definition}

pre_theorem_intro_text:
Let $\mathbb{F}_m$ denote the vector space of $m\times m$ matrices
over the field $\mathbb{F}$ with characteristic $\chr(\mathbb{F})$, where $m\in\mathbb{N}$. We will denote
by $\mathbb{F}_m\otimes\mathbb{F}_n=\mathbb{F}_{mn}$ the tensor
product of $\mathbb{F}_m$ and $\mathbb{F}_n$. By the matrix $E_{ij}$
we mean a matrix in $\mathbb{F}_m$ with a 1 in row $i$ and column $j$ and
0 in every other entry. In general, the order of the matrix $E_{ij}$ will
be clear from the context. The trace $\tr(A)$ of a matrix $A\in\mathbb{F}_m$
is the sum of the main diagonal entries of $A$.

\subsection{Kronecker products and Kronecker quotients}

Let $A\in\mathbb{F}_m$ and $B\in\mathbb{F}_s$. The Kronecker product
\cite{graham81a,horn91,kronecker3}
$A\otimes B\in\mathbb{F}_{ms}$ is the $ms\times ms$ matrix over $F$ with entries (here $:=$ denotes a definition)
\begin{equation}
 \label{eq:kronent}
 (A\otimes B)_{(i-1)s+p,(j-1)s+q} := (A)_{i,j}(B)_{p,q},
\end{equation}
where
 $i,j\in\{1,\ldots,m\}$ and
 $p,q\in\{1,\ldots,s\}$.
In other words, we can write in block matrix form
\begin{equation*}
A\otimes B=\begin{bmatrix}
                    (A)_{1,1}B & (A)_{1,2}B & \ldots & (A)_{1,n} B \\
                    (A)_{2,1}B & (A)_{2,2}B & \ldots & (A)_{2,n} B \\
                    \vdots     & \vdots     & \ddots & \vdots      \\
                    (A)_{m,1}B & (A)_{m,2}B & \ldots & (A)_{m,n} B
           \end{bmatrix}.
\end{equation*}
We note that the Kronecker product may be viewed as a family of operations
on vector spaces of square matrices (indexed by the orders of the matrices involved), 
or as an operation on the graded vector space of all square matrices. In other words,
the Kronecker product is the family of operations
$\otimes:\mathbb{F}_m\times\mathbb{F}_n\to\mathbb{F}_{mn}$ indexed by $m,n\in\mathbb{N}$.

In the same way that a Kronecker product is a family
of operations on various matrix vector spaces (or on the graded vector space of
all square matrices), a Kronecker quotient may be viewed as a family of operations
on various matrix vector spaces (or as a partially defined operation on the graded
vector space of all square matrices). In other words, we consider the family
$\oslash:\mathbb{F}_{mn}\times\mathbb{F}_n\to\mathbb{F}_m$ indexed by $m,n\in\mathbb{N}$
satisfying the following definition.

\begin{definition}[Kronecker quotient \cite{kronquotient,leopardi05a}]
 \label{def:kquotient} A (right) Kronecker quotient is an operation $\oslash$ satisfying
 \begin{equation*}
  (A\otimes B)\oslash B = A
 \end{equation*}
 for all matrices $A\in\mathbb{F}_{m}$ and $B\in\mathbb{F}_{n}$
 ($B$ non-zero) and $m,n\in\mathbb{N}$.
\end{definition}

In general, $(M\oslash A)\otimes A\neq M$ for $mn\times mn$ matrices $M$
and $n\times n$ non-zero matrices $A$. A detailed study of Kronecker quotients
appears in \cite{kronquotient}. Throughout this article, we will consider
only right Kronecker quotients and differences, analogous results hold for
left Kronecker quotients and differences in an obvious way. Uniform Kronecker
quotients are of particular interest, since the family of operations are
related to each other via algebraic equations. More precisely, there is a generating
operation for the entire family in the algebraically obvious way:

\begin{definition}
 \label{def:kquniform} A Kronecker quotient $\oslash$ is a uniform Kronecker quotient if
 \begin{equation*}
  (A\otimes C)\oslash B = A\otimes (C\oslash B)
 \end{equation*}
 for all matrices $A\in\mathbb{F}_{m}$, $B\in\mathbb{F}_n$, $C\in\mathbb{F}_p\otimes\mathbb{F}_n$ and $m,n,p\in\mathbb{N}$,
 and
 \begin{equation*}
