\begin{proposition}
 \label{prop:induceddiffprop} Let $\oslash$ be a Kronecker quotient and let $\ominus$
 be the induced Kronecker difference
 \begin{equation*}
 X\ominus B:=(X-I_m\otimes B)\oslash I_n
 \end{equation*}
 for all $X\in \mathbb{F}_{mn}$ and $B\in\mathbb{F}_n$.
 \begin{enumerate}[label=(\alph*)]
 \item
 If $(A\oslash B)^T = A^T\oslash B^T$
 then $(A\ominus B)^T = A^T\ominus B^T$.\phantom{$\dfrac1n$}
 \item
 If $\tr(A\oslash B) = \dfrac{\tr(A)}{\tr(B)}$
 then $\tr(A\ominus B) = \dfrac1n(\tr(A)-m\tr(B))$.
 \item
 If $\oslash$ is uniform then $\ominus$ is uniform.\phantom{$\dfrac1n$}
 \item
 If $(kA)\oslash B = k(A\oslash B)$
 then $(kA)\ominus(kB) = k(A\ominus B)$.\phantom{$\dfrac1n$}
 \item
 If $(A+C)\oslash B = A\oslash B+C\oslash B$
 then $(A+C)\ominus(B+D) = A\ominus B+C\ominus D$.\phantom{$\dfrac1n$}
 \end{enumerate}
