ref_dict.thm:main:
\begin{thm}
\label{thm:main}Let $K$ be any field and $A$ be a finitely generated
amenable $K$-algebra without zero divisors. Then there is a unique
conjugacy class of linear sofic approximations of $A$.
\end{thm}

ref_dict.thm:weak stability:
\begin{thm}
\label{thm:weak stability}Let $K$ be a field and $A$ be an amenable
$K$-algebra with no zero divisors. 
\begin{enumerate}
\item \label{enu:weak1}$A$ is weakly stable if and only if there is a
sequence $\psi_{n}:A\to M_{n_{k}}\left(K\right)$ of representations
such that $\left(\psi_{n}\right)$ is a linear sofic approximation.
\item \label{enu:weak2}If $A=K\Gamma$ is the group algebra of an amenable
group $\Gamma$, then $A$ is weakly stable if and only if $\Gamma$
is residually finite.
\end{enumerate}
\end{thm}

