This prompts a natural question: Can we glue these two sets of solutions from \cite{PP16} and \cite{PW13} to yield a new type of solution? Specifically, we aim to construct a new type of solutions to system \eqref{eq0} with a shape given, at the main order, by
 \begin{equation}\label{eqs2}
 \Big(u_{l}(x)+\sum_{j=1}^{k}U(\frac{x-\eta^{j}}{\epsilon}),
 v_{l}(x)+\sum_{j=1}^{k}V(\frac{x-\eta^{j}}{\epsilon})\Big),
 \end{equation}
 which
 concentrates both in a bounded domain and near infinity, where $\Big(\sum_{j=1}^{k}U(\frac{x-\eta^{j}}{\epsilon}),
\sum_{j=1}^{k}V(\frac{x-\eta^{j}}{\epsilon})\Big)$ is defined in \textbf{Theorem A} later.

Our construction requires that the two solution families from \cite{PP16} and \cite{PW13} can be glued together, requiring that the potential functions $P$ and $Q$ are radially symmetric about some fixed point. Therefore, we focus on Theorem 1.1 in \cite{PP16} (i.e., Theorem A). In this case, the two components of the solution concentrate at the same critical points of the two potential functions. Without loss of generality, we assume this point is the origin, allowing us to combine these solutions with those concentrated at $k$ symmetric points on a coordinate plane established in \cite{PW13}. However, the solutions constructed in Theorem 1.2 of \cite{PP16}, which concentrate at different critical points of $P$ and $Q$, do not satisfy the conditions for gluing and cannot yield new solutions through gluing.
\smallskip
Before delving into the details, let us revisit the following well-known results. Denote the unique radial solution of the following problem by $W$,
\begin{equation*}
\begin{cases}
-\Delta w + w = w^3, & \text{in}\; \mathbb R^3,\\
w(0)=\displaystyle\max_{x\in\mathbb R^3}w(x),& w\in H^1(\mathbb
R^3),
\end{cases}
\end{equation*}
and denote $W_{\mu_i}$ as the solution of the following problem
\begin{equation}\label{eqs1.2}
\begin{cases}
-\Delta w + w = \mu_iw^3, & \text{in}\; \mathbb R^3,\\
w(0)=\displaystyle\max_{x\in\mathbb R^3}w(x),& w\in H^1(\mathbb
R^3).
\end{cases}
\end{equation}
It is well known that $W_{\mu_i}$ is non-degenerate and $W_{\mu_i}(x)=W_{\mu_i}(|x|)$.
Moreover, one finds that $(U,V)=(\gamma_1 W,\gamma_2 W)$ solves
\begin{equation}\label{eqQ1}
\begin{cases}
-\Delta U + U= \mu_1 U^3 +\beta UV^2, &~\text{in}\;\mathbb R^3,\\[1mm]
-\Delta V+ V= \mu_2 V^3 +\beta U^2V, &~\text{in}\;\mathbb R^3
\end{cases}
\end{equation}
 provided $\beta\in \big(-\sqrt{\mu_1\mu_2},\min\{\mu_1,\mu_2\}\big)
 \cup \big(\max\{\mu_1,\mu_2\},+\infty\big)$
, where
$$\gamma_1=\sqrt{\frac{\mu_2-\beta}{\mu_1\mu_2-\beta^2}},\ \ \gamma_2=\sqrt{\frac{\mu_1-\beta}{\mu_1\mu_2-\beta^2}}.$$
\medskip

\noindent\textbf{Theorem A.} (c.f \cite{PP16})
 \emph{
 Suppose that $P(x),Q(x)$ satisfy $(A_1)$ and $(A_{2})$ and $\beta$ satisfies $(A_\beta)$. Then
 for any positive integer $n\geq 2$, system \eqref{eq0}
 has a positive solution $(u_{\epsilon},v_{\epsilon})$ with $n$ spikes concentrating near $y_{0}$ for $\epsilon$ sufficiently small.}
 Specifically, $(u_{\epsilon},v_{\epsilon})$ has the following form
 $$
 (u_{\epsilon},v_{\epsilon})=\Big(\sum_{j=1}^{n}U(\frac{x-\eta^{j}}{\epsilon})+\omega_{\epsilon}(x),
 \sum_{j=1}^{n}V(\frac{x-\eta^{j}}{\epsilon})+\varpi_{\epsilon}(x))\Big),
 $$
 where $(\omega_{\epsilon},\varpi_{\epsilon})\in H$ with
 $$
 \|(\omega_{\epsilon},\varpi_{\epsilon})\|=O\big(\epsilon^{5}|ln \epsilon|^{2}\big),\,\,\frac{|\eta^{i}-\eta^{j}|}{\epsilon}\geq |ln \epsilon|^{\frac{1}{2}}(i\neq j),\,\,\eta^{j}\in B_{\delta}(y_{0})(j=1,...,n).
 $$
\smallskip

First we are aimed to prove the non-degeneracy property of the solution $(u_{\epsilon},u_{\epsilon})$
 to \eqref{eq0} constructed in Theorem A,
 in the sense that the linearized operator $L_\epsilon$ defined by
 \begin{equation*}\label{Lk}
\begin{split}
\big\langle L_\epsilon (\psi_1,\psi_2),(\phi_1,\phi_2)\big\rangle
 :=&\int_{\mathbb R^3}
\big[\epsilon^2\nabla \psi_1\nabla\phi_1 + P(x)\psi_1\phi_1
+\epsilon^2\nabla \psi_2\nabla\phi_2 + Q(x)\psi_2\phi_2
\big]\\
&-3 \int_{\mathbb R^3}\big[\mu_1 u_\epsilon^2\psi_1\phi_1+\mu_2 v_\epsilon^2\psi_2\phi_2\big]-
\int_{\mathbb R^3}
\big[2\beta
u_\epsilon v_\epsilon \psi_2\phi_1+\beta
v_\epsilon^2\psi_1\phi_1 \big]\\
&-\int_{\mathbb R^3}
\big[2\beta
u_\epsilon v_\epsilon\psi_1\phi_2+\beta
u_\epsilon^2\psi_2\phi_2\big]
\end{split}
\end{equation*}
has trivial kernel in $ H^1(\mathbb{R}^3)\times H^1(\mathbb{R}^3)$. We note that the
non-degenerate result play an essential role to construct solutions
when Lyapunov Schmidt reduction are used to the systems. For the
non-degeneracy and the local uniqueness results of
Schr\"{o}dinger equations or systems, one can refer to
\cite{guo-musso-peng-yan2,GPY,LPY19,NY00} etc.

Moreover, denote $$H:=H_{\epsilon,P}(\mathbb{R}^3)\times H_{\epsilon,Q}(\mathbb{R}^3)$$ with the norm
\begin{align*}
\|(u,v)\|^{2}:=\|u\|^{2}_{\epsilon,P}+\|u\|^{2}_{\epsilon,Q}.
\end{align*}
