 and $m_1=m_2=m$.
Let $(u_{\epsilon},v_{\epsilon})$ be a pair of solution obtained in Theorem A. Then there exists $\varepsilon>0$ small enough such that $\beta<\varepsilon$,
 system \eqref{eq0} has infinitely many many pairs of segregated dichotomous concentrated solutions.
 More specifically, for any integer $k>k_{0}$ large enough, system \eqref{eq0} has a pair
 of solution of the following form
 $$
 u_{\epsilon,k}=\bar{S}_{\epsilon,k}(x)+\bar{\varphi}_{k}(x),\,\,v_{\epsilon,k}=\bar{T}_{\epsilon,k}(x)+\bar{\psi}_{k}(x),
 $$
where
 $$
 \bar{S}_{\epsilon,k}(x)=u_{\epsilon}(x)+\sum_{j=1}^{k}W_{\epsilon,\mu_1,x^{j}}(x),\,\,\bar{T}_{\epsilon,k}(x):=v_{\epsilon}(x)+\sum_{j=1}^{k}W_{\epsilon,\mu_2,y^{j}}(x),
 $$
 where $\|(\bar{\varphi}_{k},\bar{\psi}_{k})\| \rightarrow 0$ as $k\rightarrow\infty.$
\end{thm}

Now we are ready to prove Theorem \ref{th3}.
\begin{proof}[\textbf{Proof of Theorem \ref{th3}}]
 We prove the theorem only for the case $m_1=m_2$, since the other case is similar.
If $m_1=m_2$, using from Lemmas~\ref{lm2.2}-\ref{lm2.5}, Propositions~\ref{pro2.6} and \ref{propB.1} imply that
\begin{eqnarray*}
F(r)
&=&
I(S_{\epsilon,k},T_{\epsilon,k})+\ell(\varphi_{k},\psi_{k})+\frac{1}{2}\langle L(\varphi_{k},\psi_{k}),(\varphi_{k},\psi_{k})\rangle-R(\varphi_{k},\psi_{k})\nonumber\\
&=&
I(S_{\epsilon,k},T_{\epsilon,k})+O\big(\|\ell\|\|(\varphi_k,\psi_k)\|+\|(\varphi_k,\psi_k)\|^2\big)\nonumber\\
&=&
I(S_{\epsilon,k},T_{\epsilon,k})+O\big(\frac{1}{r^{m-1-\sigma}}\big)\nonumber\\
&=&A+k(\frac{a_1\gamma_12}{r^m}+\frac{a_2\gamma_2^2}{r^m})B-C_\beta\frac{k^2}{r}e^{-\frac{r\pi}{\epsilon k}}+O(ke^{-\frac{\pi r}{\epsilon k}}).
\end{eqnarray*}
Consider the following maximization problem
\begin{equation}\label{e2.8}
\max\limits_{r\in D_k}F(r).
\end{equation}
Assume that \eqref{e2.8} is achieved by some $r^{*}$ in $D_k.$ We will prove that $r^{*}$ is an interior point of
$D_k$.
Note that $C_\beta>0$.
Define
\begin{align*}
g(t)=\frac{aB}{r^m}-C_\beta\frac{k}{r}e^{-\frac{2\pi r}{\epsilon k}}=\frac{aB}{t^mk^m}-C_\beta\frac{e^{-2\pi t}}{t}.
\end{align*}
Then
\begin{align*}
g'(t)=-\frac{aB}{t^{m+1}k^m}+\frac{2\pi C_\beta e^{-2\pi t}}{t}+\frac{C_\beta e^{-2\pi t}}{t^2}.
\end{align*}
It is easy to check that $g(t)$ has a maximum point of $t_k$ with
\begin{align*}
t_k=\big(\frac{m}{2\pi}+o(1)\big)\ln k.
\end{align*}
So the function $F(r)$ has a maximum point of
$$r=kt_k=\big(\frac{m}{2\pi}+o(1)\big)k\ln k.$$
Hence, it follows from the expression of $F(r)$ that the maximizer of $r_k$ is an interior point of $D_k$. We can use the same argument as \cite{PW13} to show the solutions are positive.
\end{proof}
\subsection{Dichotomy for Segregated solutions}
In this subsection, we construct dichotomous segregated peak-solutions of \eqref{eq0}.

\begin{lem}\label{lm4.2}
There exist $\varepsilon>0$ small enough and $\varrho>0$, such that for any $\beta<\varepsilon, (r,\rho)\in D_k\times D_k$, there holds
$$
\bar{L}(\varphi_{k},\psi_{k})\geq \varrho\|(\varphi_{k},\psi_{k})\|,\ \ (\varphi_{k},\psi_{k})\in \bar{E}_k.
$$
\end{lem}
\begin{proof}
We argue by contradiction. Assume that there exist $k\rightarrow+\infty$, $(\varphi_k,\psi_k)\in \bar{E}_k$ satisfying $\|\bar{L}(\varphi_k,\psi_k)\|=o(1)\|(\varphi_k,\psi_k)\|^2$.
Without loss of generality, we may assume $\|(\varphi_k,\psi_k)\|^2=k$, we have
\begin{align*}
\langle \bar{L}(\varphi_k,\psi_k),(g,h)\rangle=o(1)\|(\varphi_k,\psi_k)\|\|(g,h)\|.
\end{align*}
Taking $(g,h)=(\varphi_k,\psi_k)$, we have
\begin{align*}
o(k)=&\int_{\R^3}\epsilon^2|\nabla\varphi_k|^2+P(x)\varphi_k^2-3\mu_1\bar{S}_{\epsilon, k}^2\varphi_k^2+\int_{\R^3}\epsilon^2|\nabla\psi_k|^2+Q(x)\psi_k^2-3\mu_2\bar{T}_{\epsilon, k}^2\psi_k^2\cr
&-\beta\int_{\R^3}(\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon, k}^2\varphi_k^2+4\bar{S}_{\epsilon, k}\bar{T}_{\epsilon, k}\varphi_k\psi_k).
\end{align*}
For any fixed $R>0$, there is large enough $k>0$ such that $B_R(x_1)\subset\Omega_1$. Set
\begin{align*}
\tilde{\varphi}_k=\varphi_k(x+x^1),\,\,\,\tilde{\psi}_k=\psi_k(x+y^1).
\end{align*}
We have
\begin{align*}
\int_{B_R(0)}\epsilon^2|\nabla \tilde{\varphi}_k|^2+P(x)\tilde{\varphi}_k^2+\epsilon^2|\nabla\tilde{\psi}_k|^2+Q(x)\tilde{\psi}_k^2\leq1.
\end{align*}
Up to a subsequence, we may assume there exist $(\varphi,\psi)\in H^1(\R^3)\times H^1(\R^3)$ such that
\begin{align}\label{eq1.1}
&(\tilde{\varphi}_k,\tilde{\psi}_k)\rightharpoonup(\varphi,\psi)\,\,\, \hbox{weakly in }\, H_{loc}^1(\R^3)\times H_{loc}^1(\R^3),\cr
&(\tilde{\varphi}_k,\tilde{\psi}_k)\rightarrow(\varphi,\psi)\,\,\,\hbox{strongly in}\,L_{loc}^q(\R^3)\times L_{loc}^q(\R^3),q\in[2,6).
\end{align}

Moreover, in view of the non-degeneracy of $U_\epsilon$, it holds $\varphi=0$.
By \eqref{eq1.1}, we see
\begin{align*}
o(1)=\int_{B_R(0)}\tilde{\varphi}_k^qdx=\int_{B_R(x^1)}\varphi_k^qdx.
\end{align*}
Using the same argument on $\tilde{\Omega}$, we can prove that as $k\rightarrow+\infty$,
\begin{align}\label{3.3}
\tilde{\psi}_k\rightarrow0,\,\,\hbox{weakly in }\, H_{loc}^1(\R^3),\,\,\,\tilde{\psi}_k\rightarrow0,\,\,\,\hbox{strongly in} \,L_{loc}^2(\R^3).
\end{align}
As a result, it holds
\begin{align*}
\int_{B_R(x^1)}\varphi^2=o(1),\,\,\,\,\,\,\int_{B_R(y^1)}\psi^2=o(1), \forall\,\,\,R>0.
\end{align*}
Similar as Lemma \ref{lm2.2}, we get
\begin{align*}
\Big(\int_{B_R(0)}\varphi_k^qdx\Big)^{\frac{1}{q}}=o(\sqrt{k}).
\end{align*}
Then we find
\begin{align}\label{eqs33}
o(k)=&\int_{\R^3}\epsilon^2|\nabla\varphi_k|^2+P(x)\varphi_k^2-3\mu_1\bar{S}_{\epsilon, k}^2\varphi_k^2+\int_{\R^3}\epsilon^2|\nabla\psi_k|^2+Q(x)\psi_k^2-3\mu_2\bar{T}_{\epsilon, k}^2\psi_k^2\cr
&-\beta\int_{\R^3}(\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon, k}^2\varphi_k^2+4\bar{S}_{\epsilon, k}\bar{T}_{\epsilon, k}\varphi_k\psi_k)\cr
=&k-3\mu_1\int_{\R^3}(u_{\epsilon, k}^2+U_{\epsilon,r}^2)\varphi_k^2-3\mu_2\int_{\R^3}(v_{\epsilon, k}^2+W_{\epsilon, \rho}^2)\psi_k^2-\beta\int_{\R^3}\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon ,k}^2\varphi_k^2\cr
\geq&k-(o(1)+O(e^{-\frac{R}{\epsilon}}))k-\beta\int_{\R^3}(\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon, k}^2\varphi_k^2).
\end{align}
If we choose $\beta<\frac{1}{C}$ for constant $C$ large enough, then \eqref{eqs33} is impossible for large $R$ and $k$. Consequently, we complete the proof.
\end{proof}
\begin{lem}\label{lm2.4}
There exists a constant $C>0$, independent of $k$ such that
$$
\bar{R}^{(i)}(\varphi,\psi,\xi)\leq C\|(\varphi,\psi,\xi)\|^{3-i},\ i=0,1,2.
$$
\end{lem}

\begin{eqnarray*}
I(S_{\epsilon,k}+\varphi_1,T_{\epsilon,k}+\varphi_2)
&=&
I(S_{\epsilon,k},T_{\epsilon,k})+O(\|l_k\|_*\|(\varphi_1,\varphi_2)\|_*+\|(\varphi_1,\varphi_2)\|_*^2)\nonumber\\
&=&
k\frac{\mu_1+\mu_2-2\beta}{4(\mu_1\mu_2-\beta^2)}\ds\int_{\R^3}W_\epsilon^4dx
+k\Big(\frac{a_1\gamma_1^2}{r^{m_1}}+\frac{a_2\gamma_2^2}{r^{m_2}}\Big)\frac{1}{2}\int_{\R^3}W_\epsilon^2dx\\
&&-kC_\beta W(\frac{|x^1-x^2|}{\epsilon})+O\Big(\frac1{k^{m_1-1+\sigma}}+\frac1{k^{m_2-1+\sigma}}\Big),
\end{eqnarray*}
where $\sigma>0$ is a small constant. Therefore we can prove that problem \eqref{eq0} has a solution $(u_{\epsilon,k},v_{\epsilon,k})$ of the form
\begin{eqnarray*}
u_{\epsilon,k}=S_{\epsilon,k}(x)+\varphi_{k}(x), ~~~v_{\epsilon,k}=T_{\epsilon,k}(x)+\psi_{k}(x)
\end{eqnarray*}
with $(\varphi_k,\psi_k)\in E_k$ and as $k\rightarrow+\infty$,
\begin{align}\label{5.5}
\|(\varphi_k,\psi_k)\|_*\leq\frac C{r^{m_1}}+\frac C{r^{m_2}}+Ce^{-\frac{|x^{1}-x^{2}|}{\epsilon}}.
\end{align}

post_theorem_intro_text:
\begin{rem}
In the proof of Theorem \ref{th3}, the process of constructing solutions that are concentrated respectively at the origin and at infinity is not achieved by directly superimposing spikes centered at the origin and in the vicinity of infinity as an approximate solution for reduction. Instead, it is accomplished by first proving that the solutions concentrated at the origin  as $\epsilon\rightarrow0$  described in Theorem A are non-degenerate. Then, by fixing a sufficiently small $\epsilon>0$, these concentrated solutions are combined with k spikes in the vicinity of infinity to form a new approximate solution. This process involves taking the limit as $k$ approaches infinity and reconstructing solutions concentrated at infinity.
\end{rem}

Define
\begin{align*}
y^j=\Big(\rho\cos\frac{(2j-1)\pi}{k},\rho\sin\frac{(2j-1)\pi}{k},0\Big), \ j=1,\ldots,k,
\end{align*}
where $\rho\in[c_{1}k\ln k,c_{2}k\ln k]$ for $0<c_{1}<c_{2}$. Also we write
$$
W_{\epsilon,\mu_1,x^j}:=W_{\mu_1}(\frac{|x-x^j|}{\epsilon}),~~~~~~W_{\epsilon,\mu_2,y^j}:=W_{\mu_2}(\frac{|x-y^j|}{\epsilon}).
$$
We have  another result as follows.
\begin{thm}\label{th1}
 Under the same conditions as in Theorem \ref{th3}
 and $m_1=m_2=m$.
Let $(u_{\epsilon},v_{\epsilon})$ be a pair of solution obtained in Theorem A. Then there exists $\varepsilon>0$ small enough such that $\beta<\varepsilon$,
 system \eqref{eq0} has infinitely many many pairs of segregated dichotomous concentrated solutions.
 More specifically, for any integer $k>k_{0}$ large enough, system \eqref{eq0}  has a pair
 of solution of the following form
 $$
 u_{\epsilon,k}=\bar{S}_{\epsilon,k}(x)+\bar{\varphi}_{k}(x),\,\,v_{\epsilon,k}=\bar{T}_{\epsilon,k}(x)+\bar{\psi}_{k}(x),
 $$
where
 $$
 \bar{S}_{\epsilon,k}(x)=u_{\epsilon}(x)+\sum_{j=1}^{k}W_{\epsilon,\mu_1,x^{j}}(x),\,\,\bar{T}_{\epsilon,k}(x):=v_{\epsilon}(x)+\sum_{j=1}^{k}W_{\epsilon,\mu_2,y^{j}}(x),
 $$
 where $\|(\bar{\varphi}_{k},\bar{\psi}_{k})\| \rightarrow 0$ as $k\rightarrow\infty.$
\end{thm}

Inspired by \cite{GZ-2022},  we are aimed to discuss the non-degeneracy of $(u_{\epsilon,k},v_{\epsilon,k})$
obtained in Theorem \ref{th3}, which is of great importance  to construct more new type of  concentrated solutions by the same gluing procedure.
To this end, we also define the   linearized operator $L_k$ as
 \begin{equation*}\label{Lk}
\begin{split}
\big\langle  L_k (\psi_1,\psi_2),(\phi_1,\phi_2)\big\rangle
  :=&\int_{\mathbb R^3}
\big[\epsilon^2\nabla  \psi_1\nabla\phi_1 + P(x)\psi_1\phi_1
+\epsilon^2\nabla  \psi_2\nabla\phi_2 + Q(x)\psi_2\phi_2\big]
\\
&-3 \int_{\mathbb R^3}\big[\mu_1 u_{\epsilon,k}^2\psi_1\phi_1+\mu_2 v_{\epsilon,k}^2\psi_2\phi_2\big]
-\int_{\mathbb R^3}
\big[2\beta
u_{\epsilon,k} v_{\epsilon,k} \psi_2\phi_1+\beta
v_{\epsilon,k}^2\psi_1\phi_1 \big]\\
&-\int_{\mathbb R^3}\big[2\beta
u_{\epsilon,k} v_{\epsilon,k}\psi_1\phi_2+\beta
u_{\epsilon,k}^2\psi_2\phi_2\big].
\end{split}
\end{equation*}

${\bf ( H'_2)}$: Under $(H_2)$, we further assume that
\begin{align*}
\begin{split}
&
P'(r)=-\frac{a_1m_1}{r^{m_1+1}}-\frac{b_1(m_1+1)}{r^{m_1+2}}+O(\frac 1{r^{m_1+2+\theta}}),\ \
Q'(r)=-\frac{a_2m_2}{r^{m_2+1}}-\frac{b_2(m_2+1)}{r^{m_2+2}}+O(\frac
1{r^{m_2+2+\theta}}).
\end{split}
\end{align*}

The non-degeneracy of $(u_{\epsilon,k},v_{\epsilon,k})$ can be stated as the following.
\begin{thm}\label{th1.3}
 Assume that \textup{($A_{1}),(A_2),(H_1),( H'_2)$}  and $(A_\beta)$ hold.  Let
 $(\xi_{1},\xi_{2})\in(H_{\epsilon,P}\cap H^1(\mathbb{R}^3))\times (H_{\epsilon,Q}\cap H^1(\mathbb{R}^3))$  satisfies
 $L_k(\xi_{1},\xi_{2})=0$. Then $(\xi_{1},\xi_{2})=0$ for fixed small $\epsilon$.
\end{thm}

\begin{rem}

In comparison to exploring the existence of concentrated solutions, the challenges introduced by the coupling terms in the system become notably more intricate when investigating the non-degeneracy result.  Delicate estimates becomes imperative for the interspecies interaction among the components of system \eqref{eq0}, a consideration absent in the study of single equations.
Our approach incorporates innovative observations, drawing inspiration from the characterization of Fermat points in the renowned Fermat problem. For a more comprehensive understanding, refer to the discussions in Section 3.

Additionally, unlike the approach in \cite{GZ-2022}, the proof of Theorem \ref{th1.3} necessitates the selection of distinct weighted norms, owing to differences in the form of the concentrated solutions.

\end{rem}

\begin{rem}
Recognizing the increased difficulty in establishing the non-degeneracy of the solution obtained in \ref{th1}, we plan to address this aspect in an upcoming paper.
\end{rem}
\medskip

The structure of this paper is as follows: firstly, in Section 2, we prove the non-degeneracy of the concentrated solutions obtained in Theorem A. Subsequently, utilizing this non-degeneracy result, in Section 3, we provide the proofs for Theorem \ref{th3} and Theorem \ref{th1} by constructing two types of dichotomy, namely, synchronized and segregated dichotomous solutions.
 Section 4 is dedicated to further discussing the non-degeneracy of the synchronized dichotomous solutions constructed in the Theorem \ref{th3}. Technical results and energy estimates are put in the appendix.

