 \Big( 0, \frac{1}{2} \varrho(x) \Big), \Big( \frac{1}{2} \varrho(x), 0 \Big), \Big( \frac{1}{2} \varrho(x), \varrho(x) \Big), \Big( \varrho(x), \frac{1}{2} \varrho(x) \Big), \Big( \varrho(x), \varrho(x) \Big)
 \Big\},
 \]
 for $x \in \mathcal{S}$, where $\varrho(x) = 8\pi$ if $x \in \Sigma$ and $\varrho(x) = 4\pi$ if $x \in \partial \Sigma$.

To extend the results in \cite{musso_new_2016, D'aprile_asymmetric_2016} to the case of Toda systems of rank $N$ equipped with homogeneous Neumann boundary conditions on Riemann surfaces with boundary, this paper aims to construct blow-up solutions of the Toda system \eqref{eq:toda_mfN} with $\rho_i \to 2\alpha_i \pi m$ for $i = 1, \dots, N$ on ``$k$-symmetric'' surfaces with $k > \frac{1}{2} \alpha_N $ via singular perturbation methods, where 
 \[ \alpha_i=2i \text{ for }i=1,\dots, N-1, \text{ and }\alpha_N= \begin{cases}
 2 N & \text{ for } \mathbf{A}_N\text{ or } \mathbf{B}_N \\
 4N-2 & \text{ for } \mathbf{C}_N\\
 8 & \text{ for } \mathbf{G}_2
 \end{cases}.\]
 See \eqref{def:alpha_i} in Section \ref{sec:app} for more details.

\begin{definition}\label{def:surface}
 Let $\Sigma$ be a Riemann surface. For an integer $k\geq 1$, we say $\Sigma$ is {\it $k$-symmetric} if 
 $\Sigma$ can be embedded in $\mathbb{R}^3$ and is invariant under $\fR_{k}$. 
 We say $x$ is a {\it $k$-symmetric center} of $\Sigma$ if $x\in \Sigma_0:=\left\{x\in \Sigma: \fR_{k}^i(x)=x \text{ for any } i=1,2,3,\dots\right\}$.
 \end{definition}

For technical reasons, we assume throughout that $\Sigma$ is a $k$-symmetric surface with $k > \frac 1 2 \alpha_N$, which is given by \eqref{def:alpha_i} in Section \ref{sec:app}. Due to the smoothness of the boundary, it follows that 
 $
 \Sigma_0 \cap \partial \Sigma = \emptyset.
 $

We are now ready to state the main result of this paper.

\begin{equation}
		\label{def:alpha_i}
