			\alpha_i&=2i 
			\text{ and }
			\alpha_N= 2-2(N-1)a_{N N-1}=\begin{cases}
				2 N & \text{ for }  \mathbf{A}_N\text{ or } \mathbf{B}_N \\
				4N-2 & \text{ for } \mathbf{C}_N\\
