			-\Delta_g u_1 = \sum_{j=1}^N a_{ij}\rho_j\left( \frac{V_je^{u_j}}{\int_{\Sigma} V_je^{u_j} dv_g}-\frac 1 {|\Sigma|_g} \right)    & \text{ in } \intsigma\\
			\partial_{\nu_g} u_1=\dots= \partial_{\nu_g} u_N= 0 & \text{ on } \partial\Sigma
		\end{cases},
	\end{equation}

\section{Introduction}\label{sec:1}
 Given a Riemann surface $
 (\Sigma,g)$ with smooth boundary 
 $\partial \Sigma$ (possible to be empty) and a positive integer $N\geq 2$, we consider the following Toda system equipped with homogeneous Neumann boundary conditions
 \begin{equation}\label{eq:toda_mfN}
 \begin{cases}
 -\Delta_g u_1 = \sum_{j=1}^N a_{ij}\rho_j\left( \frac{V_je^{u_j}}{\int_{\Sigma} V_je^{u_j} dv_g}-\frac 1 {|\Sigma|_g} \right) & \text{ in } \intsigma\\
 \partial_{\nu_g} u_1=\dots= \partial_{\nu_g} u_N= 0 & \text{ on } \partial\Sigma
 \end{cases},
 \end{equation}
 where 
 $\intsigma=\Sigma\setminus\partial\Sigma$ is the interior of $\Sigma$, $\nu_g$ is the outward unit normal vector on $\partial\Sigma$, $\Delta_g$ is the Laplace-Beltrami operator, $dv_g$ is the Riemannian volume element, $|\Sigma|_g=\int_{\Sigma} dv_g$ denotes the total volume of $\Sigma$, $\rho_i$ is a non-negative parameter, $V_i:\Sigma\rightarrow \R$ is smooth positive functions, and the matrix 
 $(a_{ij})$ is one of the Cartan matrices of a general simple Lie algebra with rank $N$. For simplicity, we normalize the volume of $\Sigma$, i.e., $|\Sigma|_g =1$.

For technical reasons, we assume throughout that $\Sigma$ is a $k$-symmetric surface with $k > \frac 1 2 \alpha_N$, which is given by \eqref{def:alpha_i} in Section \ref{sec:app}. Due to the smoothness of the boundary, it follows that 
 $
 \Sigma_0 \cap \partial \Sigma = \emptyset.
 $

\noindent
 As an immediate consequence, we obtain the following result for the $SU(3)$ Toda system.
 \begin{corollary}
 Let $k > 2$, and suppose that $\Sigma$ is a $k$-symmetric Riemann surface, and the potentials $V_1$ and $ V_2$ are $\fR_k$-invariant. Assume $\Sigma_0 \neq \emptyset$ and $m \leq \# \Sigma_0$, where 
 $\# \Sigma_0$
 denotes the cardinality of $\Sigma_0$. Then, there exists a family of solutions to the system \eqref{eq:A_2_Toda} with $(\rho_1^{\varepsilon}, \rho_2^\varepsilon) \to (4\pi m, 8\pi m)$ or $(8\pi m, 4\pi m)$ that blows up at exactly $m$ distinct points in $\Sigma_0$, exhibiting asymmetric blow-ups.
 \end{corollary}

We consider the following linear operator associated with the problem~\eqref{eq:todaN}: 
 \begin{equation}
 \label{eq:linear_op_a} \cL_{\xi,\varepsilon}(\bphi):=( L^1_{\xi,\varepsilon}(\bphi),\dots, L^N_{\xi,\varepsilon}(\bphi) ),
 \end{equation}
 where for any $i=1, \dots, N $
 \begin{equation*}
 \begin{split}
 L^i_{\xi,\varepsilon}(\bphi):&= -\Delta_g\phi_i -\sum_{j=1}^m\left( \chi_j e^{-\varphi_j} |y_{\xi_j}|^{\alpha_i-2} e^{U^i_j} \phi_i-\overline{\chi_j e^{-\varphi_j} |y_{\xi_j}|^{\alpha_i-2} e^{U^i_j} \phi_i}\right)\\
 &- \sum^N_{\sumi
 } \sum_{j=1}^m\frac{a_{ii'}}2\left( \chi_j e^{-\varphi_j} |y_{\xi_j}|^{\alpha_{i'}-2} e^{U^{i'}_j} \phi_{i'}-\overline{\chi_j e^{-\varphi_j} |y_{\xi_j}|^{\alpha_{i'}-2} e^{U^{i'}_j} \phi_{i'}}\right).
 \end{split}
 \end{equation*}
 The key lemma is the non-degeneracy of the linear operator $\cL_{\xi,\varepsilon}$. Formally, for $i=1,\dots, N, j=1,\dots,m$, we can derive the local limit operator of $L^i_{\xi,\varepsilon}$ is 
 $$-\Delta \phi -2\alpha_i^2 \frac{|y|^{\alpha_i-2}}{(1+|y|^{\alpha_i})^2}\phi$$ 
 by a proper scaling around $\xi_j$ on an isothermal chart (refer to Lemma~\ref{lem:invertible_as}). Del Pino et al. in \cite{DelPino2012Nondegeneracy} prove that the kernel space is generated by (in polar coordinate $(r,\theta)$) 
 \[\phi^0(r,\theta):=\frac{1-|r|^{\alpha_i}}{1+|r|^{\alpha_i}}, \, \phi^1(r,\theta):=\frac{|r|^{\frac{\alpha_i}{2}}}{1+|r|^{\alpha_i}}\cos \frac{\alpha_i}{2}\theta , \, \phi^2(r,\theta):=\frac{|r|^{\frac{\alpha_i}{2}}}{1+|r|^{\alpha_i}} \sin \frac{\alpha_i}{2} \theta. \] 
 The $k$-symmetric condition of $\cH_{k}$ with $k>\frac {\alpha_{N}} 2$ excludes $\phi^1$ and $\phi^2$. To obtain the invertibility of the linearized operator $\cL_{\xi,\varepsilon}$, we need to lay out $\phi^0$ by introducing a family of test functions in $\oH$. 
 Let $z_i(y)=\frac {1-|y|^{\alpha_i}}{ 1+|y|^{\alpha_i}}.$
 It is easy to see that 
 $$-\Delta z_i(y)= 2\alpha_i^2 \frac{|y|^{\alpha_i-2}}{(1+|y|^{\alpha_i})^2}z_i(y), y\in\R^2. $$
 For any $j=1,\dots,m$, we define 
 \[ Z_{ij}(x)=\left\{ \begin{array}{ll}
 z_i\left(\frac{|y_{\xi_j}(x)| } {\delta_{i,j}} \right), & x\in U(\xi_j)\\
 0, & x\in \Sigma\setminus U(\xi_j)
 \end{array}\right.. \]
 Then, we project $Z_{ij}$ into the space $\oH$ by following equations: 
 \begin{equation}
 \label{eq:proj_Z}
 \left\{\begin{array}{ll}
 -\Delta_gPZ_{ij}= \chi_j e^{-\varphi_j} |y_{\xi_j}|^{\alpha_i-2} e^{U^i_j}Z_{ij}-\overline{\chi_j e^{-\varphi_j} |y_{\xi_j}|^{\alpha_i-2} e^{U^i_j}Z_{ij}} &\text{ in } \intsigma\\
 \partial_{\nu_g} PZ_{ij}=0 &\text{ on } \partial\Sigma\\
 \int_{\Sigma} PZ_{ij} dv_g=0&
 \end{array}\right..
 \end{equation}
 We define that 
 $$\fL^{0}_{k}:= \left\{ h=(h_1,\dots, h_N): \int_{\Sigma} h_i dv_g =0\text{ and } h_i \text{ is }\fR_{k}\text{ invariant} \right\}. $$
 \begin{lemma}
 \label{lem:invertible_as}
 For any $p>1$, 
 there exist $\varepsilon_0 > 0$ and $C > 0$ such that for any $\varepsilon \in (0, \varepsilon_0)$, $\bh=(h_1,\dots, h_N) \in (L^p(\Sigma))^N\cap\fL^0_{k}$ there exists $\bphi=(\phi_1,\dots, \phi_N) \in (W^{2,p}(\Sigma))^N \cap \cH_{k}$ as a unique solution of 
 \begin{equation}
 \label{eq:linear_key_a} \left\{ \begin{array}{ll}
 \cL_{\xi,\varepsilon}(\bphi)=\bh & \text{ in }\intsigma\\
 \partial_{\nu_g} \bphi =0 & \text{ on }\partial\Sigma\\
 \int_{\Sigma}\bphi dv_g=0 
 \end{array}\right.,
 \end{equation}
 satisfying that 
 $$
 \|\bphi\| \leq C |\log \varepsilon| \|\bh\|_p,
 $$
 where $\|\bphi\|:= \sqrt{\sum_i \|\phi_i\|^2} \text{ and } \|\bh\|_p=\sum_i \|h_i\|_{p}$.
 \end{lemma}

\begin{proof}
 We prove it by contradiction. Suppose Lemma~\ref{lem:invertible_as} fails, i.e. there exist $p>1$ and a sequence of $\varepsilon_n\rightarrow 0$ and $\bh_n:=(h_{1,n},\dots, h_{N,n})\in (L^p(\Sigma))^N\cap \fL^0_{k}$ and $\bphi_n:=(\phi_{1,n},\dots, \phi_{N,n})\in (W^{2,p}(\Sigma))^N\cap \cH_{k}$ solves ~\eqref{eq:linear_key_a} for $\bh_n$ satisfying 
 \[ \|\bphi_n\|=1\text{ and } |\log \varepsilon_n|\|\bh_n\|_p:=|\log\varepsilon_n|\sum_{i=1}^N \|h_{i,n}\|_{p}\rightarrow 0, \]
 as $n\rightarrow +\infty.$
 For simplicity, we still use the notations $\phi_i,$ $ h_i,$ $\varepsilon$ instead of $\phi_{i,n},$ $h_{i,n},$ $ \varepsilon_n$ for $i=1,\dots, N$. 
 We define that for $i=1,\dots, N, j=1,\dots,m$
 \[ \tilde{\phi}_{ij}(y)= \left\{\begin{aligned}
 & \chi\left( \frac { \delta_{i,j}|y|}{r_0}\right) \phi_i\circ y_{\xi_j}^{-1}(\delta_{i,j} y),& &y \in \Omega_{ij}:= \frac{1}{\delta_{i,j}} B^{\xi_j}\\
 & 0& & y\in\R^2\setminus\Omega_{ij}
 \end{aligned}\right.. \]
 Then we consider the following spaces for $\alpha\geq 2 $ and $\xi\in\Sigma$,
 $$ \rL^{\alpha}:=\Big\{ u: \Big\| \frac{|y|^{\frac{\alpha-2}{2}}}{1+|y|^{\alpha}} u \Big\|_{2} <+\infty\Big\}$$
 and 
 $$ \rH^{\alpha}:=\Big\{u: \|\nabla u\|_{2}+\Big\| \frac{|y|^{\frac{\alpha-2}{2}}}{1+|y|^{\alpha}} u \Big\|_{2}<+\infty \Big\}.$$
 \begin{itemize}
 \item[{\bf Step 1.}]\label{item:step1_a} {\it $\tilde{\phi}_{ij}\rightarrow c_{ij} \frac{1-|y|^{\alpha_i}}{1+|y|^{\alpha_i}}$ as $\varepsilon\rightarrow 0$ for some $c_{ij}\in\R$, which is weakly in $\rH^{\alpha_i}$ and strongly in $\rL^{\alpha_i}$.}
 \end{itemize}
 We fix an arbitrary $l=1,\cdots, N$. 
 The Sobolev inequality and H\"{o}lder's inequality yield that
 \begin{equation}\label{eq:h_phi}
 \Big| \int_{\Sigma} h_i \phi_l\Big|\leq \|\bh\|_p \|\phi_l\|_{p'}\leq \|\bh\|_p \|\phi_l\|=o\Big(|\log\varepsilon|^{-1}\Big)\rightarrow 0,
 \end{equation} 
 where $p, p'>1$ with $\frac 1 p+\frac 1 {p'}=1. $ 
 Moreover, $|\la \phi_i, \phi_l\ra|\leq C \|\phi_i\|\|\phi_l\|=\cO(1)$.

