\[\vbI(\a)\coloneqq \lim_{k\to\infty}\frac{\vI\big(\a^k\big)}{k}\in \bbR_{\ge 0}\cup\{\infty\},\]
where $\vI\big(\a\big)\coloneqq \sup\,\{m\in\bbN \mid \a\subseteq I_m\}$ denotes the \emph{order function} of $I_{\blt}$. This construction generalizes the classical asymptotic Samuel function \cite{Sa52} and serves as an algebraic analogue of the relative type introduced in complex analytic settings \cite{Ras06} (cf. \Cref{sec-c.a.c}).

In fact, the equivalence of the first two statements, along with the equivalence of the existence of \emph{Zhou valuations} (cf. \cite{BGMY24,BGZ25}) satisfying the same interpolation conditions, has been proved in \cite[Appendix A.1]{BGMY25}.

\begin{theorem}\label{thm-infinite.interp}
 Additionally assume $R$ is local with the unique maximal ideal $\m$. Let $(\a_j)_{j\in\bbZ_+}$ be a countable sequence of nonzero ideals in $R$ such that $\sqrt{\sum_{j=1}^{\infty} \a_j}=\m$, and let $(b_j)_{j\in\bbZ_+}$ be a sequence of positive real numbers. Then the following statements are equivalent:
 \begin{enumerate}
 \item There exists a valuation $v$ on $R$ centered at $\m$ with $A(v)<\infty$ such that $v(\a_j)=b_j$ for all $j\ge 1$;
 \item For every $r\ge 1$,
 \[\vb_{I_{\blt}^{(r)}}\big(\a_1\cdots\a_r\big)=\sum_{j=1}^r b_j,\]
 and it holds that
 \[\sup_{r\ge 1}\sup_{k\in\bbN}\Big(\lct^{\a_1^k\cdots\a_r^k}\big( I^{(r)}_{\blt}\big)-k\sum_{j=1}^r b_j\Big)<\infty.\]
 \end{enumerate}
 Here $I^{(r)}_{\blt}=\sum_{j=1}^{r}\big(\frac{1}{b_j}\cdot \a_j\big)_{\blt}$.
\end{theorem}

\begin{proposition}\label{prop-v(aj)=bj.implies.mu=bj-1}
 If $v$ is valuation on $R$ such that $v(\a_j)\ge b_j$ for $j=1,\ldots, r$, then $\vb(\a_1\cdots\a_r;I_{\blt})\le \sum_{j=1}^r v(\a_j)$. Moreover, if $v(\a_j) = b_j$ for all $j$, then $\vb(\a_1\cdots\a_r;I_{\blt})=\sum_{j=1}^r b_j$.
\end{proposition}

\begin{lemma}\label{lem-finite.val.interp.exist.QM}
 Let $\a_0$ be a nonzero ideal of $R$ with $\vb(\a_0;I_{\blt})>0$. Suppose $(Y,D)$ is a log smooth pair over $X$ which gives a log resolution of $\a_1\cdots\a_r$. Then there exists a quasi-monomial valuation $v\in \QM(Y,D)$ such that
 \[\vb(\a_0;I_{\blt})=\frac{v(\a_0)}{v(I_{\blt})}.\]
\end{lemma}

\begin{proposition}\label{prop-val.interp.gr.seq}
 Assume $\ord_{\xi}(J_{\blt})>0$ and $\m_{\xi}^p\subseteq J_{q}$ for some $p,q\in\bbZ_+$. Let $\a$ be a nonzero ideal of $R$ with $\a\subseteq\m_{\xi}$. Then the following two statements are equivalent:
 \begin{enumerate}
 \item There exists $v\in\Val_{X,\xi}^{<\infty}$ such that $v(J_{\blt})=1$ and $v(\a)=\rho(\a;J_{\blt})$;
 \item It holds that
 \[M\coloneqq \sup_{k\in\bbN}\Big(\lct(\a^k;J_{\blt})-\rho(\a;J_{\blt})\cdot k\Big)<\infty.\]
 \end{enumerate} 
 Moreover, the valuation $v$ in (1) can be chosen with $A(v)\le M$ and $v(\m_{\xi})\ge q/p$ if (2) holds.
\end{proposition}

\begin{lemma}\label{lem-multiply.change.to.plus}
 Let $J_{\blt}$ be a filtration of nonzero ideals in $R$ with $\lct(J_{\blt})<\infty$, and let $\a_1,\ldots,\a_r$ be nonzero ideals in $R$. Set $\a=\a_1\cdots\a_r$. Suppose there is a valuation $v\in\Val_X^{<\infty}$ such that $v(\a)=\rho(\a;J_{\blt})$ and $v(J_{\blt})=1$. Then $v(\a_j)=\rho(\a_j;J_{\blt})$ for $j=1,\ldots,r$ if and only if $\rho(\a;J_{\blt})=\sum_{j=1}^r \rho(\a_j;J_{\blt})$.
\end{lemma}

\begin{proposition}\label{prop-gr.seq.infinite.compute}
 Let $J_{\blt}$ be a filtration of ideals in $R$ such that $\ord_{\xi}(J_{\blt})>0$ and $\m_{\xi}^p\subseteq J_{q}$ for some $p,q\in\bbZ_+$. Assume $(\a_j)_{j\in\bbZ_+}$ is a sequence of nonzero ideals of $R$ with $\a_j\subseteq\m_{\xi}$ for all $j\ge 1$. Then the following two statements are equivalent:
 \begin{enumerate}
 \item There exists $v\in\Val_{X,\xi}^{<\infty}$ such that $v(J_{\blt})=1$ and $v(\a_j)=\rho(\a_j;J_{\blt})$ for all $j\ge 1$;
 \item For every $r\in\bbZ_+$,
 \[\rho(\a_1\cdots\a_r;J_{\blt})=\sum_{j=1}^r\rho(\a_j;J_{\blt}),\]
 and it holds that
 \[\sup_{r\ge 1}\sup_{k\in\bbN}\Big(\lct(\a_1^k\cdots\a_r^k; J_{\blt})-\rho(\a_1\cdots\a_r;J_{\blt})\cdot k\Big)<\infty.\]
 \end{enumerate}
\end{proposition}

post_theorem_intro_text:
In fact, the equivalence of the first two statements, along with the equivalence of the existence of \emph{Zhou valuations} (cf. \cite{BGMY24,BGZ25}) satisfying the same interpolation conditions, has been proved in \cite[Appendix A.1]{BGMY25}.

In addition, for the infinite valuative interpolation problem, we apply the method of valuation approximation to prove the following result in the present paper.

\begin{theorem}\label{thm-infinite.interp}
    Additionally assume $R$ is local with the unique maximal ideal $\mathfrak{m}$. Let $(\a_j)_{j\in\bbZ_+}$ be a countable sequence of nonzero ideals in $R$ such that $\sqrt{\sum_{j=1}^{\infty} \a_j}=\mathfrak{m}$, and let $(b_j)_{j\in\bbZ_+}$ be a sequence of positive real numbers. Then the following statements are equivalent:
    \begin{enumerate}
        \item There exists a valuation $v$ on $R$ centered at $\mathfrak{m}$ with $A(v)<\infty$ such that $v(\a_j)=b_j$ for all $j\ge 1$;
        \item For every $r\ge 1$,
    \[\vb_{I_{\bullet}^{(r)}}\big(\a_1\cdots\a_r\big)=\sum_{j=1}^r b_j,\]
    and it holds that
    \[\sup_{r\ge 1}\sup_{k\in\mathbb{N}}\Big(\lct^{\a_1^k\cdots\a_r^k}\big( I^{(r)}_{\bullet}\big)-k\sum_{j=1}^r b_j\Big)<\infty.\]
    \end{enumerate}
    Here $I^{(r)}_{\bullet}=\sum_{j=1}^{r}\big(\frac{1}{b_j}\cdot \a_j\big)_{\bullet}$.
\end{theorem}

\vspace{.1in} {\bf Organization}. This paper is organized as follows. In \Cref{sec-r.o}, we recall the notion of asymptotic Samuel function and quickly prove the implication (1) $\Rightarrow$ (3) in \Cref{thm-finite.interp}. In \Cref{sec-f.v.i}, we prove \Cref{thm-finite.interp} by studying the asymptotic behavior of jumping numbers and an extremal problem on a cone $\QM(Y,D)$ of quasi-monomial valuations. In \Cref{sec-i.v.i}, we prove \Cref{thm-infinite.interp} using valuation approximation, a strategy that more closely parallels the approach in \cite{BGMY25}. Finally, we demonstrate how \Cref{thm-finite.interp} recovers a result in \cite{BGMY25} (which deals with the complex analytic case) and yields an analytic characterization, derived from \Cref{thm-infinite.interp}, for the existence of infinite valuative interpolation.

