\begin{align*}
\frac{\d}{\d t}\F_m(t)+ \widetilde{\D}(t)=-\int_{\R^2}\partial_t v \frac{u}{1+u}\,\d x-\int_{\R^2}\frac{u}{1+u}\,\mathrm{d}x+\lambda\int_{\R^2}\frac{v}{1+u}\,\d x,
\end{align*}
where
$\F_m(t)$ is the modified functional defined in \eqref{eqn;modifiedLyapunov} and the dissipative term $\widetilde{\D}(t)$ is given by
\begin{align*}
\widetilde{\D}(t):=\int_{\R^2}u\left|\nabla \left(\ln(1+u)-v\right)\right|^2\,\d x+\|\partial_t v\|_2^2.
\end{align*}
\end{lem}

\vspace{5mm}
\begin{pr}{Theorem \ref{thm;global}}
Let $R$ be taken as in Lemma \ref{lem;L^2-exterior}.
By Lemma \ref{lem;LlogL-bound-exterior},
\begin{align*}
\int_{ |x|>2R } (1+u) \ln(1+u) \dx\le\, C(t_0,\tau,R).
\end{align*}
On the other hand, Lemma \ref{prop;interior-bdd-entropy} gives
\begin{align*}
\int_{ \R^2}(u\ln u)\psi_R^2\dx\le\, C(t_0,\tau,R)
\end{align*}
for $t\in[t_0,\tau]\cap(0,T)$.
Now, according to \cite[Lemma 2.3]{NaOg16},
\begin{align*}
\int_{ \Omega} (1+u)\ln(1+u)\dx\le\,2\int_{ \Omega} u |\ln u | \dx+(2\ln 2)\int_{ \Omega} u\dx,
\end{align*}
where $\Omega$ is a measurable set in $\R^2$,
 so that since $\supp\psi_R\subset \{x; |x|\le 16 R\}$
 \begin{align*}
 \int_{ |x|<8R }(1+u)\ln(1+u)\dx\le\,&2\int_{ |x|<8R }u|\ln u| \dx+(2\ln 2)\|u_0\|_1
 \\
 \le\,\,&2\int_{ \R^2 }u|\ln u| \psi_R^2\dx+(2\ln 2)\|u_0\|_1
 \\
 =\,&2\int_{ \R^2 }(u\ln u) \psi_R^2\dx-4\int_{ \R^2 }(u\ln u)_-\psi_R^2\dx+(2\ln 2)\|u_0\|_1
 \\
 \le\,&C(t_0,\tau,R) +\frac4e|B_{16R}(0)|
 \end{align*}
 for $t\in[t_0,\tau]\cap(0,T)$, where we use $x\ln x \ge -1/e$ for $x\ge0$.
 This implies that
 \begin{align*}
&\int_{ \R^2 }(1+u)\ln(1+u)\dx
\\=\,&\int_{ |x|>2R } (1+u) \ln(1+u) \dx
+\int_{ |x|\le 2R } (1+u) \ln(1+u) \dx
\\
\le\,&\int_{ |x|>2R } (1+u) \ln(1+u) \dx+\int_{ |x|< 8R } (1+u) \ln(1+u) \dx
\\
\le\,&C(t_0,\tau,R) 
 \end{align*}
 for $t\in[t_0,\tau]\cap(0,T)$.
 Hence, we have along with Proposition \ref{prop;bound-energy}
 \begin{align*}
\int_{ \R^2 }(1+u) \ln (1+u)\dx+\int_{t_0}^t \|\partial_tv\|_2^2\,\d s\le\, C(t_0,\tau,R)
 \eqntag
 \label{eqn;uniform-ulogu}
 \end{align*}
 for $t\in[t_0,\tau]\cap(0,T)$.
By the parabolic regularity argument, we obtain a uniform $L^2$-bound for~$u$
on $[t_0,\tau]\cap(0,T)$ from \eqref{eqn;uniform-ulogu} (cf. \cite{Mi13,Na-Se-Yo}), which yields further regularity estimates.
In particular, the solution~$(u,v)$ cannot blow up in finite time.
Therefore, the solution to \eqref{eqn;KS} exists globally in time.
\end{pr}

