\begin{align}\label{kinematic_top}
\mathcal{V}(\partial\mathcal{D}(t)) &= \mathbf{u}\cdot \mathbf{n}\,\quad \text{on }\partial\mathcal{D}(t),\\ 
\label{kinematic_bottom}
\mathbf u\cdot e_2 &= 0\quad\quad\ \ \text{on }\{y=-d\},
\end{align}
where $\mathbf{n}$ denotes the outward unit normal to the free surface and
$\mathcal{V}(\partial\mathcal{D}(t))$ is its normal velocity. We also have the dynamic boundary condition
\begin{align}\label{Young-Laplace}
p = \sigma H\quad \text{on }\partial\mathcal{D}(t),
\end{align}
