\subsection{Motivation and setting}
	\paragraph{Optimal transport.}Optimal transport, initiated by Monge  \cite{monge1781} and reframed by  Kantorovich \cite{zbMATH03099866},  seeks the most efficient way to redistribute mass between two probability distributions.   Precisely, given two probability measures $\rho$ and $\mu$ defined on Polish spaces $X$ and $Y$ respectively, and a  cost function $c:X\times Y\rightarrow \mathbb{R}$, the Monge optimal transport problem aims to find a minimizer  $T$,   called an optimal transport map,   of the following optimization problem among all measurable maps $H: X \to Y$ pushing $\rho$ forward to $\mu$:
	\begin{equation}\label{2.1}
		\int_X c(x, T(x))  \,{\mathrm d}\rho(x)=\inf_{H_\sharp \rho = \mu}\int_X c(x, H(x))  \,{\mathrm d}\rho(x), \tag{MP}
	\end{equation}
 The   Monge problem  prevents mass splitting, sometimes making the problem ill-posed.  Its relaxation,  called Kantorovich problem, optimizes over joint couplings instead of deterministic maps. A fundamental result known as Kantorovich duality, asserts that the Kantorovich problem is equivalent to the  following dual problem:
	\begin{equation}
		\sup_{ \phi(x) + \psi(y) \leq c(x, y)} \left\{ \int_X \phi(x) \, {\mathrm d}\rho(x) + \int_Y \psi(y) \, {\mathrm d}\mu(y)  \right\}.\tag{KD}
	\end{equation}
	The optimal functions $\phi,\psi$,  which always exist under standard assumptions,   are called  Kantorovich potentials \cite{AG-U, V-O}.  

	In the Euclidean space,   for $c(x,y)=\frac{1}{2}|x-y|^2$, Brenier's landmark result \cite{brenier1991polar} established that, for absolutely continuous source measures, the optimal transport map is unique and takes the form $T(x)=\nabla u(x)$ for a convex function $u$. This was later extended to Riemannian manifolds by McCann \cite{mccann2001polar}, who showed that for $c(x,y)=\frac{1}{2}{\mathrm d}^2(x,y)$, the optimal transport map is given almost everywhere by $T(x)=\exp_x(-\nabla\varphi(x))$ for a  Kantorovich potential $\varphi$.

	 A fundamental question in both theoretical and applied contexts of optimal transport is the quantitative stability of optimal transport maps and Kantorovich potentials under perturbations of the target measure (see Letrouit's lecture note \cite{LetrouitLecture} and the references therein).   Based on recent breakthroughs in the quantitative stability of optimal transport  on  Euclidean spaces \cite{zbMATH07794624, arXiv:2411.04908},    on boundaries of convex bodies \cite{Kitagawa12,  Kitagawa25}  and  on Riemannian manifolds  \cite{arXiv:2504.05412},     
Kitagawa--Letrouit--M\'erigot   \cite[\S 1.2]{arXiv:2504.05412} conjecture that:
	\begin{center}
		\emph{the quantitative stability results are also true in more general metric measure spaces with synthetic curvature bounds.}
	\end{center}

	\paragraph{General setting.}
	In this paper, we confirm the conjecture of Kitagawa-- Letrouit--M\'erigot for the following spaces:
	\begin{itemize}
		\item  RCD$(K,N)$  spaces (metric measure spaces with synthetic Ricci curvature lower bound):  we prove quantitative $L^1$-stability of Kantorovich potentials with respect to Wasserstein perturbations of the target measure;
		\item Alexandrov spaces with (sectional) curvature lower bound:   we establish stability estimates for optimal transport maps in terms of the $L^2$-norm of the potential difference.
	\end{itemize}

	An Alexandrov space is a  geodesic  space of finite Hausdorff dimension and of curvature bounded from below (cf.  \cite{zbMATH01626771}).   An ${\rm RCD}(K,N)$ space  is  a metric measure spaces verifying the synthetic Riemannian curvature-dimension condition  \cite{zbMATH05049052,zbMATH05578758, zbMATH06303881, G-O}.   An $n$-dimensional Alexandrov space with curvature bounded from below by $k$,  equipped with its $n$-Hausdorff measure,   is an ${\rm RCD}(k(n-1), n)$ space  \cite{zbMATH06032507,zbMATH05962558}.
		 After \cite{brenier1991polar, mccann2001polar},   Gigli--Rajala--Sturm \cite[Theorem 1.1]{ gigli2016optimal}  proved the existence and uniqueness of the optimal transport map on an $\rm{RCD}(K,N)$ space $(X,{\mathrm d},\mathfrak m)$,  for the quadratic cost $c(x,y)=\frac{1}{2}{\mathrm d}^2(x,y)$ and the source measure $\rho\ll \mathfrak m$. 

	  John domains,    named after  F. John \cite{zbMATH03166766},   encompass many cases of interest, such as  bounded Lipschitz domains, bounded domains satisfying a cone condition and certain fractal domains (see \cite{zbMATH00858510} for more discussions). 
	\begin{definition}[John domain]
		A bounded open subset $S$ of a metric space is called a \emph{John domain} if there is a distinguished point $x_0 \in S$ and a constant $\eta > 0$ such that, for every $x \in S$, there is a rectifiable curve $\gamma \colon [0, \ell(\gamma)] \to S$ parametrized by arc length, such that $\gamma(0) = x$, $\gamma(\ell(\gamma)) = x_0$, and
		\begin{equation*}
			{\mathrm d}(\gamma(t), S^c) \geq \eta t,~~~\forall t \in [0, \ell(\gamma)],
		\end{equation*}
		where $S^c$ denotes the complement of $S$.
	\end{definition}
	In  \cite[Theorem 1.9]{arXiv:2411.04908}, it has been shown that when the source measure $\rho$ is the uniform density on some non-John domain  $S\subset \mathbb{R}^n$, then no quantitative stability estimates of the form $\|\phi_\mu-\phi_\nu\|_{L^2(\rho)}\leq C W_p^\alpha(\mu,\nu)$ 
	can hold for any $C, \alpha, p>0$. 
	Moreover, examples in \cite{letrouit2025unstableoptimaltransportmaps} indicates that both unboundedness of the density and openness of    $S$ may cause  instability  of optimal transport maps.

	 In this paper,  we always assume that the Kantorovich potential  $\phi_\mu$ from $\rho$ to $\mu$ satisfies $\E_\rho(\phi_\mu)=\int_S\phi_\mu\,{\mathrm d}\rho=0$.  Together with the uniqueness of the optimal transport map, such  $\phi_\mu$ is  unique and thus makes sense to study its stability.

	\subsection{Main results}
	Our main theorem concerns the quantitative  $L^1$ stability of Kantorovich potentials on ${\rm RCD}(K,N)$  spaces.

