 \mathop{\leq}^{\text{H\"{o}lder}~~}&\frac{C_3C_4C_5}{\sqrt{t}}\left(\sum_{B\in\mathcal{F}}\mm(B_{2r_B})\right)^\frac{1}{2}\left(\sum_{B\in\mathcal{F}}\int_B {\rm{Var}}_{ \mu_x^t[\psi_*]}(v)\,\d\rho(x)\right)^\frac{1}{2}\\
 \overset{\text{Boman chain~}}{\leq}&\frac{\kappa}{\sqrt{t}}\left(\int_S {\rm{Var}}_{ \mu_x^t[\psi_*]}(v)\,\d\rho(x)\right)^\frac{1}{2}
 \end{aligned}
 \end{equation}
 which is the thesis.
 \end{proof}

