\begin{lemma}\label{lemma:sym} There exists positive absolute constants $C_1$, $C_2$, $C_3$ and $C_4$ such that 
\begin{equation*}
 C_1 \exp \left(-C_2\frac{t}{N^2}\right) \le \mathbb{P}(\sigma_N > t) \le C_3 \exp \left(-C_4\frac{t}{N^2}\right),
\end{equation*}
for all $N\ge 2$ and $t \ge 1$. 
\end{lemma}

\begin{enumerate}[(i)]
 \item \textbf{Case $\bm{p \ge 1/2}$.}
 Let $\tilde{S}_0 = 0$ and, for $k\ge 1$, define recursively $\xi_k$ and $\tilde{S}_k$ by:
 \begin{equation*}
 \xi_{k} = \mathbbm{1}_{\left\{\tilde{S}_{k-1} = 0 \right\}} + \mathbbm{1}_{\left\{\tilde{S}_{k-1} \neq 0 \right\}} \left( \mathbbm{1}_{\left\{U_{k} < \frac{1}{2} \right\}} - \mathbbm{1}_{\left\{U_{k} \ge \frac{1}{2}\right\}}\right), 
 \end{equation*}
 and
 \begin{equation}\label{srw-coupling}
 \tilde{S}_{k} = \sum_{j=1}^{k}\xi_j.
 \end{equation}
 Then $\tilde{S}_k$ has the same distribution as $|S_k|$, where $(S_k)_{k \ge 0}$ is still the symmetric simple random walk defined in the previous section. Moreover, $(\tilde{S}_k)_{k\ge 0}$ and $(\tilde{Z}_{k} )_{k\ge 0}$ are constructed in such a way that the following holds:
 \begin{equation}\label{enq_1}
 \tilde{Z}_k \ge \tilde{S}_k, \, \text{ for all } k\ge 0.
 \end{equation}
 Notice that the only way inequality \eqref{enq_1} could be broken would be if at some point $\tilde{Z}_k = 1$ and $\tilde{S}_k = 0$ (and $\tilde{Z}_{k}$ jumps to the left between $k$ and $k+1$). Fortunately this never happens since $\tilde{Z}_k$ and $\tilde{S}_k$ have the same parity. Below, we deliberately abuse notation, redefining $\tau_N$ and $\sigma_N$ in terms of $(\tilde{S}_k)_{k\ge 0}$ and $(\tilde{Z}_{k} )_{k\ge 0}$. By inequality \eqref{enq_1} and Lemma \ref{lemma:sym}, for all $N\ge 1$ and $t\ge 1$, one indeed has:

\begin{equation}\label{enq_2}
 \tilde{S}_k - 2\sum_{j=1}^k\mathbbm{1}_{\left\{\frac{1}{2} + \frac{(2p-1)\tilde{Z}_{j +dN^{2}}}{j + dN^2}\le U_{j + dN^{2}} < \frac{1}{2}\right\}} \le \tilde{Z}_{k + dN^{2}} , \, \text{ for all } k\ge 0.
 \end{equation}
 Let $c > 12 + d$. For any $x < N$ we have
 \begin{align*}\label{eq:boundonethird+}
 \P_x \left(\tau_N > cN^2\right) &= \P_x\left(\tau_N > cN^{2}, \sigma_{2N} > 3(2N)^2\right) + \P_x \left(\tau_N > cN^{2}, \sigma_{2N} \le 3(2N)^2)\right)\\
 &\le \P_x \left(\sigma_{2N} > 3(2N)^2\right) + \P_x \left(\tau_N > cN^{2}, \sigma_{2N} \le 3(2N)^2\right)
 \end{align*}
 But $\P_x \left(\sigma_{2N} > 3(2N)^2 \right) \leq 1/3$ by Markov inequality (see inequality $(\ref{eq:markov_sym})$ in the proof of Lemma \ref{lemma:sym}), hence:
 \begin{equation}\label{eq:boundonethird+}
 \P_x \left(\tau_N > cN^2 \right) \le \frac{1}{3} + \P_x \left(\tau_N > cN^{2}, \, \sigma_{2N} \le 3(2N)^2 \right).
 \end{equation}
 Now observe that $\tau_N > cN^{2}$ means that the elephant has not reached $N$ yet at time $c N^2$ while $\sigma_{2N} \le 3(2N)^2$ means that the symmetric random walk reached $2N$ in the meantime, even though it was exactly at the same point $12N^2$ time-steps earlier (or more). Now assume that both hold. Then $\tilde{Z}_k < N$ for any $k \le dN^2 + \sigma_{2N}$, where $dN^2 + \sigma_{2N}$ represents the time at which $(\tilde{S}_k)_{k \geq 0}$ reaches $2N$, but on the $(\tilde{Z}_k)_{k \geq 0}$ time-scale. Then the inequality $\tilde{Z}_{dN^2 + \sigma_{2N}}< N$ together with \eqref{enq_2} implies that 
 $$2N - 2 \sum_{j=1}^{\sigma_{2N}}\mathbbm{1}_{\big\{\frac{1}{2} + \frac{(2p-1)\tilde{Z}_{j + dN^{2}}}{j + dN^{2}}\le U_{j + dN^{2}} < \frac{1}{2}\big\}} < N.$$
 Moreover, since $\sigma_{2N} \le 3(2N)^2$ and $\tilde{Z}_{j + dN^2} < N$ for any of the indices $j$ in the sum above, the above inequality implies that
 $$ 2N - 2\sum_{j=1}^{3 (2 N)^2}\mathbbm{1}_{\{\frac{1}{2} + \frac{(2p - 1)}{dN}\le U_{j + dN^{2}} < \frac{1}{2} \} } < N.$$

\begin{equation*}
 \big\{ \tau_N > cN^{2}, \sigma_{2N} \le 3(2N)^2 \big\} \subset \Big\{B_N > \frac{N}{2} \Big\},
 \end{equation*}
 where: $$B_N = \sum_{j=1}^{12 N^2}\mathbbm{1}_{\left\{\frac{1}{2} + \frac{(2p - 1)}{dN}\le U_{j + dN^{2}} < \frac{1}{2} \right\}} \sim \text{Binomial}\left(12 N^2, \, \frac{1-2p}{dN}\right).$$ 
 Now, by letting $d > \lceil 24(1-2p)\rceil$, we have:
 \begin{equation}\label{eq_2}
 \mathbb{E}[B_N] = \frac{12(1 - 2p)N}{d} < \frac{N}{2},
 \end{equation}
 and thus
 \begin{equation*}
 \P\Big(B_N > \frac{N}{2}\Big) \le \frac{1}{2}.
 \end{equation*}
 Hence, for our choice of $d$, it holds that:
 \begin{equation} \label{eq:onehalfpart}
 \P_x \left(\tau_N > cN^{2}, \sigma_{2N} \le 3(2N)^2 \right) \le \frac{1}{2}.
 \end{equation}
 Finally, inequality \eqref{eq:onehalfpart} together with inequality \eqref{eq:boundonethird+} leads to:
 \begin{equation*}
 \P_x \left(\tau_N > cN^2 \right) \le \frac{5}{6}.
 \end{equation*}
 Then the same line of reasoning as in the end of the proof of Lemma \ref{lemma:sym} allows us to conclude:

Notice that, since ${\left\{U_j < p \right\} = \left\{U_j < \frac{1}{2} + \frac{2p-1}{2} \right\}}$, one has $\tilde{Z}_k \le \hat{S}_k$, for all $k\ge 0$. Therefore, if 
\begin{equation*}
 \hat{\sigma}_N = \inf\{k\ge 1: \hat{S}_k = N\},
\end{equation*}
then, for all $N \ge 2$ and $t\ge 1$, one has: 
\begin{equation*}
 \mathbb{P}(\tau_N > t) \ge \mathbb{P}(\hat{\sigma}_N > t).
\end{equation*}
Observing that $\{U_1 > p , \, \ldots , \, U_t > p\}\subset \{\hat{\sigma}_N > t\}$, we obtain the following---very crude, but good enough---bound:
\begin{equation*}
 \mathbb{P}(\hat{\sigma}_N > t) \ge (1-p)^t = e^{\log(1 - p) t} \ge e^{-\log \left(\frac{1}{1-p}\right)C_A^2 \frac{t}{N^2}},
\end{equation*}
for all $t\ge 1$ and $2\le N\le C_A$. Hence taking $C_2 = \max \left\{\log \left(\frac{1}{1-p}\right)C_A^2, \tilde{C}_2 \right \}$, we can indeed conclude:
\begin{equation*}
 \mathbbm{P}(\tau_N \ge t) \ge C_1e^{-C_2\frac{t}{N^2}},
\end{equation*}
for all $N\ge 2$ and $t\ge 1$.
\end{enumerate}

We start with the upper bound and then proceed to the lower bound. Fix some $c > 1$. For any $x \in \llbracket -N, N \rrbracket$, a classical martingale argument (see for example Theorem 4.8.7 in \cite{durrett2019probability}) gives us:
 \begin{equation*}
 \E_x \left[\sigma_N \right] = (N-x)(x+N) \le N^2.
 \end{equation*}
 Hence, by Markov inequality:
 \begin{equation}\label{eq:markov_sym}
 \P_x \left(\sigma_N > cN^2 \right) \le \frac{\E_x \left[ \sigma_N \right]}{cN^2}\le \frac{1}{c}.
 \end{equation}
 For $t \geq 0$, it follows that:
 \begin{equation*}
 \P(\sigma_N > t) \leq \P \left(\sigma_N \ge \left\lfloor \frac{t}{cN^2}\right\rfloor cN^2 \right) \le \left(\frac{1}{c}\right)^{\left\lfloor \frac{t}{cN^2}\right\rfloor} \le \left(\frac{1}{c}\right)^{\frac{t}{cN^2} - 1} = C_3e^{-C_4\frac{t}{N^2}},
 \end{equation*}
 with $C_3 = c$ and $C_4 = \log(c)/c$. Notice that, for $t \geq cN^2$, the second inequality above is a consequence of \eqref{eq:markov_sym} together with the strong Markov property, whereas it is trivial for $t < c N^2$, since in that case $\left(\frac{1}{c}\right)^{\left\lfloor \frac{t}{cN^2} \right\rfloor} = 1$.

