\begin{theorem}
\label{mainThm}
    Let $(\Gamma, \Delta)$ be a Zamolodchikov periodic $n\times n$ $B$-matrix with Coxeter numbers $h_{\Gamma}, h_{\Delta}$.
    Let $T(t)$ be the $T$-system associated to $(\Gamma, \Delta)$.
    Then for all $i\in [n]$,
    \begin{align*}
        T_i(t + h_{\Gamma} + h_{\Delta}) = T_{\sigma(i)}(t)
    \end{align*}
    for some automorphism $\sigma\in S_n$ of $(\Gamma, \Delta)$ of order at most two.
    When $h_{\Gamma} + h_{\Delta}$ is even, this permutation is bipartite color preserving.
    Otherwise, it is color reversing.
\end{theorem}

In Section \ref{prelims}, we introduce cluster algebras, maximal green sequences, and bipartite dynamics of cluster algebras, known as \textit{$T$-systems} and \textit{$Y$-systems}.
In Section \ref{sec:maximalGreen}, we prove that for all Zamolodchikov periodic $B$-matrices, the bipartite belt is a maximal green sequence.
In Section \ref{sec:half-periodicity}, we prove the form at the half-period is a permutation of the cluster variables, and observe when it gives the identity permutation.
In Section \ref{sec:coloredMutations}, we observe that in the case of single Dynkin diagrams under a certain global tropical ordering, half-periodicity yields a bijection between almost positive roots and colored tropical mutations, as conjectured in our earlier work \cite{chin}.

\section{Preliminaries}
\label{prelims}

\subsection{Introduction to cluster algebras with coefficients}

An $n\times n$ matrix $B$ is \textit{skew-symmetrizable} if there exists some $c\in \mathbb{R}_{>0}^n$ such that $\forall i, j\in [n]$, $c_ib_{ij} = -c_jb_{ji}$.
In other words, a matrix $B$ is skew-symmetrizable if there exists some nonzero scaling of the rows $c\in \mathbb{R}_{>0}^n$ that makes the matrix skew-symmetric.

\begin{definition}
    Let $I$ be a finite index set.
    \begin{itemize}
        \item[(1)]
            A \textit{semifield} is an abelian multiplicative group $(\mathbb{P}, \oplus, \cdot)$ equipped with addition $\oplus$ which is commutative, associative, and distributive with respect to multiplication in $\mathbb{P}$.
        \item[(2)]
            For an $I$-tuple of variables $y = (y_i)_{i\in I}$, the \textit{universal semifield} $\mathbb{Q}_{sf}(y)$ consists of all rational functions $P(y) / Q(y)$, where $P(y)$ and $Q(y)$ are nonzero polynomials in the $y_i$'s over $\mathbb{Z}_{>0}$, equipped with the usual operations of multiplication and addition.
        \item[(3)]
            For an $I$-tuple of variables $y = (y_i)_{i\in I}$, the \textit{tropical semifield} Trop($y$) is the abelian multiplicative group freely generated by the variables $(y_i)_{i\in I}$, equipped with addition $\oplus$ defined by
            $$\prod_i y_i^{a_i} \oplus \prod_i y_i^{b_i} = \prod_i y_i^{\min(a_i, b_i)}.$$
    \end{itemize}
\end{definition}

\begin{definition}
    A \textit{labeled seed} in field $\mathcal{F}$ is a triple $(x, y, B)$ where
    \begin{itemize}
        \item 
            $B = (b_{ij})$ is an $n\times n$ skew-symmetrizable integer matrix,
        \item 
            $x = (x_1, \dots, x_n)$ is an $n$-tuple of elements in $\mathcal{F}$ forming a \textit{free generating set}; that is, $x_1, \dots, x_n$ are algebraically independent over $\mathbb{QP}$, and $\mathcal{F} = \mathbb{QP}(x_1, \dots, x_n)$,
        \item 
            $y = (y_1, \dots, y_n)$ is an $n$-tuple of algebraically independent elements in $\mathbb{P}$.
    \end{itemize}
\end{definition}
We use the following notation:
\begin{itemize}
    \item 
        $x$ is the (labeled) \textit{cluster} of this seed $(x, B)$,
    \item 
        the elements $x_1, \dots, x_n$ are its \textit{cluster variables},
    \item 
        the elements $y_1, \dots, y_n$ are its \textit{frozen variables} (or \textit{coefficients}),
    \item 
        $B$ is the \textit{exchange matrix}, also known as the $B$-matrix.
\end{itemize}
When the coefficients lie in the tropical semifield Trop($y$), they are called \textit{principal coefficients}.

\begin{definition}
    Let $(x, y, B)$ be a labeled seed. 
    Let $k\in [n]$.
    The \textit{seed mutation} $\mu_k$ in direction $k$ transforms $(x, y, B)$ into the new labeled seed $\mu_k(x, y, B) = (x', y', B')$ defined as follows:
    \begin{itemize}
        \item 
            The cluster $x' = (x_1', \dots, x_n')$ is given by $x_j' = x_j$ for all $j\neq k$, whereas $x_k'$ is determined by the \textit{exchange relation}
            \begin{equation}
            \label{mutationX}
                x_kx_k' = \frac{y_{k}}{1 \oplus y_k}\prod_{b_{ik} > 0} x_i^{|b_{ik}|} + \frac{1}{1\oplus y_k}\prod_{b_{ik} < 0} x_i^{|b_{ik}|}.
            \end{equation}
        \item 
            The coefficients $y' = (y_1', \dots, y_n')$ are given by
            \begin{equation}
            \label{mutationY}
                y_i' = \begin{cases}
                    y_i^{-1} & i = k,\\
                    y_iy_k^{\max(0, b_{ki})}(1\oplus y_k)^{-b_{ki}} & i\neq k.
                \end{cases}
            \end{equation}
        \item  
            The exchange matrix $B' = (b_{ij}')$ is given by
            $$b_{ij}' = \begin{cases}
                -b_{ij} & \text{if }i = k \text{ or } j = k,\\
                b_{ij} + b_{ik}b_{kj} & \text{if } b_{ik}, b_{kj} > 0,\\
                b_{ij} - b_{ik}b_{kj} & \text{if } b_{ik}, b_{kj} < 0,\\
                b_{ij} & \text{otherwise.}
            \end{cases}$$
    \end{itemize}
\end{definition}

\begin{definition}
    Let $(x, y, B)$ be a seed.
    Let $\mathcal{Y}$ be the union of all $\{\frac{y_i}{1\oplus y_i}, \frac{1}{1\oplus y_i}\}$ for every coefficient $y_i$ obtained from any sequence of mutations of this seed.
    Let $\mathcal{X}$ be the set of all cluster variables obtained from any sequence of mutations of this seed.
    The \textit{cluster algebra} $\mathcal{A}$ generated by the seed $(x, y, B)$ is the $\mathbb{ZP}$-subalgebra of the ambient field $\mathcal{F}$ generated by all cluster variables: $\mathcal{A} = \mathbb{ZP}[\mathcal{X}]$.
\end{definition}

In general, $\mathcal{X}$ is an infinite set. When $\mathcal{X}$ is finite, we say the cluster algebra $\mathcal{A}$ is of \textit{finite type}.
The following result introduces an interesting connection between root systems and cluster algebras of finite type.

\begin{theorem}[\cite{fomin}]
\label{fominBijection}
    Let $(B, x, y)$ be a seed of a finite type cluster algebra of type $\Lambda$.
    There is a unique bijection between the almost positive roots of $\Lambda$ and the cluster variables of the cluster algebra generated by $(B, x, y)$, which sends $\alpha\mapsto x[\alpha]$, where
    \[x[\alpha] = \frac{P_{\alpha}(x)}{x^{\alpha}}.\]
    Here, $P_{\alpha}(x)$ is a polynomial over $\mathbb{Z}\mathbb{P}$ with nonzero constant term.
    Moreover, every coefficient of $P_{\alpha}$ is a polynomial in the elements of $\mathcal{Y}$ with positive integer coefficients.
\end{theorem}

full_context:
\subsection{Zamolodchikov periodicity}

Cluster algebras were first introduced in \cite{fomin1} by Fomin and Zelevinsky with applications to dual canonical bases, total positivity in semisimple Lie groups, and Zamolodchikov periodicity for $Y$-systems of finite root systems.
In their fourth paper on cluster algebras, Fomin--Zelevinsky introduced what is known as the \textit{bipartite belt}, a sequence of bipartite mutations defined below whose exchange relations form a discrete dynamical system they called a \textit{generalized $Y$-system} \cite{fomin4}.

An $n\times n$ matrix $B$ is \textit{bipartite} if there exists a coloring $\epsilon: [n]\rightarrow \{\circ, \bullet\}$ of $[n]$ such that for all $i, j$ of the same color, $b_{ij} = b_{ji} = 0$.
It is well known that mutation is a local move, so mutations $\mu_i$ and $\mu_j$ commute if $b_{ij} = b_{ji} = 0$.
Thus in a bipartite matrix, we may define the \textit{bipartite mutations} $\mu_{\circ}$ and $\mu_{\bullet}$ as the combined mutation at all white vertices and all black vertices, respectively.
A bipartite matrix $B$ is \textit{recurrent} if $\mu_{\circ}\mu_{\bullet}(B) = \mu_{\circ}(-B) = B$. 
The sequence $\mu_{\circ}\mu_{\bullet}\mu_{\circ}\mu_{\bullet}\dots$ is known as the \textit{bipartite belt}.

A bipartite recurrent matrix $B$ is \textit{Zamolodchikov periodic} if the bipartite belt is periodic.
Zamolodchikov periodicity was first observed by Zamolodchikov in his study \cite{zamolodchikov} of thermodynamic Bethe ansatz, initially focusing on the simply-laced Dynkin diagrams $A_n, D_n$, and $E_n$.
In \cite{fomin4}, it was proved that the bipartite belt associated with a generalized Cartan matrix is periodic exactly when the matrix is of finite type.
The conjecture was further proved for all tensor products $\Gamma\otimes \Delta$ of Dynkin diagrams by Keller \cite{keller} and later in a different way by Inoue--Iyama--Keller--Kuniba--Nakanishi \cite{inoue, inoue2}.
In our previous work \cite{chin}, we fully classified all Zamolodchikov periodic cluster algebras.

In particular, the period is a divisor of $2(h + h')$, where $h, h'$ are the Coxeter numbers associated to the bipartite recurrent $B$-matrix.
The behavior after $(h + h')$ mutations is known as \textit{half-periodicity}, and was conjectured in \cite{kuniba} for $Y$-systems and in \cite{inoue2} for $T$-systems of finite type Cartan matrices.
In \cite{inoue}, half-periodicity was proved for tensor products of two simply-laced Dynkin diagrams.
In this paper, we prove half-periodicity for every Zamolodchikov periodic cluster algebra.

\subsection{The main theorem}
The following theorem is the main result of this paper.

\subsection{The main theorem}
The following theorem is the main result of this paper.

In Section \ref{prelims}, we introduce cluster algebras, maximal green sequences, and bipartite dynamics of cluster algebras, known as \textit{$T$-systems} and \textit{$Y$-systems}.
In Section \ref{sec:maximalGreen}, we prove that for all Zamolodchikov periodic $B$-matrices, the bipartite belt is a maximal green sequence.
In Section \ref{sec:half-periodicity}, we prove the form at the half-period is a permutation of the cluster variables, and observe when it gives the identity permutation.
In Section \ref{sec:coloredMutations}, we observe that in the case of single Dynkin diagrams under a certain global tropical ordering, half-periodicity yields a bijection between almost positive roots and colored tropical mutations, as conjectured in our earlier work \cite{chin}.

At each time step, when $\epsilon_k = \circ$, $T_k(t+1)$ and $Y_k(t+1)$ are only dependent on black indices ($\epsilon_i = \bullet$).
Similarly when $\epsilon_k = \bullet$, $T_k(t+1)$ and $Y_k(t+1)$ are only dependent on white indices ($\epsilon_i = \circ$).
Because of this, both systems associated with $B$ split into two independent components.
For our purposes, we consider only one component.
From now on, assume that the two systems are defined only for $k\in [n]$ and $t\in \mathbb{Z}$ such that
\begin{equation}
\label{splitTsystem}
 \epsilon_k = \circ\quad\text{and}\quad t\equiv 0\hspace{-2mm}\pmod{2}\qquad \text{or} \qquad \epsilon_k = \bullet\quad \text{and} \quad t\equiv 1\hspace{-2mm}\pmod{2}.
\end{equation}
Both systems are set to the following initial conditions:
\begin{align*}
 T_k(0) = Y_k(0) = x_k\quad \text{and}\quad T_k(1) = Y_k(1) = x_k, \quad\text{for all } k \text{ satisfying } (\ref{splitTsystem}).
\end{align*}
Notice that the $T$-system relations are exactly the same as the exchange relations (\ref{mutationX}) for cluster mutation in a bipartite recurrent setting, when specialized at $y_i = 1$. In particular, this initialization will result in the same sequence of cluster variables as the mutation sequence $\mu_{\circ}\mu_{\bullet}\mu_{\circ}\mu_{\bullet}\dots$ acting on the initial seed $(B, x)$.
We say the $T$-system or $Y$-system is \textit{periodic} if there exists some positive integer $N$ such that $T_k(t + 2N) = T_k(t)$ for all $k\in[n], t\in\mathbb{Z}$. 
\begin{remark}
In particular, a bipartite recurrent matrix $B$ is Zamolodchikov periodic if its associated $T$-system or $Y$-system is periodic.
The original formulation of Zamolodchikov periodicity was in terms of $Y$-systems.
\end{remark}

\begin{proposition}
\label{maximalGreen}
 Let $B = (\Gamma, \Delta)$ be a Zamolodchikov periodic $B$-matrix with associated Coxeter numbers $h_{\Gamma}, h_{\Delta}$. 
 Let $\epsilon: [n]\rightarrow \{\circ, \bullet\}$ be a bipartition on $(\Gamma, \Delta)$ such that white vertices are sinks in $\Gamma$ and sources in $\Delta$, and black vertices are sources in $\Gamma$ and sinks in $\Delta$.
 Then, $\mu_{\circ}\mu_{\bullet}\mu_{\circ}\cdots$ ($h_{\Gamma}$ factors) and $\mu_{\bullet}\mu_{\circ}\mu_{\bullet}\cdots$ ($h_{\Delta}$ factors) are maximal green sequences for the framed matrix $\hat{B}$.
\end{proposition}

The following proposition states Theorem \ref{mainThm} for simply-laced types.
\begin{proposition}
\label{ADE}
 Let $(\Gamma, \Delta)$ be an ADE bigraph with Coxeter numbers $h_{\Gamma}, h_{\Delta}$.
 Let $T(t)$ be the $T$-system associated to $(\Gamma, \Delta)$.
 Then for all $i\in [n]$,
 \begin{align*}
 T_i(t + h_{\Gamma} + h_{\Delta}) = T_{\sigma(i)}(t)
 \end{align*}
 for some automorphism $\sigma\in S_n$ of $(\Gamma, \Delta)$ of order at most two.
 When $h_{\Gamma} + h_{\Delta}$ is even, this permutation is bipartite color preserving.
 Otherwise, it is color reversing.
\end{proposition}
\begin{proof}
 Let the initial seed be our coframed matrix $\check{B}$, and let $\hat{y}_i$ denote the tropical evaluation of the coefficient $y_i$ (in the tropical semifield Trop($y$)).
 As noted in Remark \ref{remark1}, applying $\mu_{\circ}\mu_{\bullet}\cdots$ ($h_{\Gamma} + h_{\Delta}$ factors) gives us a frozen isomorphism, or a permutation $\sigma$ of the $C$-matrix.
 Moreover by the separation formula (\ref{separation}), $c$-vectors are exactly the exponent vectors for principal coefficients, the tropical evaluation of coefficients, so we have $\hat{y}_i(t) = \hat{y}_{\sigma(i)}$, $\forall i\in [n]$.
 Thus by the periodicity theorem (\ref{periodicity}), the cluster variables also exhibit the same permutation $\sigma$ of variables at time $N = h_{\Gamma} + h_{\Delta}$.

\begin{lemma}
\label{tropicalT}
 Let $B$ be a bipartite recurrent $B$-matrix.
 Let $\sigma\in S_n$ be a bipartite color preserving automorphism of $B$, and let $N\in \mathbb{Z}_{>0}$ be an even integer. 
 The following are equivalent:
 \begin{itemize}
 \item[(1)]
 $\boldsymbol{t}^{\delta_j}_i(t + N) = \boldsymbol{t}^{\delta_j}_{\sigma(i)}(t)$ for all $i, j\in [n], t\in \mathbb{Z}$.
 \item[(2)]
 $\boldsymbol{t}^{\lambda}_i(t + N) = \boldsymbol{t}^{\lambda}_{\sigma(i)}(t)$ for all $i\in [n], t\in \mathbb{Z}$, for any initial labeling $\lambda\in \mathbb{R}^n$.
 \item[(3)]
 There exists a labeling $c\in\mathbb{R}_{>0}^n$ such that $T_i(t + N) = c_{\sigma(i)}T_{\sigma(i)}(t)$ for all $i\in [n], t\in\mathbb{Z}$.
 \end{itemize}
\end{lemma}
\begin{proof}

\begin{lemma}
\label{transposeCommutes}
 Let $\sigma\in S_n$ be a bipartite color preserving automorphism of $B$, and let $N\in \mathbb{Z}_{>0}$ be an even integer. 
 For any initial labeling $\lambda\in\mathbb{R}^n$, let the tropical $T$-system of $B$ satisfy
 $$\boldsymbol{t}^{\lambda}_i(t + N) = \boldsymbol{t}^{\lambda}_{\sigma(i)}(t), \text{ for all } i\in [n], t\in \mathbb{Z}.$$
 Then, the tropical $T$-system of the Langland dual $-B^{\top}$ satisfies the same relations.
\end{lemma}

\section{Colored mutations}
\label{sec:coloredMutations}
Let $B$ be a Zamolodchikov periodic $B$-matrix, and let $\boldsymbol{t}_i^{\lambda}$ be its corresponding tropical $T$-system with initial labeling $\lambda\in \mathbb{R}^n$.
Recall the form for tropical mutation at index $k\in [n]$:
\begin{align*}
 \boldsymbol{t}_k^{\lambda}(t + 1) + \boldsymbol{t}_k^{\lambda}(t - 1) = \max\left(\sum_i\Gamma_{ik}\boldsymbol{t}_i^{\lambda}(t), \sum_j \Delta_{jk}\boldsymbol{t}_j^{\lambda}(t)\right).
\end{align*}
For a generic initial labeling $\lambda\in\mathbb{R}^n$, we can color this mutation either red or blue, depending on the evaluation of the max function. 
If the maximum is $\sum_i\Gamma_{ik}\boldsymbol{t}_i^{\lambda}(t)$, then we call this a \textit{$\Gamma$-mutation}, and color it red.
Otherwise if the maximum is $\sum_j\Delta_{jk}\boldsymbol{t}_j^{\lambda}(t)$, then we call this a \textit{$\Delta$-mutation}, and color it blue.

