\label{Thm_Uniform_bound}
		Let $\Omega=B_1(0)$ be the unit ball in $\mathbb R^2$, assume conditions $(H_1)$, $(H_2)$, $(H_3)$, $(H_b)$, and alternatively
		\begin{enumerate}
			\item[i)] \begin{equation}\label{BM}
		\lim_{t\to+\infty}\frac{f'}f(t)=p\quad\mbox{and}\quad\lim_{t\to+\infty}\frac{g'}g(t)=q\,.
	\end{equation} holds;
			\item[ii)] \begin{equation}\label{nonBM}
		\lim_{t\to+\infty}\frac{f'}f(t)=0\quad\mbox{and}\quad\lim_{t\to+\infty}\frac{g'}g(t)=+\infty
	\end{equation}, $(H_4)$, $(H_5)$, and either $(H_6)$ or $(H_6')$ hold.
		\end{enumerate}
		Then there exists a constant $C>0$ such that
		\begin{equation*}
			\|u\|_\infty\leq C\qquad\mbox{and}\qquad\|v\|_\infty\leq C
		\end{equation*}
		for all (eventual) solutions $(u,v)$ of the system
		\begin{equation}\label{sys}
		\begin{cases}
			-\Delta u=f(v)\quad&\mbox{in }\Omega\,,\\
			-\Delta v=g(u)\quad&\mbox{in }\Omega\,,\\
			u=v=0\quad&\mbox{on }\dOmega\,.
		\end{cases}
	\end{equation}.

theorem.content:
[Volume and circumference]\label{thm:vol-circumference}
Let $M$ be a closed hyperbolic $3$-manifold with a pseudo-Anosov flow $\varphi$. Let $S$ be a closed connected surface in $M$ that is almost transverse to $\varphi$, but is not a fiber. Let $c^{s/u}$ be the stable/unstable multicurves of $S$. Assume that $\mathfrak{c}(M\backslash \!\! \backslash S)<\infty$.

There is a constant $k_S = k_S(\chi(S)) \ge 1$, depending only on $\chi(S)$, and a constant $k_{M \backslash \!\! \backslash S} \ge 1$, depending only on $\chi(S)$ and $\mathfrak c(M\backslash \!\! \backslash S)$, so that the following inequalities hold:
\begin{enumerate}
