\overrightarrow{\bfz}^{-1}_{i,j}:=(1/z_i,1/z_{i+1},\ldots,1/z_j)\quad\text{and}\quad \overleftarrow{\bfz}^{-1}_{i,j}:=(1/z_j,1/z_{j-1},\ldots,1/z_i)\quad (\forall\ z_l\in \mathbb{C}\setminus\{0\}).
\end{align*}
This paper also agrees that $z$ and $\bfz$ above can be replaced with other letters for similar definitions, such as $\overrightarrow{\bfy}_{i,j}=(y_i,y_{i+1},\ldots,y_j)$ and $\overleftarrow{\bfy}_{i,j}:=(y_j,y_{j-1},\ldots,y_i)$. In particular, for the addition of two sequences, we define
\begin{align*}
\overrightarrow{(\bfy\pm \bfz)}_{i,j}:=(y_i\pm z_i,y_{i+1}\pm z_{i+1},\ldots,y_j\pm z_j)\quad\text{and}\quad \overleftarrow{(\bfy\pm\bfz)}_{i,j}:=(y_j\pm z_j,y_{j-1}\pm z_{j-1},\ldots,y_i\pm z_i).
\end{align*}
Furthermore, if all elements in a sequence are equal, for example, $\overrightarrow{\bfy}_{i,j}=\overleftarrow{\bfy}_{i,j}=(\{y\}_{j-i})$ (where $\{y\}_r$ denotes the sequence of $y$ repeated $r$ times), then we adopt the following notation (the order of $y$ and $\bfz$ can also be interchanged)
\begin{align*}
\overrightarrow{(y\pm\bfz)}_{i,j}:=(y\pm z_i,y\pm z_{i+1},\ldots,y\pm z_j)\quad\text{and}\quad \overleftarrow{(y\pm \bfz)}_{i,j}:=(y\pm z_j,y\pm z_{j-1},\ldots,y\pm z_i).
\end{align*}
Let $i,j\in\N_0:=\mathbb{N}\cup\{0\}$ with $i\leq j$. If $k_i,k_{i+1},\ldots,k_j\in\mathbb{N}$, we define
\begin{align}
|\overrightarrow{\bfk}_{i,j}|:=k_i+k_{i+1}+\cdots+k_j\quad\text{and}\quad |\emptyset|:=0.
\end{align}

Let $\overrightarrow{\bfa}_{1,r}:=(a_1,\ldots,a_r)$ and $a_j\in \mathbb{C}\setminus \mathbb{N}^-\ (\mathbb{N}^-:=\{-1,-2,-3,\ldots\})$. For $\overrightarrow{\bfk}_{1,r}:=(k_1,\ldots,k_r)\in \mathbb{N}^r$ and $\overrightarrow{\bfx}_{1,r}:=(x_1,\ldots,x_r)$, where each $x_j$ is a root of unity and $(k_r,x_r)\neq (1,1)$, we define the \emph{cyclotomic multiple Hurwitz zeta values} with $r$-variables (namely $x_1,\ldots,x_r$) and $r$-parameters (namely $a_1,\ldots,a_r$) by
\begin{align}\label{defn-CMHZV}
\Li_{\overrightarrow{\bfk}_{1,r}}\left(\overrightarrow{\bfx}_{1,r};\overrightarrow{(1+\bfa)}_{1,r}\right)&\equiv \Li_{k_1,\ldots,k_r}(x_1,\ldots,x_r;a_1+1,\ldots,a_r+1)\nonumber\\
&:=\sum_{0<n_1<\cdots<n_r} \displaystyle\!frac{x_1^{n_1}\cdots x_r^{n_r}}{(n_1+a_1)^{k_1}\cdots (n_r+a_r)^{k_r}},
\end{align}
where $r$ and $|\overrightarrow{\bfk}_{1,r}|=k_1+\cdots+k_r$ are called the \emph{depth} and \emph{weight}, respectively.
In particular, when all $x_j=1$, \eqref{defn-CMHZV} is referred to as the \emph{multiple Hurwitz zeta value} (also see \cite{AkiyamaIshikawa}). This can be viewed as a Hurwitz-type generalization of the classical \emph{multiple zeta values}, which are defined as follows (see \cite{H1992,DZ1994} ):
\begin{align}\label{defn-MZV}
\zeta\left(\overrightarrow{\bfk}_{1,r}\right)\equiv \zeta(k_1,\ldots,k_r):=\sum_{0<n_1<\cdots<n_r} \displaystyle\!frac{1}{n_1^{k_1}\cdots n_r^{k_r}},
\end{align}
where $k_1,\ldots,k_r$ are positive integers and $k_r\geq 2$ (i.e. admissible).
If all $a_j=0$ then \eqref{defn-CMHZV} is called the \emph{cyclotomic multiple zeta value}, denoted by the symbol (see \cite{YuanZh2014a,Zhao2010})
\begin{align}\label{defn-CMZV}
\Li_{\overrightarrow{\bfk}_{1,r}}\left(\overrightarrow{\bfx}_{1,r}\right)\equiv \Li_{\overrightarrow{\bfk}_{1,r}}\left(\overrightarrow{\bfx}_{1,r};\{1\}_r\right)=\sum_{0<n_1<\cdots<n_r} \displaystyle\!frac{x_1^{n_1}\cdots x_r^{n_r}}{n_1^{k_1}\cdots n_r^{k_r}}.
\end{align}
Furthermore, if all \(x_j \in \{\pm 1\}\) in \eqref{defn-CMZV} and at least one \(x_j = -1\), then it is referred to as an \emph{alternating multiple zeta value} (\cite{BBB1997}). It is worth emphasizing that many special alternating multiple zeta values can essentially be expressed as rational linear combinations of multiple zeta values. An alternating multiple zeta value that admits such a representation is referred to as an \emph{unramified} alternating multiple zeta value. For instance, Zhao proved in \cite{Zhao2-2010} the following beautiful unramified family of alternating multiple zeta values, which was initially discovered numerically in \cite{BBB1997}:
\[\zeta(\{1,{\bar 2}\}_l)=8^{-l}\zeta(\{3\}_l)\quad (l \in\N_0)\]
is one such unramified alternating multiple zeta value.
In fact, cyclotomic multiple zeta values are a special case of multiple polylogarithm function with $r$-variables. The \emph{multiple polylogarithm function with $r$-variables} refer to the case where all $x_j$ in \eqref{defn-CMZV} are treated as continuous variables and satisfy the condition $|x_j\cdots x_r|\leq 1$ with $(k_r,x_r)\neq (1,1)$. It can be analytically continued to a multi-valued meromorphic function on $\mathbb{C}^r$ (see \cite{Zhao2007d}). In particular, if $a_1=a_2=\cdots=a_r=a$ in \eqref{defn-CMHZV}, we adopt the notation (We refer to these as cyclotomic multiple Hurwitz zeta values with $r$-variables and single parameter):
\begin{align}\label{defn-CMHZV-single}
\Li_{\overrightarrow{\bfk}_{1,r}}\left(\overrightarrow{\bfx}_{1,r};a+1\right)&\equiv \Li_{k_1,\ldots,k_r}(x_1,\ldots,x_r;\{a+1\}_r)\nonumber\\&=\sum_{0<n_1<\cdots<n_r} \displaystyle\!frac{x_1^{n_1}\cdots x_r^{n_r}}{(n_1+a)^{k_1}\cdots (n_r+a)^{k_r}}.
\end{align}
Recently, Rui \cite{Rui2026} proposed the following symmetry conjecture concerning cyclotomic multiple Hurwitz zeta values with $r$-variables and single parameter:

Flajolet and Salvy \cite{Flajolet-Salvy} introduced a kernel function $\xi(s)$ satisfying two key properties:
(1) $\xi(s)$ is meromorphic on the whole complex plane.
(2) Over an infinite sequence of circles $|s| = \rho_k$ with $\rho_k \to \infty$, the growth condition $\xi(s) = o(s)$ holds.
Using these properties of the kernel function, Flajolet and Salvy established the following residue lemma.
\begin{lem}\emph{(cf.\ \cite{Flajolet-Salvy})}\label{lem-redisue-thm}
Let $\xi(s)$ be a kernel function and let $r(s)$ be a rational function which is $O(s^{-2})$ at infinity. Then
\begin{align}\label{residue-}
\sum\limits_{\alpha \in O} {{\mathop{\rm Res}}{{\left( {r(s)\xi(s)},\alpha \right)}}} + \sum\limits_{\beta \in S} {{\mathop{\rm Res}}{{\left( {r(s)\xi(s)}, \beta \right)}}} = 0,
\end{align}
where $S$ is the set of poles of $r(s)$ and $O$ is the set of poles of $\xi(s)$ that are not poles $r(s)$. Here ${\mathop{\rm Re}\nolimits} s{\left( {r(s)},\alpha \right)} $ denotes the residue of $r(s)$ at $s= \alpha.$
\end{lem}
Notably, Lemma \ref{lem-redisue-thm} also holds under the weaker condition $r(s)\xi(s)=o(s^{-1})$. It is straightforward to show that the contour integrals corresponding to \eqref{contour-integral-one} and \eqref{contour-integral-two} must equal zero. Therefore, by the residue theorem, the sum of the residues of the integrand at all its poles in the complex plane must also equal zero. To compute these residues, it is necessary to determine the order of each pole. For this purpose, we need to clarify the Laurent expansion of the integrand at its poles. To better describe these expansions, we need to provide the following definitions: for $\overrightarrow{\bfk}_{1,r}=(k_1,\ldots,k_r)\in\N^r$, positive integer $n$, and $\bfx=(x_1,\ldots,x_r)\in \mathbb{C}^r$, we define the \emph{multiple harmonic sums} with $r$-variables by
\begin{align}
\zeta_n\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfx}_{1,r}\right)\equiv \zeta_n(k_1,\ldots,k_r;x_1,\ldots,x_r):=\sum\limits_{0<n_1<\cdots<n_r\leqslant n } \frac{x_1^{n_1}\cdots x_r^{n_r}}{n_1^{k_1}\cdots n_r^{k_r}}\label{MHSsr}.
\end{align}
If $n<r$ then $\zeta_n\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfx}_{1,r}\right):=0$ and ${\zeta _n}(\emptyset;\emptyset ):=1$. Furthermore, we can similarly define the Hurwitz-type generalization of the aforementioned multiple harmonic sums with $r$-variables as follows:
\begin{align}
\zeta_n\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfx}_{1,r};\overrightarrow{\bfa}_{1,r}\right)&\equiv \zeta_n(k_1,\ldots,k_r;x_1,\ldots,x_r;a_1,\ldots,a_r)\nonumber\\
&:=\sum\limits_{0<n_1<\cdots<n_r\leqslant n } \frac{x_1^{n_1}\cdots x_r^{n_r}}{(n_1+a_1)^{k_1}\cdots (n_r+a_r)^{k_r}}\label{MHtHSsr},
\end{align}
where $\overrightarrow{\bfa}_{1,r}=(a_1,\ldots,a_r)$ and $a_j\in \mathbb{C}\setminus \N^-\ (j=1,2,\ldots,r)$. Obviously, according to the definitions of \eqref{defn-CMHZV}, \eqref{defn-CMZV}, \eqref{MHSsr}, and \eqref{MHtHSsr}, when all $x_j$ are roots of unity and $(k_r, x_r) \neq (1, 1)$, letting $n$ approach infinity yield the limits as
\begin{align}
\lim_{n\rightarrow \infty} \zeta_n\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfx}_{1,r}\right)=\Li_{\overrightarrow{\bfk}_{1,r}}\left(\overrightarrow{\bfx}_{1,r}\right)
\end{align}
and
\begin{align}
\lim_{n\rightarrow \infty} \zeta_n\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfx}_{1,r};\overrightarrow{\bfa}_{1,r}\right)=\Li_{\overrightarrow{\bfk}_{1,r}}\left(\overrightarrow{\bfx}_{1,r};\overrightarrow{(1+\bfa)}_{1,r}\right).
\end{align}

\begin{lem}(\cite[Eq. (5.4)]{LiXu2026})\label{lem-Laurent-expansion-mhpolyf} Let $n\in \N$. For $(k_1,\ldots,k_r)\in\N^r$ and roots of unity $x_1,\ldots,x_r$ with $(k_r,x_r)\neq(1,1)$, if $|s+n|<1$, we have
\begin{align}\label{Laurent-expansion-mhpolyf}
&\Li_{k_1,\ldots,k_r}(x_1,\ldots,x_r;1+s)\nonumber\\
&=\sum_{j=0}^r \sum_{m=0}^\infty \sum_{|\overrightarrow{\bfn}_{1,r}|=m,\atop \forall n_l\geq 0}A_j\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfn}_{1,r}\right) (x_1\cdots x_r)^n\zeta_{n-1}\left(\overleftarrow{(\bfk+\bfn)}_{1,j};\overleftarrow{\bfx}_{1,j}^{-1}\right)\nonumber\\&\qquad\qquad\qquad\qquad\qquad\qquad\times\Li_{\overrightarrow{(\bfk+\bfn)}_{j+1,r}}\left(\overrightarrow{\bfx}_{j+1,r}\right)(s+n)^m
\nonumber\\
&\quad+\sum_{j=1}^r\sum_{m=0}^\infty \sum_{|\bfn_r|-n_j=m,\atop \forall n_l\geq 0} \widetilde{A}_j\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfn}_{1,r}\right) (x_1\cdots x_r)^n
\zeta_{n-1}\left(\overleftarrow{(\bfk+\bfn)}_{1,j-1};\overleftarrow{\bfx}_{1,j-1}^{-1}\right)\nonumber\\&\qquad\qquad\qquad\qquad\qquad\qquad\times
\Li_{\overrightarrow{(\bfk+\bfn)}_{j+1,r}}\left(\overrightarrow{\bfx}_{j+1,r}\right)(s+n)^{m-k_j},
\end{align}
where
\begin{align}
&A_j\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfn}_{1,r}\right):=(-1)^{|\overrightarrow{\bfk}_{1,j}|+|\overrightarrow{\bfn}_{j+1,r}|}\prod\limits_{l=1}^r \binom{n_l+k_l-1}{k_l-1} ,\\
&\widetilde{A}_j\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfn}_{1,r}\right):=(-1)^{|\overrightarrow{\bfk}_{1,j-1}|+|\overrightarrow{\bfn}_{j+1,r}|} \left(\prod\limits_{l=1,\atop l\neq j}^r \binom{n_l+k_l-1}{k_l-1} \right).
\end{align}
\end{lem}
In fact, the analytic part in \eqref{Laurent-expansion-mhpolyf} is redundant, as it will equal zero in the subsequent residue computation.
Through calculations similar to the proofs of \cite[Thms. 2.2 and 2.3]{LiXu2026}, we can obtain the following Taylor or Laurent expansions of the cyclotomic multiple Hurwitz zeta values:

\begin{lem}\label{lem-Talyor-expansion-CMHZ-single-a} Let $a,a_1,\ldots,a_r\in \mathbb{C}\setminus \N^-$ and $a_j-a\notin \N^-$ for any $j=1,2,\ldots,r$. For $(k_1,\ldots,k_r)\in\N^r$ and roots of unity $x_1,\ldots,x_r$ with $(k_r,x_r)\neq(1,1)$, if $|s+a|<1$, we have
\begin{align}\label{Talyor-expansion-CMHZ-single-a}
&\Li_{k_1,\ldots,k_r}(x_1,\ldots,x_r;1+a_1+s,\ldots,1+a_r+s)\nonumber\\
&=\sum_{m=0}^\infty \sum_{|\overrightarrow{\bfm}_{1,r}|=m,\atop \forall\ m_l\geq 0} B_m\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfm}_{1,r}\right)\Li_{\overrightarrow{(\bfk+\bfm)}_{1,r}}\left(\overrightarrow{\bfx}_{1,r};\overrightarrow{(1+\bfa-a)}_{1,r}\right)(s+a)^m.
\end{align}
\end{lem}
\begin{proof}
By directly computing the transformation of the denominator $n_j + s + a_j$ in the definition \eqref{defn-CMHZV} of the cyclotomic multiple Hurwitz zeta function into $n_j + a_j - a + s + a$, we can deduce that
\begin{align*}
&\Li_{k_1,\ldots,k_r}(x_1,\ldots,x_r;1+a_1+s,\ldots,1+a_r+s)\\
&=\sum_{0<n_1<\cdots<n_r} \frac{x_1^{n_1}\cdots x_r^{n_r}}{(n_1+a_1-a+s+a)^{k_1}\cdots (n_r+a_r-a+s+a)^{k_r}}\\
&=\sum_{0<n_1<\cdots<n_r} \frac{x_1^{n_1}\cdots x_r^{n_r}}{(n_1+a_1-a)^{k_1}\cdots (n_r+a_r-a)^{k_r}}\frac{1}{\left(1+\frac{s+a}{n_1+a_1-a}\right)^{k_1}\cdots \left(1+\frac{s+a}{n_r+a_r-a}\right)^{k_r}}\\
&=\sum_{0<n_1<\cdots<n_r} \frac{x_1^{n_1}\cdots x_r^{n_r}}{(n_1+a_1-a)^{k_1}\cdots (n_r+a_r-a)^{k_r}}\prod_{l=1}^r \left(\sum_{m_l=0}^\infty \binom{m_l+k_l-1}{k_l-1} \left(-\frac{s+a}{n_l+a_l-a}\right)^{m_l}\right)\\
&=\sum_{m_1,\ldots,m_r=0}^\infty \left(\prod_{l=1}^r (-1)^{m_l}\binom{m_l+k_l-1}{k_l-1}\right) \sum_{0<n_1<\cdots<n_r} \frac{x_1^{n_1}\cdots x_r^{n_r}(s+a)^{m_1+\cdots+m_r}}{(n_1+a_1-a)^{k_1+m_1}\cdots (n_r+a_r-a)^{k_r+m_r}}\\
&=\sum_{m=0}^\infty \sum_{|\overrightarrow{\bfm}_{1,r}|=m,\atop \forall\ m_l\geq 0} B_m\left(\overrightarrow{\bfk}_{1,r};\overrightarrow{\bfm}_{1,r}\right)\Li_{\overrightarrow{(\bfk+\bfm)}_{1,r}}\left(\overrightarrow{\bfx}_{1,r};\overrightarrow{(1+\bfa-a)}_{1,r}\right)(s+a)^m.
\end{align*}
This completes the proof of Lemma \ref{lem-Talyor-expansion-CMHZ-single-a}.
\end{proof}

