\begin{theorem}\emph{(Wielandt, \cite[Theorem 29.2]{neumann2023infinitepermutationgroups})}
\label{thm:wielandt}
    Let $S$ be an infinite set and $G$ be a primitive group acting on $S$. If $G$ contains a non-identity permutation with finite support, then $\alt(S)\leq G$.
\end{theorem}

ref_dict.prop:imprimitive-equiv-decomposition:
\begin{proposition} \emph{\cite[Theorem 27]{Burda2012Topological}}
\label{prop:imprimitive-equiv-decomposition}
    Let $X \subseteq \mathbb{C}$ be an open connected set and $f:X\to\mathbb{C}$ be a meromorphic map with monodromy group $G$. Then $G$ is imprimitive if and only if $f$ can be expressed as a composition $(h\circ g)(x)$ of two meromorphic functions $g:X\to Y$ and $h:Y\to\mathbb{C}$ for some open connected set $Y\subseteq\mathbb{C}$. Moreover, the monodromy groups of $g$ and $h$ are quotients of $G$.
\end{proposition}

full_context:
Pondering on this question, Abel laid the foundations of the theory of algebraic curves, while Galois was the first to notice that solvability by radicals is dependent on an associated group, now called the Galois group of an algebraic equation. Liouville continued Abel's work on algebraic and differential forms and made significant improvements regarding expressibility by elementary functions, that is, compositions of arithmetic operations, the exponential function $\exp$ and the logarithmic function $\ln$. He rigorously proved the unsolvability in elementary functions of some differential equations \cite{Khovanskii2014}, e.g. $f'(x) = e^{-x^2}$. Later work by Chebyshev, Ritt, Risch, Rosenlicht, and others extended this aspect of Galois theory further.

Arnold discovered topological reasons for the unsolvability of equations -- for instance, see his proof for the quintic \cite{GoldmakherArnoldQuintic}. His student Khovanskii \cite{khovanskii2019dimensionaltopologicalgaloistheory,Khovanskii2014} formalized the methods of the one-dimensional version of topological Galois theory around 1970. The fundamental concepts of topological Galois theory are similar to classical Galois theory, but are suitable for analyzing transcendental functions -- the former one works with extensions of the rational numbers $\mathbb{Q}$, while the latter one is with extensions of the field of rational functions $\mathbb{C}(x)$. The topological criterion for solvability is also based on a group defined through $f$, known as the monodromy group.

Consider the equation $f(x)=a$, where $f:X\to\mathbb{C}$ is a meromorphic elementary function defined on a connected open set $X\subseteq\mathbb{C}$, and $a\in\mathbb{C}$ is a parameter. We aim to determine when the inverse $f^{-1}(a)$ is also an elementary function. All approaches so far rely on analyzing the specific monodromy group and the structure of the roots, hence results up to now have been on individual equations, such as $\tan(x)-x=a$ \cite{Belov_Kanel_2020}, $e^x + x = a$ and $x^x=a$ \cite{kanelbelov2024insolvabilityxxa} by Kanel-Belov, Malistov, Zaytsev.

Other recent developments are by Zelenko \cite{zelenko2021genericmonodromygroupriemann}, proving unsolvability in quadratures, i.e. elementary functions, integration, differentiation and taking the solutions of an algebraic equation, when $f$ is holomorphic, surjective, no two critical points share the same critical value, and for some positive integer $\rho$ \[\lim_{R\to\infty}\sup_{z:|z|\geq R}\frac{\ln|f(z)|}{|z|^\rho}\] is bounded.

\smallskip

We extend the unsolvability to all elementary meromorphic functions for which the set of critical values
 \[B=\{a\in\mathbb{C}:\ \exists x\in X:f(x)=a,f'(x)=0\}\]
is infinite.

\begin{abstract} 
 An equation $f(x)=a$, where $f$ is a complex meromorphic function and $a\in\mathbb{C}$ is a parameter, is solvable in elementary functions if the inverse map $x=f^{-1}(a)$ can be expressed as a finite composition of arithmetic operations (addition, subtraction, multiplication, and division), the exponential function, the complex logarithm, and constants. Specific functions such as $\tan x - x$, $\exp x + x$, $x^x$ have been proven to be unsolvable by Kanel-Belov, Malistov, Zaytsev, while almost all entire surjective functions of at most exponential growth have been covered by Zelenko. All these rely on one-dimensional topological Galois theory, developed by Khovanskii. We generalize to provide a proof for the unsolvability of all elementary meromorphic functions $f$ such that the derivative of $f$ has infinitely many roots $x_i$ and the set of distinct values $f(x_i)$ is infinite.
\end{abstract}

Consider the equation $f(x)=a$, where $f:X\to\mathbb{C}$ is a meromorphic elementary function defined on a connected open set $X\subseteq\mathbb{C}$, and $a\in\mathbb{C}$ is a parameter. We aim to determine when the inverse $f^{-1}(a)$ is also an elementary function. All approaches so far rely on analyzing the specific monodromy group and the structure of the roots, hence results up to now have been on individual equations, such as $\tan(x)-x=a$ \cite{Belov_Kanel_2020}, $e^x + x = a$ and $x^x=a$ \cite{kanelbelov2024insolvabilityxxa} by Kanel-Belov, Malistov, Zaytsev.

We extend the unsolvability to all elementary meromorphic functions for which the set of critical values
 \[B=\{a\in\mathbb{C}:\ \exists x\in X:f(x)=a,f'(x)=0\}\]
is infinite.

The provided proof combines a result of Wielandt on primitive group actions on infinite sets (Theorem \ref{thm:wielandt}), and a relation between primitivity and decompositions (Theorem \ref{prop:imprimitive-equiv-decomposition}) stated, for example, in the doctoral work of Burda on algebraic functions.

\section{\Large Topological unsolvability in elementary functions}
Consider the equation $f(x)=a$, where $f:X\to\mathbb{C}$ is a meromorphic non-constant function defined on a connected open set $X\subseteq\mathbb{C}$, and $a\in\mathbb{C}$ is a parameter. By Theorem~\ref{theorem:identity-theorem} for any $a$ the set of roots is discrete, hence the inverse $f^{-1}$ is an $\mathscr{S}$-function.

\begin{proposition}
\label{prop:wielandt-corollary}
 Let $X \subseteq \mathbb{C}$ be an open connected set and $f:X\to\mathbb{C}$ be a meromorphic map with infinite monodromy group $G$. Suppose $G$ is primitive. Then $G$ contains an unsolvable subgroup, and $f(x)=a$ is unsolvable in elementary functions.
\end{proposition}

\begin{theorem}
\label{thm:unsolvability-infinite-branch-locus}
 Let $X \subseteq \mathbb{C}$ be an open connected set and $f:X\to\mathbb{C}$ be an elementary meromorphic function with an infinite branch locus and infinite monodromy group $G$. Then the equation $f(x)=a$ is unsolvable in elementary functions.
\end{theorem}

\begin{conjecture}
\label{conj:any-solvable-tower-core}
 Let $X\subseteq\mathbb{C}$ be a connected open set and $f: X \to \mathbb{C}$ be a meromorphic elementary function. If the equation $f(x)=a$ is solvable in elementary functions, then there exists a finite sequence $g_1,g_2,\ldots,g_\ell$ of solvable functions of depth at most $1$, such that $f(x)=(g_1\circ g_2\circ\ldots\circ g_\ell)(x)\text{.}$
\end{conjecture}

\begin{proposition} \emph{\cite[Theorem 27]{Burda2012Topological}}
\label{prop:imprimitive-equiv-decomposition}
    Let $X \subseteq \mathbb{C}$ be an open connected set and $f:X\to\mathbb{C}$ be a meromorphic map with monodromy group $G$. Then $G$ is imprimitive if and only if $f$ can be expressed as a composition $(h\circ g)(x)$ of two meromorphic functions $g:X\to Y$ and $h:Y\to\mathbb{C}$ for some open connected set $Y\subseteq\mathbb{C}$. Moreover, the monodromy groups of $g$ and $h$ are quotients of $G$.
\end{proposition}

\begin{theorem}\emph{(Wielandt, \cite[Theorem 29.2]{neumann2023infinitepermutationgroups})}
\label{thm:wielandt}
    Let $S$ be an infinite set and $G$ be a primitive group acting on $S$. If $G$ contains a non-identity permutation with finite support, then $\alt(S)\leq G$.
\end{theorem}

