\begin{proof}[\textbf{Proof of Theorem \ref{th3}}]
 We prove the theorem only for the case $m_1=m_2$, since the other case is similar.
If $m_1=m_2$, using from Lemmas~\ref{lm2.2}-\ref{lm2.5}, Propositions~\ref{pro2.6} and \ref{propB.1} imply that
\begin{eqnarray*}
F(r)
&=&
I(S_{\epsilon,k},T_{\epsilon,k})+\ell(\varphi_{k},\psi_{k})+\frac{1}{2}\langle L(\varphi_{k},\psi_{k}),(\varphi_{k},\psi_{k})\rangle-R(\varphi_{k},\psi_{k})\nonumber\\
&=&
I(S_{\epsilon,k},T_{\epsilon,k})+O\big(\|\ell\|\|(\varphi_k,\psi_k)\|+\|(\varphi_k,\psi_k)\|^2\big)\nonumber\\
&=&
I(S_{\epsilon,k},T_{\epsilon,k})+O\big(\frac{1}{r^{m-1-\sigma}}\big)\nonumber\\
&=&A+k(\frac{a_1\gamma_12}{r^m}+\frac{a_2\gamma_2^2}{r^m})B-C_\beta\frac{k^2}{r}e^{-\frac{r\pi}{\epsilon k}}+O(ke^{-\frac{\pi r}{\epsilon k}}).
\end{eqnarray*}
Consider the following maximization problem
\begin{equation}\label{e2.8}
\max\limits_{r\in D_k}F(r).
\end{equation}
Assume that \eqref{e2.8} is achieved by some $r^{*}$ in $D_k.$ We will prove that $r^{*}$ is an interior point of
$D_k$.
Note that $C_\beta>0$.
Define
\begin{align*}
g(t)=\frac{aB}{r^m}-C_\beta\frac{k}{r}e^{-\frac{2\pi r}{\epsilon k}}=\frac{aB}{t^mk^m}-C_\beta\frac{e^{-2\pi t}}{t}.
\end{align*}
Then
\begin{align*}
g'(t)=-\frac{aB}{t^{m+1}k^m}+\frac{2\pi C_\beta e^{-2\pi t}}{t}+\frac{C_\beta e^{-2\pi t}}{t^2}.
\end{align*}
It is easy to check that $g(t)$ has a maximum point of $t_k$ with
\begin{align*}
t_k=\big(\frac{m}{2\pi}+o(1)\big)\ln k.
\end{align*}
So the function $F(r)$ has a maximum point of
$$r=kt_k=\big(\frac{m}{2\pi}+o(1)\big)k\ln k.$$
Hence, it follows from the expression of $F(r)$ that the maximizer of $r_k$ is an interior point of $D_k$. We can use the same argument as \cite{PW13} to show the solutions are positive.
\end{proof}
\subsection{Dichotomy for Segregated solutions}
In this subsection, we construct dichotomous segregated peak-solutions of \eqref{eq0}.

\begin{lem}\label{lm4.2}
There exist $\varepsilon>0$ small enough and $\varrho>0$, such that for any $\beta<\varepsilon, (r,\rho)\in D_k\times D_k$, there holds
$$
\bar{L}(\varphi_{k},\psi_{k})\geq \varrho\|(\varphi_{k},\psi_{k})\|,\ \ (\varphi_{k},\psi_{k})\in \bar{E}_k.
$$
\end{lem}
\begin{proof}
We argue by contradiction. Assume that there exist $k\rightarrow+\infty$, $(\varphi_k,\psi_k)\in \bar{E}_k$ satisfying $\|\bar{L}(\varphi_k,\psi_k)\|=o(1)\|(\varphi_k,\psi_k)\|^2$.
Without loss of generality, we may assume $\|(\varphi_k,\psi_k)\|^2=k$, we have
\begin{align*}
\langle \bar{L}(\varphi_k,\psi_k),(g,h)\rangle=o(1)\|(\varphi_k,\psi_k)\|\|(g,h)\|.
\end{align*}
Taking $(g,h)=(\varphi_k,\psi_k)$, we have
\begin{align*}
o(k)=&\int_{\R^3}\epsilon^2|\nabla\varphi_k|^2+P(x)\varphi_k^2-3\mu_1\bar{S}_{\epsilon, k}^2\varphi_k^2+\int_{\R^3}\epsilon^2|\nabla\psi_k|^2+Q(x)\psi_k^2-3\mu_2\bar{T}_{\epsilon, k}^2\psi_k^2\cr
&-\beta\int_{\R^3}(\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon, k}^2\varphi_k^2+4\bar{S}_{\epsilon, k}\bar{T}_{\epsilon, k}\varphi_k\psi_k).
\end{align*}
For any fixed $R>0$, there is large enough $k>0$ such that $B_R(x_1)\subset\Omega_1$. Set
\begin{align*}
\tilde{\varphi}_k=\varphi_k(x+x^1),\,\,\,\tilde{\psi}_k=\psi_k(x+y^1).
\end{align*}
We have
\begin{align*}
\int_{B_R(0)}\epsilon^2|\nabla \tilde{\varphi}_k|^2+P(x)\tilde{\varphi}_k^2+\epsilon^2|\nabla\tilde{\psi}_k|^2+Q(x)\tilde{\psi}_k^2\leq1.
\end{align*}
Up to a subsequence, we may assume there exist $(\varphi,\psi)\in H^1(\R^3)\times H^1(\R^3)$ such that
\begin{align}\label{eq1.1}
&(\tilde{\varphi}_k,\tilde{\psi}_k)\rightharpoonup(\varphi,\psi)\,\,\, \hbox{weakly in }\, H_{loc}^1(\R^3)\times H_{loc}^1(\R^3),\cr
&(\tilde{\varphi}_k,\tilde{\psi}_k)\rightarrow(\varphi,\psi)\,\,\,\hbox{strongly in}\,L_{loc}^q(\R^3)\times L_{loc}^q(\R^3),q\in[2,6).
\end{align}

Moreover, in view of the non-degeneracy of $U_\epsilon$, it holds $\varphi=0$.
By \eqref{eq1.1}, we see
\begin{align*}
o(1)=\int_{B_R(0)}\tilde{\varphi}_k^qdx=\int_{B_R(x^1)}\varphi_k^qdx.
\end{align*}
Using the same argument on $\tilde{\Omega}$, we can prove that as $k\rightarrow+\infty$,
\begin{align}\label{3.3}
\tilde{\psi}_k\rightarrow0,\,\,\hbox{weakly in }\, H_{loc}^1(\R^3),\,\,\,\tilde{\psi}_k\rightarrow0,\,\,\,\hbox{strongly in} \,L_{loc}^2(\R^3).
\end{align}
As a result, it holds
\begin{align*}
\int_{B_R(x^1)}\varphi^2=o(1),\,\,\,\,\,\,\int_{B_R(y^1)}\psi^2=o(1), \forall\,\,\,R>0.
\end{align*}
Similar as Lemma \ref{lm2.2}, we get
\begin{align*}
\Big(\int_{B_R(0)}\varphi_k^qdx\Big)^{\frac{1}{q}}=o(\sqrt{k}).
\end{align*}
Then we find
\begin{align}\label{eqs33}
o(k)=&\int_{\R^3}\epsilon^2|\nabla\varphi_k|^2+P(x)\varphi_k^2-3\mu_1\bar{S}_{\epsilon, k}^2\varphi_k^2+\int_{\R^3}\epsilon^2|\nabla\psi_k|^2+Q(x)\psi_k^2-3\mu_2\bar{T}_{\epsilon, k}^2\psi_k^2\cr
&-\beta\int_{\R^3}(\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon, k}^2\varphi_k^2+4\bar{S}_{\epsilon, k}\bar{T}_{\epsilon, k}\varphi_k\psi_k)\cr
=&k-3\mu_1\int_{\R^3}(u_{\epsilon, k}^2+U_{\epsilon,r}^2)\varphi_k^2-3\mu_2\int_{\R^3}(v_{\epsilon, k}^2+W_{\epsilon, \rho}^2)\psi_k^2-\beta\int_{\R^3}\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon ,k}^2\varphi_k^2\cr
\geq&k-(o(1)+O(e^{-\frac{R}{\epsilon}}))k-\beta\int_{\R^3}(\bar{S}_{\epsilon, k}^2\psi_k^2+\bar{T}_{\epsilon, k}^2\varphi_k^2).
\end{align}
If we choose $\beta<\frac{1}{C}$ for constant $C$ large enough, then \eqref{eqs33} is impossible for large $R$ and $k$. Consequently, we complete the proof.
\end{proof}
\begin{lem}\label{lm2.4}
There exists a constant $C>0$, independent of $k$ such that
$$
\bar{R}^{(i)}(\varphi,\psi,\xi)\leq C\|(\varphi,\psi,\xi)\|^{3-i},\ i=0,1,2.
