&\lesssim
\left(
\|\nabla n\|_{\tL_T^2(\dB_{p,1}^{\frac{d}{p}})}^{\ell,J_\varepsilon}
+ \|\nabla n\|_{\tL_T^2(\dB_{2,1}^{\frac{d}{2}})}^{h,J_\varepsilon}
\right)
\|\bv\|_{\tL_T^2(\dB_{2,1}^{\frac{d}{2}})}.
\end{split}
\end{equation*}
