The following is an explicit formula from \cite[Theorem 5.12]{IK}.
\begin{proposition} \label{prop: explicit}
 Let $\phi$ be an even Schwartz function whose Fourier transform is compactly supported.
 Under the generalized Riemann hypothesis for $L(f, s)$, 
 \begin{align*}
 \sum_{\rho} \phi \lbrb{ \gamma \frac{\log X}{2 \pi}}
 &= \widehat{\phi}(0) \frac{\log \ff(f)}{\log X}
 - \frac{1}{\log X} \sum_n \lbrb{\frac{\Lambda_n(f) + \Lambda_n(\overline{f}) }{\sqrt{n}}} \widehat{\phi}\lbrb{\frac{\log n}{\log X}}\\
 &+ \frac{1}{2 \pi} \int^{\infty}_{-\infty} \lbrb{\frac{\gamma'}{\gamma}\left(f, \frac{1}{2} + it\right) + \frac{\gamma'}{\gamma}\left(\overline{f}, \frac{1}{2} + it \right)} \phi\lbrb{\frac{t\log X}{2 \pi}} dt
 \end{align*}
 where $\rho = \frac{1}{2} + i\gamma$ is taken over non-trivial zeros of $L(f, s)$.
\end{proposition}

\begin{proposition}
Assume the generalized Riemann hypothesis for the family $\lcrc{C_d/\bQ : d \in S(X)}$. Let $\phi$ be a positive test function whose Fourier transform is compactly supported. Then,
\begin{align} \label{eqn: average rank bound}
 \frac{1}{|S(X)|} \sum_{d \in S(X)} g_d \leq (6+o(1))\frac{ \widehat{\phi}(0)}{\phi(0)} - \frac{1}{\phi(0)}S_1 - \frac{1}{\phi(0)}S_2 + O\lbrb{\frac{1}{\log X}}.
\end{align}
\end{proposition}
\begin{proof}
We note that $\gamma(f, s)$ is a product of an exponential function $\pi^{-\frac{ks}{2}}$ for some $k \in \bZ$ and the Gamma functions (cf. \cite[(5.3)]{IK}).
Therefore
\begin{align*}
 \frac{1}{2 \pi} \int^{\infty}_{-\infty} \lbrb{\frac{\gamma'}{\gamma}\left(f, \frac{1}{2} + it\right) + \frac{\gamma'}{\gamma}\left(\overline{f}, \frac{1}{2} + it\right)} \phi\lbrb{\frac{t\log X}{2 \pi}} dt \ll \frac{\log \log X}{\log X}.
\end{align*}
On the other hand, the Weil bound for genus $2$ curves gives that $|\Lambda_{p^k}(C_d)| \leq 4\log p$, which gives
\begin{align*}
 \frac{1}{\log X} \sum_{\substack{n = p^k \\ k \geq 3}} \lbrb{\frac{\Lambda_n(C_d) + \overline{\Lambda_n(C_d)} }{\sqrt{n}}} \widehat{\phi}\lbrb{\frac{\log n}{\log X}} \ll \frac{1}{\log X}.
\end{align*}

\begin{lemma}
Let $E_0 : y^2 = x^3+1$ and let $E$ an elliptic curve not isogenous to $E_0$.
Let $\widehat{\phi}$ be an even continuous function supported in $[-\sigma, \sigma]$ whose Fourier transform is $\phi$.
Then we have
\begin{align}
 \frac{1}{\log X}\sum_{p } \frac{\log p }{p^2} \widehat{\phi}\lbrb{\frac{\log p}{ \log X}} a_p(E_0) a_p(E)&= O\lbrb{\frac{1}{\log X}}, \label{eqn: ap weight E0E1} \\
 \frac{1}{\log X}\sum_{p \equiv 1 \, (3)} \frac{\log p}{p^2} \widehat{\phi} \lbrb{\frac{2 \log p }{\log X}} (a_p(E_0)^2 - 2 p) &= O\lbrb{\frac{1}{\log X}}. \label{eqn: ap^2 weight E0-2p} 
\end{align}
\end{lemma}
\begin{proof}
Since $E_0$ and $E$ are not isogenous, we can use the prime number theorem for Rankin--Selberg $L$-function.
Namely, we have
\begin{align*}
A(t) := 
 \sum_{n \leq t} \Lambda(n)\lambda_n(E_0) \lambda_n(E_1) = O\lbrb{t \exp(-c\sqrt{\log t})}.
\end{align*}
Then, the Abel summation formula gives
\begin{align*}
 \sum_{p \leq X} \frac{\log p}{p^2} a_p(E_0)a_p(E_1)w(p) 
 = \sum_{n \leq X} \Lambda(n) \lambda_p(E_0) \lambda_p(E_1) \frac{w(n)}{n}
 = \frac{A(X)w(X)}{X} + \int^X_2 A(t) d\frac{w(t)}{t} .
\end{align*}
If we choose $\widehat{\phi}(t)$ as $w(t)$, the first term is bounded by $O(\exp(-c \sqrt{\log X}))$ and 
\begin{align*}
 \int^X_2 A(t) d \frac{w(t)}{t} \ll \int^X_2 \frac{\exp(-c \sqrt{\log t})}{t} dt \ll 1.
\end{align*}
Hence, we yield the first asymptotic.

\begin{lemma}
Let $C_1 : y^2 = 24x^5 - 42x^3 + 18x$ and $E_0 : y^2 = x^3 + 1$. Let $\widehat{\phi}$ be an even continuous function supported in $[-\sigma, \sigma]$ whose Fourier transform is $\phi$. Then,
\begin{align}
 \frac{1}{\log X}\sum_{p } \frac{\log p }{p^2} \widehat{\phi}\lbrb{\frac{\log p}{ \log X}} a_p(E_0) a_p(C_1) &= O\lbrb{\frac{1}{\log X}}. \label{eqn: ap weight E0C1}
\end{align}
\end{lemma}
\begin{proof}
The defining equation of $C_1$ can be rewritten as follows:
\begin{align*}
 y^2=24x^5-42x^3+18x=6x(4x^2-3)(x^2-1).
\end{align*}
For simplicity, we denote $a:=\frac{\sqrt{3}}{2}$ which is a root of $4x^2-3$. The curve $C_1$ admits the following automorphisms, which are defined over $\mathbb{Q}(i,\sqrt{2},\sqrt[4]{3})$:
\begin{align*}
 \tau(x,y):=(-x,iy),\qquad\rho(x,y):=\left(\frac{a}{x},\frac{a^{\frac{3}{2}}y}{x^3}\right).
\end{align*}
We note that $\rho$ and $\sigma:=\tau\circ\rho$ are involutions on $C_1$. Consider the quotient maps:
\begin{align*}
 \xymatrix{\pi_\rho:C_1 \ar[r] & E_\rho:=C_1/\langle\rho\rangle & \pi_\sigma:C_1 \ar[r] & E_\sigma:=C_1/\langle\sigma\rangle\rlap{\ .}}
\end{align*}
Applying the Riemann--Hurwitz to $\pi_\rho$, we get
\begin{align*}
 2g(C_1)-2=2(2g(E_\rho)-2)+\#\{\textrm{fixed points of $\rho$}\}.
\end{align*}
Since $\rho$ has exactly two fixed points $(\sqrt{a},\pm y_\sigma)$, it follows that $g(E_\rho)=1$. Similarly, $g(E_\sigma)=1$ because $\sigma$ has two fixed points. Consequently, $E_\rho$ and $E_\sigma$ are elliptic curves, and hence $\pi_\rho$ and $\pi_\sigma$ induce a natural map $(\pi_{\rho\ast},\pi_{\sigma\ast}):J(C_1)\rightarrow E_\rho\times E_\sigma$. One can show that $\pi_\rho^\ast\omega_{E_\rho}$ and $\pi_\sigma^\ast\omega_{E_\sigma}$ are linearly independent and hence $J(C_1)$ is isogenous to $E_\rho\times E_\sigma$ over $\mathbb{Q}(i,\sqrt{2},\sqrt[4]{3})$.

\begin{proposition} \label{prop: S1}
Suppose that $\mathrm{supp}(\widehat{\phi}) \subset [-\sigma, \sigma]$ for $\sigma > 0$.
Then,
\begin{align*}
 S_1 \ll \frac{X^{\frac{3\sigma}{2} - \frac{1}{2}}}{\log X}.
\end{align*}
\end{proposition}
\begin{proof} 
We recall that
\begin{align*}
 S_1= \frac{2}{|S(X)|\log X} 
 \sum_p \widehat{\phi}\lbrb{\frac{\log p}{\log X}} \frac{\log p}{\sqrt{p}}
