\begin{prop}\label{prop:gamma=gamma_crit}
 We assume the same set-up as in Theorem \ref{thm:CoveringGenerald}. For $d=2$ and $\gamma=\gamma_{\mathrm{crit}}$ it holds
 $\displaystyle\mathbb{P}[\limsup_{n\to\infty} \mathcal{S}^\circ(u_n, \varphi(r_n)) = \mathbb{S}^{1}] = 1$. Thus, the visibility set $Z_{\gamma_\mathrm{crit},\lambda,2}$ in \eqref{eq:DefVisibilitySet} is almost surely bounded.
 \end{prop}
 \begin{proof}
 As before, let $0<r_1<r_2<\dots$ be such that they form an inhomogeneous Poisson point process on $(0,1)$ with intensity function $f$ defined in \eqref{eq:intensity_r}. Then, in the Poincar\'e disc model a $\lambda$-geodesic hyperplane $H(r_n,u)$ of distance $r_n$ to $o$ in direction $u\in\mathbb{S}^1$ covers an arc of length $2\arccos(\varphi(r_n))$ for $n\in\mathbb{N}$ (see Figure \ref{fig: configuration_caps}). Now, by \cite[Equation (1)]{Shepp}, Proposition \ref{prop:gamma=gamma_crit} follows once we have shown that
 $$\sum_{n=1}^{\infty}\frac{1}{n^2}e^{\ell_1+\ldots+\ell_n}=\infty,$$
 where $2\pi\ell_i$ is the arc length covered by $r_i$, i.e.\ $\ell_i=\frac{1}{\pi}\arccos(\varphi(r_i))$ for $i\in\mathbb{N}$. Combining \eqref{eq: 1-phi(rn)_asymptotics}, $\gamma_{\mathrm{crit}}=\pi$ and the refined $d=2$ asymptotics from Lemma~\ref{lemma:asymptotics_rn} we can sharpen the estimate for the arc lengths $\ell_i$.
 Indeed, for $d=2$ and $\gamma=\gamma_{\mathrm{crit}}=\pi$, Lemma~\ref{lemma:asymptotics_rn} yields almost surely
 \begin{equation*}
 1-r_i=\frac{\pi(1+\lambda)}{i} +O\left(\sqrt{\frac{\log\log(i)}{i^3}}\right),\qquad i\to\infty.
 \end{equation*}
 Together with Lemma~\ref{lemma:asymptotics_varphi} this implies almost surely
 \begin{equation*}
 \delta_i:=1-\varphi(r_i)
 =\frac{(1-r_i)^2}{2(1+\lambda)^2}+O\big((1-r_i)^3\big)
 =\frac{\pi^2}{2i^2}+O\left(\sqrt{\frac{\log\log(i)}{i^5}}\right),
 \qquad i\to\infty.
 \end{equation*}
 Using the Taylor expansions $\arccos(1-x)=\sqrt{2x}+O(x^{3/2})$ as $x\downarrow 0$ and $\sqrt{1+x}=1+\frac{x}{2}+O(x^2)$ as $x\downarrow 0$, we obtain almost surely
 \[
 \arccos(\varphi(r_i))
 =\arccos(1-\delta_i)
 =\sqrt{2\delta_i}+O(\delta_i^{3/2})
 =\frac{\pi}{i}+O\left(\sqrt{\frac{\log\log(i)}{i^3}}\right),
 \qquad i\to\infty.
 \]
 Consequently,
 \begin{equation*}
 \ell_i=\frac{1}{\pi}\arccos(\varphi(r_i))
 =\frac{1}{i}+O\left(\sqrt{\frac{\log\log(i)}{i^3}}\right),
 \qquad i\to\infty,
 \end{equation*}
 almost surely. Hence, as $\sum_{k=1}^\infty \sqrt{\frac{\log\log(k)}{k^3}}<\infty,$ this
 implies that there exists $c\in\mathbb{R}$ such that
 \[
 \sum_{k=1}^{n}\ell_k
 \ge \sum_{k=1}^{n}\frac{1}{k}+c
 \ge \ln(n)+c,
 \]
 where we used $\sum_{k=1}^n \frac1k \ge \ln(n)$.
 Thus,
 \begin{align*}
 \sum_{n=1}^{\infty}\frac{1}{n^2}e^{\ell_1+\ldots+\ell_n}
 &\ge \sum_{n=1}^{\infty}\frac{1}{n^2}e^{\ln(n)+c}
 = \sum_{n=1}^\infty \frac{e^{c}}{n}
 =\infty,
 \end{align*}
 which completes the proof.
 \end{proof}

\begin{proof}[Proof of Theorem \ref{thm:MainIntro} (b)]
 Fix $u\in\mathbb{S}^{d-1}$ and let $\ell(h)$ be a geodesic segment of length $h>0$ starting at $o$ in an arbitrary direction. Then by Corollary \ref{coro:mu(F_[o,l])} we have
 \begin{align*}
 \p(s_u(\eta_{\gamma,\lambda})>h)&=\p(\eta_{\gamma,\lambda}([\ell(h)]_\lambda)=0)
 =\exp\big({-\mu_{\gamma,\lambda}([\ell(h)]_\lambda)}\big)=\exp\Big({-\gamma\,\frac{\Gamma(\frac{d}{2})}{2\sqrt{\pi}\,\Gamma(\frac{d+1}{2})}\,h}\Big),
 \end{align*}
 independently of $\lambda$.
 Hence, the random variable $s_u(\eta_{\gamma,\lambda})$ is exponentially distributed with parameter $\gamma\,\frac{\Gamma(\frac{d}{2})}{2\sqrt{\pi}\,\Gamma(\frac{d+1}{2})}$ and by the polar decomposition of hyperbolic space we have
 \begin{align*}
 \mathbb{E}{\rm vol}_d(Z_{\gamma,\lambda,d})
 &={2\pi^{d/2}\over\Gamma({d\over 2})}\E\Bigg[\int_{\mathbb{S}^{d-1}}\int_0^{s_u(\eta_{\gamma,\lambda})}\sinh^{d-1}(s)\;\mathrm{d}s\sigma_d(\mathrm{d}u)\Bigg]\\
 &={2\pi^{d/2}\over\Gamma({d\over 2})}\int_{\mathbb{S}^{d-1}}\int_0^{\infty}\p(s_u(\eta_{\gamma,\lambda})\geq s)\sinh^{d-1}(s)\;\mathrm{d}s\sigma_d(\mathrm{d}u)\Bigg]\\
 &={2\pi^{d/2}\over\Gamma({d\over 2})}\int_0^\infty \exp\Big({-\gamma\,\frac{\Gamma(\frac{d}{2})}{2\sqrt{\pi}\,\Gamma(\frac{d+1}{2})}\,s}\Big)\sinh^{d-1}(s)\;\mathrm{d}s,
 \end{align*}
 where $\sigma_d$ denotes the normalized spherical Lebesgue measure on $\mathbb{S}^{d-1}$.
 According to Identity 3.541.1 in \cite{GradRysz} (see also \cite[Equation (6.9)]{BuehlerHugThaele}) it holds that
 \begin{equation}\label{eq:SinhExpIntegral}
 \int_0^\infty\sinh^{d-1}(s)e^{-as}\,\mathrm{d}s=\frac{(d-1)!}{2^d}\frac{\Gamma(\frac{a-d+1}{2})}{\Gamma(\frac{a+d+1}{2})},
 \end{equation}
 whenever $a>d-1$. Thus, the expected volume is finite if and only if $\gamma\,\frac{\Gamma(\frac{d}{2})}{2\sqrt{\pi}\,\Gamma(\frac{d+1}{2})}>d-1$ or $\gamma>\frac{2(d-1)\sqrt{\pi}\Gamma(\frac{d+1}{2})}{\Gamma(\frac{d}{2})}=(d-1)^2\sqrt{\pi}\frac{\Gamma(\frac{d-1}{2})}{\Gamma(\frac{d}{2})}=\gamma_{\mathrm{crit}}$ and, in this case,
 $$
 \mathbb{E}{\rm vol}_d(Z_{\gamma,\lambda,d})= \mathbb{E}{\rm vol}_d(Z_{\gamma,0,d}) = {2^{1-d}\pi^{d/2}(d-1)!\over \Gamma({d\over 2})}{\Gamma\big({\gamma_d^\ast-d+1\over 2}\big)\over\Gamma\big({\gamma_d^\ast+d+1\over 2}\big)}\quad\text{with}\quad \gamma_d^\ast := \gamma\,{\Gamma({d\over 2})\over2\sqrt{\pi}\Gamma({d+1\over 2})}.
 $$
 To arrive at the desired expression, we simplify the factor ${2^{1-d}\pi^{d/2}(d-1)!\over \Gamma({d\over 2})}$ using the Legendre duplication formula.
 It follows that
 \begin{align*}
 {2^{1-d}\pi^{d/2}(d-1)!\over \Gamma({d\over 2})}&=2^{1-d}\pi^{d/2}(d-1)! \frac{\Gamma(\frac{d+1}{2})}{2^{1-d}\sqrt{\pi}\Gamma(d)}= \pi^{\frac{d-1}{2}} \Gamma\left(\frac{d+1}{2}\right).
 \end{align*}
 Plugging this into the expression for $\mathbb{E}{\rm vol}_d(Z_{\gamma,\lambda,d})$ completes the proof.
\end{proof}

\begin{rema}\rm
 The notion of $\lambda$-geodesic hyperplanes as totally umbilical hypersurfaces of $\mathbb{H}^d$ can be extended to the case $\lambda>1$. In that situation, a $\lambda$-geodesic 'hyperplane' is a hyperbolic sphere of radius
 \[
 R_\lambda : = \operatorname{artanh}\Big(\frac{1}{\lambda}\Big).
 \]
 Hence, in this regime the visibility question in presence of a Poisson process of such spheres reduces to that in a Boolean model of balls with fixed radius $R_\lambda$, which in turn has been studied in \cite{L96}. As for $\lambda\in[0,1]$, there exists a critical intensity $\gamma_{B,\mathrm{crit}}>0$ such that the visibility region is unbounded with positive probability if $\gamma<\gamma_{B,\mathrm{crit}}$ and almost surely bounded for $\gamma>\gamma_{B,\mathrm{crit}}$. However, a key difference to the case $\lambda\in[0,1]$ is that, for $\lambda>1$, this critical intensity depends on $\lambda$. By \cite[p.\ 447]{L96} and \cite[Remark 6.5]{BuehlerHugThaele} it is given by $$\gamma_{B,\mathrm{crit}}=\frac{(d-1)\Gamma(\frac{d+1}{2})}{\pi^{(d-1)/2}\sinh(R_\lambda)}=\frac{(d-1)\Gamma(\frac{d+1}{2})}{\pi^{(d-1)/2}(\lambda^2-1)^{(d-1)/2}}.$$ In the bounded phase, the expected visible volume is derived in \cite[Theorem 6.2]{BuehlerHugThaele}. It can be expressed in the same way as the mean visible volume in \eqref{eq:MeanVolume} by replacing $\gamma_d^*$ by $v_d^*=\gamma\frac{\pi^{(d-1)/2}}{\Gamma(\frac{d+1}{2})}\sinh(R_\lambda)=\gamma\frac{\pi^{(d-1)/2}}{\Gamma(\frac{d+1}{2})(\lambda^2-1)^{(d-1)/2}}$.
\end{rema}

