\begin{Theorem}{\rm (van Kampen \cite{VK33}, Flores \cite{Flores32})}\label{VKF} 
Let $n$ be a positive integer, and let $K$ be a simplicial $n$-complex that is $\sigma_{2n+2}^{n}$ or $[3]^{*n+1}$. Then for every generic immersion $\varphi$ of $K$ into ${\mathbb R}^{2n}$, the following holds: 
\begin{eqnarray*}
\sum_{\substack{s,s'\in\varDelta^{n}(K)\\ s\cap s'=\varnothing}}l(\varphi(s),\varphi(s'))\equiv 1\pmod{2}. 
\end{eqnarray*}
\end{Theorem}

