Therefore, $N_1^{(n)}$, $N_2^{(n)}$ and $N_3^{(n)}$ are simplicial $n$-complexes that are `intrinsically linked' with respect to embeddings into ${\mathbb R}^{2n}$. We note that the simplicial $n$-complex $\sigma_{2n+2}^{n}\setminus\{|a_{0}a_{1}\cdots a_{n}|\}$ has already been shown to satisfy this property (Freedman--Krushkal \cite[Proposition 4.1]{FK14}; see also Freedman--Krushkal--Teichner \cite[Lemma 6]{FKT94}). However, both our $N_{1}^{(n)}$ and $N_{3}^{(n)}$ are proper subcomplexes of this complex. Moreover, the complexes $N_{1}^{(n)}$, $N_{2}^{(n)}$ and $N_{3}^{(n)}$ are minimal in the following sense among all simplicial $n$-complexes possessing this property.

\begin{Proposition}\label{min}
Let $N$ be a proper subcomplex of $N_1^{(n)}$, $N_2^{(n)}$ or $N_3^{(n)}$. Then there exists an embedding $f:N\to {\mathbb R}^{2n}$ such that ${\rm lk}_{2}(f(\lambda))= 0$ for any element $\lambda$ in $\Lambda^{n-1,n}(N)$.
\end{Proposition}

\begin{Remark}\label{nsp}
A graph $G$ is said to be {\it non-separating planar} if there exists an embedding $f: G \to \mathbb{R}^2$ such that, for every cycle $\gamma$ in $G$, all vertices of $G$ not lying on $\gamma$ belong to the same connected component of $\mathbb{R}^2 \setminus f(\gamma)$. Equivalently, $G$ is not non-separating planar if and only if for every embedding $f:G\to \mathbb{R}^2$, the image $f(G)$ contains a two-component link consisting of a $0$-sphere and a $1$-sphere with $\mathbb{Z}_2$-linking number $1$. Dehkordi--Farr proved in \cite{DF} that a graph is non-separating planar if and only if it contains no subgraph homeomorphic to $K_1 \sqcup K_4$, $K_1 \sqcup K_{2,3}$, or $K_{1,1,3}$ as illustrated in Fig. \ref{nonsp}. They further applied this characterization to the study of linkless embeddings of graphs in $\mathbb{R}^3$. For related results, see Fowler--Li--Pavelescu \cite{FLP23}, Pavelescu--Pavelescu \cite{PP24}. Note that $N_1^{(1)}$ is isomorphic to $K_1 \sqcup K_4$, $N_2^{(1)}$ is isomorphic to $K_1 \sqcup K_{2,3}$, and $N_3^{(1)}$ is isomorphic to $K_{1,1,3}$. Thus, our simplicial $n$-complexes $N_{1}^{(n)}$, $N_{2}^{(n)}$ and $N_{3}^{(n)}$ may be regarded as higher-dimensional analogues of the minimal subgraphs that prevent a graph from being non-separating planar.
\end{Remark}

\begin{Theorem}{\rm (van Kampen \cite{VK33}, Flores \cite{Flores32})}\label{VKF} 
Let $n$ be a positive integer, and let $K$ be a simplicial $n$-complex that is $\sigma_{2n+2}^{n}$ or $[3]^{*n+1}$. Then for every generic immersion $\varphi$ of $K$ into ${\mathbb R}^{2n}$, the following holds: 
\begin{eqnarray*}
\sum_{\substack{s,s'\in\varDelta^{n}(K)\\ s\cap s'=\varnothing}}l(\varphi(s),\varphi(s'))\equiv 1\pmod{2}. 
\end{eqnarray*}
\end{Theorem}

\begin{proof}[Proof of Theorem \ref{ILR2n}]
We first consider the case $K = N_1^{(n)}$. In what follows, for an $m$-simplex $s$, we will also denote its $(m-1)$-skeleton $s^{m-1}$ by $\partial s$. We define collections $\Gamma^{n-1}$ and $\Gamma^n$ of $(n-1)$ and $n$-subcomplexes of $N_1^{(n)}$, respectively, as follows: 
\begin{eqnarray*}
\Gamma^{n-1} &=& \left\{\partial s \mid s\in \varDelta^{n}(\sigma_{2n+2}^{n}),\,a_{0}\in s\right\},\\
\Gamma^{n} &=& \left\{\partial t \mid t\in \varDelta^{n+1}(\sigma_{2n+2}),\,a_{0}\notin t\right\}. 
\end{eqnarray*}
Then every $\lambda \in \Lambda^{n-1,n}(N_1^{(n)})$ is the disjoint union of an element $\gamma$ of $\Gamma^{n-1}$ and an element $\gamma'$ of $\Gamma^n$, see Fig. \ref{N_1_link} for $n=2$. Let $f:N_{1}^{(n)}\to {\mathbb R}^{2n}$ be an embedding. This can be extended to a generic immersion $\hat{f}:\sigma_{2n+2}^{n} \to \mathbb{R}^{2n}$ such that, for any two $n$-simplices $s,s' \in \varDelta^n(\sigma_{2n+2}^{n})$ with $a_0 \in s$ and $a_0 \notin s'$, the images $\hat{f}(s)$ and $\hat{f}(s')$ intersect transversely at finitely many double points, all of which occur in the interiors of both $n$-simplices. Note that for any $\lambda = \gamma \sqcup \gamma' \in \Lambda^{n-1,n}(N_1^{(n)})$ with $\gamma = \partial s$, $s \in \varDelta^n(\sigma_{2n+2}^n)$ and $a_0 \in s$, we have 
\begin{eqnarray}\label{lkdef}
{\rm lk}_{2}(f(\gamma),f(\gamma'))
\equiv \sum_{s'\in \varDelta^{n}(\gamma')}l(\hat{f}(s),\hat{f}(s'))\pmod{2}.
\end{eqnarray}
On the other hand, for any two disjoint $n$-simplices $s, s' \in \varDelta^n(\sigma_{2n+2}^n)$ with $a_0 \in s$ and $a_0 \notin s'$, there uniquely exists an element $\lambda = \gamma \sqcup \gamma' \in \Lambda^{n-1,n}(N_1^{(n)})$ such that $\gamma = \partial s$ and $\gamma' \supset s'$. Then, by (\ref{lkdef}) and Theorem \ref{VKF}, we obtain 
\begin{eqnarray*}\label{lksum}
\sum_{\lambda\in \Lambda^{n-1,n}(N_{1}^{(n)})}{\rm lk}_{2}(f(\lambda))
&=& \sum_{\substack{\gamma\sqcup\gamma'\in \Lambda^{n-1,n}(N_{1}^{(n)}) \\ \gamma\in \Gamma^{n-1},\,\gamma'\in\Gamma^{n}}}{\rm lk}_{2}(f(\gamma),f(\gamma'))\\
&\equiv& \sum_{\substack{\gamma\sqcup\gamma'\in \Lambda^{n-1,n}(N_{1}^{(n)}) \\ \gamma=\partial s,\,s\in \varDelta^{n}(\sigma_{2n+2}^{n}),\,a_{0}\in s}}
\bigg(\sum_{s'\in \varDelta^{n}(\gamma')}l(\hat{f}(s),\hat{f}(s'))\bigg)\nonumber\\
&=& \sum_{\substack{s,\,s'\in \varDelta^{n}(\sigma_{2n+2}^{n}) \\ s\cap s'=\varnothing}} 
l(\hat{f}(s),\hat{f}(s'))\nonumber\\
&\equiv& 1\pmod{2}. \nonumber
\end{eqnarray*}
Thus, there exists some $\lambda$ in $\Lambda^{n-1,n}(N_{1}^{(n)})$ such that ${\rm lk}_{2}(f(\lambda))=1$.

Next, we consider the case $K = N_{2}^{(n)}$. We define collections $\Gamma^{n-1}$ and $\Gamma^n$ of $(n-1)$ and $n$-subcomplexes of $N_{2}^{(n)}$, respectively, as follows: 
\begin{eqnarray*}
\Gamma^{n-1} &=& \left\{\partial s \mid s\in \varDelta^{n}([3]^{*n+1}),\,a_{0}^{0}\in s\right\},\\
\Gamma^{n} &=& \left\{\left\{a_{1}^{0},a_{2}^{0}\right\}*\left\{a_{i_{1}}^{1},a_{j_{1}}^{1}\right\}*\cdots*\left\{a_{i_{n}}^{n},a_{j_{n}}^{n}\right\} \mid 0\le i_{q}<j_{q}\le 2,\,q\ge 1\right\}. 
\end{eqnarray*}
Note that the $(n+1)$-fold join of two points is homeomorphic to the $n$-sphere. Then every $\lambda \in \Lambda^{n-1,n}(N_{2}^{(n)})$ is the disjoint union of an element $\gamma$ of $\Gamma^{n-1}$ and an element $\gamma'$ of $\Gamma^n$, see Fig. \ref{N_2_link} for $n=2$. Let $f:N_{2}^{(n)}\to {\mathbb R}^{2n}$ be an embedding. This can be extended to a generic immersion $\hat{f}:[3]^{*n+1} \to \mathbb{R}^{2n}$ such that, for any two $n$-simplices $s,s' \in \varDelta^n([3]^{*n+1})$ with $a_{0}^{0} \in s$ and $a_{0}^{0} \notin s'$, the images $\hat{f}(s)$ and $\hat{f}(s')$ intersect transversely at finitely many double points, all of which occur in the interiors of both $n$-simplices. Then, in a similar way as in the case of $N_{1}^{(n)}$, we have 
\begin{eqnarray*}\label{lksum2}
\sum_{\lambda\in \Lambda^{n-1,n}(N_{2}^{(n)})}{\rm lk}_{2}(f(\lambda))
&=& \sum_{\substack{\gamma\sqcup\gamma'\in \Lambda^{n-1,n}(N_{2}^{(n)}) \\ \gamma\in \Gamma^{n-1},\,\gamma'\in\Gamma^{n}}}{\rm lk}_{2}(f(\gamma),f(\gamma'))\\
&\equiv& \sum_{\substack{\gamma\sqcup\gamma'\in \Lambda^{n-1,n}(N_{2}^{(n)}) \\ \gamma=\partial s,\,s\in \varDelta^{n}([3]^{*n+1}),\,a_{0}^{0}\in s}}
\bigg(\sum_{s'\in \varDelta^{n}(\gamma')}l(\hat{f}(s),\hat{f}(s'))\bigg)\nonumber\\
&=& \sum_{\substack{s,\,s'\in \varDelta^{n}([3]^{*n+1}) \\ s\cap s'=\varnothing}} 
l(\hat{f}(s),\hat{f}(s'))\nonumber\\
&\equiv& 1\pmod{2}. \nonumber
\end{eqnarray*}
Thus the result follows.

