\begin{equation}\label{GuoZhaoconj7.2}
\sum_{k=0}^{p^r-1}(8k+1)\frac{(\f14)_k^3(\f12)_k}{(1)_k^3(\f34)_k}\equiv 3p^r+\frac{27}{4}p^{3r}\sum_{j=1}^{(p^r-3)/4}\frac{1}{j^2}\pmod{p^{r+3}}.
\end{equation}
