\begin{theorem}
    \label{thrm:beat-cactus-introversion}
    For all $n\geq14$, minors of size $n(n-1)(n-2)+1$ of the tangency flattenings vanish on the $n$-th secant variety of the Segre variety in $\P(\CC^n\otimes\CC^n\otimes\CC^n)$ but do not vanish on its $n$-th cactus variety.
\end{theorem}

ref_dict.prop:1de-koszul:
\begin{proposition}
    \label{prop:1de-koszul}
    Let $R$ be the apolar algebra to $e\leq \binom{d+1}2$ general quadrics in $d$ variables. If $e\geq3$, then the structure tensor $T$ of $R$ has border cactus rank at least $\floor{\frac32d}+3$. In particular, if $3\leq e\leq \floor{\frac d2}+1$, then $R$ is nonsmoothable.
\end{proposition}

ref_dict.prop:quadratic-better-than-koszul:
\begin{proposition}
    \label{prop:quadratic-better-than-koszul}
    The space $\im\Phi_{\mathrm Q}^C(T)\subset A\otimes B$ equals the sum of all $(T(\alpha)\otimes \id_A)\left(\im\koszul^{C,B}(T)\right)$ over $\alpha\in A^*$, where we consider $T(\alpha)$ as a map $C^*\to B$. In particular, if $\dim B=\dim C$ and $T$ is $1_A$-generic, this implies $\rank \Phi_{\mathrm Q}^C(T) \geq \rank\koszul^{C,B}(T)$.
\end{proposition}

