The article is divided into three parts : in \Cref{sec:largeness}, we survey and compare three related notions of largeness, namely, Ketonen and Solvay's $\alpha$-largeness, Le Houérou, Levy Patey and Yokoyama's $\alpha$-largeness$(\theta)$, and our new notion of $\alpha$-largeness${}^*(\theta)$, for $\alpha$ of the form $\bbomega^n \cdot k$. In \Cref{sec:combinatorics}, we develop the framework of $\alpha$-largeness${}^*(\theta)$ and prove polynomial upper bounds for $\RT^2_2$-$\bbomega^n$-largeness${}^*(\theta)$. Last, in \Cref{sec:translation}, we combine this upper bound with the framework of forcing interpretation to prove \Cref{thm:rt22-polynomially-simulated}.

\Cref{fig:forcing-translations} summarizes the different intermediate theories we will consider between $\RCA_0 + \BSig_2$ and $\RT_2^2 + \WKL_0$, and the polynomial simulation between them. It is adapted from \cite[Figure 1]{kolodziejczyk2023ramsey}, with $\BSig_2$ added to every theory, and with a $\forall \Sigma_3^0$ polynomial simulation between 
$\RCA_0 + \BSig_2 + \mathbb{I}'$ and $\WKL_0 + \RT_2^2$ instead of a $\forall \Sigma_2^0$ polynomial simulations.

\begin{lemma}\label[lemma]{lem:poly-sim-I1}
 $\RCA_0 + \BSig_2 + (\mathbb{I}1)$ is polynomially simulated by:
 \begin{enumerate}[(a)]
 \item $\RCA_0 + \ISig_2$ with respect to $\forall \Sigma_3^0$ sentences,
 \item $\RCA_0 + \BSig_2 + \neg \ISig_2$ with respect to $\mathcal{L}_2$ sentences.
 \end{enumerate}
\end{lemma}

\begin{lemma}\label[lemma]{lem:polynomially-reflecting}
 The forcing interpretation of $\WKL_0 + \RT_2^2$ in $\RCA_0 + \BSig_2 + \mathbb{I}'$ given by $\mathsf{Cond}, \trianglelefteqslant$, $\Vdash$ of \Cref{def:forcing-interpretation-def} is polynomially $\forall \Sigma_3^0$-reflecting.
\end{lemma}

\begin{lemma}\label[lemma]{lem:polynomial-simulation}
 $\RCA_0 + \mathbb{I}'$ polynomially simulates $\WKL_0 + \RT_2^2$ with respects to $\forall \Sigma_3^0$-sentences.
\end{lemma}

\begin{repmaintheorem}{thm:rt22-polynomially-simulated}
$\RCA_0 + \BSig_2$ polynomially simulates $\WKL_0 + \RT_2^2$ with respect to $\forall \Sigma_3^0$ sentences.
\end{repmaintheorem}

