\begin{enumerate}
\item Each sentence in $\th(\langle\HH, \{f_g:g \in G\rangle)$. These
include `Special Point axioms' $SP_g$: For each  $g\in \Gamma$ that
fixes a unique point in $D$.

$$\forall x, y \in D
[(g(x) =x \wedge  g(y) =y) \Rightarrow x=y] $$
\item  $\th(S(\CC),\mathcal{R})$ (where $\mathcal{R}$ is as in Definition~\ref{mcvocab}).
\item{Connection axioms}
\begin{enumerate}
\item Equivariance axioms
\begin{enumerate}
\item For $\gamma \in \Gamma$,
$x =\gamma y  \rightarrow J(x) =J(y)$.
\item For $\gamma \in \Gamma$ and $\check g_i$
such that $g= \gamma g_i$

 $x =g y  \rightarrow J(x) =J(y)$
\end{enumerate}
\item Modular axioms\footnote{Lemma~\ref{Zgthm} shows the modular axioms hold in $\MMM_{\jbar}$. And so they can consistently be added here. Moreover,
when $[G:\Gamma] < \omega$ the axiom is needed only for $\check \gbar$.}: Let $\gbar=\langle e,g_2, \ldots, g_k\rangle$ be from $G$ and $Y_{\gbar}$ as given in Lemma~\ref{Zgthm}.
    \begin{enumerate}
\item $Mod^1_{\gbar}: \forall x \in D \ \{J(x),J(g_2 x), \ldots J(g_k x)\} \in Y_{\gbar}$.
\item  $Mod^2_{\gbar}: \forall z \in Y_{\gbar}\subseteq S^{k}  \ \exists x  \in D
    \left(J(x),J(g_2 x), \ldots J(g_k x)) =z \right) $ 
\item $${\bf MOD}  = \{ Mod^1_{\gbar}\wedge Mod^2_{\gbar}:
    \gbar\in G^{m}, m<\omega\}$$

\end{enumerate}
\end{enumerate}
\end{enumerate}
\item We add the infinitary axioms
\begin{enumerate}
\item $\Phi_\infty$ is the $L_{\omega_1,\omega}$ sentence asserting that  for $(D, S, J)$ both the transcendence degree of $S(F)$ over $\QQ$ 
and the strongly minimal  structure $\langle D, \{f_g: g \in \Gamma \}\rangle$ are infinite.

\item $SF$ (standard fibers) denotes the $L_{\omega_1,\omega}$-axiom:
$$(\forall x \forall y \in D(J(x)= J(y) \rightarrow \bigvee_{g \in \Gamma}
x =f_g(y)).$$

\item We extend  $T(\jbar)$ in two ways.
\begin{enumerate}
\item $T^\infty (\jbar)$ denotes $T(\jbar) \cup \{\Phi_{\infty} \}$ and

\item $T^\infty_{SF}(\jbar)$ denotes $T(\jbar) \cup \{SF\}\cup \{\Phi_{\infty} \}$.

\end{enumerate}
\end{enumerate}
\end{enumerate}
\end{definition}

