\subsection{Wavelet transform} \label{sec:coefficient}
Let $(\pi, \Hpi)$ be a projective unitary representation of $G$ on a Hilbert space $\Hpi$, i.e., a strongly measurable map $\pi : G \to \mathcal{U}(\Hpi)$ satisfying $\pi(e_G) = I_{\Hpi}$ and
\[ \pi(g_1) \pi( g_2) = \sigma(g_1, g_2) \pi(g_1 g_2), \quad g_1, g_2 \in G ,\]
for some (measurable) function $\sigma : G \times G \to \mathbb{T}$.
For $\psi, f \in \Hpi$, we define the function
\[ C_\psi f(g) = \langle f, \pi(g) \psi \rangle, \quad g \in G. \]
 By \cite[Lemma 7.1, Theorem 7.5]{varadarajan1985geometry}, the absolute value $|C_{\psi} f| : G \to [0, \infty)$ is continuous for arbitrary $f, \psi \in \Hpi$.
We say that a vector $\psi \in \Hpi$ is \emph{admissible} if the associated \emph{wavelet transform} $C_{\psi} : \Hpi \to L^{\infty} (G)$ given by $f \mapsto C_{\psi} f$ is an isometry into $L^2 (G)$, that is, the orbit $\pi(G) \psi$ is a continuous Parseval frame for $\Hpi$. Throughout, we always consider $L^2 (G)$ with respect to the left Haar measure $\mu_G$.

\begin{proof}
Let $\varepsilon > 0$, $f \in \Hpi$ and let $U \subseteq G$ be an open, relatively compact set such that $\Lambda$ is $U$-separated.
Let $\Gamma \in \Omega(\Lambda)$ and let $(\Lambda_n)_{n \in \mathbb{N}}$ be a sequence of left translates $\Lambda_n \subseteq G$ of $\Lambda$ such that $\Gamma = \lim_{n \to \infty} \Lambda_n$. Clearly, each set $\Lambda_n$, $n \in \mathbb{N}$, is $U$-separated and, by \Cref{lem:relsep-reldense-passes-to-hull}, also the set $\Gamma$ is $U$-separated. 
\\~\\
(i) Let $\pi(\Lambda)\psi$ be a Bessel sequence with Bessel bound $C_2$. Then $\pi(\Lambda_n)\psi$ is a Bessel sequence with Bessel bound $C_2$ for all $n \in \N$. Let $K \subseteq G$ be a compact set. Enlarging $K$, we may assume that $\Gamma \cap \partial K = \emptyset$. Write $\Gamma \cap K= \{ \gamma^{(1)}, ..., \gamma^{(k)} \} $. Then, by \Cref{lem:convergence_sets}, there exists $n_0 \in \mathbb{N}$ such that $\Lambda_n \cap K = \{\lambda_n^{(1)}, ..., \lambda_n^{(k)} \}$ for all $n \geq n_0$ and $\lambda_n^{(j)} \to \gamma^{(j)}$ for all $1 \leq j \leq k$ as $n \to \infty$. This, combined with the continuity of the function $|C_{\psi} f|$ on $G$, yields that there exists $n_1 \geq n_0$ such that
\begin{align} \label{eq:passes-to-hull_2}
\bigg| \sum_{\gamma \in \Gamma \cap K} |(C_{\psi} f)(\gamma) |^2 - \sum_{\mu \in \Lambda_n \cap K} |(C_{\psi} f)(\mu) |^2 \bigg| \leq \frac{\varepsilon}{2}, \qquad n \geq n_1 .
\end{align}
Thus, since $\varepsilon > 0$ is arbitrary, we conclude that
\[ \sum_{\gamma \in \Gamma \cap K} | (C_\psi f)(\gamma)|^2 \leq \sum_{\mu \in \Lambda_n \cap K} |(C_\psi f)(\mu)|^2 \leq C_2 \| f \|^2 . \]
Since $f \in \Hpi$ and this holds for arbitrarily large compact sets $K \subseteq G$, we deduce that $\pi(\Gamma)\psi$ is a Bessel sequence with Bessel bound $C_2$.
\\~\\
(ii) Suppose $\pi(\Lambda)\psi$ is a frame and $\psi \in \mathcal{B}_{\pi}$. By \Cref{lem:sampling} there exists a compact set $K \subseteq G$ such that
\[
\sum_{\gamma \in \Gamma \cap K^c} |(C_{\psi} f)(\gamma) |^2 < \frac{\varepsilon}{4} \quad \text{and} \quad \sum_{\mu \in \Lambda_n \cap K^c} |(C_{\psi} f)(\mu) |^2 < \frac{\varepsilon}{4}
\]
for all $n \in \mathbb{N}$. Therefore,
\begin{align} \label{eq:passes-to-hull_1}
\bigg| \sum_{\gamma \in \Gamma \cap K^c} |(C_{\psi} f)(\gamma) |^2 - \sum_{\mu \in \Lambda_n \cap K^c} |(C_{\psi} f)(\mu) |^2 \bigg| \leq \frac{\varepsilon}{2}.
\end{align}
By enlarging $K$ if necessary, we may assume that \eqref{eq:passes-to-hull_1} holds for some compact $K \subseteq G$ with $\Gamma \cap \partial K = \emptyset$, see, e.g., the proof of \cite[Theorem 3.9]{enstad2025dynamical}.

\begin{theorem} 
Let $A, P \in \mathrm{GL}(d, \mathbb{R})$.
If $\psi \in \mathcal{B}_{\pi}$ and
$
 \{\pi(A^j P k, A^j) \psi \}_{ j \in \mathbb{Z}, k \in \mathbb{Z}^d } 
$
is a frame for $L^2 (\mathbb{R}^d)$ with frame bounds $0<C_1\leq C_2 < \infty$, then $\{ \pi(x, A^j) \psi \}_{x \in \mathbb{R}^d, j \in \mathbb{Z}}$ is a continuous frame for $L^2 (\mathbb{R}^d)$ with frame bounds $C_1|\det(P)|$ and $ C_2|\det(P)|$, and 
\[
C_1 \leq \frac{1}{|\det(P)|} \sum_{j \in \mathbb{Z}} |\widehat{\psi} ((A^t)^j \xi)|^2 \leq C_2 \quad \text{for a.e.} \;\; \xi \in \mathbb{R}^d.
\]
\end{theorem}
\begin{proof}
By \Cref{lem:quasilattice_affine}, the set $\Lambda = \{ (A^j Pk, A^j) : j \in \mathbb{Z}, k \in \mathbb{Z}^d \}$ is a quasi-lattice in $G$ with complement $C = P [0, 1)^d \times \{I_d\}$, so that $\rho_G (C) = |\det(P)|$. 
Hence, if the system $\pi(\Lambda) \psi$
is a frame for $L^2 (\mathbb{R}^d)$ with $\psi \in \mathcal{B}_{\pi}$, then \Cref{cor:quasi-lattice} implies that
\begin{align*} \label{eq:multiple_isometry}
C_1 |\det (P)| \leq \| C_{\psi} f \|^2 \leq C_2 |\det (P)| \| f \|^2
\end{align*}
for all $f \in L^2 (\mathbb{R}^d)$, which shows that 
$\{ \pi(x, A^j) \psi \}_{x \in \mathbb{R}^d, j \in \mathbb{Z}}$ is a frame with the claimed bounds.
A standard calculation (see, e.g., \cite{laugesen2002characterization, fuehr2002continuous}) next shows that
\begin{align*}
\| C_{\psi} f \|^2 &= \int_{G} | \langle \widehat{f}, \widehat{\pi(x, A^j) \psi} \rangle |^2 \; d\mu_G(x,A^j) \\
 &= \int_G \bigg| \int_{\mathbb{R}^d} \widehat{f}(\xi) |\det (A) |^{j/2} e^{- 2\pi i \xi \cdot x} \overline{\widehat{\psi}((A^t)^{j} \xi)} \; d\xi \bigg|^2 \; d\mu_G(x, A^j) \\
 &= \sum_{j \in \mathbb{Z}} \int_{\mathbb{R}^d} \bigg| \int_{\mathbb{R}^d} \widehat{f}(\xi) \overline{\widehat{\psi}((A^t)^{j} \xi)} e^{- 2\pi i \xi \cdot x} \; d\xi \bigg|^2 \; dx \\
 &= \sum_{j \in \mathbb{Z}} \int_{\mathbb{R}^d} \big|\widehat{f} (\xi) \widehat{\psi} ((A^t)^j \xi)\big|^2 \; d\xi \\
 &= \int_{\mathbb{R}^d} |\widehat{f} (\xi)|^2 \sum_{j \in \mathbb{Z}} |\widehat{\psi} ((A^t)^j \xi)|^2 \; d\xi, 
\end{align*}
where the penultimate step used Plancherel's formula. Hence,
\[
C_1 |\det(P)| \| \widehat{f} \|^2 \leq \int_{\mathbb{R}^d} |\widehat{f} (\xi)|^2 \sum_{j \in \mathbb{Z}} |\widehat{\psi} ((A^t)^j \xi)|^2 \; d\xi
\leq C_2 |\det(P)| \| \widehat{f} \|^2.
\]
Since this holds for arbitrary $f \in L^2 (\mathbb{R}^d)$, it follows that
\[
C_1 |\det(P)| \leq \sum_{j \in \mathbb{Z}} |\widehat{\psi} ((A^t)^j \xi)|^2 \leq C_2 |\det(P)|
\]
for a.e. $\xi \in \mathbb{R}^d$.
\end{proof}

