\begin{remark}
In contrast to \cite{ZN26}, where the H\"older index $\gamma \in (0,\frac{sp}{p-1})$ relies on the parameters $s$ and $p$, Theorem \ref{Th13} establishes a parameter-independent H\"older regularity with $\gamma \in (0,1)$. This holds under more general nonlinear frameworks and is particularly advantageous for subsequent regularity analysis.
\end{remark}

\begin{proposition}\label{Pro41}
Let $2\le p <\infty,\;0<s<1$ and $0\le \Lambda \le 1$. Assume $u \in HW_{{\rm{loc}}}^{1,p}\left( {{B_2}\left( {{\xi _0}} \right) \cap L_{sp}^{p - 1}\left( {{\mathbb{H}^n}} \right)} \right)$ is a weak solution of \eqref{eq0} in ${{B_2}\left( {{\xi _0}} \right)}$ satisfying
\begin{equation}\label{eq41}
{\left\| u \right\|_{{L^\infty }\left( {{B_1}\left( {{\xi _0}} \right)} \right)}} \le 1,\int_{{\mathbb{H}^n}\backslash {B_1}\left( {{\xi _0}} \right)} {\frac{{{{\left| {u\left( \eta \right)} \right|}^{p - 1}}}}{{\left\| \eta \right\|_{{\mathbb{H}^n}}^{Q + sp}}}d\eta } \le 1.
\end{equation}
If $0<h_0<\frac{1}{10}$ and $R$ satisfy $4{h_0}<R\le 1-5{h_0}$, and ${\nabla _H}u \in {L^q}\left( {{B_{R + 4{h_0}}}\left( {{\xi _0}} \right)} \right)$ for some $q \ge p$, then
\begin{equation}\label{eq42}
 \mathop {\sup }\limits_{0 < \left| h \right| < {h_0}} \int_{{B_{R - {4h_0}}}} {{{\left| {\frac{{\Delta _{Z,h}^2u}}{{{{\left| h \right|}^{\frac{1}{{q + 1}} + 1}}}}} \right|}^{q + 1}}d\xi } \le c(1+\Lambda) \left( {\int_{{B_{R + {4h_0}}}} {{{\left| {{\nabla _H}u} \right|}^q}d\xi } + 1} \right),
\end{equation}
where $c=c(Q,h_0,p,q,s)>0$.
\end{proposition}

For simplicity, we denote $u_R$ by $u$. Fix $0<\gamma<1$ and choose $i_\infty \in \mathbb{N}\setminus {0}$ such that
\begin{equation}\label{eq492}
1 - \gamma > \frac{Q}{{p + {i_\infty }}}.
\end{equation}
For $i = 0, \cdots ,{i_\infty }$, we define
\[{q_i} = p + i,\]
and
\[{h_0} = \frac{1}{{112{i_\infty }}},\;{R_i} = \frac{7}{8} - 4{h_0} - 14{h_0}i,\]
so
\[{R_0} + 4{h_0} = \frac{7}{8},\;{R_{{i_\infty }}} + 4{h_0} = \frac{3}{4},\;4{h_0} <R_i<1-5{h_0} .\]
By using Proposition \ref{Pro41} with
\[R = {R_i},q = {q_i},\;i = 0, \cdots ,{i_\infty },\]
and we have by \eqref{eq485}
\begin{equation}\label{eq486}
\mathop {\sup }\limits_{0 < \left| h \right| < {h_0}} \int_{{B_{R_0 - {4h_0}}}} {{{\left| {\frac{{\Delta _{Z,h}^2u}}{{{{\left| h \right|}^{\frac{1}{{{q_1}}} + 1}}}}} \right|}^{{q_1}}}d\xi } \le c(1 + \Lambda )\left( {\int_{{B_{\frac{7}{8}}}} {{{\left| {{\nabla _H}u} \right|}^p}d\xi } + 1} \right) \le C\left( {Q,p,s,\gamma} \right).
\end{equation}
Consider ${R_i} - 10{h_0} = {R_{i + 1}} + 4{h_0}$ for $i = 0, \cdots ,{i_\infty }$, we use Lemma \ref{Le213} in \eqref{eq486} to get
\begin{equation}\label{eq487}
\int_{{B_{{R_1} + 4{h_0}}}} {{{\left| {{\nabla _H}{u}} \right|}^{{q_1}}}d\xi } \le C\left( {Q,p,s,\gamma} \right).
\end{equation}
Applying Proposition \ref{Pro41} and \eqref{eq487} once again, we obtain
\begin{equation}\label{eq488}
\mathop {\sup }\limits_{0 < \left| h \right| < {h_0}} \int_{{B_{{R_1} - 4{h_0}}}} {{{\left| {\frac{{\Delta _{Z,h}^2u}}{{{{\left| h \right|}^{\frac{1}{{{q_2}}} + 1}}}}} \right|}^{{q_2}}}d\xi } \le c(1 + \Lambda )\left( {\int_{{B_{{{{R_1} + 4{h_0}}}}}} {{{\left| {{\nabla _H}u} \right|}^{{q_1}}}d\xi } + 1} \right) \le C\left( {Q,p,s,\gamma} \right).
\end{equation}
Moreover, by Lemma \ref{Le213} in \eqref{eq488}, we have
\begin{equation}\label{eq489}
