\[\int_{{B_{\frac{1}{4}}}\left( {{\xi _0}} \right)} {\frac{{{{\left| {{u_R}\left( {{\xi _0}} \right) - {u_R}\left( \eta \right)} \right|}^{p - 1}}}}{{{{\left\| {{\eta ^{ - 1}} \circ {\xi _0}} \right\|}_{{\mathbb{H}^n}}^{Q + sp}}}}d\eta } \le c\left( {Q,p,s,\gamma } \right)\int_{{B_{\frac{1}{4}}}\left( {{\xi _0}} \right)} {\frac{1}{{{{\left\| {{\eta ^{ - 1}} \circ {\xi _0}} \right\|}_{{\mathbb{H}^n}}^{Q + sp - \gamma \left( {p - 1} \right)}}}}d\eta } = c\left( {Q,p,s,\gamma } \right).\]
