\[{\left\| {{{{{\left( { - \Delta _{{{\mathbb{H}},p}}} \right)}^s}}}{u_R}} \right\|_{{L^\infty }\left( {{B_{\frac{1}{4}}}} \right)}} \le c\left( {Q,p,s,\gamma } \right),\]
