\subsection{Self-improvement of a simplified cutoff Sobolev inequality} \label{ss:self-improve}

We prove the following   version of cutoff Sobolev inequality using the Whitney blending result. This result can be viewed as a proof of the non-local analogue of simplified cutoff Sobolev inequality introduced in \cite[Definition 6.1]{Mur24} using the Whitney blending method of \cite{Eri}.

\begin{prop} \label{p:css}
Let $(\mathcal{E},\mathcal{F})$ be a regular, pure jump Dirichlet form on $L^2(X,m)$ that satisfies  \hyperlink{jphi}{$\operatorname{J(\phi)}$} and   \hyperlink{cap}{$\operatorname{Cap(\phi)_{\le}}$}, where $\phi:[0,\infty) \to [0,\infty)$ is a scale function. Then there exists $C>0$ such that for any $r,\rho>0, f\in C(X) \cap \mathcal{F}$, the equilibrium potential $\psi$ for $\overline{B(x,r)} \subset B(x,2r)$ for the truncated Dirichlet form $(\mathcal{E}^{(\rho)}, \mathcal{F})$ satisfies
\begin{align} \label{e:css}
	\int_X f^2 \,d\Gamma^{(\rho)}(\psi,\psi) &= \int_{B(x,2r+\rho)} f^2 \,d\Gamma^{(\rho)}(\psi,\psi) \nonumber\\
	& \le C  	\int_{B(x,2r+2\rho)} \int_{B(x,2r+2\rho)} (f(y)-f(z))^2  J(y,z)\,m(dy)\,m(dz) \nonumber \\
	&\quad\quad\quad+ \frac{C}{\phi(r)} \int_{B(x,2r)} f^2\,dm 
\end{align}

