ref_dict.definition WH:
\begin{definition}\label{definition WH}
    $G$ is \textit{weakly Haagerup} if there is a sequence of maps $\phi_n:G\rightarrow\mathbb{C}$ with 
    \begin{enumerate}
        \item $\phi_n$ vanishes at infinity, for each $n\in \mathbb{N}$,
        \item $\{\phi_n\}$ is an approximate identity i.e. $\lim_{n\rightarrow\infty}\phi_n(g)=1$ for all $g\in G$,
         \item there exists a constant $B>0$ such that $||\phi_n||_{B_2}\leq B$ for each $n\in \mathbb{N}$.
    \end{enumerate}
        The weak Haagerup constant, denoted $\Lambda_{WH}$ for $G$ is the infimum of all such $B>0$ for which there is a sequence $\{\phi_n\}_n$ satisfying the above properties.
\end{definition}

ref_dict.definition completely bounded:
\begin{definition}\label{definition completely bounded}
    A function $\phi:G\rightarrow \mathbb{C}$ is called \textit{completely bounded} if there is a $B>0$ such that the operator-norm of $M_{n,\phi}$, defined above is bounded by $B$, for each $n\in\mathbb{N}$. The $B_2$-norm (alternately the completely bounded norm or the cb-norm) of $\phi$ is
    $$||\phi||_{B_2}:=\sup_{n\in\mathbb{N}} ||M_{n,\phi}||$$
\end{definition}

ref_dict.main I:
\begin{theorem}\label{main I}
    Suppose $\Gamma$ is a finite simplicial graph and $\{G_{v}\}_{v\in V(\Gamma)}$ is a collection of weakly Haagerup groups with $\Lambda_{WH}(G_v)=1$, for each $v$. Then the group $G(\Gamma)$ has the weak Haagerup property with $\Lambda_{WH}(G(\Gamma))=1$.
\end{theorem}

