\subsection{Marstrand's projection theorem}
Marstrand's projection theorem in the plane \cite{Mar} may be stated as follows.

We will assume, sometimes without mentioning it specifically, that the subsets of $\mathbb{R}^m$ with which we work are all Borel or analytic, indeed for many results little is lost by assuming them to be compact. We avoid consideration of completely general sets that do not have analytic or measurable structure; they may behave strangely depending on the axioms of logic that are assumed. Nevertheless we note that recently Lutz and Stull \cite{LS} have used effective dimension and computational complexity to obtain some results on projections with no requirement on sets to be Borel or analytic.

The natural higher dimensional analogue of Marstrand's theorem was first presented by Mattila \cite{Mat} in 1975.

Briefly, the potential-theoretic method depends on the characterisation of Hausdorff dimension in terms of energy integrals. We write $\mathcal{M}(E)$ for the positive finite Borel measures supported on $E\subset \mathbb{R}^n$. For $s>0$ we write:
\begin{equation}\label{endef}
I^s(\mu) := \int \!\! \int \frac{d\mu(x)d\mu(y)}{|x-y|^s} 
\end{equation}
for the $s$-{\it energy} of the measure $\mu\in \mathcal{M}(E)$. Then
\begin{equation*}\label{endefhau}
\dh E = \sup\Big\{s : \mbox{ there exists $\mu \in \mathcal{M}(E)$ such that $I^s(\mu) < \infty$}\Big\}.
\end{equation*}
Theorem \ref{marthm}(i) may then be proved by noting that for all $0<s< \dh E$ there is a measure $\mu\in \mathcal{M}(E)$ such that $I^s(\mu) <\infty$, and verifying that $\int I^s(\mu_\theta) d\theta \leq c_sI^s(\mu)$, where $\mu_\theta$ is the projection of the measure $\mu$ onto the line $L_\theta$ in direction $\theta$, given by $\mu_\theta(F) = \mu(\proj^{-1}_\theta F)$ for $F\subset L_\theta$. The higher dimensional case, Theorem \ref{higherdim}(i), may be proved in a similar way.

Whilst Marstrand's Theorem gives that the Lebesgue measure of the `exceptional set' of projection directions $\theta$ for which $\dh \mbox{\rm proj}_\theta E < \min\{\dh E, 1\}$ has Lebesgue measure 0, often the set of exceptional directions must be somewhat smaller than this. Indeed Kaufman's potential theoretic approach \cite{Kau} also yields an upper bound for the dimension of the exceptional set in Theorems \ref{marthm}(i) and \ref{higherdim}(i), namely that if $E \subset \mathbb{R}^n$ and $0\leq s< \dh E < m$ then
\begin{equation}\label{Kaut}
\dh\{V \in G(n,m) : \dh \mbox{\rm proj}_V E< s\} \leq m(n-m) -(m-s).
\end{equation}
(This bound is written in this form for comparison with $m(n-m)$, the dimension of the Grassmanian $G(n,m))$.
Using Fourier transforms, Falconer \cite{Fal1} in 1982 obtained bounds for the exceptional sets of an alternative form: if $0\leq s \leq m \leq \dh E$ then
\begin{equation}\label{Falt}
\dh\{V \in G(n,m) : \dh \mbox{\rm proj}_V E< s\} \leq \max\{m(n-m) -(\dh E-s), 0\},
\end{equation}
and if $m \leq \dh E \leq n$, 
\begin{equation}\label{Falt2}
\dh\{V \in G(n,m) : \mathcal{L}^n(\mbox{\rm proj}_V E) =0\} \leq m(n-m) -(\dh E-m);
\end{equation}
the idea here is the greater the `excess dimension' $ \dh E - s$ or $ \dh E - m$, the smaller the set of exceptional $V$.
Estimates for the dimensions of exceptional sets in the spirit of \eqref{Kaut}, where there is a direct estimate, and \eqref{Falt}--\eqref{Falt2}, where the bound depends on by how much the dimension of a set exceeds a threshold, have become known as `Kaufman-type' and `Falconer-type' estimates respectively.

\begin{theo}\label{assd} 
Let $\log 3/\log 5 <s<1$. Then there is $\epsilon>0$ such that
${\dim}_{\rm A}\proj_\theta E_s=1$ for almost all $\theta \in (-\epsilon, \epsilon)$ and ${\dim}_{\rm A}\proj_\theta E_s=s<1$ for all $\theta \in (\pi/4 -\epsilon, \pi/4+ \epsilon)$.
\end{theo}
\noindent This example, due to Fraser and Orponen \cite{FO}, depends on the fact that a self-similar $E\subset \mathbb{R}^2$ defined by contracting homotheties has
$$
{\dim}_{\rm A}\mbox{proj}_\theta E =
\left\{
\begin{array}{ll}
 \dh \proj_\theta E& \text{ if } \mathcal{H}^{\dh {\rm proj}_\theta E}(\proj_\theta E) >0 \\
 1 & \text{ if }\mathcal{H}^{\dh {\rm proj}_\theta E}(\proj_\theta E)=0 
\end{array}
\right.,
$$
where $\mathcal{H}^s$ is $s$-dimensional Hausdorff measure, so the construction is equivalent to finding a set of homotheties for which the IFS attractor $E$ has projections with positive or zero ($\proj_\theta E$)-dimensional Hausdorff measure in the appropriate directions.

\begin{theo}\label{projgeneral}
Let $P \subset \mathbb{R}^k$ be an open parameter set and let $E \subset \mathbb{R}^n$ be a Borel or analytic set. Let $\{V(t)\subset G(n,m): t \in P\}$ be a family of subspaces such that $V$ is $C^1$ with the derivative $D_t V(t)$ injective for all $t \in P$. Then, for all $l=0,1,\ldots,m$ and ${\mathcal L}^k$-almost all $t \in P$,
$$
\dh\proj_{V(t)} E \geq 
\left\{
\begin{array}{llrl}
 \dh E-p(l) &\ \mbox{if} & p(l) + l & \leq \dh E \leq p(l) + l +1 \\
l+1 &\ \mbox{if} & \ p(l) + l +1 &\leq \dh E \leq p(l+1) + l +1
\end{array}
\right. .
$$
Moreover, if $\dh E > p(m-1) + m$ then ${\mathcal L}^m ( \proj_{V(t)} E) > 0$ for ${\mathcal L}^k$-almost all $t \in P$.
\end{theo}

\begin{theo}\label{projline}
Let $E \subset \mathbb{R}^3$ be a Borel or analytic set and let $\theta: [0,1] \to S^2$ be a non-degenerate family of directions. Then 
\begin{equation}\label{projlineeq}
\dh\proj_{\theta(t)} E = \min\{\dh E, 1\}\quad \text{ for almost all } t\in [0,1],
\end{equation}
and if $\dh E >1$ then
\begin{equation}\label{resmes}
{\mathcal L} (\proj_{\theta(t)} E)>0 \quad \text{ for almost all } t\in [0,1].
\end{equation}
Concerning exceptional directions, if $0\leq s\leq \min\{\dh E, 1\}$ then
\begin{equation}\label{PYZ}
 \dh\{t : \dh \proj_{\theta(t)} E <s\} \leq s,
\end{equation}
and if $0\leq s\leq 1$ then 
\begin{equation}\label{GGM}
 \dh \{t: \proj_{\theta(t)} E <s\} \leq \max\big\{0, 1 + {\textstyle \frac12} (s-\dh E) \big\},
\end{equation}
and
\begin{equation}\label{resmes1}
\dh\{t: {\mathcal L} (\proj_{\theta(t)} E) = 0 \} \leq \textstyle{\frac13}(4-\dh E).
\end{equation}
\end{theo}

\begin{theo}\label{projplane}
Let $E \subset \mathbb{R}^3$ be a Borel or analytic set and let $\theta: [0,1] \to S^2$ be a non-degenerate family of directions. 
Then 
\begin{equation}\label{projplaneeq}
\dh\proj_{V_{\theta(t)}} E = \min\{\dh E, 2\} \quad \text{ for almost all } t\in [0,1].
\end{equation}
Moreover, if $\dh E >2$ then
\begin{equation}\label{projlplanex}
{\mathcal L^2} (\proj_{\theta(t)} E)>0 \quad \text{ for almost all } t\in [0,1].
\end{equation}
For exceptional directions, if $0\leq s\leq 1$ then 
\begin{equation}\label{GGG}
 \dh\{t : \dh \proj_{\theta(t)} E <s\} \leq \max\{ 1 + s-\dh E, 0 \}.
\end{equation}
\end{theo}

\begin{theo}\label{higherdim}
Let $E \subset \mathbb{R}^n$ be a Borel or analytic set. Then

(i) $\dh\mbox{\rm proj}_V E \leq \min\{\dh E, m\}$  with equality for $\gamma_{n,m}$-almost all $V \in G(n,m)$,
\smallskip

(ii) if $\dh E >m$ then ${\mathcal L}^m (\mbox{\rm proj}_V E) > 0$ for $\gamma_{n,m}$-almost all $V \in G(n,m)$. 
\end{theo}

\begin{theo}\label{marthm}
Let $E \subset \mathbb{R}^2$ be a Borel or analytic set. Then

(i) $\dh \mbox{\rm proj}_\theta E \leq \min\{\dh E, 1\}$ with equality for almost all $\theta \in [0,\pi)$,
\smallskip

(ii) if $\dh E >1$ then ${\mathcal L} (\mbox{\rm proj}_\theta E) > 0$ for almost all $\theta \in [0,\pi)$.
\end{theo}

post_theorem_intro_text:
The  natural higher dimensional analogue of Marstrand's theorem was first presented by Mattila \cite{Mat} in 1975.

\begin{theo}\label{higherdim}
Let $E \subset \mathbb{R}^n$ be a Borel or analytic set. Then

(i) $\dh\mbox{\rm proj}_V E \leq \min\{\dh E, m\}$  with equality for $\gamma_{n,m}$-almost all $V \in G(n,m)$,
\smallskip

(ii) if $\dh E >m$ then ${\mathcal L}^m (\mbox{\rm proj}_V E) > 0$ for $\gamma_{n,m}$-almost all $V \in G(n,m)$. 
\end{theo}

Since orthogonal projection is a Lipschitz map that does not increase distances between points, the inequalities in (i) of Theorems \ref{marthm} and \ref{higherdim}   follow easily from the definition of Hausdorff measure and dimension, but showing that equality holds for almost all $\theta$ or $V$ is more involved. 
In his original paper, Marstrand  \cite{Mar} used intricate estimates involving plane geometry and measure theory, but in 1968  Kaufman \cite{Kau} gave a new proof of Theorem \ref{marthm}(i) using potential theory and of Theorem \ref{marthm}(ii)  using Fourier transforms before
Mattila \cite{Mat} used this approach in higher dimensions to obtain Theorem 1.2.

Briefly, the potential-theoretic method depends on the characterisation of Hausdorff dimension in terms of energy integrals. We write $\mathcal{M}(E)$ for the positive finite Borel measures supported on $E\subset \mathbb{R}^n$. For $s>0$ we write:
\begin{equation}\label{endef}
I^s(\mu) := \int \!\! \int \frac{d\mu(x)d\mu(y)}{|x-y|^s} 
\end{equation}
for the $s$-{\it energy} of the measure $\mu\in \mathcal{M}(E)$. Then
\begin{equation*}\label{endefhau}
\dh E = \sup\Big\{s :  \mbox{ there exists $\mu \in \mathcal{M}(E)$ such that $I^s(\mu) < \infty$}\Big\}.
\end{equation*}
Theorem \ref{marthm}(i) may then be proved by noting that for all $0<s< \dh E$ there is a measure $\mu\in \mathcal{M}(E)$ such that $I^s(\mu) <\infty$,   and verifying that  $\int I^s(\mu_\theta) d\theta \leq c_sI^s(\mu)$, where $\mu_\theta$ is the projection of the measure $\mu$ onto the line $L_\theta$ in direction $\theta$, given by $\mu_\theta(F) = \mu( \mbox{\rm proj}^{-1}_\theta F)$ for $F\subset L_\theta$. The higher dimensional case, Theorem \ref{higherdim}(i), may be proved in a similar way.

Theorem \ref{marthm}(ii) may be obtained using Fourier transforms. Writing $\widehat{\mu}(z):= \int e^{-2\pi i x.z} d\mu(x) \  (z\in \mathbb{R}^n)$ for the Fourier transform of $\mu$, applying Parseval's theorem and the convolution formulae to the energy expression in \eqref{endef} gives 
\begin{equation}\label{ftend}
I^s(\mu) = c_{n,s}\int_{\mathbb{R}^n} \frac{|\widehat{\mu}(z)|^2} {|z|^{n-s}}dz \qquad (0<s<n),
\end{equation}
where   $c_{n,s}$ depends only on $n$ and $s$, see \cite[Theorem 3.10]{Mat2}.
Then if $E\subset  \mathbb{R}^2$ and $\dh E >1$  we may find $\mu\in \mathcal{M}(E)$ and $1<s<\dh E$ such that $I^s(\mu) < \infty$. Writing \eqref{ftend} in radial coordinates this implies that $\int \!\! \int | \widehat{\mu_\theta}(t)|^2 dt\, d\theta <\infty$, so that for almost all $\theta$, the projected measure $\mu_\theta$ on $L_\theta$ is absolutely continuous with respect to $\mathcal{L}$ and is a square integrable function, so in particular $E$ has support of positive $\mathcal{L}$-measure.

Energy and Fourier methods and their generalisations and extensions have been used widely across fractal geometry and in particular in work on projections. Further examples will be encountered in this survey, but for thorough treatments see, for example, \cite{Fal, FFJ, Mat, Mat1,Mat4,Mat5,Mat2}

Marstrand's theorem is the prototype for a great deal of work in fractal geometry. If, in some setting, a dimensional property of parameterised images of a set is true for almost all parameters, perhaps for almost all $\theta$ or $V$, we say that a `Marstrand-type theorem holds'. We will see many instances of this in the sections that follow.

ref_dict.thm:cdbound:
\begin{theorem}\label{thm:cdbound}
    Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$
\end{theorem}

ref_dict.lemma:p_zd_on_H_I^n:
\begin{lemma}\label{lemma:p_zd_on_H_I^n}
    Let $I$, $A$, $x$, $I_1$ and $I_2$ be as in Lemma \ref{lemma:radical(I+p)}, $M$ be an $A$-module and $n>\max(\cd(M,I_1),\cd(M,I_2))$. Then $H_I^n(M)$ is $x$-power torsion, that is, every element of $H^n_I(M)$ is annihilated by some power of $x$.
\end{lemma}

ref_dict.thm:induction:
\begin{theorem}\label{thm:induction}
    Let $(A,\mathfrak{m},k)$ be an unramified regular local ring of mixed characteristic $(0,p)$, and let $I$ be an ideal of $A$. Suppose $\height(I)<\height(I:(I:p))$ (for example, this holds if $p$ is a nonzerodivisor on $A/I)$.\footnote{We use the convention that $\height(A)=\infty.$}

    Set $c=\bight(I)$. Let $n>c$ be an integer. Assume that for all integers $s$, with $1\leq s\leq c-1,$ and for all $q\geq n-s$, $H^q_{IA_P}(A_P)=0$ for all $P\in \Spec(A)$ such that $I\subseteq P$ and $\dim(A/P)\geq s+1.$ Then $H^q_I(A)=0$ for all $q\geq n.$
\end{theorem}

ref_dict.example:sharpness:
\begin{example}\label{example:sharpness}
    Given an unramified regular local ring $(A,\mathfrak{m})$ of dimension $d>0$ and a positive integer $c\leq d$, there exists an ideal $I$ of $A$ such that $\cd(A,I)=d-\floor*{\frac{d-1}{c}}.$ We construct this ideal as in \cite{Lyu2}. 

    Let $N=\floor*{\frac{d-1}{c}}.$ Let $I_0,\dots,I_N$ be ideals of pure height $c$ in $A$ such that $I_0+\dots+I_N$ is $\mathfrak{m}$-primary and let $I=I_0\cap\dots\cap I_N$. Then $\cd(A,I)=d-N.$ The proof of this statement is identical to \cite{Lyu2}.

    To resolve any conflict with the previous remark, we show that in this example, if $p\in I$, then $\floor*{\frac{d-2}{c-1}}= \floor*{\frac{d-1}{c}}.$ Indeed, if $p\in I,$ we have $p\in I_j$ for all $j\in\{0,\dots,N\}$ and by Theorem \ref{thm:Serre}, $$d=\height(I_0+\dots+I_N)\leq 1+(N+1)(c-1)=Nc+c-N.$$ Let $d-1=Nc+k$, where $0\leq k<c$. Then the above equation yields $N+k+1\leq c$, or $N+k-1\leq c-2$. Observe that $$d-2=N(c-1)+N+k-1,$$ and hence, $\floor*{\frac{d-2}{c-1}}=N=\floor*{\frac{d-1}{c}}$. 
\end{example}

ref_dict.thm:maintheorem:
\begin{maintheorem}\label{thm:maintheorem}(cf. Theorem \ref{thm:cdbound})
Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$  
\end{maintheorem}

full_context:
Local cohomology, introduced by Grothendieck in the early 1960s, plays a pivotal role in commutative algebra and algebraic geometry. Its vanishing behavior reflects subtle geometric and topological properties of the underlying scheme and has been studied extensively in the work of Grothendieck, Hartshorne, Faltings, and others. Understanding when local cohomology modules vanish remains a fundamental and delicate problem.

Let $A$ be a commutative Noetherian ring of Krull dimension $d$ and $I$ be an ideal of $A$. The \textit{cohomological dimension} of $I$ in $A$ is $$\operatorname{cd}(A,I):=\max\{n\:|\:H^n_I(A)\neq 0\}.$$ Alternatively, $\operatorname{cd}(A,I)$ is the least integer $n$ such that $H^q_I(M)=0$ for all $A$-modules $M$ and $q>n$ \cite[Theorem 9.6]{24h}. As $H^q_I(M)=0$ for all $A$-modules $M$ and $q>d$ \cite{Gr}, $\operatorname{cd}(A,I)$ always exists and is bounded above by $d$.

The computation of better upper bounds on cohomological dimension has been of great interest over the past few decades. It is well-known that $$\operatorname{cd}(A,I)\leq\operatorname{ara}(I),$$ where $\operatorname{ara}(I)$, the $\textit{arithmetic rank}$ of $I$, is the least number of equations required to generate $I$ up to radical. However, the arithmetic rank of an ideal is difficult to compute and can be far from the cohomological dimension \cite{BS,Bar,JPSW,BMMP}.

A complementary approach is to bound the cohomological dimension using topological invariants of the spectrum of $A/I$. The most famous result in this direction is the Hartshorne--Lichtenbaum Vanishing Theorem \cite{Ha1}, which states that for a complete local domain $(A,\mathfrak{m})$, we have $\operatorname{cd}(A,I)\leq d-1$ if and only if $I$ is not $\mathfrak{m}$-primary. Furthermore, the Second Vanishing Theorem \cite{Ogus,PS,HunLyu,Zhang} asserts that in equal characteristic or unramified mixed characteristic, for a complete regular local ring $(A,\mathfrak{m})$ with separably closed residue field, we have $\operatorname{cd}(A,I)\leq d-2$ if and only if $\dim(A/I)\geq 2$ and the punctured spectrum of $A/I$ is connected. Peskine and Szpiro \cite{PS} proved that if $(A,\mathfrak{m)}$ is a regular local ring of equal characteristic $p$ and $A/I$ is Cohen-Macaulay, then $\operatorname{cd}(A,I)=\operatorname{ht}(I).$ Beyond the results discussed here, further vanishing statements have been proved in various settings \cite{MR3078644,DaoTakagi, Burke}, though the conditions required become progressively harder to check. Ogus \cite{Ogus}, Hartshorne and Speiser \cite{HarSpe}, Lyubeznik \cite{Lyu3}, Mustață and Popa \cite{MuPo}, and Reichelt, Saito and Walther \cite{RTW} obtained concrete formulae for cohomological dimension in equal characteristic in terms of singularity invariants, see also \cite{BBLSZ}. However, these methods require the understanding of de Rham cohomologies, Hodge filtrations, or Frobenius structures, and in practice they can be difficult to compute.

In equal characteristic, Faltings \cite{Faltings} established a general bound on cohomological dimension in terms of the \textit{big height} of an ideal. The big height of an ideal is the maximum of the heights of all its minimal primes. In this article, we extend Faltings' result to the unramified mixed characteristic setting.

\begin{theorem}\label{thm:cdbound}
    Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$
\end{theorem}

In equal characteristic, Faltings \cite{Faltings} established a general bound on cohomological dimension in terms of the \textit{big height} of an ideal. The big height of an ideal is the maximum of the heights of all its minimal primes. In this article, we extend Faltings' result to the unramified mixed characteristic setting.

We also establish an inductive criterion for the vanishing of local cohomology modules. See Theorem \ref{thm:induction} for a more general statement than the one stated below.

\begin{theorem}\label{thm:cdbound}
 Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$
\end{theorem}
\begin{proof} We may assume that $A$ is complete and $I$ is radical as local cohomology and big height remain unchanged. If $c=1$, $I$ is principal and $\cd(A,I)\leq 1$. Thus we assume $c>1.$ We also assume $c<d$ as the claimed bound is immediate if $c=d.$

\begin{corollary}[cf. {\cite[Lemma]{Lyu2}}, {\cite[Lemma 3.10]{HNBPW}}]\label{cor:Lyu}
 Let $A$ be a $d$-dimensional regular local ring of equal characteristic or unramified mixed characteristic. Let $I_1,\dots,I_N$ be ideals of $A$ of big height at most $c\geq 1$. Then $$\cd(A,I_1+\dots+I_N)\leq d-\floor*{\frac{d-1}{c}}+N-1.$$
\end{corollary}
\begin{proof}
 We proceed by induction on $N$. The case $N=1$ follows from \cite[Satz 1]{Faltings} in equal characteristic and Theorem \ref{thm:cdbound} in unramified mixed characteristic. For $N>1,$ let $I'=I_1+\dots+I_{N-1}$, $I=I'+I_N$ and $J=I_1\cap I_t+\dots+I_{N-1}\cap I_N$. Note that each $I_j\cap I_t$ has big height at most $c$ by Remark \ref{rmk:bight}. As $\sqrt{J}=\sqrt{I'\cap I_N}$, the Mayer-Vietoris sequence for local cohomology yields $$\cdots\to H_J^{i-1}(A)\to H_I^{i}(A)\to H_{I'}^{i}(A)\oplus H_{I_N}^{i}(A)\to \cdots$$ 
 For $i>d-\floor*{\frac{d-1}{c}}+N-1$, $H_J^{i-1}(A)=H_{I'}^{i}(A)=H_{I_N}^{i}(A)=0$ by the induction hypothesis. Hence, $H_I^i(A)=0$ for $i>d-\floor*{\frac{d-1}{c}}+N-1$.
\end{proof}

\begin{theorem}[cf. {\cite[Theorem 5.2]{HunLyu}}]\label{thm:example}
 Let $(A,\mathfrak{m})$ be a $d$-dimensional regular local ring of equal characteristic or unramified mixed characteristic. Let $c<d$ be a positive integer and set $N=\floor*{\frac{d-1}{c}}$. Let $I_1,\dots,I_N$ be ideals of $A$ of big height at most $c$ such that $\Spec(A/(I_1+\dots+I_N))-\{\mathfrak{m}\}$ is disconnected. Then $\cd(A,I_1\cap\dots\cap I_N)=d-N.$ 
\end{theorem}
\begin{proof} 
 If $(B,\mathfrak{n})$ is a faithfully flat $A$-algebra with zero-dimensional fiber, then $\bight(I_jB)=\bight(I)$ (Lemma \ref{lemma:fflat}) and $\Spec(B/(I_1B+\cdots+I_NB)-\{\mathfrak{n}\}$ is disconnected. Hence, we may assume that $A$ has separably closed residue field.

\begin{example}[{\cite[Example 5.4]{HunLyu}}]
 Let $(A,\mathfrak{m})$ be a $d$-dimensional regular local ring of equal characteristic or unramified mixed characteristic. Suppose $P_1,\dots,P_5$ are prime ideals of $A$ of height $c$ such that $\floor*{\frac{d-1}{c}}=2.$ Further, suppose that $P_i+P_j+P_k$ is $\mathfrak{m}$-primary iff $$\{i,j,k\}\in\Lambda=\{(1,3,4),(1,3,5),(1,2,5),(2,3,4),(2,4,5)\}.$$ Let $I=P_1\cap\cdots\cap P_5.$
 For instance, we may consider $A=V[[x_2,\dots,x_9]]$, where $V$ is a discrete valuation ring with uniformizer $p$ and separably closed residue field, and $$P_1=(p,x_2,x_3,x_4), \;P_2=(x_3,x_4,x_5,x_6),\; P_3=(x_5,x_6,x_7,x_8),$$ $$P_4=(p,x_2,x_8,x_9) \text{ and } P_5=(x_6,x_7,x_8,x_9).$$
 Note that $\Lambda$ has the property that each $i$, $1\leq i\leq5$ appears no more than thrice and each pair $(i,j)$ appears no more than twice. This implies that we cannot split $\{1,\dots,5\}$ into three distinct subsets $S_0$, $S_1$ and $S_2$ such that $P_i+P_j+P_k$ is $\mathfrak{m}$-primary for all $i\in S_0$, $j\in S_1$, $k\in S_2$. Hence, we are unable to apply the result of Example \ref{example:sharpness}.

\begin{theorem}[{\cite[Theorem 3.8]{HunLyu}}]\label{thm:HunLyu_irred}
 Let $A$ be a $d$-dimensional regular local ring of equal characteristic and $I$ be a formally geometrically irreducible ideal of $A$ of big height $c$. Suppose $0<c<d.$ Then $$\cd(A,I)\leq d-1-\floor*{\frac{d-2}{c}}.$$
\end{theorem}

\begin{question}\label{question:irredbound}
 Let $A$ be a $d$-dimensional regular local ring of unramified mixed characteristic and $I$ be a formally geometrically irreducible ideal of $A$ of big height $c$. Suppose $0<c<d$. Is $$\cd(A,I)\leq d-1-\floor*{\frac{d-2}{c}}?$$
\end{question}

\begin{example}\label{example:sharpness}
    Given an unramified regular local ring $(A,\mathfrak{m})$ of dimension $d>0$ and a positive integer $c\leq d$, there exists an ideal $I$ of $A$ such that $\cd(A,I)=d-\floor*{\frac{d-1}{c}}.$ We construct this ideal as in \cite{Lyu2}. 

    Let $N=\floor*{\frac{d-1}{c}}.$ Let $I_0,\dots,I_N$ be ideals of pure height $c$ in $A$ such that $I_0+\dots+I_N$ is $\mathfrak{m}$-primary and let $I=I_0\cap\dots\cap I_N$. Then $\cd(A,I)=d-N.$ The proof of this statement is identical to \cite{Lyu2}.

    To resolve any conflict with the previous remark, we show that in this example, if $p\in I$, then $\floor*{\frac{d-2}{c-1}}= \floor*{\frac{d-1}{c}}.$ Indeed, if $p\in I,$ we have $p\in I_j$ for all $j\in\{0,\dots,N\}$ and by Theorem \ref{thm:Serre}, $$d=\height(I_0+\dots+I_N)\leq 1+(N+1)(c-1)=Nc+c-N.$$ Let $d-1=Nc+k$, where $0\leq k<c$. Then the above equation yields $N+k+1\leq c$, or $N+k-1\leq c-2$. Observe that $$d-2=N(c-1)+N+k-1,$$ and hence, $\floor*{\frac{d-2}{c-1}}=N=\floor*{\frac{d-1}{c}}$. 
\end{example}

\begin{theorem}\label{thm:cdbound}
    Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$
\end{theorem}

\begin{theorem}\label{thm:induction}
    Let $(A,\mathfrak{m},k)$ be an unramified regular local ring of mixed characteristic $(0,p)$, and let $I$ be an ideal of $A$. Suppose $\height(I)<\height(I:(I:p))$ (for example, this holds if $p$ is a nonzerodivisor on $A/I)$.\footnote{We use the convention that $\height(A)=\infty.$}

    Set $c=\bight(I)$. Let $n>c$ be an integer. Assume that for all integers $s$, with $1\leq s\leq c-1,$ and for all $q\geq n-s$, $H^q_{IA_P}(A_P)=0$ for all $P\in \Spec(A)$ such that $I\subseteq P$ and $\dim(A/P)\geq s+1.$ Then $H^q_I(A)=0$ for all $q\geq n.$
\end{theorem}

