The following is an explicit formula from \cite[Theorem 5.12]{IK}.
\begin{proposition} \label{prop: explicit}
 Let $\phi$ be an even Schwartz function whose Fourier transform is compactly supported.
 Under the generalized Riemann hypothesis for $L(f, s)$, 
 \begin{align*}
 \sum_{\rho} \phi \lbrb{ \gamma \frac{\log X}{2 \pi}}
 &= \widehat{\phi}(0) \frac{\log \ff(f)}{\log X}
 - \frac{1}{\log X} \sum_n \lbrb{\frac{\Lambda_n(f) + \Lambda_n(\overline{f}) }{\sqrt{n}}} \widehat{\phi}\lbrb{\frac{\log n}{\log X}}\\
 &+ \frac{1}{2 \pi} \int^{\infty}_{-\infty} \lbrb{\frac{\gamma'}{\gamma}\left(f, \frac{1}{2} + it\right) + \frac{\gamma'}{\gamma}\left(\overline{f}, \frac{1}{2} + it \right)} \phi\lbrb{\frac{t\log X}{2 \pi}} dt
 \end{align*}
 where $\rho = \frac{1}{2} + i\gamma$ is taken over non-trivial zeros of $L(f, s)$.
\end{proposition}

\begin{proposition}
Assume the generalized Riemann hypothesis for the family $\lcrc{C_d/\bQ : d \in S(X)}$. Let $\phi$ be a positive test function whose Fourier transform is compactly supported. Then,
\begin{align} \label{eqn: average rank bound}
 \frac{1}{|S(X)|} \sum_{d \in S(X)} g_d \leq (6+o(1))\frac{ \widehat{\phi}(0)}{\phi(0)} - \frac{1}{\phi(0)}S_1 - \frac{1}{\phi(0)}S_2 + O\lbrb{\frac{1}{\log X}}.
\end{align}
\end{proposition}
\begin{proof}
We note that $\gamma(f, s)$ is a product of an exponential function $\pi^{-\frac{ks}{2}}$ for some $k \in \bZ$ and the Gamma functions (cf. \cite[(5.3)]{IK}).
Therefore
\begin{align*}
 \frac{1}{2 \pi} \int^{\infty}_{-\infty} \lbrb{\frac{\gamma'}{\gamma}\left(f, \frac{1}{2} + it\right) + \frac{\gamma'}{\gamma}\left(\overline{f}, \frac{1}{2} + it\right)} \phi\lbrb{\frac{t\log X}{2 \pi}} dt \ll \frac{\log \log X}{\log X}.
\end{align*}
On the other hand, the Weil bound for genus $2$ curves gives that $|\Lambda_{p^k}(C_d)| \leq 4\log p$, which gives
\begin{align*}
 \frac{1}{\log X} \sum_{\substack{n = p^k \\ k \geq 3}} \lbrb{\frac{\Lambda_n(C_d) + \overline{\Lambda_n(C_d)} }{\sqrt{n}}} \widehat{\phi}\lbrb{\frac{\log n}{\log X}} \ll \frac{1}{\log X}.
\end{align*}

\begin{lemma}
