	\left|\left\{x\in\R^d:\;\lambda(N_\lambda(T_{\Omega,\epsilon}f(x)))^\frac{1}{\rho}>\alpha\right\}\right|\lesssim\frac{\|f\|_1}{\alpha},\quad\text{for}\;\rho>2.\label{weak:jump}
\end{align}

Campbell, Jones, Reinhold and Wierdl~\cites{CJRRW2000,CJRW2003} investigated the $L^p-$bounds of variational and jump inequalities for the family $\{T_{\Omega,\epsilon}:\;\epsilon\in (0,\infty)\}$. In particular, they proved the following bounds for $\Omega\in L\log L(\Sp^{d-1})$ and $1<p<\infty$:
\begin{align}
 \left\|V_q(T_{\Omega,\epsilon}f)\right\|_p\lesssim\|f\|_p,\quad\text{for}\;q>2,\label{strong:var}\\
 \left\|\lambda(N_\lambda(T_{\Omega,\epsilon}f))^\frac{1}{\rho}\right\|_p\lesssim\|f\|_p,\quad\text{for}\;\rho>2.\label{strong:jump}
\end{align}
Jones, Seeger and Wright \cite{JSW2008} established the strong type inequality \eqref{strong:jump} at the critical case $\rho=2$ for $\Omega\in L^r(\Sp^{d-1}),\;1<r\leq\infty$. The estimate \eqref{strong:jump} for $\rho=2$ and $\Omega\in L\log L(\Sp^{d-1})$ was obtained by Ding, Hong and Liu~\cite{DHL2017}.

The main distinction between the short and long jumps is the presence of multiscale analysis in the estimate for the long jump. The estimate for the short jumps relies on a single scale argument reminiscent of the ideas developed in \cite{CJRW2003}. In contrast, the estimates for the long jumps are based on an algorithm that controls the interaction of scales, pioneered in the work of Krause and Lacey \cite{KL2018,KL2020} for obtaining sparse bounds for maximal truncations of oscillatory Calder\'on-Zygmund operators. We also refer to \cite{IKM2025} for a simplified approach to proving endpoint estimates for such maximal oscillatory operators in dimension one.

We have the following estimates, which is essentially an amalgamation of Lemmas 2.1 and 2.2 in \cite{Seeger1996}.
 \begin{lemma}[\cite{Seeger1996}]\label{lemma:Seeger}
 Let $\alpha>0$ and $\mathcal{Q}$ be a collection of cubes with disjoint interior such that for each $Q\in\mathcal{Q}$ there exists a function $b_Q\in L^1(Q)$ such that
 \[\int|b_Q(x)|dx\leq\alpha|Q|.\]
 Let $B^k=\sum_{Q\in\mathcal{Q}:|Q|=2^{dk}}b_Q$. Then, for $s\geq5$, we have
 \[\left\|\sum_{j\in\Z}\Gamma_j^s*B^{j-s}\right\|_2^2\lesssim\mathscr{M}^22^{-s(1-\kappa)}\alpha\sum_{Q\in\mathcal{Q}}\|b_Q\|_1.\]
 Moreover, if $\int b_Q=0$ for each $Q\in\mathcal{Q}$. Then, for $N\geq d+1$ and $0\leq\kappa'\leq1$, we have
 \[\left\|\sum_{j\in\Z}(H_j-\Gamma_j^s)*B^{j-s}\right\|_1\lesssim\mathscr{M}(2^{-s\kappa'}+2^{s(d+(\kappa'-\kappa)N)})\sum_{Q\in\mathcal{Q}}\|b_Q\|_1.\]
 \end{lemma}
 We combine the $L^1$ and $L^2$ estimates in \Cref{lemma:Seeger} into a single $L^2$ estimate in the following manner. 
 \begin{lemma}\label{lemma:Seegercombined}
 Let $\alpha>0$ and $\mathcal{Q}$ be a collection of cubes with disjoint interior such that for each $Q\in\mathcal{Q}$ there exists a function $b_Q\in L^1(Q)$ such that
 \[\int|b_Q(x)|dx\leq\alpha|Q|.\]
 Let $B_k=\sum_{Q\in\mathcal{Q}:|Q|=2^{dk}}b_Q$. Then, there exists $\delta>0$ such that for $s\geq5$, we have
 \[\left\|\sum_{j\in\Z}H_j*B^{j-s}\right\|_2^2\lesssim\mathscr{M}^22^{-s\delta}\alpha\sum_{Q\in\mathcal{Q}}\|b_Q\|_1.\]
 \end{lemma}
 \begin{proof}
 We write 
 \begin{align*}
 \sum_{j\in\Z}H_j*B^{j-s}=\sum_{j\in\Z}\Gamma_j^s*B^{j-s}+\sum_{j\in\Z}(H_j-\Gamma_j^s)*B^{j-s}=:A+B.
 \end{align*}
 We observe that
 \begin{align*}
 \int|(A+B)(x)|^2dx&=\left(\int_{|B(\cdot)|\leq2^{\rho s}\alpha}+\int_{|A(\cdot)|>2^{\rho s-1}\alpha}+\int_{|(A+B)(\cdot)|>2^{\rho s-1}\alpha}\right)|(A+B)(x)|^2dx\\
 &=:I+II+III
 \end{align*}
 \textit{Estimate for I:} By \Cref{lemma:Seeger} with $\kappa=\frac{1}{2},\;\kappa'=\frac{1}{4},\;N=4d+1$, we have
 \begin{align*}
 I&\lesssim \int|A(x)|^2dx+\int_{|B(\cdot)|\leq2^{\rho s}\alpha}|B(x)|^2dx\\
 &\lesssim\int|A(x)|^2dx+2^{\rho s}\alpha\int_{|B(\cdot)|\leq2^{\rho s}\alpha}|B(x)|dx\\
 &\lesssim\mathscr{M}^22^{-\frac{s}{8}}\alpha\sum\|b_Q\|_1,
 \end{align*}
 where we used $\rho$ such that $\rho<\frac{1}{8}$. To estimate $II$ and $III$, we will need the following claim:
 \begin{equation}\label{claim:sublevel}
 \left|\left\{x\in\R^d:|\sum_{j\in\Z}H_j*B^{j-s}|>\lambda\alpha\right\}\right|\lesssim \frac{\mathscr{M}}{\lambda^3\alpha}\sum\|b_Q\|_1,\quad\text{for}\;\lambda>0.
 \end{equation}
 Assuming the above estimate, we estimate $II$ and $III$.

\textit{Estimate for $II$:} By Chebyshev's inequality, \Cref{lemma:Seeger} ($\kappa=\frac{1}{2}$) and \eqref{claim:sublevel}, we have
 \begin{align*}
 II&\lesssim\int_{0}^\infty\min\left\{\left|\left\{|A(x)|>2^{\rho s-1}\alpha\right\}\right|,\left|\left\{|(A+B)(x)|>\lambda\right\}\right|\right\}\lambda d\lambda\\
 &\lesssim\int_{0}^{2^{\rho s}\alpha}\left|\left\{|A(x)|>2^{\rho s-1}\alpha\right\}\right|\lambda d\lambda+\int_{2^{\rho s}\alpha}^{\infty}\left|\left\{|(A+B)(x)|>\lambda\right\}\right|\lambda d\lambda\\
 &\lesssim\|A\|_2^2+\mathscr{M}\alpha^2\sum\|b_Q\|_1\int_{2^{\rho s}\alpha}^{\infty}\frac{d\lambda}{\lambda^2}\\
 &\lesssim\mathscr{M}^2\alpha2^{-\frac{s}{8}}\sum\|b_Q\|_1.
 \end{align*}
 \textit{Estimate for $III$:} It is not difficult to see that an application of \eqref{claim:sublevel} implies that 
 \begin{align*}
 II&\lesssim\int_{0}^\infty\left|\left\{|(A+B)(x)|>\max\{\lambda,2^{\rho s-1}\alpha\}\right\}\right|\lambda d\lambda\lesssim\mathscr{M}^2\alpha2^{-\frac{s}{8}}\sum\|b_Q\|_1.
 \end{align*}
 We now prove \eqref{claim:sublevel}. We choose a smooth and positive function $\nu_0$ supported in $\{2^{-2}\leq|x|\leq2^2\}$ such that $\|\nu_0\|_\infty,\|\nu_0\|_1\leq10^d\mathscr{M}$ and $H_0(x)\leq\nu_0(x)$. We will prove \eqref{claim:sublevel} for $\nu_j(x)=2^{-jd}\nu(2^{-j}x)$ instead of $H_j$ and \eqref{claim:sublevel} will be a consequence. We note that the estimate \eqref{claim:sublevel} follows from the following two estimates
 \begin{align}
 &\left\|\sum_{j\in\Z}\nu_j*B^{j-s}\right\|_1\lesssim\mathscr{M}\sum\|b_Q\|_1,\label{est:claim1}\\
 &\left\|\sum_{j\in\Z}\nu_j*B^{j-s}\right\|_{BMO}\lesssim\mathscr{M}\alpha.\label{est:claim2}
 \end{align}
 Indeed, by Chebyshev's inequality and interpolation, we have that
 \begin{align*}
 \left|\left\{x\in\R^d:|\sum_{j\in\Z}H_j*B^{j-s}|>\lambda\alpha\right\}\right|&\lesssim\frac{1}{(\lambda\alpha)^3}\left\|\sum_{j\in\Z}\nu_j*B^{j-s}\right\|_3^3\\
 &\lesssim\frac{\mathscr{M}}{(\lambda\alpha)^3}\left[\left(\sum\|b_Q\|_1\right)^\frac{1}{3}\alpha^\frac{2}{3}\right]^3\\
 &\lesssim\frac{\mathscr{M}}{\lambda^3\alpha}\sum\|b_Q\|_1.
 \end{align*}
 The estimate \eqref{est:claim1} is easy to verify.

We will provide the proof for inequality \eqref{est:claim2}. First, we observe that by the disjointness of the collection $\mathcal{Q}$, for any $F\subset\R^d$, we have
 \begin{align}\label{est:suppcalculation}
 \sum_{j\in\Z}\|B^{j-s}\chi_F\|_1\sum_{Q\in\mathcal{Q}:Q\cap F\neq\emptyset}\alpha|Q|\leq\alpha|F|.
 \end{align}
 Now, we fix a cube $R\subset\R^d$, we write
 \begin{align*}
 &\frac{1}{|R|}\int_R\left|\sum_{j\in\Z}\nu_j*|B^{j-s}|(x)-\frac{1}{|R|}\int_R\sum_{2^j\geq\ell(R)}\nu_j*|B^{j-s}|(y)dy\right|dx\\
 \leq&\frac{1}{|R|}\int_R\left|\sum_{2^j\geq\ell(R)}\nu_j*|B^{j-s}|(x)-\frac{1}{|R|}\int_R\sum_{2^j\geq\ell(R)}\nu_j*|B^{j-s}|(y)dy\right|dx+\frac{1}{|R|}\int_R\left|\sum_{2^j<\ell(R)}\nu_j*|B^{j-s}|(x)\right|dx\\
 =:&S_1+S_2.
 \end{align*}
 By mean value theorem and local support of the functions, we have
 \begin{align*}
 S_1&\lesssim\frac{1}{|R|}\int_R\sum_{2^j\geq\ell(R)}2^{-j}\ell(R)\|(\nabla\nu)_j\|_\infty\|B^{j-s}\chi_{B(c_R,2^{j+3})}|\|_1dx\\
 &\lesssim\sum_{2^j\geq\ell(R)}2^{-j}\ell(R)2^{-jd}\mathscr{M}\alpha|B(c_R,2^{j+3})|\\
 &\lesssim\mathscr{M}\alpha,
 \end{align*}
 where $C_R$ is the center of the cube $R$ and we used \eqref{est:suppcalculation} in the second step.

post_theorem_intro_text:
By a standard limiting argument, \Cref{mainthm} recovers the weak $(1,1)-$boundedness of $T_\Omega^*$ proved recently by Lai~\cite{Lai2025}.
\subsection*{Methodology of the proof of \Cref{mainthm}:} We first note that by \cite[Lemma 2.3]{MSZ2020}, the weak type $(1,1)$ estimate \eqref{main:var} for the $q-$variation operator will follow from the corresponding weak type estimate \eqref{main:jump} involving the jump function. Further, it is well known that in order to prove \eqref{main:jump}, it is enough to consider the short and long jump operators separately via the inequality \eqref{shortlong}. In both the cases, the variational Rademacher-Menshov theorem is a key ingredient. This result was first obtained in \cite{LL2012}. We will use the following version of the variational Rademacher-Menshov theorem from \cite[Lemma 7.2]{DOP2017}.
\begin{lemma}[\cite{DOP2017}]\label{VarRM}
	Let $\{F_i\}_{i=1}^N$ be a sequence of functions on a measure space $X$ such that for all $\varepsilon_i\in\{-1,0,1\}$, we have
	\begin{equation*}
		\left\|\sum_{i=1}^N\varepsilon_iF_i\right\|_2\leq B.
	\end{equation*}
	Then, the following estimate holds 
	\begin{equation*}
		\left\|V_2\left(\sum_{i=1}^nF_i:1\leq n\leq N\right)\right\|_2\lesssim (\log N) B.
	\end{equation*}
\end{lemma}
The second ingredient consists of microlocal estimates of Seeger \cite{Seeger1996}. Our task is to  combine the $L^1$ and $L^2$ estimates of Seeger \cite{Seeger1996} into a single $L^2$ estimate. This step relies on a careful interpolation argument, motivated by the approach in \cite{Honzik2020}. We provide the details of this estimate in \Cref{sec:microlocal}. 

The main distinction between the short and long jumps is the presence of multiscale analysis in the estimate for the long jump. The estimate for the short jumps relies on a single scale argument reminiscent of the ideas developed in \cite{CJRW2003}. In contrast, the estimates for the long jumps are based on an algorithm that controls the interaction of scales, pioneered in the work of Krause and Lacey \cite{KL2018,KL2020} for obtaining sparse bounds for maximal truncations of oscillatory Calder\'on-Zygmund operators. We also refer to \cite{IKM2025} for a simplified approach to proving endpoint estimates for such maximal oscillatory operators in dimension one. 

In the process of adapting the ideas of \cite{KL2020}, we streamline certain aspects of their proof. First, we do away with the recursion argument employed there. Second, we introduce an effective decomposition of the bad functions based on the shifted dyadic grids. This allows us to use the $L^2-$bounds (\Cref{lemma:Seegercombined}) as a blackbox instead of arduously reproving similar estimates for a localised version of the truncations of rough singular integrals. As a consequence, this approach provides us with a new and simpler proof of the weak $(1,1)-$boundedness of $T_\Omega^*$. The proof of \Cref{mainthm} \eqref{main:jump} is given in \Cref{sec:proofmain}.

