\subsection{Conformal Risk Control is Stable for Monotonic Losses}

\subsubsection{General Bounded Losses}
\label{sec:general-bounded}
To handle general losses bounded in $[0,1]$, we will use algorithms that discretize $\Theta$ to impose stability.
First, let $\A(D) = \inf\{\theta \in \Theta_m = \{0, \tfrac{1}{m}, \tfrac{2}{m}, \ldots, 1\} : \hat{R}_D(\theta) \leq \alpha\}$ for $\Theta = [0,1]$ and any positive integer $m$.
This is simply the discretized version of the previously studied algorithms.
We will assume nothing about the loss other than the existence of a safe solution, $\ell(z;1)=0$ for all $z \in \cX\times\cY$.
\begin{proposition}
\label{prop:general-stability}
Let $D_{1:n+1}$ be sampled i.i.d., $\Theta_m=\{0,\tfrac1m,\ldots,1\}$, $\ell(\cdot;1)=0$, and define
\begin{equation}
\A(D)\ :=\ \inf\bigl\{\theta\in\Theta_m:\ \hat R_D(\theta)\le \alpha\bigr\}.
\end{equation}
Then
\begin{equation}
\E\bigl[R(\thetahat_{n})\bigr]\ \leq\ \alpha+\frac{1}{2\sqrt{n}}\left(\sqrt{-W_{-1} \left( -\frac{1}{4n(m+1)^2}\right)}+\sqrt{-\frac{1}{W_{-1} \left( -\frac{1}{4n(m+1)^2}\right)}}\right) = \alpha + \tilde{\mathcal{O}}\left(\frac{1}{\sqrt{n}}\right),
\end{equation}
where $W_{-1}$ is the $-1$st branch of the Lambert W function and $\tilde{\mathcal{O}}$ denotes the growth rate excluding logarithmic factors.
\end{proposition}
This proposition tells us that we can achieve risk control for general losses with the discretized algorithm up to a dominating factor of $\tilde{\mathcal{O}}\left(\tfrac{1}{\sqrt{n}}\right)$, since $W_{-1}$ is of logarithmic order.

\begin{proposition}
 \label{prop:stability-selective}
 The selective classification algorithm in~\eqref{eq:leftmost-root} is $\beta$-stable with
 \begin{equation}
 \beta = \frac{2\max\{\alpha, 1-\alpha\}\E[K]}{n+1}, \text{ where } K = \max_i|\hat{\jmath}_{-i} - \hat{\jmath}_{n+1}|.
 \end{equation}
\end{proposition}
\begin{proof}
 By~\eqref{eq:selective-eq-neq}, it suffices to prove that, almost surely,
 \begin{equation}
 \sum\limits_{i=1}^{n+1} \Big(\ell(X_{i}, Y_{i}; \A(D_{-i})) - \ell(X_{i}, Y_{i}; \A^*(D_{1:n+1}))\Big) = \sum_{i\in [n+1]} w_i\Delta_i
 \leq 2\max\{\alpha, 1-\alpha\}K,
 \end{equation}
 where $\Delta_i = \ind{\A(D_{-i}) \geq \hat P_i} - \ind{\A^*(D_{1:n+1}) \geq \hat P_i}$ and $w_i = \alpha$ for $i \in V^{=}$ and $-(1-\alpha)$ otherwise.
 We can begin by rewriting the $\Delta_i$ terms as 
 \begin{align}
 \Delta_i &= \ind{\A(D_{-i}) \geq \hat{P}_i > \A(D_{1:n+1})} - \ind{\A(D_{-i}) < \hat{P}_i \leq \A(D_{1:n+1})} \\
 &= \ind{\hat{\jmath}_{-i} \leq V_i < \hat{\jmath}_{n+1}} - \ind{\hat{\jmath}_{-i} > V_i \geq \hat{\jmath}_{n+1}}.
 \end{align}
 Note that the two events inside the indicators are mutually exclusive, and correspond to the ``crossing'' of $\A(D_{-i})$ over $\hat{P}_i$ in the downward or upward directions.
 Therefore,
 \begin{equation}
 \label{eq:pf-selective-cauchy-schwarz}
 \sum_{i\in [n+1]} w_i\Delta_i \leq \max\{\alpha, 1-\alpha\} \sum_{i\in [n+1]}|\Delta_i| \leq \max\{\alpha, 1-\alpha\}\left|\{i : \hat{\jmath}_{-i} \leq V_i < \hat{\jmath}_{n+1} \text{ or } \hat{\jmath}_{-i} > V_i \geq \hat{\jmath}_{n+1}\} \right|.
 \end{equation}
 Define the index sets
\[
S_- \;:=\; \bigl\{i\in[n{+}1]:\ \hat{\jmath}_{-i}\le V_i<\hat{\jmath}_{n+1}\bigr\}
\quad\text{and}\quad
S_+ \;:=\; \bigl\{i\in[n{+}1]:\ \hat{\jmath}_{-i}> V_i\ge \hat{\jmath}_{n+1}\bigr\}.
\]
Then the set of indices that contribute nonzero terms to $\sum_{i\in[n+1]}|\Delta_i|$ is $S:=S_-\cup S_+$, and $S_-\cap S_+=\varnothing$ by definition.

\subsubsection{Risk Control Guarantees on the Loss}
First, we show the stability of ERM on the scale of the loss.
\begin{proposition}
\label{prop:erm-stable-loss}
Let $\Theta=\R^d$, $\ell$ be convex in $\theta$, and assume there exists $\rho:\cZ\to[0,\infty)$ such that for all $z\in\cZ$ and $\theta,\theta'\in\R^d$,
\begin{equation}
\label{eq:lipschitz-rho-simple}
|\ell(z;\theta)-\ell(z;\theta')|\ \le\ \rho(z)\,\|\theta-\theta'\|_2.
\end{equation}
Then $\A$ is $\beta$-stable with
\begin{equation}
\label{eq:beta-simple}
\beta \leq \frac{2\,\E[\rho(Z_{n+1})^2]}{\lambda(n+1)}.
\end{equation}
\end{proposition}
This result can be used in conjunction with Theorem~\ref{thm:main-intro} to give a generalization guarantee on ERM, as below.
\begin{corollary}
 In the setting of Proposition~\ref{prop:erm-stable-loss},
 \begin{equation}
 \E\left[ \ell(X_{n+1}, Y_{n+1}; \thetahat_n) + \tfrac{\lambda}{2}\|\thetahat_n\|_2^2 \right] \leq R^* + \frac{2\,\E[\rho(Z_{n+1})^2]}{\lambda(n+1)},
 \end{equation}
 where $R^* = \min_{\theta \in \Theta} \E[\ell(X_{n+1},Y_{n+1};\theta)+ \tfrac{\lambda}{2}\|\theta\|_2^2]$.
\end{corollary}
These results represent minor variations on the canonical results in Section 5 of~\cite{bousquet2002stability}.

Next, we address stability of the expected gradient.
Building towards this, we will need a multivariate notion of stability to handle gradients when $d>1$: an algorithm $\cA$ is $\beta$-stable with respect to $\A^*$ and $g$ if
\begin{equation}
 \E\left[\frac{1}{n+1}\sum\limits_{i=1}^{n+1} g(X_{i}, Y_{i}; \A(D_{-i}))\right] 
 \preceq \E\left[\frac{1}{n+1}\sum\limits_{i=1}^{n+1} g(X_{i}, Y_{i}; \A^*(D_{1:n+1}))\right] + \beta,
\end{equation}
where $\beta \in \R^d$, and $\preceq$ represents the standard partial ordering on vectors (i.e., the inequality holds component-wise).
Theorem~\ref{thm:main-intro} also has an extension to $d>1$, which we present below.
\begin{theorem}
 \label{thm:main-high-d}
 Assume $\A$ is symmetric and $\beta$-stable with respect to $\A^*$ and $g$, that $D_{1:n+1}$ is exchangeable, and that
\begin{equation}
 \E\left[g(X_{n+1}, Y_{n+1}; \A^*(D_{1:n+1})) \right] \preceq \alpha-\beta.
\end{equation}
 Then
 \begin{equation}
 \E\left[g(X_{n+1}, Y_{n+1}; \A(D_{1:n})) \right] \preceq \alpha.
 \end{equation}
\end{theorem}
The proof of this theorem is identical to that of Theorem~\ref{thm:main-intro}, except with $\preceq$ in place of $\leq$.
Now we proceed with the stability result, stated below for differentiable convex losses. The differentiability is not needed, and is only used to simplify the statement and proof of the proposition.
\begin{proposition}
\label{prop:erm-grad-stability}
Assume $\ell$ is a convex, differentiable function of $\theta$ and that there exists a measurable function $\rho : \cZ \to [0,\infty)$ such that for all $\theta,\theta' \in \R^d$ and almost all $z \in \cZ$,
\begin{equation}
\|\nabla\ell(z;\theta) - \nabla\ell(z;\theta')\|_2 \leq \rho(z)\|\theta - \theta'\|_2.
\end{equation}
Assume also that $\hat{R}_{1:n+1}$ is $\mu$-strongly convex for some $\mu \in [0,\infty)$ (noting that $\mu=0$ is also allowable, so it need not be strongly convex).
Then the regularized ERM algorithm $\cA$ is $\beta$-stable with respect to $\nabla\ell$, where
\begin{equation}
\beta = \frac{\E[\rho(Z_{n+1})\|\nabla\ell(Z_{n+1}; \thetahat_n)\|_2] + \E\left[\rho(Z_{n+1})\|\tfrac{1}{n}\sum_{j=1}^n\nabla\ell(Z_j;\thetahat_n)\|_2\right]}{(\mu + \lambda)(n+1)} \mathbf{1}_d.
\end{equation}
\end{proposition}
Eliding the Lipschitz constant $\rho(Z_{n+1})$, this result tells us that ERM is stable with
\begin{equation}
 \beta = \frac{\E[\text{magnitude of test gradient}] + \E[\text{magnitude of training gradient}]}{(\mu + \lambda)(n+1)}.
\end{equation}
Under normal circumstances, both terms in the numerator will be constant-order, and the latter term will be near-zero (in fact, when $\lambda=0$, it is exactly zero).
Proposition~\ref{prop:erm-grad-stability} also holds for nondifferentiable losses, replacing every gradient in $\beta$ with a supremum over all subgradients in the subdifferential at $\thetahat_{n}$; the proof of this more general result is morally the same, so we omit it.
The assumption that $\hat{R}_{1:n+1}$ is strongly convex is weaker than strong convexity of the loss function itself, and allows for, e.g., ordinary least squares with a full-rank design matrix, even though the individual losses may not be strongly convex.

post_theorem_intro_text:
Theorem~\ref{thm:main-intro} gives us an actionable workflow for producing risk-control algorithms.
First, we try to identify a reference algorithm, $\mathcal{A}^*$, that controls the risk when applied on the full dataset of $n+1$ datapoints.
Then, we try to approximate that algorithm via $\mathcal{A}$, which runs only on $n$ datapoints, and prove that the difference in risks between these two algorithms is low.
The proof of the main result is below. 
\begin{proof}
By exchangeability and symmetry,
\[
\mathbb{E}\!\left[\frac{1}{n+1}\sum_{i=1}^{n+1}\ell(X_i,Y_i;\mathcal{A}^*(D_{1:n+1}))\right]
= \mathbb{E}\!\left[\ell(X_{n+1},Y_{n+1};\mathcal{A}^*(D_{1:n+1}))\right],
\]
and
\[
\mathbb{E}\!\left[\frac{1}{n+1}\sum_{i=1}^{n+1}\ell(X_i,Y_i;\mathcal{A}(D_{-i}))\right]
= \mathbb{E}\!\left[\ell(X_{n+1},Y_{n+1};\mathcal{A}(D_{1:n}))\right].
\]
By $\beta$-stability, $\mathbb{E}\!\left[\ell(X_{n+1},Y_{n+1};\mathcal{A}(D_{1:n}))\right] \leq \mathbb{E}\!\left[\ell(X_{n+1},Y_{n+1};\mathcal{A}^*(D_{1:n+1}))\right] + \beta$.
Combining this with the assumption that $\mathbb{E}[\ell(X_{n+1},Y_{n+1};\mathcal{A}^*(D_{1:n+1}))] \leq \alpha-\beta$ yields the result.
\end{proof}
Notice that Theorem~\ref{thm:main-intro} applies to $\theta$ in any space, and that boundedness of $\ell$ was never needed in the proof of Theorem~\ref{thm:main-intro}.
These concerns will come up later in determining stability bounds, building on the literature on algorithmic stability~\cite{kearns1997algorithmic, bousquet2002stability, kutin2002almost, mukherjee2006learning, shalev-shwartz2010learnability, yu2013stability, hardt2016train, yu2017three, feldman2018generalization, bousquet2020sharper, zrnic2023post}; see Chapter 13 of~\cite{shalev-shwartz2014understanding} for a review of this extensive field.
The notion of stability used herein is a form of leave-one-out stability with respect to generic algorithms $\cA$ and $\cA^*$; we will prove guarantees for a few different choices of algorithms depending on the setting.

\subsection{Conformal Risk Control is Stable for Monotonic Losses}

Here we will show that the conformal risk control algorithm is stable for monotonic losses, and thus, satisfies the guarantee in Theorem~\ref{thm:main-intro}.

\begin{proposition}
    \label{prop:crc-stable}
    Let $d=1$, $D$ be any dataset, $\ell$ be nonincreasing in its last argument, 
    \begin{equation}
        \mathcal{A}(D) = \inf\left\{ \theta : \frac{1}{|D|+1}\sum_{(x,y) \in D}\ell(x,y;\theta) \leq \alpha - \frac{1}{|D|+1} \right\}, 
    \end{equation}
    and
    \begin{equation}
        \mathcal{A}^*(D) = \inf\left\{ \theta : \frac{1}{|D|}\sum_{(x,y) \in D}\ell(x,y;\theta) \leq \alpha \right\}.
    \end{equation}
    Then $\mathcal{A}$ is $0$-stable with respect to $\mathcal{A}^*$.
\end{proposition}
\begin{proof}
    The boundedness of $\ell$ and definition of $\mathcal{A}$ imply that for all $i$,
    \begin{equation}
        \frac{1}{n+1}\sum_{j=1}^{n+1}\ell(X_j,Y_j;\mathcal{A}(D_{-i})) \leq \frac{1}{n+1}\sum_{j \in [n+1] \setminus i} \ell(X_j,Y_j;\mathcal{A}(D_{-i})) + \frac{1}{n+1} \leq \alpha.
    \end{equation}
    $\mathcal{A}(D_{-i})$ therefore satisfies the constraint in the definition of $\mathcal{A}^*(D_{1:n+1})$, and the monotonicity of the loss gives $\mathcal{A}(D_{-i}) \geq \mathcal{A}^*(D_{1:n+1})$. Therefore, $\ell(X_{i}, Y_{i}; \mathcal{A}(D_{-i})) \leq \ell(X_{i}, Y_{i}; \mathcal{A}^*(D_{1:n+1}))$, and
    \begin{equation}
        \E\left[\frac{1}{n+1}\sum\limits_{i=1}^{n+1} \Big(\ell(X_{i}, Y_{i}; \mathcal{A}(D_{-i})) - \ell(X_{i}, Y_{i}; \mathcal{A}^*(D_{1:n+1}))\Big)\right] \leq 0.
    \end{equation}
    Rearranging terms gives $0$-stability.
\end{proof}

Combining Proposition~\ref{prop:crc-stable} with Theorem~\ref{thm:main-intro} exactly recovers the classical conformal risk control guarantee.
\begin{corollary}
    The conformal risk control algorithm $\mathcal{A}$ defined in Proposition~\ref{prop:crc-stable} satisfies
    \begin{equation}
        \E\left[ \ell(X_{n+1},Y_{n+1};\mathcal{A}(D_{1:n})) \right] \leq \alpha.
    \end{equation}
\end{corollary}
\begin{proof}
    For monotonic losses, Proposition~\ref{prop:crc-stable} shows that the conformal risk control algorithm $\mathcal{A}$ is $0$-stable. Applying Theorem~\ref{thm:main-intro} with $\beta=0$ recovers the guarantee.
\end{proof}

The key takeaway is that the proof of conformal risk control's validity has two parts, which can be decoupled: (1) proving monotonicity implies stability, and (2) proving that stability implies risk control.
Theorem~\ref{thm:main-intro} tells us that (2) holds for general algorithms.
The remainder of the paper will be dedicated to replacing step (1) with other stable algorithms, in the context of non-monotonic losses.
Looking forward, Section~\ref{sec:methods} gives stability bounds for classes of non-monotonic losses and shows how to estimate these stability bounds for use in Theorem~\ref{thm:main-intro}. Section~\ref{sec:experiments} shows experimental validation of these methods.

