\label{thm:asboundsPoly}
    Let $f$ be a  Rademacher or Steinhaus random multiplicative function. In the Rademacher case, assume $P\in\mathbb Z[x]$ is a product of at least two distinct linear factors over $\mathbb Q$, or irreducible of degree $2$, taking infinitely many square-free values. In the Steinhaus case, assume $P(x)$ is not of the form $w(x+c)^d$ for $w\in\mathbb Z, c\in\mathbb Q$. Then almost surely we have $$\left\lvert\sum_{n\leq N} f(P(n))\right\rvert \ll \sqrt{N\log\log N}.$$ Moreover, almost surely there exists a sequence $N_k\to\infty$ such that 
    \begin{equation*}
        \left\lvert\sum_{n\leq N_k} f(P(n))\right\rvert\gg \sqrt{N_k\log\log N_k}.
    \end{equation*},

theorem.content:
\label{theorem:k-dim-ds}
   Let $k\geq 1$, and let $\map{\psi}{\mathbb{N}}{\left[0,1/2\right]}$ be such that $\sum_{q=1}^\infty \left(\varphi(q)\psi(q)/q\right)^k=\infty$. For $\alpha\in \left[0,1\right]^k$, denote by $S_k(\alpha,Q)$ the number of solutions $(a,q)\in\mathbb{Z}^k\times \mathbb{N}$ to the inequality:
    \begin{align*}
        \pn{q\alpha-a}{\infty} < \psi(q), \quad \text{given } q \leq Q,
    \end{align*}
    satisfying $\gcd(a_i, q)=1$, for $i\in\{1,\dots, k\}$, $a=(a_1,\dots, a_k)$. Moreover, given $Q\in \mathbb{N}$, define:
    \begin{align*}
        \Psi_k(Q)\coloneq \sum_{q\leq Q}\left(\frac{2\psi(q)\varphi(q)}{q}\right)^k.
    \end{align*}
    Then for all $\varepsilon>0$, as $Q\to \infty$, we have for almost all $\alpha$ that:
    \begin{align*}
        S_k(\alpha,Q)=\Psi_k(Q)+O_{\varepsilon,k}\left( \Psi_k(Q)^{1/2+\varepsilon} \right).
    \end{align*}

