 \pn{q\alpha-a}{\infty}< \psi(q),\label{eq:kdim-approx-ineq}
\end{align}
where $a=(a_1,\dots,a_k)$ satisfies $\gcd(a_i, q)=1$ for $i\in\{1,\dots, k\}$. When $k=1$, this is then exactly the question of the Duffin-Schaeffer conjecture. For $k\geq 2$, the question was first raised by Sprind\v{z}uk \cite{sprindzhuk1979metric}, and then resolved by Pollington and Vaughan \cite{pollington1990kdimensionalduffinschaeffer} as follows: assuming the notation and hypothesis above, there exists infinitely many solutions to the inequality \eqref{eq:kdim-approx-ineq} if and only if the sum $\sum_{q\in\N}(\psi(q)\varphi(q)/q)^k$ diverges.

Finally, we prove the variance estimate, and thus conclude the proof of our main result. The proof follows \cite{koukoulopoulos2024sharpquantitativeversionduffinschaeffer} with minor modifications.
\begin{proof}[Proof of Theorem~\ref{theorem:k-dim-variance}]
 Note that we have:
 \begin{align*}
 \lint{\left[0,1\right]^k}{}{\left(S_k(\alpha, Q)-\Psi_k(Q)\right)^2}{\alpha}= \sum_{q,r\leq Q} \lambda_k(\A_q^k \cap \A_r^k) - \Psi_k(Q)^2,
 \end{align*}
 and so we will show instead that:
 \begin{align*}
 \sum_{q,r\leq Q} \lambda_k(\A_q^k \cap \A_r^k) \leq \Psi_k(Q)^2 + \Psi_k(Q) + O_{\ep,k}(\Psi_k(Q)^{1+\ep}).
 \end{align*}
 When $q=r$, we have simply $\sum_{q\leq Q}\lambda_k(\A_q^k) = \Psi_k(Q)$. Thus, consider the sum of terms $q\neq r$, and assume that $D=D(q,r)\geq 1/2$. We consider the contributions over the following partition:
 \begin{align*}
 \E^{(1)} &\coloneq\set{(q,r)\in \left[1,Q\right]^k}{L_{D^2}(q,r)\leq \frac{1}{D},\ \omega_{D^2}(q,r)\leq \frac{\ep}{4k}\log(2D)},\\
 \E^{(2)} &\coloneq\set{(q,r)\in \left[1,Q\right]^k}{L_{D^2}(q,r)> \frac{1}{D}},\\
 \E^{(3)} &\coloneq\set{(q,r)\in \left[1,Q\right]^k}{L_{D^2}(q,r)\leq \frac{1}{D},\ \omega_{D^2}(q,r)> \frac{\ep}{4k}\log(2D)}.
 \end{align*}
 First, consider the sum over $\E^{(1)}$. Then applying Lemma~\ref{lem:k-dim-overlap} with $t=D^2$ gives:
 \begin{align*}
 \lambda_k(\A_q^k\cap\A_r^k) &\leq \lambda_k(\A_q^k)\lambda_k(\A_r^k)\me^{2k/D}\left(1+O\left(\frac{2^{\ep\log(2D)/4}\log(4D)}{D}\right)\right)\\
 &\leq \lambda_k(\A_q^k)\lambda_k(\A_r^k)\left(1+O_k(D^{-1+\ep/2})\right)
 \end{align*}
 Therefore:
 \begin{align*}
 \sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k\cap\A_r^k) &\leq \sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k) + O_k\left(\sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k)D^{-1+\ep/2}\right)\\
 &\leq \Psi_k(Q)^2+O_k\left(\sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k)D^{-1+\ep/2}\right).
 \end{align*}
 Focusing on the error term, define $R\coloneq\sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k)D^{-1+\ep/2}$, and let $I$ be the smallest non-negative integer such that $2^I\geq \Psi_k(Q)$. We then split $R$ via dyadic partition on $D$, writing $R_i$ as the part of the sum with $D\in [2^{i-1},2^i)$, and $R'$ the part with $D\geq 2^I$. Then:
 \begin{align*}
 R'&\leq \Psi_k(Q)^{-1+\ep/2}\sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k) \leq \Psi_k(Q)^{1+\ep/2},
 \end{align*}
 and for $i\in \{0,1,\dots,I\}$ we have by Proposition~\ref{proposition:overlap-sum-1} with $y=2^i$ that:
 \begin{align*}
 R_i &\leq (2^{i-1})^{-1+\ep/2}\sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k)\\
 &\ll_{\ep,k} (2^i)^{-1+\ep/2}(2^i)^{1-\ep}\Psi_k(Q)^{1+\ep}\\
 &= 2^{-i\epsilon/2}\Psi_k(Q)^{1+\ep}.
 \end{align*}
 We thus have $R \ll_{\ep,k}\Psi_k(Q)^{1+\ep}$ and so:
 \begin{align*}
 \sum_{(q,r)\in\E^{(1)}}\lambda_k(\A_q^k\cap\A_r^k) \leq \Psi_k(Q)^k + O_{\ep,k}(\Psi_k(Q)^{1+\ep}).
 \end{align*}
 Considering $\E^{(2)}$, we use Lemma~\ref{lem:pv-overlap} to say:
 \begin{align*}
 \sum_{(q,r)\in\E^{(2)}}\lambda_k(\A_q^k\cap\A_r^k) &\ll_k \sum_{(q,r)\in\E^{(2)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k)\me^{kL_D(q,r)}.
 \end{align*}
 If $D\in [2^{i-1},2^i)$, we have $L_{4^{i-1}}(q,r)\geq L_{D^2}(q,r)>1/D\geq 2^{-i}$. We then write:
 \begin{align*}
 \E^{(2)}=\bigcup_{i=0}^\infty \bigcup_{j=i}^\infty \E^{(2)}_{i,j},
 \end{align*}
 where:
 \begin{align*}
 \E^{(2)}_{i,i}&\coloneq\set{(q,r)\in \E^{(2)}}{D(q,r)\in[2^{i-1},2^i),\ L_{4^{i-1}}(q,r)\leq 1},\text{ and}\\
 \E^{(2)}_{i,j}&\coloneq\set{(q,r)\in \E^{(2)}}{D(q,r)\in[2^{i-1},2^i),\ L_{4^{j-1}}(q,r)\leq 1<L_{4^{j-2}}(q,r)},\text{ for }j>i.
 \end{align*}
 Then, if $(q,r)\in\E^{(2)}_{i,j}$, we have:
 \begin{align*}
 L_D(q,r)\leq L_{2^{i-1}}(q,r)\leq \sum_{2^{i-1}< p\leq 4^{j-1}}\frac{1}{p}+L_{4^{j-1}}(q,r) \leq \log\frac{j+1}{i+1} + O(1),
 \end{align*}
 and so:
 \begin{align*}
 \sum_{(q,r)\in\E^{(2)}}\lambda_k(\A_q^k\cap\A_r^k) \ll_k \sum_{j\geq i\geq 0}\left(\frac{j+1}{i+1}\right)^k\sum_{(q,r)\in\E^{(2)}_{i,j}}\lambda_k(\A_q^k)\lambda_k(\A_r^k).
 \end{align*}
 Then for $i\geq 0$, Proposition~\ref{proposition:overlap-sum-2} with $y=2^i$, $t=\max\{1, 4^{i-1}\}$, $s=2^i$ and $C=8$ gives:
 \begin{align*}
 \sum_{(q,r)\in\E^{(2)}_{i,i}}\lambda_k(\A_q^k)\lambda_k(\A_r^k) &\ll_{\ep,k} \exp(-2^i)\Psi_k(Q)^{1+\ep}.
 \end{align*}
 Similarly, for $j>i$, choosing $y=2^i$, $t=\max\{1, 4^{j-2}\}$, $s=1$ and $C=17$ gives:
 \begin{align*}
 \sum_{(q,r)\in\E^{(2)}_{i,j}}\lambda_k(\A_q^k)\lambda_k(\A_r^k) \ll_{\ep,k} \exp(-4^j)\Psi_k(Q)^{1+\ep}.
 \end{align*}
 Together, this gives:
 \begin{align*}
 \sum_{(q,r)\in\E^{(2)}}\lambda_k(\A_q^k\cap\A_r^k) &\ll_{\ep,k} \Psi_k(Q)^{1+\ep}\left(\sum_{i\geq 0}\exp(-2^i) +\sum_{j>i}\left(\frac{j+1}{i+1}\right)^k\exp(-4^j)\right)\\
 &\ll_{\ep,k} \Psi_k(Q)^{1+\ep}.
 \end{align*}
 Finally, considering $\E^{(3)}$, we have that:
 \begin{align*}
 L_D(q,r)\leq \sum_{D<p\leq D^2}\frac{1}{p} + L_{D^2}(q,r) \ll \log\log D^2-\log\log D + \frac{1}{D} \ll 1.
 \end{align*}
 We thus have by Lemma~\ref{lem:pv-overlap} that:
 \begin{align*}
 \sum_{(q,r)\in\E^{(3)}}\lambda_k(\A_q^k\cap\A_r^k) &\ll_k \sum_{(q,r)\in\E^{(3)}}\lambda_k(\A_q^k)\lambda_k(\A_r^k).
 \end{align*}
 If $D\in [2^{i-1},2^i)$, we have:
 \begin{align*}
 \omega_{4^i}(q,r)\geq \omega_{D^2}(q,r)&> \frac{\ep}{4k}\log(2D) \geq \frac{\ep}{8k}\log(4^i).
 \end{align*}
 We can thus write:
 \begin{align*}
 \sum_{(q,r)\in\E^{(3)}}\lambda_k(\A_q^k\cap\A_r^k) &\ll_k \sum_{i\geq 0}\sum_{(q,r)\in\E^{(3)}_i}\lambda_k(\A_q^k)\lambda_k(\A_r^k),
 \end{align*}
 where, for each $i\geq 0$:
 \begin{align*}
 \E^{(3)}_{i}&\coloneq\set{(q,r)\in \E^{(3)}}{D(q,r)\in[2^{i-1},2^i),\ \omega_{4^i}(q,r)> \frac{\ep}{8k}\log(4^i)}.
 \end{align*}
 Applying Proposition~\ref{proposition:overlap-sum-3} with $y=2^i$, $t=4^i$, $\kappa=\ep/8k$ and $C=2$ gives:
 \begin{align*}
 \sum_{(q,r)\in\E^{(3)}_i}\lambda_k(\A_q^k)\lambda_k(\A_r^k) &\ll_{\ep,k} (4^i)^{-2}(2^i)^{1-\ep}\Psi_k(Q)^{1-\ep} \ll_\ep 2^{-i}\Psi_k(Q)^{1+\ep},
 \end{align*}
 and so:
 \begin{align*}
 \sum_{(q,r)\in\E^{(3)}}\lambda_k(\A_q^k\cap\A_r^k) &\ll_{\ep,k} \sum_{i\geq 0}2^{-i}\Psi_k(Q)^{1+\ep} \ll_\ep\Psi_k(Q)^{1+\ep}.
 \end{align*}
 Putting everything together:
 \begin{align*}
 \sum_{q,r\leq Q}\lambda_k(\A_q^k\cap\A_r^k) &= \sum_{q\leq Q}\lambda_k(\A_q^k) + \sum_{i=1}^3\sum_{(q,r)\in\E^{(i)}}\lambda_k(\A_q^k\cap\A_r^k)\\
 &\leq \Psi_k(Q) + \Psi_k(Q)^2 + O_{\ep,k}(\Psi_k(Q)^{1+\ep}),
 \end{align*}
 as required.
\end{proof}

post_theorem_intro_text:
This result establishes a quantitative estimate for the number of solutions for the $k$-dimensional Duffin-Schaeffer conjecture for all $k\geq 2$, matching the best-known error term in the 1-dimensional case from \cite{koukoulopoulos2024sharpquantitativeversionduffinschaeffer}. We note that, in the original, non-reduced fraction case of Khintchine, without assuming monotonicity, asymptotic formulae exist only in the case $k\geq 3$. For $k=1,2$, we have such formulae with monotonicity; for $k=1$, we know that this monotonicity is essential, but for $k=2$, it remains an open question: see \cite[Chapter~3]{harman1998metricnumbertheory} or \cite[Section~5]{beresnevich2010khintchinegroshev}.

The method of proving Theorem~\ref{theorem:k-dim-ds} and similar results in metric Diophantine approximation is a standard procedure in metric number theory, with ideas dating back to at least \cite{cassels1950somemetricaltheorems, schmidt1964metricaltheorems}. We omit the proof, referring the reader to \cite[Lemma~1.5]{harman1998metricnumbertheory} for the general procedure and to \cite{koukoulopoulos2024sharpquantitativeversionduffinschaeffer} for the details in our case. The key is a variance estimate of random variables describing the number of solutions for a given $\alpha$. From a probabilistic perspective, the 1-dimensional Duffin-Schaeffer conjecture asks whether a uniformly randomly chosen irrational $\alpha$ is contained within the set system:
\begin{align*}
    \A_q \coloneq \bigcup_{\substack{0\leq a \leq q,\\\gcd(a,q)=1}}\left(\frac{a}{q}-\frac{\psi(q)}{q}, \frac{a}{q} + \frac{\psi(q)}{q}\right)\cap \left[0,1 \right]
\end{align*}
for infinitely or finitely many $q$; for $k\geq2$, we ask about $\A_q^k\coloneq \A_q^{k-1}\times \A_q$. Denoting then by $\lambda_k$ the $k$-dimensional Lebesgue measure restricted to $[0,1]^k$, we note that $\Psi_k(Q) = \sum_{q=1}^Q\lambda_k(\A_q^k)$ as:
\begin{align*}
        \lambda_k(\A_q^k) = \left(\frac{2\psi(q)\varphi(q)}{q}\right)^k.
\end{align*}
Following this, one can also see that $S_k(\alpha,Q)=\sum_{q=1}^Q\ind{\A_q^k}(\alpha)$ for every $\alpha$. The result of Theorem~\ref{theorem:k-dim-ds} can then be understood as describing the concentration of $S_k(\alpha,Q)$ around its mean. As before, the result would follow immediately from the divergence Borel-Cantelli lemma with pairwise independence of the random variables $\ind{\A_q}$, which we do not have here. In fact, the overlap $\lambda_k(\A_q^k\cap \mathcal{A}^k_r)$ can be significantly larger than $\lambda_k(\A_q^k)\lambda_k(\A_r^k)$ for pairs $(q,r)$ where the prime factorisation of $Q$ contains a large number of small primes not dividing $r$, or vice versa. The crux of the argument involves showing that such pairs are relatively rare, and thus on average we have a form of quasi-independence. In fact, one can show that the set system moves towards pairwise independence on average as the total mass tends towards infinity. Our key result below establishes exactly this for the case $k\geq 2$; again, stated as $k\geq 1$ for completeness.

\begin{theorem}\label{theorem:k-dim-variance}
    Let $k\geq 1$ and $Q\in \mathbb{N}$, and define $S_k(\alpha,Q)$ and $\Psi_k(Q)$ as in Theorem~\ref{theorem:k-dim-ds}. Then, for every fixed $\varepsilon>0$, we have:
    \begin{align*}
         \lint{\left[0,1\right]^k}{}{\left(S_k(\alpha, Q)-\Psi_k(Q)\right)^2}{\alpha} \leq \Psi_k(Q) + O_{\varepsilon,k}(\Psi_k(Q)^{1+\varepsilon}).
     \end{align*}
\end{theorem}

The rest of this paper is dedicated to constructing the proof of Theorem~\ref{theorem:k-dim-variance}. The standard approach involves a counting argument on the prime factorisations of $q$ and $r$, followed by a sieve on the coprimality condition. In the $k$-dimensional problem, one can simply adapt the $1$-dimensional overlap estimates proven in \cite{aistleitner2023metrictheoryofapproximations, koukoulopoulos2024sharpquantitativeversionduffinschaeffer, pollington1990kdimensionalduffinschaeffer}, as shown in Section~\ref{sec:overlap}. From here, we construct three bilinear estimates, allowing us to bound the variance contributions of the problematic pairs of integers $(q,r)$ with many prime factors. In the $1$-dimensional case, the approach of \cite{koukoulopoulos2020duffin, koukoulopoulos2024sharpquantitativeversionduffinschaeffer} is a technical iterative construction via GCD graphs. This approach was generalised in \cite{hauke2024provingduffinschaefferconjecturegcd, vazquez2024almostsharpquantitativeduffinschaeffergcd}, providing a framework for similar bounds on general multiplicative functions. In Section~\ref{sec:bilinear}, we show how this framework can be employed to construct equivalent bilinear bounds in all dimensions $k\geq 2$. From here, the variance estimate follows with an approach adapted from \cite{koukoulopoulos2024sharpquantitativeversionduffinschaeffer}, as shown in Section~\ref{sec:variance}.

\subsection*{Acknowledgements}
The author would like to thank Manuel Hauke for introducing them to the topic and for guidance and discussion throughout the work. The work was conducted during a research stay in TU Graz, as part of the author's master's thesis in NTNU; the author would thus also like to thank the Institute of Analysis and Number Theory in TU Graz for their hospitality.

