\label{theorem:k-dim-ds}
   Let $k\geq 1$, and let $\map{\psi}{\mathbb{N}}{\left[0,1/2\right]}$ be such that $\sum_{q=1}^\infty \left(\varphi(q)\psi(q)/q\right)^k=\infty$. For $\alpha\in \left[0,1\right]^k$, denote by $S_k(\alpha,Q)$ the number of solutions $(a,q)\in\mathbb{Z}^k\times \mathbb{N}$ to the inequality:
    \begin{align*}
        \pn{q\alpha-a}{\infty} < \psi(q), \quad \text{given } q \leq Q,
    \end{align*}
    satisfying $\gcd(a_i, q)=1$, for $i\in\{1,\dots, k\}$, $a=(a_1,\dots, a_k)$. Moreover, given $Q\in \mathbb{N}$, define:
    \begin{align*}
        \Psi_k(Q)\coloneq \sum_{q\leq Q}\left(\frac{2\psi(q)\varphi(q)}{q}\right)^k.
    \end{align*}
    Then for all $\varepsilon>0$, as $Q\to \infty$, we have for almost all $\alpha$ that:
    \begin{align*}
        S_k(\alpha,Q)=\Psi_k(Q)+O_{\varepsilon,k}\left( \Psi_k(Q)^{1/2+\varepsilon} \right).
    \end{align*}

theorem.content:
\label{thm 1}
Let $\Omega\subset \mathbb{R}^m$ be a bounded  Lipschitz domain symmetric about the origin. Suppose $h(r)\in C^2([0, +\infty))$ satisfies  $h'(r)\ge 0$ and $h''(r)\ge 0$ for $r\in (0, +\infty)$. Let  $B \subset \mathbb{R}^m$  be the  origin-centered  round ball with the same $\gamma_h$-volume as $\Omega$, namely $ \int_{\Omega} e^{h(|x|)}\, dx= \int_{B} e^{h(|x|)}\, dx$. Denote by $\sigma_1(B; \gamma_h)$ the first nonzero Steklov eigenvalue of \eqref{eq 1.4} on $B$, and $\l_{2,\alpha}(\Omega; \gamma_h)$ the second Robin eigenvalue of \eqref{eq 1.1} on $\Omega$.  If  $\alpha \in [-\sigma_1(B; \gamma_h), 0]$, then 
\begin{align}\label{eq 1.6}
\l_{2,\alpha}(\Omega; \gamma_h) \le \l_{2,\alpha}(B; \gamma_h).
\end{align}
Equality holds  if and only if 
$\Omega=B$.

