\begin{align*}
||u||_{W^{1,2}(\Omega;\gamma_h)}:=\left(\int_\Omega u^2 \, d\gamma_h\right)^{1/2}+ \left(\int_\Omega |\nabla u|^2 \, d\gamma_h\right)^{1/2}. 
\end{align*}

