 \int_{S}\big| \E_{\mu_x^t[\psi_*]}(v)-\E_{\mu^t[\psi_*]}(v))\big|\,\d\rho(x)\leq \frac{\kappa}{\sqrt{t}}\left(\int_S {\rm{Var}}_{ \mu_x^t[\psi_*]}(v)\,\d\rho(x)\right)^\frac{1}{2},
 \end{equation}
 where $\mu^t[\psi_*]$ is defined as in \eqref{mu} and $\kappa$ depends on $K,N,\Lambda_\psi,a_1,a_2, S$.
 \end{proposition}
 \begin{proof}
 Since $a_1\mm\leq \rho\leq a_2\mm$, by \cite[Corollary 2.4]{zbMATH05049052}, $\rho$ is a doubling measure. Moreover, 
 since $S$ is a John domain, by \cite[Proposition 3.7]{arXiv:2504.05412}, $\rho$ satisfies the Boman chain condition (see Definition \ref{Boman chain condition}) and we can choose a covering $\mathcal{F}$, such that for any $B\in \mathcal{F}$, $r_B\leq 1$. Then 
 \begin{equation}
 \begin{aligned}
 &\int_{S}\big| \E_{\mu_x^t[\psi_*]}(v)-\E_{\mu^t[\psi_*]}(v))\big|\,\d\rho(x)\\
 \mathop{\leq}^{\text {Lemma \ref{3.1}}} &C_5 \sum_{B\in\mathcal{F}}\rho(B)\int_B \big| \E_{\mu_x^t[\psi_*]}(v)-{\rho(B)}^{-1}\E_{\mu^t[\psi_*]}(v))\big|\,\d\rho_B(x)\\
 \mathop{\leq }^{\text{Lemma \ref{p3.10}}}&C_5 \sum_{B\in\mathcal{F}}\rho(B)C_4 r_B\int_B \big|\nabla_x \E_{\mu_x^t[\psi_*]}(v)\big|\,\d\rho_B(x)\\
 \mathop{\leq}^{\text{Proposition \ref{3.9}} }& \frac{C_3C_4C_5}{\sqrt{t}}\sum_{B\in\mathcal{F}}\sqrt{\mm(B_{2r_B})}\sqrt{r_B}\left(\int_B {\rm{Var}}_{ \mu_x^t[\psi_*]}(v)\,\d\rho(x)\right)^\frac{1}{2}\\
 \mathop{\leq}^{\text{H\"{o}lder}~~}&\frac{C_3C_4C_5}{\sqrt{t}}\left(\sum_{B\in\mathcal{F}}\mm(B_{2r_B})\right)^\frac{1}{2}\left(\sum_{B\in\mathcal{F}}\int_B {\rm{Var}}_{ \mu_x^t[\psi_*]}(v)\,\d\rho(x)\right)^\frac{1}{2}\\
 \overset{\text{Boman chain~}}{\leq}&\frac{\kappa}{\sqrt{t}}\left(\int_S {\rm{Var}}_{ \mu_x^t[\psi_*]}(v)\,\d\rho(x)\right)^\frac{1}{2}
 \end{aligned}
 \end{equation}
 which is the thesis.
 \end{proof}

\begin{theorem}\label{thm2}
 Let $(X, \d)$ be an Alexandrov space with no boundary. Then under the same assumptions of Theorem \ref{thm0.2}, there exists a constant $\bar{C}>0$, depending on $k,n,a_1, a_2, \diam(S\cup Y), {\rm{Per}}(S), S$, such that for any $\mu,\nu\in\mathcal{P}_2(Y)$, we have 
 \begin{equation}
 \int_S |\nabla\phi_\mu(x)-\nabla\phi_\nu(x)|^2\,\d\rho(x)\leq \bar{C} \left(\int_S|\phi_\mu(x)-\phi_\nu(x)|^2\,\d\rho(x)\right)^\frac{1}{3},
 \end{equation}
 where $\phi_\mu$ and $\phi_\nu$ are the Kantorovich potentials from $\rho$ to $\mu$ and $\rho$ to $\nu$ respectively.
 \end{theorem}

\begin{lemma}[\cite{zbMATH07794624}, Lemma 5.1]\label{l0.18}
 Let $I\subseteq \R$ be a compact segment and let $u,v: I\rightarrow\R$ be two convex functions such that $|u'|$ and $|v'|$ (defined a.e. on $I$) are uniformly bounded on $I$. Then
 \begin{equation*}
 \|u'-v'\|_{L^2(I)}^2\leq 8 (\|u'\|_{L^\infty(I)}+\|v'\|_{L^\infty(I)})^\frac{4}{3}\|u-v\|_{L^2(I)}^\frac{2}{3}.
 \end{equation*}
 \end{lemma}
 Therefore, applying Lemma \ref{l0.18} to the functions $\zeta|s|^2-u_\mu^{(x,v)}$ and $\zeta|s|^2-u_\nu^{(x,v)}$ on each compact segment $[\alpha_i(x,v),\beta_i(x,v)]$ and using H\"{o}lder inequality, we obtain
 \begin{equation}\label{0.55}
 \begin{aligned}
 &\int_S |\nabla\phi_\mu(x)-\nabla\phi_\nu(x)|^2\,\d\rho(x)\\
 \mathop{\leq}^{\eqref{0.54}}& \frac{a_2}{c_nd_n}\int_{{\rm S}X}\sum_{i\in I_S(x,v)}\int_{\alpha_i(x,v)}^{\beta_i(x,v)}\langle\nabla\phi_\mu(b_s(x,v))-\nabla\phi_\nu(b_s(x,v)),t_s(x,v)\rangle^2\,\d s \,\d\mm_S(x,v)\\
 \leq&C_1 \int_{{\rm S}X}\sum_{i\in I_S(x,v)}\left(\int_{\alpha_i(x,v)}^{\beta_i(x,v)}|\phi_\mu(b_s(x,v))-\phi_\nu(b_s(x,v))|^2\,\d s\right)^\frac{1}{3}\,\d\mm_S(x,v)\\
 \leq&C_1 \int_{{\rm S}X}\left(\# I_S\right)^\frac{2}{3}\left(\int_0^1|\phi_\mu(b_s)-\phi_\nu(b_s)|^2\chi_S(b_s)\,\d s\right)^\frac{1}{3}\d\mm_S\\
 \leq&C_1 \left(\int_{{\rm S}X}\# I_S\,\d\mm_S\right)^\frac{2}{3}\left(\int_{{\rm S}X}\int_0^1|\phi_\mu(b_s)-\phi_\nu(b_s)|^2\chi_S(b_s)\,\d s \,\d\mm_S\right)^\frac{1}{3}\\
 \leq&C_1 \left(\frac{c_n}{a_1}\right)^\frac{1}{3}\left(\int_{{\rm S}X}\# I_S\,\d\mm_S\right)^\frac{2}{3}\left(\int_S|\phi_\mu-\phi_\nu|^2\,\d\rho\right)^\frac{1}{3},
 \end{aligned}
 \end{equation}
 where $C_1$ depends on $k,n,a_2, \diam(S\cup Y)$, and the last inequality follows from the invariance of $\mm_S$ under the geodesic flow.

Let $\phi_\mu$ and $\phi_\nu$ be the Kantorovich potentials from $\rho$ to $\mu$ and $\rho$ to $\nu$ respectively. From \cite{zbMATH05349267,zbMATH06032507} we know that $\nabla \phi_\mu(x), \nabla \phi_\nu(x) \in {\rm{T}}_xX$ and
 $T_\mu(x)= \exp_x(-\nabla \phi_\mu(x))$, $T_\nu(x)= \exp_x(-\nabla \phi_\nu(x))$ are well-defined for almost every $x\in S$. By triangle comparison condition (cf. \cite{zbMATH05342782}), it holds
 \begin{equation}\label{exp}
 \d \big(T_\mu(x), T_\nu(x) \big) \leq C_2|\nabla \phi_\mu(x)-\nabla \phi_\nu(x)|,
 \end{equation}
 for some constant $C_2>0$ which depends on $k, \diam(S\cup Y)$. 
