Let $L$ be a positive-definite, unimodular even lattice of rank $m$ with bilinear form $(\cdot,\cdot)$. Then $m$ must be divisible by $8$. For an integer $g\geq1$ we define the degree $g$ \emph{theta series}
 \[ \theta_L^{(g)}(\tau) \coloneqq \frac{1}{|\operatorname{Aut}(L)|}\sum_{\lambda\in L^g}e^{\pi i\operatorname{tr}((\lambda,\lambda)\tau)}, \quad \tau\in\mathbb{H}_g \]
 where $(\lambda,\lambda) = ((\lambda_i,\lambda_j))_{i,j=1}^g\in\mathrm{Mat}_g(\mathbb Z)$ for $\lambda = (\lambda_1,\hdots,\lambda_g)\in L^g$ and $\mathbb{H}_g$ denotes the Siegel half-space of degree $g$. By Poisson summation, $\theta_L^{(g)}$ is a Siegel modular form of weight $m/2$ for the full modular group $\Sp_{2g}(\mathbb Z)$. We denote the space of Siegel modular forms of weight $k$ by $\mathrm{M}_k(\Sp_{2g}(\mathbb Z))$ and the subspace of cuspforms by $\mathrm{S}_k(\Sp_{2g}(\mathbb Z))$.

Let $I\!I_{m,0}$ denote the genus of positive-definite, unimodular even lattices of rank $m$ and let us write $[L]\in I\!I_{m,0}$ for the isomorphism class of $L$. Clearly, $\theta_L^{(g)}$ only depends on $[L]$ so that it induces a homomorphism
 \[ \vartheta_m^{(g)}: \mathbb C[I\!I_{m,0}] \to \mathrm{M}_{m/2}(\Sp_{2g}(\mathbb Z)). \]
 It is not difficult to verify that $\vartheta_m^{(m)}$ is injective. Let $\g_m\geq0$ be the smallest integer such that $\vartheta_m^{(\g_m)}$ is injective. For $m=8$ the genus $I\!I_{8,0}$ contains only the lattice $E_8$, hence, $\g_8 = 0$. In the case $m=16$ we have $\g_{16} = 4$, which comes from the existence of the \emph{Schottky form} in $\mathrm{S}_{8}(\Sp_{8}(\mathbb Z))$ \cite{Igusa}. It was shown in \cite{BFW} that $\g_{24} = 12$ by constructing a non-zero cusp form in $\mathrm{S}_{12}(\Sp_{24}(\mathbb Z))$ and this construction was generalized in \cite{Salvati} to all $m=24k$ yielding a lower bound $\g_{24k}\geq12k$. We will show

Let $I\!I_{m,0}$ denote the genus of positive-definite, unimodular even lattices of rank $m$ and let us write $[L]\in I\!I_{m,0}$ for the isomorphism class of $L$. Clearly, $\theta_L^{(\g)}$ only depends on $[L]$ so that it induces a homomorphism
 \[ \vartheta_m^{(\g)}: \C[I\!I_{m,0}] \to \mathrm{M}_{m/2}(\Sp_{2\g}(\Z)). \]
 It is not difficult to verify that $\vartheta_m^{(m)}$ is injective. Let $\g_m\geq0$ be the smallest integer such that $\vartheta_m^{(\g_m)}$ is injective. For $m=8$ the genus $I\!I_{8,0}$ contains only the lattice $E_8$, hence, $\g_8 = 0$. In the case $m=16$ we have $\g_{16} = 4$, which comes from the existence of the \emph{Schottky form} in $\mathrm{S}_{8}(\Sp_{8}(\Z))$ \cite{Igusa}. It was shown in \cite{BFW} that $\g_{24} = 12$ by constructing a non-zero cusp form in $\mathrm{S}_{12}(\Sp_{24}(\Z))$ and this construction was generalized in \cite{Salvati} to all $m=24k$ yielding a lower bound $\g_{24k}\geq12k$. We will show

\begin{rem}\label{rem}
 Let $f\in\mathrm{S}_k(\SL_2(\Z))$ be an eigenform with automorphic $L$-function $L(s,f)$ (normalized such that $\frac{1}{2}$ is the natural center of the functional equation). When $k\equiv2\bmod4$, then $L\left(\frac{1}{2},f\right) = 0$. It is conjectured (see e.g.\ \cite{ConreyFarmer}) that $L\left(\frac{1}{2},f\right) \not= 0$ whenever $k\equiv0\mod4$. If this is the case for a given $k=\frac{m}{2}$, then $\g_{m}<\frac{3m}{4}$, otherwise $\g_{m} = \frac{3m}{4}$ (see end of Section \ref{sec:ProofOfTheorem}). The conjecture has been verified for all $k\leq500$ in \cite{ConreyFarmer}.
 \end{rem}
 \begin{rem}
 Theorem \ref{thm:mainthm} also implies that when $\g>\frac{3m}{4}$, then no cusp form $f\in\mathrm{S}_{m/2}(\Sp_{2\g}(\Z))$ is a linear combination of theta series $\theta_L^{(\g)}$ with $[L]\in I\!I_{m,0}$.
 \end{rem}
 \comment{\begin{rem}
 When $F\in\mathrm{S}_{\frac{k+\g}{2}}(\Sp_{2\g}(\Z))$ is the Ikeda lifting of an eigenform $f\in\mathrm{S}_k(\SL_2(\Z))$ with $k+\g\equiv0\bmod8$ such that $F$ lies in the image of $\vartheta_{k+\g}^{(\g)}$, then $\g\leq k$. This can be seen for example by comparing $L$-functions (\cite[Theorem 3.3]{Ikeda} and \cite[Folgerung 2.1]{Boecherer}). Hence, when $\g_m>m/2$, then the cuspforms in the image of $\vartheta_m^{(\g)}$ for $\g>m/2$ are not Ikeda liftings.
 \end{rem}}

Finally, let 
 \[ \psi = \bigoplus_{i=1}^k\pi_i[d_i] \]
 and assume that the eigenvalues of $\psi_\infty$ are the integers
 \[ w_1>\hdots>w_{m/2}\geq-w_{m/2}>\hdots>-w_1. \]
 We define a character $\chi:\{\pm1\}^{I_0}\to\{\pm1\}$ where $I_0\subset\{1,\hdots,k\}$ is the subset consisting of those indices $i$ for which $n_id_i\equiv 0\bmod4$ in the following way: For $i\in\ I_0$ let $s_i$ be the element defined by $(s_i)_j = (-1)^{\delta_{ij}}$.
 \begin{enumerate}[(i)]
 \item If $d_i\equiv0\bmod2$, then $\chi(s_i) = (-1)^{n_id_i/4}$.
 \item If $d_i\equiv1\bmod2$, then $\chi(s_i) = (-1)^{|K_i|}$ where $K_i$ is the set of odd indices $1\leq j\leq m/2$ such that $w_j$ is an eigenvalue of $c_\infty(\pi_i)$.
 \end{enumerate}
 The following is Theorem 8.5.8 and Conjecture 8.1.2 in \cite{CL}, which were dependent on the more general case of Arthur's multiplicity formula that has since been proven by Ta\"ibi in \cite{Taibi}.
 \begin{thm}[Theorem 8.5.8 and Conjecture 8.1.2 in \cite{CL}, cf.\ \cite{Taibi}]\label{thm:Arthur}
 Let $\psi$, $I_0$ and $\chi$ be as above. Let $\Pi\subset\Pi_{\mathrm{disc}}(\Sort_m)^{\Sort_m(\widehat{\Z})}$ be the subset of representations such that $\psi(\pi,\St) = \psi$. Suppose that \cite[Hypothesis 3.2.1]{Arthur} is true. Then $\Pi\not=\emptyset$ if and only if
 \[ \chi(s_i) = \prod_{1\leq j\leq k,j\not=i}\varepsilon(\pi_i\times\pi_j)^{\min(d_i,d_j)}\quad\forall i\in I_0. \]
 If this condition holds, then we have $\sum_{\pi\in\Pi}m(\pi) = 1$ if $I_0\not=\{1,\hdots,k\}$ and $\sum_{\pi\in\Pi}m(\pi) = 2$ otherwise. Furthermore, any $\pi\in\Pi_{\mathrm{disc}}(\Sort_m)^{\Sort_m(\widehat{\Z})}$ has a standard parameter $\psi(\pi,\St) = \bigoplus_{i=1}^k\pi_i[d_i]$.
 \end{thm}

We will now describe how $\g_m$ can be determined from the standard $L$-functions of the elements in $\Pi_\mathrm{disc}(\Ort_m)^{\Ort_m(\widehat{\Z})}$. By Theorem \ref{thm:Fact}, any $\pi\in\Pi_\mathrm{disc}(\Ort_m)^{\Ort_m(\widehat{\Z})}$ with $\pi_\infty\cong\C$ defines a line $\C v_\pi\subset\C[I\!I_{m,0}]$. We denote by $\g(\pi)$ the smallest integer $\g\geq0$ such that $\vartheta_m^{(\g)}(v_\pi)\not=0$. The minimality of $\g$ is equivalent to requiring that $0\not=\vartheta_m^{(\g)}(v_\pi)\in\mathrm{S}_{m/2}(\Sp_{2\g}(\Z))$. Let
 \[ T(\pi) \coloneqq\{t\in\Z_{\geq1}\mid L(s,\pi) \text{ has a zero or pole in } t\} \]
 and $t(\pi) = \max T(\pi)$. We then have the following Theorem due to B\"ocherer.
 \begin{thm}[Theorem 3.4 in \cite{Boecherer}]\label{thm:Boecherer}
 Let $\pi\in\Pi_{\mathrm{disc}}(\Ort_m)^{\Ort_m(\widehat{\Z})}$ with $\pi_\infty\cong\C$. Then
 \begin{enumerate}[(i)]
 \item If $T(\pi) = \emptyset$, then $\g(\pi) = \frac{m}{2}$.
 \item If $T(\pi) \not= \emptyset$ and $L(s,\pi)$ has a pole in $t(\pi)$, then $\g(\pi) = \frac{m}{2}-t(\pi)$.
 \item If $T(\pi) \not= \emptyset$ and $L(s,\pi)$ has a zero in $t(\pi)$, then $\g(\pi) = \frac{m}{2}+t(\pi)$.
 \end{enumerate}
 \end{thm}

Before we prove the main theorem let us make some observations: Let $\pi\in\Pi_\mathrm{disc}(\Ort_m)^{\Ort_m(\widehat{\Z})}$ with $\pi_\infty\cong\C$ and standard parameter $\psi = \bigoplus_{i=1}^k\pi_i[d_i]$ where $\pi_i\in\Pi_\mathrm{disc}(\PGL_{n_i})$.
 \begin{enumerate}[1)]
 \item Since the maps $\vartheta_m^{(\g)}$ are intertwining-operators between the $\mathcal{H}(\Ort_m)$-module $\C[I\!I_{m,0}]$ and the $\mathcal{H}(\Sp_{2\g})$-modules $\mathrm{M}_{m/2}(\Sp_{2\g}(\Z))$ (see \cite{Rallis}), it follows that $\ker\vartheta_m^{(\g)}$ is an $\mathcal{H}(\Ort_m)$-submodule. Therefore, by Theorem \ref{thm:Fact}
 \[ \g_m = \max\{\g(\pi)\mid\pi\in\Pi_\mathrm{disc}(\Ort_m)^{\Ort_m(\widehat{\Z})}\text{ such that }\pi_\infty\cong\C\}. \]\label{obs:Max}
 \item The eigenvalues of $c_\infty(\pi)$ are the $m-2$ integers
 \[ \pm\left(\frac{m}{2}-1\right),\pm\left(\frac{m}{2}-2\right),\hdots,\pm1 \]
 as well as $0$ with multiplicity $2$ and $\C$ is the unique representation with this infinitesimal character \cite[Section 6.4.3]{CL}.\label{obs:Eigenvalues}
 \item We have $d_i= \left(m-\sum_{j\not=i}n_jd_j\right)/n_i\leq m/n_i$ for all $i=1,\hdots,k$.\label{obs:BoundOnD}
 \item Either $n_id_i \equiv 0 \bmod 4$ for every $i$ or there exist exactly two integers $i$, say $i_1$ and $i_2$, such that $n_id_i \not\equiv 0 \bmod 4$. These integers satisfy $n_{i_1} d_{i_1}n_{i_2}d_{i_2} \equiv 3 \bmod 4$ \cite[Corollary 8.2.15 (iii)]{CL}.\label{obs:0mod4}
 \end{enumerate}

\begin{prp}\label{prp:BorcherdsFreitagWeissauerForm}
 Let $f\in\mathrm{S}_{m/2}(\SL_2(\Z))$ be an eigenform with corresponding automorphic representation $\pi_f\in\Pi_{\mathrm{disc}}(\PGL_2)$. Then there exist $\pi^+,\pi^-\in\Pi_{\mathrm{disc}}(\Ort_m)^{\Ort_m(\widehat{\Z})}$ with $\pi^+_\infty\cong\C$, $\pi^-_\infty\cong\det$ and $\psi(\pi^\pm,\St) = \pi_f[\frac{m}{2}]$ and
 \[ \g(\pi^+) = \begin{cases}
 \frac{m}{2} & \text{if } L\left(\frac{1}{2},\pi_f\right)\not=0 \\
 \frac{3m}{4}& \text{if } L\left(\frac{1}{2},\pi_f\right)=0 .
 \end{cases} \]
 \end{prp}
 \begin{proof}
 Let the notation be as in Theorem \ref{thm:Arthur}. Since $k=1$ with $n_1=2$ and $d_1\equiv0\bmod4$, the character $\chi$ is trivial and clearly satisfies the condition of Theorem \ref{thm:Arthur}. Therefore, there exist $\pi',\pi''\in\Pi_{\mathrm{disc}}(\Sort_m)^{\Sort_m(\widehat{\Z})}$ with $\psi(\pi',\St) = \psi(\pi'',\St) = \pi_f[\frac{m}{2}]$. The eigenvalues of $\psi(\pi',\St)$ are
 \[ \pm\left(\frac{m/2-1}{2}\right)+\left(-\frac{m/2-1}{2}+j\right),\quad j=0,\hdots,\frac{m}{2}-1 \]
 so that by Observation \ref{obs:Eigenvalues}, $\pi'_\infty\cong\pi''_\infty\cong\C$.

