\begin{theoA}\label{thm:B}
Let $G$ be a finite group of order divisible by $p$, let $N\normal G$ be an abelian $p$-group and assume $G/N$ has cyclic Sylow $p$-subgroups and let $\tau\in\mathcal{H}$ be a $p$-power order element. Then $\tau$ fixes the same number of height-zero characters in $\Irr(B_0(G))$ as in $\Irr(B_0(\norm G P))$, where $P\in{\rm Syl}_p(G)$.
\end{theoA}

ref_dict.thm:A:
\begin{theoA}\label{thm:A}
    Let $G$ be a finite group and $P\in\Syl_3(G)$. Then $|P:\Phi(P)|=9$ if the principal $3$-block $B_0(G)$ contains exactly $6$ or $9$ $\sigma$-invariant characters of degree coprime to $3$.
\end{theoA}

full_context:
In Problem 12 of his famous list of problems from 1963, Brauer asked what information could be gleaned about a Sylow $p$-subgroup $P$ of a finite group $G$ from its character table. In particular, the question of whether the number of generators of $P$ could be obtained in this way has been studied in recent years, see e.g. \cite{Riz-Sch-Val20, Nav-Riz-Sch-Val20, Mor-Sam23, Va23}. Many questions in this realm seem linked to the action of the Galois automorphism $\sigma\in{\rm Gal}(\mathbb{Q}^{ab}/\mathbb{Q})$ that fixes $p'$-roots of unity and sends $p$-power roots of unity to their $1+p$ power. For any cyclotomic extension $\mathbb{Q}_n:=\mathbb{Q}(e^{2\pi i/n})$ of $\mathbb{Q}$, we keep the notation $\sigma$ for the restriction of this automorphism to $\mathbb{Q}_n$.
Here, we contribute to this line of problems by proving the following direction of the main conjecture from \cite{Nav-Riz-Sch-Val20}.

\section{Introduction}

As noted in \cite{Nav-Riz-Sch-Val20}, Theorem \ref{thm:A} (and its converse) would follow from the Alperin--McKay--Navarro conjecture \cite[Conj.~B]{Nav04}, or even the more restrictive version \cite[Conj.~D]{Isa-Nav02}. Hence, this result gives further evidence for these elusive conjectures. We remark that although the block-free version \cite[Conj.~C]{Isa-Nav02} was recently established in \cite{RSF25}, the blockwise version (even for principal blocks) is much further from completion and has not yet been reduced to a problem on simple groups. For this reason, finding additional evidence of this blockwise version remains pertinent.

We begin by collecting some basic facts about principal blocks. Throughout, given a prime $p$, $B_0(G)$ denotes the principal $p$-block of the finite group $G$. We denote by $\Irr(B_0(G))$ the set of irreducible characters in $B_0(G)$ and by $\Irr_0(B_0(G))$ the subset of those with height zero (that is, $p'$-degree). The set of $\sigma$-invariant characters in $\Irr_0(B_0(G))$ will be denoted $\irrsigma(B_0(G))$, and we set $\ksigma(B_0(G)):=|\irrsigma(B_0(G))|$.

\begin{lem}\label{lem:kernel of sigmas}
Let $G$ be a finite group with $\oh{p'}G=1$ and let $P\in\Syl_p(G)$. Then
$$K=\bigcap_{\chi\in\irrsigma(B_0(G))}\ker\chi\leq \Phi(P).$$
\end{lem}
\begin{proof}
 Let $\lambda\in\Irr(P/\Phi(P))$. Write $P\cent G P=P\times X$ and let $\psi=\lambda\times 1_X\in\irrsigma(B_0(P\cent G P))$. By Lemma \ref{lem:3.7MMSV} we have that $\lambda^G$ contains a constituent $\chi\in\irrsigma(B_0(G))$. By Frobenius reciprocity, $\chi_{P\cent G P}$ contains $\lambda\times 1_X$ so $\chi_P$ contains $\lambda_P$. Moreover $\chi_{P\cap K}=\chi(1)1_{P\cap K}$ contains $\lambda_{P\cap K}$ which shows that $\ker{\lambda}$ contains $P\cap K$. Therefore $$P\cap K\sbs\bigcap_{\lambda\in\Irr(P/\Phi(P))}\ker\lambda=\Phi(P).$$
By Tate's theorem \cite[Cor.~6.14]{Nav18}, this implies that $K$ is $p$-nilpotent. Then if $K$ is not a $p$-group, $\oh{p'}K>1$, which contradicts $\oh{p'}G=1$. Therefore $K$ is a normal $p$-subgroup so $K=P\cap K\sbs\Phi(P)$, as desired.
\end{proof}

\begin{pro}\label{pro:noelia relative sigma} Let $G$ be a finite group, $p\in\{2,3\}$, and $P\in\Syl_p(G)$. Let $N\normal G$ and assume $p$ divides $|G:N|$. Suppose that $\theta\in\Irr(B_0(N))$ is $P\times\langle \sigma\rangle$-invariant. Then $p$ divides $ \ksigma(B_0(G)|\theta)$. In particular, if $\theta$ extends to $\hat\theta\in\irrsigma(B_0(PN))$ then $\ksigma(B_0(G)|\theta)\geq p$.
\end{pro}
\begin{proof}
 Arguing as in \cite[Thm.~2.7]{Gia-Riz-Sch-Val24} we get that
 $$\sum_{\chi\in\Irr_0(B_0(G)|\theta)}\chi(1)^2\equiv 0\mod p.$$

\begin{pro}\label{thm:ppalblock gam2}
 Let $N\normal G$ be perfect and let $P\in\Syl_p(G)$. Assume every $P$-invariant character $\theta\in\irrsigma(B_0(N))$ that extends to a $\sigma$-invariant character of $PN$ also extends to a $\sigma$-invariant character of $B_0(G_\theta)$ and assume $G/N$ has cyclic Sylow $p$-subgroups. Then $|\irrsigma(B_0(G))|=|\irrsigma(B_0(N\norm G P))|$.
\end{pro}
\begin{proof}
We may argue as in the proof of Theorem \ref{thm:ppalblock gam} that every $\chi\in\irrsigma(B_0(G))$ lies over a $P$-invariant $\theta\in\Irr(B_0(N))$. Since $\theta$ has a number of $G$-conjugates not divisible by $p$ and $\langle \sigma \rangle$ acts on the set of $G$-conjugates of $\theta$, it follows that $\theta$ is also $\sigma$-invariant. Arguing again as in Theorem \ref{thm:ppalblock gam} we conclude that $\chi\in\Irr_{0}(B_0(G))$ is $\sigma$-invariant if and only if its Clifford correspondent $\psi\in\Irr_{0}(B_0(G_\theta))$ is $\sigma$-invariant.

\begin{thm}
 Let $G$ be a finite group, let $B_0(G)$ be the principal 3-block of $G$, and let $P\in\syl 3 G$. Suppose that $k_{0,\sigma}(B_0(G))\in\{6,9\}$. Then $|P:\Phi(P)|=9.$
\end{thm}
\begin{proof}
 We argue by induction on $|G|$. Since $\irrsigma(B_0(G))=\irrsigma(B_0(G/\oh{p'}G))$ by \cite[Thm.~9.9]{Nav98}, we may assume $\oh{p'}G=1$. We can also assume that $P$ is not cyclic by \cite[Thm.~A]{Riz-Sch-Val20}.

\begin{thm}\label{thm:simple group conditions}
Let $S$ be a nonabelian simple group of order divisible by $3$ and let $X\in\Syl_3(\Aut(S))$. 
\begin{enumerate}
 \item One of the following holds.
 \begin{enumerate}
 \item There exist $1_S\neq\theta_1,\theta_2\in\irrsigma(B_0(S))$ nonconjugate in $\Aut(S)$ and invariant under $X$, or
 \item There is an $X$-invariant $1_S\neq \theta\in\irrsigma(B_0(S))$ that extends to some $\sigma$-invariant character in $B_0(T)$ for all $S\leq T\leq \Aut(S)_\theta$.
 \end{enumerate}
 \item The set of degrees of characters in $\irrsigma(B_0(S))$ has size at least $3$.
 \item If $S$ has noncyclic Sylow $3$-subgroups, then there exist $1_S\neq \theta_1,\theta_2,\theta_3\in\irrsigma(B_0(S))$ nonconjugate in $\Aut(S)$. 
\end{enumerate}
\end{thm}

\begin{theoA}\label{thm:A}
    Let $G$ be a finite group and $P\in\Syl_3(G)$. Then $|P:\Phi(P)|=9$ if the principal $3$-block $B_0(G)$ contains exactly $6$ or $9$ $\sigma$-invariant characters of degree coprime to $3$.
\end{theoA}

