theorem.content:
[Quantitative stability for parabolic equations]\label{thm:parabolic}
		Let $T>0$ and $\Omega$ be a bounded domain in ${\mathbb R}^n$. For $\varepsilon\geq 0$, assume that $A_\varepsilon: {\mathbb R}^n_0\to \S_+^n$ and ${H_\varepsilon: \Omega_T\times {\mathbb R}^n\to {\mathbb R}}$ are continuous functions satisfying (A1)(A2) and (C1)(C2). Let $g_\varepsilon\in C(\partial_p \Om_T)$ and $u_\varepsilon\in C(\overline{\Omega}\times [0, T))$ be bounded ${\mathcal F}$-solutions of  \eqref{general parabolic approx eq}\eqref{parabolic approx bdry-cond}. Assume in addition that $u_\varepsilon$ are equi-H\"older continuous in $\overline{\Om_T}$, that is, there exist $L>0$ and $\theta\in (0, 1]$ such that,   
		\begin{equation}\label{equi-holder}
			|u_\varepsilon(x_1, t_1)-u_\varepsilon(x_2, t_2)|\leq L(|x_1-x_2|^\theta +|t_1-t_2|^\theta) 
		\end{equation}
		for all $(x_1, t_1), (x_2, t_2)\in \overline{\Omega}\times [0, T)$ and $\varepsilon\geq 0$ small. 
		Then, for all $\varepsilon>0$ small, 
		\begin{equation}\label{error-est parabolic}
			\sup_{\overline{\Omega}\times [0, T)}|u_\varepsilon-u_0|\leq \sup_{\partial_p \Om_T}|g_\varepsilon-g_0|+C\varepsilon^{\nu}  +c_H T\varepsilon^\gamma,
		\end{equation}
		holds with 
		\begin{equation}\label{nu-exponent}
			\nu=\frac{\alpha\theta}{1+(1-\theta)\max\{\beta, 0\}},    
		\end{equation}
		where $C>0$ depends on $T, n, k, L_A, L_H, \beta, c_A$ as well as the H\"older exponent $\theta$ and the constant $L$. Here, $k>2$, $L_A\geq0$, $L_H\geq0$ appear in (A1)(A2), and $\alpha, \beta, \gamma, c_A, c_H\in {\mathbb R}$ are given in (C1)(C2).

ref_dict.thm:parabolic:
\begin{thm}[Quantitative stability for parabolic equations]\label{thm:parabolic}
		Let $T>0$ and $\Omega$ be a bounded domain in $\R^n$. For $\vep\geq 0$, assume that $A_\vep: \R^n_0\to \S_+^n$ and ${H_\vep: \Omega_T\times \R^n\to \R}$ are continuous functions satisfying (A1)(A2) and (C1)(C2). Let $g_\vep\in C(\partial_p \Om_T)$ and $u_\vep\in C(\Oba\times [0, T))$ be bounded $\F$-solutions of  \eqref{general parabolic approx eq}\eqref{parabolic approx bdry-cond}. Assume in addition that $u_\vep$ are equi-H\"older continuous in $\ol{\Om_T}$, that is, there exist $L>0$ and $\theta\in (0, 1]$ such that,   
		\begin{equation}\label{equi-holder}
			|u_\vep(x_1, t_1)-u_\vep(x_2, t_2)|\leq L(|x_1-x_2|^\theta +|t_1-t_2|^\theta) 
		\end{equation}
		for all $(x_1, t_1), (x_2, t_2)\in \Oba\times [0, T)$ and $\vep\geq 0$ small. 
		Then, for all $\vep>0$ small, 
		\begin{equation}\label{error-est parabolic}
			\sup_{\Oba\times [0, T)}|u_\vep-u_0|\leq \sup_{\partial_p \Om_T}|g_\vep-g_0|+C\vep^{\nu}  +c_H T\vep^\gamma,
		\end{equation}
		holds with 
		\begin{equation}\label{nu-exponent}
			\nu=\frac{\alpha\theta}{1+(1-\theta)\max\{\beta, 0\}},    
		\end{equation}
		where $C>0$ depends on $T, n, k, L_A, L_H, \beta, c_A$ as well as the H\"older exponent $\theta$ and the constant $L$. Here, $k>2$, $L_A\geq0$, $L_H\geq0$ appear in (A1)(A2), and $\alpha, \beta, \gamma, c_A, c_H\in \R$ are given in (C1)(C2). 
	\end{thm}

ref_dict.rmk:periodic:
\begin{rmk}\label{rmk:periodic}
		Our discussions on the Cauchy-Dirichlet problem in Theorem~\ref{thm:parabolic} and Theorem~\ref{thm:parabolic2} extend readily to the case of spatially periodic settings. 
		Instead of considering \eqref{general parabolic lim eq} in a bounded domain $\Omega$, we may obtain the same stability results as in Theorem~\ref{thm:parabolic} and Theorem~\ref{thm:parabolic2} for the whole space $\R^n$, provided that the initial value $g$ and $H$ are both periodic with respect to $x$. Note that the periodic setting essentially plays the same role as a bounded domain (without boundary) in our comparison arguments and therefore does not substantially affect the proofs. For clarity of presentation, here we choose not to repeat the statements for this case.
	\end{rmk}

