\begin{thm}[Quantitative stability for elliptic equations]\label{thm:elliptic}
		Let $\Omega$ be a bounded domain in $\R^n$. For $\vep\geq 0$, assume that $A_\vep: \R^n_0\to \S_+^n$ and $H_\vep: \Omega\times \R\times  \R^n\to \R$ are continuous functions satisfying (A1)(A2')(A3) and (C1)(C2'). Let $g_\vep\in C(\partial\Omega)$ and $u_\vep\in C(\Oba)$ be $\F$-solutions of \eqref{general approx eq}\eqref{approx bdry-cond}. Assume in addition that $u_\vep$ are equi-H\"older continuous in $\Oba$, that is, there exist $L>0$ and $0<\theta\leq 1$ such that  		\[
		|u_\vep(x_1)-u_\vep(x_2)|\leq L|x_1-x_2|^\theta 
		\]
		for all $x_1, x_2\in \Oba$ and $\vep\geq 0$.
		Then, for all $\vep>0$ small,  
		\begin{equation}\label{error-est}
			\max_{\Oba} |u_\vep-u_0|\leq \max_{\partial \Omega} |g_\vep-g|+\frac{1}{\lambda}\left(C_0\vep^{\nu}+c_H \vep^\gamma \right)
		\end{equation}
		holds with $\nu$ given as in \eqref{nu-exponent}, where $C_0>0$ is a constant depending on 
		$k>2$,$L_A>0$, $L_H>0$, $\lambda>0$ in (A1)(A2')(A3) and $\alpha, \beta, c_A, \in \R$ given in (C1). The constants $\gamma, c_H>0$ are given as in (C2'). 
	\end{thm}

pre_theorem_intro_text:
\subsection{Motivation}
	In this paper we study the stability of a class of quasilinear parabolic partial differential equations, which takes the form 
	\begin{equation}\label{general parabolic lim eq}
		\partial_t u-\operatorname{tr}(A(\nabla u)\nabla^2 u)+H(x, t, \nabla u)=0 \quad \text{in $\Omega\times (0, T)$,}
	\end{equation}
	where $\Omega$ is a bounded domain in ${\mathbb R}^n$, $T>0$ is fixed, and 
	\[
	A: {\mathbb R}^n\setminus \{0\}\to {\mathcal S}^n_+, \quad H: \Omega\times (0, T)\times {\mathbb R}^n\to {\mathbb R},
	\]
	are given functions satisfying appropriate assumptions to be introduced later. Here, ${\mathcal S}^n_+$ represents the set of all nonnegative symmetric $n\times n$ matrices. A key feature of this general setting is that the elliptic operator may exhibit singularity at vanishing gradients. 

	One typical example of applicable equations we have in mind is the following parabolic normalized $p$-Laplace type equation (with $1<p<\infty$)
	\begin{equation}\label{np-parabolic0}
		\partial_t u-\Delta^N_p u=0 \quad \text{in $\Om_T:=\Omega\times (0, T)$,}
	\end{equation}  
	where
	\[
