Our main result is the following.

\begin{lemma}\label{lemma main}
 Suppose that $\Sigma$ is a smooth $(n-1)$-manifold and that $H_-,H_+\colon \Sigma\to\bbR$ are smooth functions, and let $\underline H_{-},\overline H_+\in(0,\infty)$ be such that $H_-\ge \underline H_-$ and $H_+\le\overline H_+$.
 Given $a\in\bbR$ satisfying $\overline{H}_+^2-\underline{H}_-^2+a^2\ge0$, we define functions $\vec{H}_+, \vec{H}_- \colon \Sigma \to \mathbb{R}^{1,1}$ via
 \begin{align*}
 \vec H_-=\begin{pmatrix}
 H_-\\
 a
 \end{pmatrix},
 \qquad
 \vec H_+=\begin{pmatrix}
 H_+\\
 \sqrt{\overline H_+^2-\underline H_-^2+a^2}
 \end{pmatrix}.
 \end{align*}
 Then there exists a hyperbolic rotation angle $\vartheta\in \mathbb R$ such that the function
 \begin{align*}
 X=F_\vartheta \vec H_--\vec H_+ \colon \Sigma \to \mathbb R^{1,1}, \qquad F_\vartheta=
 \begin{pmatrix}
 \cosh \vartheta & -\sinh \vartheta\\
 -\sinh \vartheta &\cosh\vartheta
 \end{pmatrix},
 \end{align*}
 satisfies
 \begin{align*}
 X_1\ge|X_2| \quad \textrm{ along } \Sigma,
 \end{align*}
 where $X_1$ and $X_2$ denotes the first and second component of $X$, respectively.
\end{lemma}

\begin{proof}
Let us abbreviate $\xi\coloneqq\sqrt{\overline H_+^{2}-\underline H_-^{2}+a^2}$.
We choose 
\begin{align}\label{eq vartheta 1}
 \vartheta =\sinh^{-1}\left( 
 \frac{a\overline H_+ - \xi\underline H_-}
 {\underline H_-^{2}-a^2}
 \right),
\end{align}
in case $\underline H_-\ne a$, and
\begin{align}\label{eq vartheta 2}
 \vartheta=\log(\underline H_-)-\log(\overline H_+)
\end{align}
in case $\underline H_-=a$.
Using $\cosh(\vartheta) = \sqrt{1+\sinh^2(\vartheta)}$, we obtain
\begin{align*}
 & F_\vartheta \vec H_- - \vec H_+
 =
 \begin{pmatrix}
 \sqrt{1+\sinh^2(\vartheta)}\,H_- - \sinh(\vartheta)\, a - H_+\\[0.4em]
 \sqrt{1+\sinh^2(\vartheta)}\,a - \sinh(\vartheta)\, H_- 
 - \xi
 \end{pmatrix}.
\end{align*}
If $\underline H_-\neq a$, then
\begin{align*}
 &\left(\underline H_-^{2}-a^2\right)^2\left(1+\sinh^2(\vartheta)\right)\\
 &\qquad\qquad = \underline H_-^4 - 2a^2\underline H_-^2 + a^4 + (a\overline H_+ - \xi\underline H_-)^2\\
 &\qquad\qquad = \underline H_-^4 - 2a^2\underline H_-^2 + a^4 + a^2\overline H_+^2 - 2a\xi\overline H_+\underline H_- + (\overline H_+^2-\underline{H}_-^2+a^2)\underline H_-^2\\
 &\qquad\qquad = \left(\overline H_+ \underline H_- - a\xi\right)^2
\end{align*}
and hence $\left|\underline H_-^{2}-a^2\right|\sqrt{1+\sinh^2(\vartheta)}=\left|\overline H_+\underline H_- - a \xi\right|$.

In the case that $\underline H_->a$, we note that $\xi< \overline H_+$, and that both $\underline H_-^{2} -a^2$ and $\overline H_+ \underline{H}_--a\xi$ are positive. 
We can thus estimate
\begin{align*}
 &(\underline H_-^{2} - a^2) 
 \left(\sqrt{1+\sinh^2(\vartheta)}\,H_- - \sinh(\vartheta)\, a - H_+\right)\\
 &\qquad\qquad= H_- \left(\overline H_+ \underline H_- - a \xi \right) - a \left(
 a\overline H_+ - \xi\underline H_-\right)- H_+(\underline H_-^{2}-a^2)\\
 &\qquad\qquad\ge(H_- -\underline H_-)\left(\overline H_+ \underline H_- - a \xi\right),
\end{align*}
where we used $H_+(\underline H_-^{2}-a^2)\le \overline H_+(\underline H_-^{2}-a^2)$ for the final inequality.
Moreover, we have
\begin{align*}
 &(\underline H_-^{2}-a^2)\left(\sqrt{1+\sinh^2(\vartheta)}\,a - \sinh(\vartheta)\, H_- - \xi\right)\\
 &\qquad\qquad= a \left(\overline H_+ \underline H_- - a \xi\right) - H_- \left(a\overline H_+ - \xi\underline H_-\right)- \xi(\underline H_-^{2}-a^2)\\
 &\qquad\qquad=(H_--\underline H_-)\left(\xi\underline H_--a\overline H_+\right)
\end{align*}
Since
\begin{align}\label{computation1}
\begin{split}
 &\left(\overline H_+ \underline H_- - a \xi \right)^2 -\left(\xi\underline H_- -a\overline H_+\right)^2\\
 &\qquad=\overline H_+^2\underline H_-^2- 2a\xi\overline H_+\underline H_- + a^2\xi^2 - \underline H_-^2\xi^2 + 2a\xi\overline H_+\underline H_- - a^2\overline H_+^2\\
 &\qquad= \overline H_+^2\underline H_-^2 + a^2 \left(\overline H_+^{2}-\underline H_-^{2}+a^2\right) - \underline H_-^2\left(\overline H_+^{2}-\underline H_-^{2}+a^2\right)- a^2 \overline H_+^2\\
 &\qquad =a^4-2a^2\underline H_-^2+\underline H_-^4 \ge0,
 \end{split}
\end{align}
we obtain $\overline H_+ \underline H_- - a\xi\ge |\xi\underline H_--a\overline H_+|$ and consequently,
\begin{align}\label{computation2}
 \begin{split}
 &\left(\sqrt{1+\sinh^2(\vartheta)}\,H_- - \sinh(\vartheta)\, a - H_+\right)\\
 &\qquad\qquad\qquad\ge \Big|\sqrt{1+\sinh^2(\vartheta)}\,a - \sinh(\vartheta)\, H_- - \xi\Big|.
 \end{split}
\end{align}
In the case $\underline H_-<a$, where $\xi> \overline H_+$ and both $\underline H_-^{2} - a^2$ and $\overline H_+ \underline{H}_--a\xi$ are negative, we can similarly estimate
\begin{align*}
 &-(\underline H_-^{2} - a^2) 
 \left(\sqrt{1+\sinh^2(\vartheta)}\,H_- - \sinh(\vartheta)\, a - H_+\right)\\
 &\qquad\qquad= -H_- \left(\overline H_+ \underline H_- - a \xi \right) + a \left(
 a\overline H_+ - \xi\underline H_-\right)+ H_+(\underline H_-^{2}-a^2)\\
 &\qquad\qquad\ge (H_- -\underline H_-)\left(-\overline H_+ \underline H_- + a \xi \right)\\
 &\qquad\qquad\ge (H_- -\underline H_-)\left|a \overline H_+ - \xi\underline H_- \right|,
\end{align*}
where the last inequality follows as in \eqref{computation1}.
Moreover,
\begin{align*}
 &-(\underline H_-^{2}-a^2)\left(\sqrt{1+\sinh^2(\vartheta)}\,a - \sinh(\vartheta)\, H_- - \xi\right)\\
 &\qquad\qquad= -a \left(\overline H_+ \underline H_- - a \xi\right) + H_- \left(a\overline H_+ - \xi\underline H_-\right)+ \xi(\underline H_-^{2}-a^2)\\
 &\qquad\qquad=(H_--\underline H_-)\left(a\overline H_+-\xi\underline H_-\right)
\end{align*}
Consequently, \eqref{computation2} holds in this case as well.

\begin{proof}[Proof of \cref{thm main}]
 Put $d_0=c_0= 0$, and for $1 \leq \ell \leq N$, put 
 \begin{align}\label{eq:def-of-c-and-d}
 d_\ell :=\sum_{i=1}^\ell(\overline H_{i,+}^2-\underline H_{i,-}^2), \quad c_{\ell} := \sqrt{ \max \{d_\ell, 0\}}. 
 \end{align}
 Without loss of generality, we can assume that $d_{\ell} > 0$ for some $\ell$. 
 Otherwise, \cref{thm main} is implied by \cite{Miao2002cornersATP}.

Let $\ell \in \{ 1, \ldots, \Lambda' \}$.
 If we choose 
 \begin{align}\label{eq:choice-for-lemma}
 \Sigma\coloneqq\Sigma_\ell,\quad H_\mp := H_{\ell,\mp},\quad \underline H_-\coloneqq \underline H_{\ell,-},\quad \overline H_+\coloneqq \overline H_{\ell,+}\quad\text{and}\quad a:=c_{\ell-1}
 \end{align}
 then $c_\ell = \sqrt{d_\ell} = \sqrt{\overline H_+^2-\underline H_-^2+a^2}$, and we obtain from \cref{lemma main} a hyperbolic angle $\vartheta_\ell$ such that
 \begin{align*}
 X=F_{\vartheta_\ell}\begin{pmatrix}
 H_{\ell,-}\\ c_{\ell-1}
 \end{pmatrix}
 -\begin{pmatrix}
 H_{\ell,+}\\ c_\ell
 \end{pmatrix}\in C^\infty\left(\Sigma_\ell,\mathbb{R}^{1,1}\right)
 \end{align*}
 satisfies $X_1\ge|X_2|$.

For $\ell \in \{ \Lambda' +1, \ldots, N \}$, we choose $\Sigma$, $H_-$, $H_+$, $\underline H_-$, and the constant $a$ as in \eqref{eq:choice-for-lemma}, and we choose 
 \[\overline H_+ := \sqrt{ \underline H_{\ell,-}^2-c^2_{\ell-1}}.\]
 Note, that by the assumption on $\Lambda'$, we have $\underline H_{\ell,-}^2-c^2_{\ell-1}\ge \overline H_{\ell,+}^2$ and hence $\overline H_+ \geq \overline H_{\ell,+}\ge H_+$ and $\overline H_+^2 - \underline H_-^2 + a^2 = 0$.
 Therefore, an application of \cref{lemma main} gives a $\vartheta\in\bbR$ such that
 \begin{align*}
 X=F_{\vartheta_\ell}\begin{pmatrix}
 H_{\ell,-}\\ c_{\ell-1}
 \end{pmatrix}
 -\begin{pmatrix}
 H_{\ell,+} \\ 0 
 \end{pmatrix}\in C^\infty\left(\Sigma_\ell,\mathbb{R}^{1,1}\right)
 \end{align*}
 again satisfies $X_1\ge|X_2|$.

