\begin{proposition}\label{Pro41}
Let $2\le p <\infty,\;0<s<1$ and $0\le \Lambda \le 1$. Assume $u \in HW_{{\rm{loc}}}^{1,p}\left( {{B_2}\left( {{\xi _0}} \right) \cap L_{sp}^{p - 1}\left( {{\mathbb{H}^n}} \right)} \right)$ is a weak solution of \eqref{eq0} in ${{B_2}\left( {{\xi _0}} \right)}$ satisfying
\begin{equation}\label{eq41}
{\left\| u \right\|_{{L^\infty }\left( {{B_1}\left( {{\xi _0}} \right)} \right)}} \le 1,\int_{{\mathbb{H}^n}\backslash {B_1}\left( {{\xi _0}} \right)} {\frac{{{{\left| {u\left( \eta \right)} \right|}^{p - 1}}}}{{\left\| \eta \right\|_{{\mathbb{H}^n}}^{Q + sp}}}d\eta } \le 1.
\end{equation}
If $0<h_0<\frac{1}{10}$ and $R$ satisfy $4{h_0}<R\le 1-5{h_0}$, and ${\nabla _H}u \in {L^q}\left( {{B_{R + 4{h_0}}}\left( {{\xi _0}} \right)} \right)$ for some $q \ge p$, then
\begin{equation}\label{eq42}
 \mathop {\sup }\limits_{0 < \left| h \right| < {h_0}} \int_{{B_{R - {4h_0}}}} {{{\left| {\frac{{\Delta _{Z,h}^2u}}{{{{\left| h \right|}^{\frac{1}{{q + 1}} + 1}}}}} \right|}^{q + 1}}d\xi } \le c(1+\Lambda) \left( {\int_{{B_{R + {4h_0}}}} {{{\left| {{\nabla _H}u} \right|}^q}d\xi } + 1} \right),
\end{equation}
where $c=c(Q,h_0,p,q,s)>0$.
\end{proposition}

For simplicity, we denote $u_R$ by $u$. Fix $0<\gamma<1$ and choose $i_\infty \in \mathbb{N}\setminus {0}$ such that
\begin{equation}\label{eq492}
1 - \gamma > \frac{Q}{{p + {i_\infty }}}.
\end{equation}
For $i = 0, \cdots ,{i_\infty }$, we define
\[{q_i} = p + i,\]
and
\[{h_0} = \frac{1}{{112{i_\infty }}},\;{R_i} = \frac{7}{8} - 4{h_0} - 14{h_0}i,\]
so
\[{R_0} + 4{h_0} = \frac{7}{8},\;{R_{{i_\infty }}} + 4{h_0} = \frac{3}{4},\;4{h_0} <R_i<1-5{h_0} .\]
By using Proposition \ref{Pro41} with
\[R = {R_i},q = {q_i},\;i = 0, \cdots ,{i_\infty },\]
and we have by \eqref{eq485}
\begin{equation}\label{eq486}
\mathop {\sup }\limits_{0 < \left| h \right| < {h_0}} \int_{{B_{R_0 - {4h_0}}}} {{{\left| {\frac{{\Delta _{Z,h}^2u}}{{{{\left| h \right|}^{\frac{1}{{{q_1}}} + 1}}}}} \right|}^{{q_1}}}d\xi } \le c(1 + \Lambda )\left( {\int_{{B_{\frac{7}{8}}}} {{{\left| {{\nabla _H}u} \right|}^p}d\xi } + 1} \right) \le C\left( {Q,p,s,\gamma} \right).
\end{equation}
Consider ${R_i} - 10{h_0} = {R_{i + 1}} + 4{h_0}$ for $i = 0, \cdots ,{i_\infty }$, we use Lemma \ref{Le213} in \eqref{eq486} to get
\begin{equation}\label{eq487}
\int_{{B_{{R_1} + 4{h_0}}}} {{{\left| {{\nabla _H}{u}} \right|}^{{q_1}}}d\xi } \le C\left( {Q,p,s,\gamma} \right).
\end{equation}
Applying Proposition \ref{Pro41} and \eqref{eq487} once again, we obtain
\begin{equation}\label{eq488}
\mathop {\sup }\limits_{0 < \left| h \right| < {h_0}} \int_{{B_{{R_1} - 4{h_0}}}} {{{\left| {\frac{{\Delta _{Z,h}^2u}}{{{{\left| h \right|}^{\frac{1}{{{q_2}}} + 1}}}}} \right|}^{{q_2}}}d\xi } \le c(1 + \Lambda )\left( {\int_{{B_{{{{R_1} + 4{h_0}}}}}} {{{\left| {{\nabla _H}u} \right|}^{{q_1}}}d\xi } + 1} \right) \le C\left( {Q,p,s,\gamma} \right).
\end{equation}
Moreover, by Lemma \ref{Le213} in \eqref{eq488}, we have
\begin{equation}\label{eq489}
\int_{{B_{{R_2} + 4{h_0}}}} {{{\left| {{\nabla _H}{u}} \right|}^{{q_2}}}d\xi } \le C\left( {Q,p,s,\gamma} \right).
\end{equation}
Repeating this procedure, it yields
\begin{equation}\label{eq490}
 \int_{{B_{{R_{i+1}} + 4{h_0}}}} {{{\left| {{\nabla _H}{u}} \right|}^{{q_{i+1}}}}d\xi } \le C\left( {Q,p,s,\gamma} \right)
\end{equation}
for all $i = 0, \cdots ,{i_\infty }-1.$ Taking $i={i_\infty }-1$ in \eqref{eq490} and using ${\left\| {{u}} \right\|_{{L^\infty }\left( {{B_1}} \right)}} \le 1$, we deduce
\begin{equation}\label{eq491}
{\left\| u \right\|_{H{W^{1,{q_{{i_\infty }}}}}\left( {{B_{{R_{{i_\infty }}} + 4{h_0}}}} \right)}} \le C\left( {Q,p,s,\gamma } \right).
\end{equation}
By means of \eqref{eq492}, we know ${q_{{i_\infty }}}>Q$, so we use ${R_{{i_\infty }}} + 4{h_0} = \frac{3}{4}$ and Lemma \ref{Le23} to get
$u \in C_{loc}^\gamma \left( {{B_{\frac{3}{4}}}} \right)$. In fact, we take a cut-off function $\psi$ between ${{B_{\frac{1}{2}}}}$ and ${{B_{\frac{3}{4}}}}$. Then
\begin{align}\label{eq493}
{\left\| u \right\|_{{C^\gamma }\left( {{B_{\frac{1}{2}}}} \right)}}& \le {\left\| {u\psi } \right\|_{{C^\gamma }\left( {{{\mathbb{H}}^n}} \right)}} \le c{\left\| {u\psi } \right\|_{H{W^{1,{q_{{i_\infty }}}}}\left( {{{\mathbb{H}}^n}} \right)}} = c{\left\| {u\psi } \right\|_{H{W^{1,{q_{{i_\infty }}}}}\left( {{B_{\frac{3}{4}}}} \right)}}\nonumber\\
& \le c{\left\| u \right\|_{H{W^{1,{q_{{i_\infty }}}}}\left( {{B_{\frac{3}{4}}}} \right)}} \le C\left( {Q,p,s,\gamma } \right).
\end{align}
Therefore, Theorem is proved.

\textbf{Proof of Theorem \ref{Th14}} After rescaling the variables as in the proof of Theorem \ref{Th13}, it suffices to show that
$${\left\| u_R \right\|_{{C^{1,\alpha }}\left( {{B_{\frac{1}{8}}}} \right)}} \le c\left( {Q,p,s,\gamma } \right),$$
where the function $u_R$ defined in \eqref{eq484} satisfies the following conditions:
\begin{equation}\label{eq52}
{\left\| {{u_R}} \right\|_{{L^\infty }\left( {{B_1}} \right)}} \le 1,\;{\int _{{\mathbb{H}^n}\backslash {B_1}}}\frac{{{{\left| {{u_R}\left( \eta \right)} \right|}^{p - 1}}}}{{\left\| \eta \right\|_{{\mathbb{H}^n}}^{Q + sp}}}d\eta \le 1.
\end{equation}
By Theorem \ref{Th13}, there exists $\gamma>\frac{sp}{p-1}$ such that
\[\mathop {\sup }\limits_{\xi \ne \eta \in {B_{\frac{1}{2}}}\left( {{\xi _0}} \right)} \frac{{\left| {{u_R}\left( \xi \right) - {u_R}\left( \eta \right)} \right|}}{{{{\left\| {{\eta ^{ - 1}} \circ \xi } \right\|}_{{\mathbb{H}^n}}^\gamma }}} \le c\left( {Q,p,s,\gamma } \right).\]
Now take any $\xi_0 \in {B_{\frac{1}{4}}}$, then we deduce from the above formula and the choice of $\gamma$ that
\[\int_{{B_{\frac{1}{4}}}\left( {{\xi _0}} \right)} {\frac{{{{\left| {{u_R}\left( {{\xi _0}} \right) - {u_R}\left( \eta \right)} \right|}^{p - 1}}}}{{{{\left\| {{\eta ^{ - 1}} \circ {\xi _0}} \right\|}_{{\mathbb{H}^n}}^{Q + sp}}}}d\eta } \le c\left( {Q,p,s,\gamma } \right)\int_{{B_{\frac{1}{4}}}\left( {{\xi _0}} \right)} {\frac{1}{{{{\left\| {{\eta ^{ - 1}} \circ {\xi _0}} \right\|}_{{\mathbb{H}^n}}^{Q + sp - \gamma \left( {p - 1} \right)}}}}d\eta } = c\left( {Q,p,s,\gamma } \right).\]
Moreover, we have by \eqref{eq52}
\[\int_{{\mathbb{H}^n}\backslash {B_{\frac{1}{4}}}\left( {{\xi _0}} \right)} {\frac{{{{\left| {{u_R}\left( {{\xi _0}} \right) - {u_R}\left( \eta \right)} \right|}^{p - 1}}}}{{{{\left\| {{\eta ^{ - 1}} \circ {\xi _0}} \right\|}_{{\mathbb{H}^n}}^{Q + sp}}}}d\eta } \le c\left( {Q,p,s} \right).\]
Hence
\[{\left\| {{{{{\left( { - \Delta _{{{\mathbb{H}},p}}} \right)}^s}}}{u_R}} \right\|_{{L^\infty }\left( {{B_{\frac{1}{4}}}} \right)}} \le c\left( {Q,p,s,\gamma } \right),\]
and also
\[{\left\| {{{{\left( { - \Delta _{{{\mathbb{H}},p}}} \right)}}}{u_R}} \right\|_{{L^\infty }\left( {{B_{\frac{1}{4}}}} \right)}} \le c\left( {Q,p,s,\gamma } \right),\]
which together with \eqref{eq52} and Theorem 1.2 in \cite{MZ21} imply
\[{\left\| {{u_R}} \right\|_{{C^{1,,\alpha }}\left( {{B_{\frac{1}{8}}}} \right)}} \le c\left( {Q,p,s,\gamma } \right).\]

post_theorem_intro_text:
\begin{remark}
In contrast to \cite{ZN26}, where the H\"older index $\gamma \in (0,\frac{sp}{p-1})$ relies on the parameters $s$ and $p$, Theorem \ref{Th13} establishes a parameter-independent H\"older regularity with $\gamma \in (0,1)$. This holds under more general nonlinear frameworks and is particularly advantageous for subsequent regularity analysis.
\end{remark}

\begin{theorem}\label{Th14}
Let $2\le p <\infty,\;0<s<1,\;sp<p-1$ and $0\le \Lambda \le 1$. Suppose $\Omega \in \mathbb{H}^n$ is a bounded open set and $u \in HW_{{\rm{loc}}}^{1,p}\left( \Omega \right) \cap{ L_{sp}^{p - 1}\left( {{\mathbb{H}^n}} \right)} $ is a weak solution of \eqref{eq0}. Then $u \in C_{loc}^{1,\alpha} \left( \Omega  \right)$ for some $0 < \alpha  < 1$. Moreover, for some $0 < \alpha  < 1$ and any Kor\'{a}nyi ball ${B_{2R}}\left( {{\xi _0}} \right) \subset  \subset \Omega $ with $0<R<1$, there exists a positive constant $c=c(Q,p,q,s,\gamma)$ such that
\begin{equation}\label{eq51}
 \mathop {\sup }\limits_{\xi  \ne \eta  \in {B_{\frac{R}{8}}}\left( {{\xi _0}} \right)} \frac{{\left| {{\nabla _H}u\left( \xi  \right) - {\nabla _H}u\left( \eta  \right)} \right|}}{{{{\left\| {{\eta ^{ - 1}} \circ \xi } \right\|}^\alpha _{\mathbb{H}^n}}}} \le \frac{c}{{{R^{1 + \alpha }}}}\left( {{{\left\| u \right\|}_{{L^\infty }\left( {{B_R}\left( {{\xi _0}} \right)} \right)}} + {\rm{Tai}}{{\rm{l}}_{p - 1,sp,p}}\left( {u;{\xi _0},R} \right)} \right),
\end{equation}
where the definition of ${\rm{Tai}}{{\rm{l}}_{p - 1,sp,p}}\left( {u;{\xi _0},R} \right)$ see \eqref{eq26} below.
\end{theorem}

The paper is organized as follows: In Section 2, we introduce relevant knowledge of the Heisenberg group, function spaces, and several necessary and new lemmas. In Section 3, we employ horizontal difference, along with certain difference estimates and the fractional Sobolev-type inequality on the Heisenberg group, to establish the crucial iteration scheme of Morrey-type for weak solutions to \eqref{eq0} required for the proof of the Theorem \ref{Th13}, i.e. Proposition \ref{Pro41}. In Section 4, we first establish a proposition regarding the gradient integrability of weak solutions by using Caccioppoli-type inequality, i.e. Proposition \ref{Pro42}. Then, by combining local boundedness, the Proposition \ref{Pro41}, the Proposition \ref{Pro42}, an iterative method, and the Morrey inequality, we prove Theorem \ref{Th13}. Finally, Theorem \ref{Th14} is derived by utilizing Theorem \ref{Th13} and Theorem 1.2 from \cite{MZ21}.

In the sequel, we denote by $c$ a generic positive constant which may vary from line to line. Relevant dependencies on parameters shall be emphasised utilizing parentheses, i.e., $c= c(n, p, q)$ means that $c$ depends on $n, p, q$.

expanded_sketch:
To prove the main theorem, the paper proceeds as follows. Next, it uses “horizontal difference, along with certain difference estimates and the fractional Sobolev-type inequality on the Heisenberg group” to “establish the crucial iteration scheme of Morrey-type for weak solutions to
\begin{equation}\label{eq0}
 - \Delta _{{{\mathbb{H}},p}}u + \Lambda{\left( { - \Delta _{{{\mathbb{H}},p}}} \right)^s}u = 0\;{\rm{in}}\;\Omega ,
\end{equation}
required for the proof of the main theorem, i.e. the following proposition.

\begin{proposition}\label{Pro41}
Let $2\le p <\infty,\;0<s<1$ and $0\le \Lambda \le 1$. Assume $u \in HW_{{\rm{loc}}}^{1,p}\left( {{B_2}\left( {{\xi _0}} \right) \cap L_{sp}^{p - 1}\left( {{\mathbb{H}^n}} \right)} \right)$ is a weak solution of \eqref{eq0} in ${{B_2}\left( {{\xi _0}} \right)}$ satisfying
\begin{equation}\label{eq41}
{\left\| u \right\|_{{L^\infty }\left( {{B_1}\left( {{\xi _0}} \right)} \right)}} \le 1,\int_{{\mathbb{H}^n}\backslash {B_1}\left( {{\xi _0}} \right)} {\frac{{{{\left| {u\left( \eta  \right)} \right|}^{p - 1}}}}{{\left\| \eta  \right\|_{{\mathbb{H}^n}}^{Q + sp}}}d\eta }  \le 1.
\end{equation}
If $0<h_0<\frac{1}{10}$ and $R$ satisfy $4{h_0}<R\le 1-5{h_0}$, and ${\nabla _H}u \in {L^q}\left( {{B_{R + 4{h_0}}}\left( {{\xi _0}} \right)} \right)$ for some $q \ge p$, then
\begin{equation}\label{eq42}
 \mathop {\sup }\limits_{0 < \left| h \right| < {h_0}} \int_{{B_{R - {4h_0}}}} {{{\left| {\frac{{\Delta _{Z,h}^2u}}{{{{\left| h \right|}^{\frac{1}{{q + 1}} + 1}}}}} \right|}^{q + 1}}d\xi } \le c(1+\Lambda) \left(  {\int_{{B_{R + {4h_0}}}} {{{\left| {{\nabla _H}u} \right|}^q}d\xi } + 1} \right),
\end{equation}
where $c=c(Q,h_0,p,q,s)>0$.
\end{proposition}

Next, it “first establish[es] a proposition regarding the gradient integrability of weak solutions by using Caccioppoli-type inequality, i.e.” the following.

\begin{proposition}\label{Pro42}
Let $2\le p <\infty,\;0<s<1$ and $0\le \Lambda \le 1$. If $u \in HW_{{\rm{loc}}}^{1,p}\left( {{B_2}\left( {{\xi _0}} \right) \cap L_{sp}^{p - 1}\left( {{\mathbb{H}^n}} \right)} \right)$ is a weak solution of \eqref{eq0} in ${{B_{2}}\left( {{\xi _0}} \right)}$ satisfying \eqref{eq41}, then
\begin{equation*}
\int_{{B_{\frac{7}{8}}}\left( {{\xi _0}} \right)} {{{\left| {{\nabla _H}u} \right|}^p}d\xi }  \le C\left( {Q,p,s} \right).
\end{equation*}
\end{proposition}

Then, “by combining local boundedness, the proposition above, the preceding proposition, an iterative method, and the Morrey inequality, we prove the main theorem.”

