\begin{conjecture}{\rm~\cite{Pak}}\label{conj:pak}
	For every $ k,\, D\in \mathbb{N}  $ there exist  $ C,\, L > 0 $ such that if $ H $
	is a graph with $ \Delta(H) \leq D $ and $ \sigma(e)\ge L\log(|V(H^{\sigma})|) $ for all $ e \in E(H) $, then
	$\widehat{R}(H^{\sigma}, k)\leq C|V(H^{\sigma})| $.
\end{conjecture}

