 \| \psi \|_{L^6(X)}\lesssim_\varepsilon \lambda^{\frac{26}{171}+\varepsilon}=\lambda^{\frac{1}{6}-\frac{5}{342}+\varepsilon}.
\end{align}

On the noncompact quotient $\operatorname{SL}(2,\mathbb{Z})\backslash\mathbb{H}$, for a Hecke-Maass cusp form $\psi$ whose spectral parameter is $\lambda$, both $L^\infty$-norm bound \eqref{eq: IS bound} and $L^4$-norm bound \eqref{eq: HK L4} hold as well, so one still has the same $L^6$-norm bound \eqref{eq: HK L6}. In \cite{ki20234}, Ki showed an essentially sharp upper bound $\|\psi\|_{L^4(\operatorname{SL}(2,\mathbb{Z})\backslash\mathbb{H})}\lesssim_\varepsilon\lambda^{\varepsilon}$, by using the
Fourier-Whittaker expansions of Hecke-Maass cusp forms. This result justifies Iwaniec-Sarnak's conjecture for $2<q\leq4$, and therefore implies a better $L^6$-norm bound
\begin{align*}
 \| \psi \|_{L^6(\operatorname{SL}(2,\mathbb{Z})\backslash\mathbb{H})}\lesssim_\varepsilon \lambda^{\frac{1}{6}-\frac{1}{36}+\varepsilon}.
\end{align*}

The main result of the paper is the following sublocal $L^6$-norm bound in the \textit{compact} setting, which is weaker than \eqref{eq: HK L6} but is based on a completely different approach.

For these $X$ and $\psi$, the first power-saving result was obtained by Iwaniec and Sarnak \cite{IS95}. They showed that 
\begin{align}\label{eq: IS bound}
 \|\psi\|_{L^\infty(X)} \lesssim_\epsilon\lambda^{\frac{5}{12}+\epsilon},
\end{align}
which is a $\la^{\frac1{12}}$ improvement over the uniform bound \eqref{r1} for $n=2$ and $q=\infty$. In two-dimensional cases, the critical exponent is $q_c=6$, by interpolation, \eqref{eq: IS bound} implies an improvement for $ \| \psi \|_{L^q(X)}$ for all $q>6$. Their proof uses the technique known as arithmetic amplification. This approach has since been used by many authors to bound $L^\infty$-norms of Hecke-Maass forms on other groups. For instance, see \cite{BM13,Mar14,BHM16,BM16,BP16,BHM20} for results in the spectral aspect.

On the noncompact quotient $\SL(2,\BZ)\backslash\BH$, for a Hecke-Maass cusp form $\psi$ whose spectral parameter is $\la$, both $L^\infty$-norm bound \eqref{eq: IS bound} and $L^4$-norm bound \eqref{eq: HK L4} hold as well, so one still has the same $L^6$-norm bound \eqref{eq: HK L6}. In \cite{ki20234}, Ki showed an essentially sharp upper bound $\|\psi\|_{L^4(\SL(2,\BZ)\backslash\BH)}\lesssim_\epsilon\la^{\epsilon}$, by using the
Fourier-Whittaker expansions of Hecke-Maass cusp forms. This result justifies Iwaniec-Sarnak's conjecture for $2<q\leq4$, and therefore implies a better $L^6$-norm bound
\begin{align*}
 \| \psi \|_{L^6(\SL(2,\BZ)\backslash\BH)}\lesssim_\epsilon \la^{\frac{1}{6}-\frac{1}{36}+\epsilon}.
\end{align*}

\subsection{Proof strategy}
A main step in the proof of Theorem~\ref{thm1} is the following.
\begin{theorem}\label{thm2}
 Let $(M,g)$ be a compact $2$-dimensional Riemannian manifold without boundary. Let $e_\la$ be an $L^2$ normalized eigenfunction of $-\Delta_g$ with eigenvalue $\la^2$, satisfying \eqref{1.2} for some $\la\gg1$. Set $\theta_0=\la^{-\delta_1}$ with $0<\delta_1< \frac12$, and let $A_\nu^{\theta_0}$ be the pseudo-differential operator defined in \eqref{qnusymbol}. Assume that 
\begin{equation}\label{i3}
 \sup_\nu\|A_\nu^{\theta_0} e_\la\|_{L^6(M)}\lesssim_\e \la^{\frac16-a{\delta_1}+\e},
 \end{equation}
 and 
 \begin{equation}\label{i4}
 \|e_\la\|_{L^\infty(M)}\lesssim_\e \la^{\frac12-\delta_2+\e}
 \end{equation}
for some constant $a>0$ and $0<\delta_2<\frac{1}{2}$. Then 
 \begin{equation}\label{i5}
 \|e_\la\|_{L^6(M)}\lesssim_\e \la^{\frac16-\frac23a{\delta_1}+\e}+\la^{\frac23(-\frac14+\frac53\delta_1)}+\la^{\frac16(1+\delta_1-2\delta_2)+\e}.
 \end{equation}
\end{theorem}
For each fixed $\nu$, the operator $A_\nu^{\theta_0}$ is microlocally supported in a $\theta_0$-neighborhood of a geodesic segment and is frequency-localized to directions near that geodesic; the precise definition will be given in Section \ref{sec: microlocal decomposition}. The proof of Theorem~\ref{thm2} follows a strategy similar to that of \cite{huang2024curvature}, relying on bilinear techniques from harmonic analysis together with the improved $L^\infty$ estimate \eqref{i4}. We will prove Theorem~\ref{thm2} in Section \ref{sec: 2}. 
The idea of using improved microlocal $L^6$-norm estimate to derive improved global $L^6$-norm estimate is inspired by the recent work \cite{blair2024improved}.

\begin{theorem}\label{thm microlocal KN}
 Let $\psi$ be a Hecke–Maass form on $X$ with spectral parameter $\lambda\gg1$. Set $\theta_0=\la^{-\delta_1}$ with $0<\delta_1<\frac12$, and let $A_\nu^{\theta_0}$ be the pseudo-differential operator defined in \eqref{qnusymbol}. We have
 \begin{equation*}
 \sup_\nu\|A_\nu^{\theta_0} \psi\|_{L^6(X)}\lesssim_\e \la^{\frac16-\frac{\delta_1}{12}+\e}.
 \end{equation*}
\end{theorem}

We let $\Delta_g$ be the Laplace-Beltrami operator on $\BH$ and $X$, which is induced from the standard hyperbolic Riemannian metric. Let $\psi\in L^2(X)$ be a Hecke-Maass form that is an eigenfunction of $\Delta_g$ and the operators $T_n$ with $(n,q)=1$. We let $\lambda(n)$ be the Hecke eigenvalues of $\psi$ and $\lambda$ be its spectral parameter, so that
\begin{equation}\label{def}
 \begin{aligned}
 &T_n\psi=\lambda(n)\psi,\\
 &\Delta_g\psi+(\frac{1}{4}+\lambda^2)\psi=0. 
 \end{aligned}
\end{equation}
We assume that $\| \psi \|_{L^2(X)}=1$ with respect to the hyperbolic volume on $X$ and assume that $\lambda\gg1$. Note that because $\Delta_g$ and $T_n$ with $(n,q)=1$ are self-adjoint, we may assume that $\psi$ is real-valued. For functions on $X$, we will also think of them as functions on $G$ that are left $\Gamma$-invariant and right $K$-invariant.

\begin{proof}[Proof of Theorem \ref{thm microlocal KN}]
 By Lemma \ref{lem 3.10}, we may bound $\| \sA\psi\|_{L^6(X)}$ instead, and moreover by duality, it suffices to bound $\langle\sA\psi,\phi\rangle_X$ uniformly for any $\phi\in C^\infty(X)$ with $\|\phi\|_{L^{6/5}(X)}=1$.
 By Proposition \ref{prop: amplification inequality}, we have
 \begin{align}\label{eq: amplification inequality}
 \left|\langle \sA\cT\psi,\phi\rangle_X\right|^2\leq\sum_{m,n\leq N} |\alpha_m \alpha_n | \sum_{d|(m,n)} \frac{d}{\sqrt{mn}}\sum_{\gamma\in R(mn/d^2)} |I_\sA(\la,\phi,\gamma )|.
 \end{align}
 Fix $0<\epsilon_0\ll\delta_1$. By assuming the support of $k_\la$ and $\Omega$ are sufficiently small, and by Proposition \ref{prop: bound for I_A}, we only need to consider the terms in \eqref{eq: amplification inequality} with $d(g_0^{-1}\gamma g_0,e)\leq1$ and $d(g_0^{-1}\gamma g_0,A)\leq\lambda^{-\delta_1+2\epsilon_0}$. Lemma \ref{lem: Hecke return} gives
 \[
 M(g_0,n,\lambda^{-\delta_1 +2\epsilon_0})\ll_\epsilon n^\epsilon \lambda^{\epsilon_0+\epsilon}(n\lambda^{-\delta_1/2}+1),
 \]
 and so by the uniform estimate $|I_\sA(\la,\phi,\gamma )|\lesssim_\epsilon \la^{1/3+\epsilon}$ from Proposition \ref{prop: bound for I_A} we have
 \begin{align*}
 &\sum_{m,n\leq N} |\alpha_m\alpha_n| \sum_{d|(m,n)} \frac{d}{\sqrt{mn}}\sum_{\gamma\in R(mn/d^2)}\left| I_{\sA}(\lambda, \phi, \gamma ) \right|\\
 \lesssim& \sum_{m,n\leq N} |\alpha_m\alpha_n| \sum_{d|(m,n)} \frac{d}{\sqrt{mn}}\lambda^{1/3+\e} M(g_0,\frac{mn}{d^2},\lambda^{-\delta_1+2\epsilon_0})+O_{\epsilon_0,A}(\lambda^{-A})\\
 \lesssim&_\epsilon N^\epsilon\lambda^{\epsilon_0+\epsilon}\sum_{m,n\leq N} |\alpha_m\alpha_n| \sum_{d|(m,n)} \left(\frac{\sqrt{mn}}{d}\lambda^{1/3-\delta_1/2}+\frac{d}{\sqrt{mn}}\lambda^{1/3}\right) +O_{\epsilon_0,A}(\lambda^{-A}).
 \end{align*}
 As in \cite[p.310]{IS95}, we have
 \begin{align*}
 \sum_{m,n\leq N} \sum_{d|(m,n)}|\alpha_m\alpha_n|\frac{\sqrt{mn}}{d}\lesssim_\epsilon N^{1+\epsilon} \left( \sum_{n\leq N} |\alpha_n|\right)^2
 \end{align*}
 and
 \begin{align*}
 \sum_{m,n\leq N} \sum_{d|(m,n)}|\alpha_m\alpha_n|\frac{d}{\sqrt{mn}}&=\sum_{\substack{m,n\leq N\\(m,n)=1}} \sum_{ml,nl\leq N}\sum_{d|l}|\alpha_{ml}\alpha_{nl}|\frac{d}{l\sqrt{mn}}\\
 &\lesssim_\epsilon N^\epsilon\sum_{ml,nl\leq N}\left( \frac{|\alpha_{ml}|^2}{n} + \frac{|\alpha_{nl}|^2}{m} \right)\\
 &\lesssim_\epsilon N^\epsilon \sum_{n\leq N} |\alpha_n|^2.
 \end{align*}
 Hence from \eqref{eq: amplification inequality} we have
 \begin{align*}
 \left| \langle \sA\cT\psi,\phi\rangle_X \right|^2 \lesssim&_\epsilon N^\epsilon\lambda^{\epsilon_0+\epsilon}\left(N\lambda^{1/3-\delta_1/2}\left( \sum_{n\leq N} |\alpha_n|\right)^2+\lambda^{1/3}\sum_{n\leq N} |\alpha_n|^2\right) +O_{\epsilon_0,A}(\lambda^{-A}).
 \end{align*}
 Combining this with \eqref{eq: moment for alpha} and \eqref{eq: lower bound for amplifier eigenvalue} and choosing $\epsilon_0$ small gives
 \begin{align*}
 N^{1-\epsilon}\left|\langle \sA\psi,\phi\rangle_X \right|^2\lesssim&_\epsilon N^\epsilon\lambda^{\epsilon}\left(N^2\lambda^{1/3-\delta_1/2}+N^{1/2}\lambda^{1/3}\right)+O_{\epsilon,A}(\lambda^{-A}),
 \end{align*}
 which completes the proof by choosing $N=\lambda^{\delta_1/3}$.
\end{proof}

