full_context:
A central problem in extremal combinatorics is to determine the maximum possible size of a set family subject to a given constraint. We consider families $\mathcal{F} \subseteq 2^{[n]}$ on the ground set $[n] = \{1, \dots, n\}$. A \emph{matching} in $\mathcal{F}$ is a collection of pairwise disjoint members of $\mathcal{F}$. The \emph{matching number} of $\mathcal{F}$, denoted $\nu(\mathcal{F})$, is the cardinality of a maximum matching.

This paper focuses on $k$-uniform families, $\mathcal{F} \subseteq \binom{[n]}{k}$, that are $s$-matching-free, i.e., $\nu(\mathcal{F}) \le s-1$. We denote the maximum possible size of such a family by $f(n,k,s)$. In 1965, Erd\H{o}s \cite{erdos1965} posed a conjecture for the exact value of $f(n,k,s)$, which has become a celebrated open problem in the field.

\begin{conjecture}[Erd\H{o}s Matching Conjecture \cite{erdos1971}] \label{emc}
 For $n \ge sk$,
 \[f(n,k,s) = \max\left\{\binom{sk-1}{k}, \binom{n}{k}-\binom{n-s+1}{k}\right\}.\]
 \end{conjecture}

The two expressions in the maximum correspond to two canonical extremal families.
 \begin{enumerate}
 \item The family $\mathcal{G}^* = \binom{[sk-1]}{k}$, which consists of all $k$-subsets of a fixed set of $sk-1$ elements.
 \item The family $\mathcal{F}^* = \{F \in \binom{[n]}{k} : F \cap S \neq \emptyset\}$ for a fixed set $S \subset [n]$ with $|S| = s-1$. This family consists of all $k$-subsets that intersect a fixed set of $s-1$ elements.
 \end{enumerate}
 The conjecture is trivially true for $n < sk$, as in this case $\nu(\mathcal{F}) \le s-1$ holds for the entire family $\binom{[n]}{k}$.
 The conjecture has a rich history and has been verified in several important cases. For $s=2$, the problem is to find the largest intersecting family, and the conjecture follows from the Erd\H{o}s-Ko-Rado theorem \cite{erdos1961}. Kleitman \cite{kleitman1968} proved the conjecture for the boundary case $n=sk$.

\begin{definition}
 A family is said to be \emph{trivial} if there exists at least one element $x \in [n]$ that is not contained in any $F \in \mathcal{F}$. A family that is not trivial is \emph{non-trivial}.
 \end{definition}

By analyzing the behavior of families under shift operations, and paying close attention to whether intermediate families in our algorithm become trivial, we establish the following theorem in Section \ref{sec:4}.

\newtheorem*{statement1}{Statement of Theorem 1}
\newtheorem*{statement2}{Statement of Lemma 2}
\begin{document}
 \title{Erd\H{o}s Matching (Conjecture) Theorem}
 \author{Tapas Kumar Mishra \footnote{Orcid: 0000-0002-9825-3828} \\
 Department of Computer Science and Engineering,\\
 National Institute of Technology, Rourkela
 769008, India\\
 mishrat@nitrkl.ac.in\\
 https://mishra-tapas.github.io/}
 \maketitle \begin{abstract}
 Let $\mathcal{F}$ be a family of $k$-sized subsets of $[n]$ that does not contain $s$ pairwise disjoint subsets.
 The Erd\H{o}s Matching Conjecture, a celebrated and long-standing open problem in extremal combinatorics, asserts the maximum cardinality of $\mathcal{F}$ is upper bounded by
 $\max\left\{\binom{sk-1}{k}, \binom{n}{k}-\allowbreak \binom{n-s+1}{k}\right\}$.
 These two bounds correspond to the sizes of two canonical extremal families: one in which all subsets are contained within a ground set of $sk-1$ elements, and one in which every subset intersects a fixed set of $s-1$ elements.
 In this paper, we prove the conjecture.

\begin{conjecture}[Erd\H{o}s Matching Conjecture \cite{erdos1971}] \label{emc}
 For $n \ge sk$,
 \[f(n,k,s) = \max\left\{\binom{sk-1}{k}, \binom{n}{k}-\binom{n-s+1}{k}\right\}.\]
 \end{conjecture}

By analyzing the behavior of families under shift operations, and paying close attention to whether intermediate families in our algorithm become trivial, we establish the following theorem in Section \ref{sec:4}.

The key technical ingredients in our proof are the classical $(i,j)$ shift operator of Fr\'{a}nkl. The precise effects of these operators on a family's matching number and its potential for triviality are detailed in Lemma \ref{lemma:1}, \ref{lemma:2}. This algorithmic framework, which tracks the properties of families through a sequence of shifts, can be extended to the non-uniform case as well.
 \section{Shifting operator and supporting lemmas}
 \label{sec:2}
 \begin{definition}[Fr\'{a}nkl's $(i,j)$ shift]
 Let $\mathcal{F} \subseteq 2^{[n]}$. For $1 \leq i,j \leq n$, define $\mathcal{C}_{ij}(\mathcal{F})= \{\mathcal{C}_{ij}(F): F \in \mathcal{F}\}$, where
 \begin{align*}
 \mathcal{C}_{ij}(F) = \begin{cases}
 (F \setminus \{j\})\cup \{i\} , \text{ if $i \not \in F$, $j \in F$, and $(F \setminus \{j\})\cup \{i\} \not\in \mathcal{F}$},\\
 F, \text{ otherwise.}
 \end{cases}
 \end{align*}
 \end{definition}
 We have two lemmas on the effects of a $(i,j)$ shift on a family $\mathcal{F}$.

\begin{lemma} \label{lemma:1}
 Let $\mathcal{F}$ be a family of subsets of $[n]$ and let $1 \leq i, j \leq n$. Then the following hold:
 \begin{enumerate}[label=(\roman*)]
 \item For any $F \in \mathcal{F}$, $|\mathcal{C}_{ij}(F)| = |F|$.
 \item $|\mathcal{C}_{ij}(\mathcal{F})| = |\mathcal{F}|$.
 \item The matching number does not increase, i.e., $\nu(\mathcal{C}_{ij}(\mathcal{F})) \leq \nu(\mathcal{F})$.
 \end{enumerate}
 \end{lemma}
 \begin{proof}
 The proof of (i) and (ii) are given in \cite{frankl1987}. As (iii) is probably folklore, the proof is given in the Appendix \ref{app:1}. 
 \end{proof}

\section{Proof of Theorem \ref{thm:main1}}
 \label{sec:4}
For a family $\mathcal{F}$ and an element $x \in [n]$, we denote the subfamily of sets containing $x$ as $\mathcal{F}^x = \{F \in \mathcal{F} : x \in F\}$. 
 \begin{statement1}
 Let $n,s,k$ be positive integers, $n \geq sk$, $k \geq 1$.
 Let $\mathcal{F} \subseteq \binom{[n]}{k}$ be a family with no $s$ pairwise disjoint sets. Then, $|\mathcal{F}| \leq \max\left\{\binom{n}{k}-\binom{n-s+1}{k}, \binom{sk-1}{k}\right\}$.
 \end{statement1}
 \begin{proof}
 The family $\mathcal{F}^* = \{F \in \binom{[n]}{k} : F \cap \{1, \dots, s-1\} \neq \emptyset\}$ satisfies the condition $\nu(\mathcal{F}^*) \le s-1$ and has size exactly $\binom{n}{k} - \binom{n-s+1}{k}$. 
 Let $\mathcal{G}^*=\binom{[sk-1]}{k}$.
 We will show that no family satisfying the hypothesis can be larger in cardinality than both $\mathcal{F}^*$ and $\mathcal{G}^*$. The proof uses an iterative algorithm that transforms any valid family $\mathcal{F}$ into one where the desired structure is evident.

\begin{enumerate}
 \item If $\mathcal{F}$ is trivial, let $Y \subseteq [n']$ be the largest set of vertices with no element of $Y$ being a member of any set in $\mathcal{F}$ (i.e. $\forall y \in Y \forall F \in \mathcal{F}$, $y \not\in F$). Set $\mathcal{F}$ to be the non-trivial family on $[n']\setminus Y$ and with a relabeling (that does not change $S$), assume the ground set is exactly $[n'-|Y|]$. Set $n'=n'-|Y|$. Note that this transformation preserves $|\mathcal{F}|$ and $\nu(\mathcal{F})$.
 If $n' \leq sk-1$, $\mathcal{F} \subseteq \mathcal{G}^*$ and we terminate the algorithm.
 Otherwise, set $\mathcal{F}^* = \{F \in \binom{[n']}{k} : F \cap \{1, \dots, s-1\} \neq \emptyset\}$.
 \item If the current family $\mathcal{F}$ is not a subfamily of $\mathcal{F}^*$, then there must exist a set $A \in \mathcal{F}$ such that $A \cap S = \emptyset$.
 \item There must also exist a set $B \notin \mathcal{F}$ such that $B \cap S \neq \emptyset$. If no such $B$ exists, the algorithm terminates and proceeds to the ``Contradiction'' phase described in Section III.
 \item Let $X = A \cap B$. Define $A' = A \setminus X = \{a_1, \dots, a_r\}$ and $B' = B \setminus X = \{b_1, \dots, b_r\}$. By construction, all elements $a \in A'$ are not in $S$. We can order the elements in $B'$ such that $b_1 \in S$. The remaining elements in $B'$ and all elements in $A'$ are ordered arbitrarily.

The algorithm terminates under three conditions.\\
 \textbf{Condition 1: $n' \leq sk-1$}. In this case, $\mathcal{F} \subseteq \mathcal{G}^*$ and $|\mathcal{F}| \leq \binom{sk-1}{k}$.\\
 \textbf{Condition 2: the current family $\mathcal{F}$ is a subfamily of $\mathcal{F}^*$}. In this case, $|\mathcal{F}| \leq \binom{n'}{k}-\binom{n'-s+1}{k} \leq \binom{n}{k}-\binom{n-s+1}{k}$ and the bound follows.\\
 \textbf{Condition 3: if the algorithm reaches a state where it can find a set $A \in \mathcal{F}$ with $A \cap S = \emptyset$, but it cannot find a set $B \notin \mathcal{F}$ with $B \cap S \neq \emptyset$}. This implies that the current family $\mathcal{F}$ contains \textbf{all possible $k$-sets that intersect $S$}.
 We can now derive a contradiction. Let $A$ be the set in $\mathcal{F}$ that is disjoint from $S$. We can construct $s-1$ new sets, $B_1, \dots, B_{s-1}$, that are pairwise disjoint and also disjoint from $A$.
 \begin{itemize}
 \item Choose a set $X$ of size $(s-1)k$ from $[n']\setminus A$
 such that $\{1,\ldots,s-1\} \subset X$.
 Partition $X$ into $s-1$ sets $B_1,\ldots,B_{s-1}$
 with $B_i \cap \{1,\ldots,s-1\}=\{i\}$.
 \end{itemize}
 This construction is possible because the condition $n' \ge sk$ ensures there are enough elements available. Since each $B_i$ intersects $S$, and our family $\mathcal{F}$ contains all such sets, it follows that $\{B_1, \dots, B_{s-1}\} \subset \mathcal{F}$.
 The collection \textbf{$\{A, B_1, \dots, B_{s-1}\}$} is therefore a matching of size $s$ within $\mathcal{F}$. This contradicts the hypothesis that $\nu(\mathcal{F}) \le s-1$.

\begin{lemma} \label{lemma:1}
		Let $\mathcal{F}$ be a family of subsets of $[n]$ and let $1 \leq i, j \leq n$. Then the following hold:
		\begin{enumerate}[label=(\roman*)]
			\item For any $F \in \mathcal{F}$, $|\mathcal{C}_{ij}(F)| = |F|$.
			\item $|\mathcal{C}_{ij}(\mathcal{F})| = |\mathcal{F}|$.
			\item The matching number does not increase, i.e., $\nu(\mathcal{C}_{ij}(\mathcal{F})) \leq \nu(\mathcal{F})$.
		\end{enumerate}
	\end{lemma}

\begin{lemma}\label{lemma:2}
		Let $\mathcal{F}$ be a trivial family on the ground set $[n]$. Then for any $1 \leq i, j \leq n$, $i\neq j$, the family $\mathcal{C}_{ij}(\mathcal{F})$ is also a trivial family.
	\end{lemma}

