 \begin{equation}
 \label{eq:rho-trig}
 \rho^{-2}(\varphi) = a_2 + b_2\cos 2\varphi + c_2\sin 2\varphi,
 \end{equation}
 with $a_2 = (a_1+c_1)/2$, $b_2 = (a_1-c_1)/2$ and $c_2 = b_1$, so
 \begin{equation}
 \label{eq:ellipse-cond}
 a_2 > 0,\quad a_2^2 > b_2^2 + c_2^2.
 \end{equation}
 Usually this is expressed in terms of $\cos2(\varphi-\theta)$, where $\theta$ is the tilt angle. Let $\mathcal E$ be the family of all ellipses in polar co-ordinates, that is, all curves in the form \eqref{eq:rho-trig} for all values of the parameters $a_2,b_2,c_2$ which satisfy \eqref{eq:ellipse-cond}. It is clear that the cone \eqref{eq:ellipse-cond} parametrises one-to-one the ellipses, as well as $\PD{\R^2}{X}$, which we will use when establishing the uniqueness part of our main result. Let
 \begin{equation}
 \label{eq:C-def}
 \mathcal{C} := \{\log \rho:\ \rho\in\mathcal{E}\}.
 \end{equation}
