ref_dict.prop:law-TG:
\begin{proposition}
\label{prop:law-TG}
Fix $u>0$, let $\G$ be distributed according to $\Pu$, and denote by $(\bTT,(\bphi_v,v\in \bTT))$ the decorated block tree $\TT_\G$, where $\bTT$ is the undecorated block tree and $(\bphi_v,v\in \bTT)$ is its family of vertex decorations. Then the law of $\TT_\G$ can be described as follows:
\begin{itemize}
\item $\bTT$ follows the law $\BGWl{\muT^u}$;
\item Conditionally given $\bTT=\t$, the decorations $(\bphi_{v},v\in \t)$ are independent random variables, and, for $v\in\t$, $\bphi_{v}$ is distributed according to $\Gamma \Phi(C^\bullet(\rho(u),u),u)$ conditioned to have size $d_\t(v)$.
\end{itemize}
For every $n\in\Npos$, the same statements hold under $\Pnu$, only replacing $\BGWl{\muT^u}$ with $\BGWl{\muT^u,n}$.
\end{proposition}

ref_dict.thm:block-sizes:
\begin{theorem}\label{thm:block-sizes}
There is a phase transition for block sizes depending on the value of $u$:
\begin{itemize}
    \item In the subcritical phase $u < u_C$, there is a largest block of size $\Theta_\mathbb{P}(n)$ and a second largest block of size $\Theta_\mathbb{P}(n^{2/3})$;
    \item In the critical phase $u = u_C$, there is a largest block of size $\Theta_\mathbb{P}(n^{2/3})$ and likewise for the next largest block sizes;
    \item In the supercritical phase $u > u_C$, there is a largest block of size $\Theta_\mathbb{P}(\ln (n))$ and likewise for the next largest block sizes.
\end{itemize}
\end{theorem}

ref_dict.thm:phase-transition:
\begin{theorem}\label{thm:phase-transition}
Let $\cC$ be a block-stable class of connected graphs, let $\cB$ be its class of $2$-connected components whose EGF we denote by $B(y)$, and let $\rho_B$ be the radius of convergence of $B$. Let
\[u_C := \frac{1}{\rho_B B''(\rho_B)}.\]
Then the following hold. 
\begin{itemize}
    \item The singular behaviour of $C^{\bullet}(x,u)$ depends on the relative positions of $u$ and $u_C$;
    \item The block tree corresponding to a graph drawn according to $\Pnu$ follows a subcritical \BGW{} tree law if $u<u_C$, and a critical \BGW{} tree law if $u \ge u_C$.
\end{itemize}
\end{theorem}

ref_dict.subsec:anal-comb-block-tree:
\begin{enumerate}
    \item \emph{Block graph} $B(\g)$ (see e.g., \cite{harary1969}): The vertices of $B(\g)$ are the blocks of $\g$, and two blocks are joined by an edge in $B(\g)$ if they overlap at a vertex. The resulting graph $B(\g)$ is characterised by the property of being connected and that all of its blocks are cliques.
    \item \emph{Block-cut graph} $T(\g)$ (see e.g., \cite{diestel2025graph}): The vertices of $T(\g)$ are the blocks and the cut-vertices of $\g$, and a cut-vertex is joined to a block by an edge in $T(\g)$ if that vertex is contained in that block. The resulting graph $T(\g)$ is a tree.
\end{enumerate}

In the present work, we use an alternative block decomposition that naturally arises from the Lagrangean form of \eqref{eq:Cbullet-block} of the generating series $C^{\bullet}(x)$. It originates from work of Addario-Berry \cite{2Louigi} on planar maps (see also \cite{Sal24}), and we give a precise algorithmic description in \cref{subsec:anal-comb-block-tree}. We note that this construction works specifically for \emph{rooted} labelled connected graphs, and we call its output a \emph{decorated block tree}. In a decorated block tree, the vertices represent all the vertices of the original graph $\g$ but each vertex is decorated by a set of blocks that contain that vertex. In \cite{2Louigi}, the decorations were simply blocks, but in our construction the decorations are more general \emph{sets of blocks}.

\section{Decorated block trees of connected block-stable graphs}
\label{sec:decorated}
In this section, we describe \emph{decorated block trees}, which are a central tool in our analysis.

\subsection{Construction of decorated block tree}
\label{subsec:anal-comb-block-tree}
Recalling the Lagrangean form of \cref{eq:Cbullet-block}, we define
\begin{equation}
\label{eq:def-Phi}
\Phi(y) = \sum_{k=0}^\infty \frac{\phi_k}{k!} y^k \coloneqq \exp(B'(y)) \in \mathbb C [[y]],
\end{equation}
which is precisely the exponential generating function for the class $\Set \circ \mathcal{B}'$. For convenience we also use $\Phi$ to denote  the class $\Set \circ \mathcal{B}'$. It follows from \cref{eq:Cbullet-block} that
\[C^\bullet(x) = x \Phi(C^\bullet(x)).\]
As explained in \cite[\S 2.2.1]{Sal24}, there is a systematic way to define a (plane) block tree from a Lagrangean decomposition scheme. Namely, each vertex of the tree is decorated with an object $\varphi$ from the class $\Phi$, and the subtrees attached to a vertex of the tree (corresponding to some $\varphi$) are the trees of the rooted graphs substituted into $\varphi$. The situation in the case of graphs is a little more involved than in the case of maps because of the labelling possibilities. Thus, we use the following notion.

Remember that elements of the class $\Phi$ are well-labelled. Therefore, for each $\g \in \cC$, when we consider sets of derived blocks of $\g$, it is always implied that the set has been relabelled with a well-labelling which is consistent with the order of the labels in $\g$.

\begin{figure}
\begin{center}
\includegraphics[width=1\textwidth]{images/block-tree.pdf}
\end{center}
\caption{The image on the left is a connected labelled rooted planar graph $\g$, with root highlighted in grey. The image on the right is the associated decorated block tree $\TT_\g$.}
\label{fig:block-tree-2}
\end{figure}

Now, we give an algorithmic definition of decorated block trees. An example is provided in \cref{fig:block-tree-2}.

\begin{definition}
For $\g\in \cC^\bullet$ (which for ease of presentation $\g$ is also allowed to be a rooted derived graph, with a root and one unlabelled non-root vertex), we define the \emph{decorated block tree $\TT_\g$} as the result of the following construction:
\begin{enumerate}
    \item Let $r$ be the root of $\g$, and let $\varphi = \{\b'_1, \ldots, \b'_\ell\}$ be the set of derived blocks containing $r$ \emph{and no unlabelled vertex} in $\g$, where the label of the vertex corresponding to $r$ is removed. Start with a root vertex $r_{\TT}$ in $\TT_\g$ and decorate it with $\varphi$.
    \item For $i \in \{1, \ldots, \ell\}$, we construct a derived graph $\g'_{\b_i}$ by deleting $r$ from $\g$, keeping the connected component of $\g$ that intersects $\b'_i$, and then adding $r$ back to this subgraph. We consistently relabel the vertices of $\g'_{\b_i}$ except $r$ which remains unlabelled. For every labelled vertex $v$ of $\b'_i$, we construct the rooted derived graph $\g_{(v)}$ by rooting $\g_{\b_i}'$ at $v$ (and keeping the unlabelled vertex).
    \item For $v$ a vertex in $\varphi$, in increasing order of label in $\varphi$, let $\t_v := \TT_{\g_{(v)}}$ be the decorated block tree on this rooted subgraph with an unlabelled vertex. Add $\t_v$ as the rightmost child of $r_{\TT}$.
\end{enumerate}

