ref_dict.lem:sasaki-graph-volume:
\begin{lemma}[Sasaki volume of a smooth graph]\label{lem:sasaki-graph-volume}
Let $V\in C^\infty(\Sph^n,T\Sph^n)$ be a smooth unit vector field and let $s_V(x)=(x,V(x))\in E=\UTS^n$.
Then $T\Gamma_V:=(s_V)_\#\llbracket \Sph^n\rrbracket$ is an integral $n$--cycle in $E$, and its mass equals the Sasaki graph volume:
\begin{equation}\label{eq:sasaki-graph-volume}
\mass(T\Gamma_V)
=\int_{\Sph^n} \sqrt{\det\bigl(I+(\nabla V_x)^{\top}(\nabla V_x)\bigr)}\,\dd\vol(x),
\end{equation}
where $\nabla V_x:T_x\Sph^n\to V(x)^\perp\subset T_x\Sph^n$ is the linear map $X\mapsto\nabla_XV(x)$.
(In particular $\nabla V_x$ takes values in $V(x)^\perp$ because $|V|\equiv 1$.)
Equivalently, in an orthonormal basis $(e_1,\dots,e_n)$ of $T_x\Sph^n$ with matrix entries $(\nabla V_x)_{ij}=\langle \nabla_{e_i}V,e_j\rangle$, the pointwise Jacobian density is $\sqrt{\det(I+(\nabla V_x)^{\top}(\nabla V_x))}$.
\end{lemma}

ref_dict.lem:BCNlower:
\begin{lemma}[Calibration lower bound for graphs]\label{lem:BCNlower}
For any smooth unit field $V$ on $\Sph^n$,
\[
\Vol^S(V)\ge \int_{\Sph^n}\omega(T\Gamma_V)\,\dd\vol = h(\omega)=c(m;1)\,\vol(\Sph^n).
\]
\end{lemma}

