\end{maintheorem}

full_context:
Local cohomology, introduced by Grothendieck in the early 1960s, plays a pivotal role in commutative algebra and algebraic geometry. Its vanishing behavior reflects subtle geometric and topological properties of the underlying scheme and has been studied extensively in the work of Grothendieck, Hartshorne, Faltings, and others. Understanding when local cohomology modules vanish remains a fundamental and delicate problem.

Let $A$ be a commutative Noetherian ring of Krull dimension $d$ and $I$ be an ideal of $A$. The \textit{cohomological dimension} of $I$ in $A$ is $$\operatorname{cd}(A,I):=\max\{n\:|\:H^n_I(A)\neq 0\}.$$ Alternatively, $\operatorname{cd}(A,I)$ is the least integer $n$ such that $H^q_I(M)=0$ for all $A$-modules $M$ and $q>n$ \cite[Theorem 9.6]{24h}. As $H^q_I(M)=0$ for all $A$-modules $M$ and $q>d$ \cite{Gr}, $\operatorname{cd}(A,I)$ always exists and is bounded above by $d$.

The computation of better upper bounds on cohomological dimension has been of great interest over the past few decades. It is well-known that $$\operatorname{cd}(A,I)\leq\operatorname{ara}(I),$$ where $\operatorname{ara}(I)$, the $\textit{arithmetic rank}$ of $I$, is the least number of equations required to generate $I$ up to radical. However, the arithmetic rank of an ideal is difficult to compute and can be far from the cohomological dimension \cite{BS,Bar,JPSW,BMMP}.

A complementary approach is to bound the cohomological dimension using topological invariants of the spectrum of $A/I$. The most famous result in this direction is the Hartshorne--Lichtenbaum Vanishing Theorem \cite{Ha1}, which states that for a complete local domain $(A,\mathfrak{m})$, we have $\operatorname{cd}(A,I)\leq d-1$ if and only if $I$ is not $\mathfrak{m}$-primary. Furthermore, the Second Vanishing Theorem \cite{Ogus,PS,HunLyu,Zhang} asserts that in equal characteristic or unramified mixed characteristic, for a complete regular local ring $(A,\mathfrak{m})$ with separably closed residue field, we have $\operatorname{cd}(A,I)\leq d-2$ if and only if $\dim(A/I)\geq 2$ and the punctured spectrum of $A/I$ is connected. Peskine and Szpiro \cite{PS} proved that if $(A,\mathfrak{m)}$ is a regular local ring of equal characteristic $p$ and $A/I$ is Cohen-Macaulay, then $\operatorname{cd}(A,I)=\operatorname{ht}(I).$ Beyond the results discussed here, further vanishing statements have been proved in various settings \cite{MR3078644,DaoTakagi, Burke}, though the conditions required become progressively harder to check. Ogus \cite{Ogus}, Hartshorne and Speiser \cite{HarSpe}, Lyubeznik \cite{Lyu3}, Mustață and Popa \cite{MuPo}, and Reichelt, Saito and Walther \cite{RTW} obtained concrete formulae for cohomological dimension in equal characteristic in terms of singularity invariants, see also \cite{BBLSZ}. However, these methods require the understanding of de Rham cohomologies, Hodge filtrations, or Frobenius structures, and in practice they can be difficult to compute.

In equal characteristic, Faltings \cite{Faltings} established a general bound on cohomological dimension in terms of the \textit{big height} of an ideal. The big height of an ideal is the maximum of the heights of all its minimal primes. In this article, we extend Faltings' result to the unramified mixed characteristic setting.

\begin{theorem}\label{thm:cdbound}
    Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$
\end{theorem}

In equal characteristic, Faltings \cite{Faltings} established a general bound on cohomological dimension in terms of the \textit{big height} of an ideal. The big height of an ideal is the maximum of the heights of all its minimal primes. In this article, we extend Faltings' result to the unramified mixed characteristic setting.

We also establish an inductive criterion for the vanishing of local cohomology modules. See Theorem \ref{thm:induction} for a more general statement than the one stated below.

\begin{theorem}\label{thm:cdbound}
 Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$
\end{theorem}
\begin{proof} We may assume that $A$ is complete and $I$ is radical as local cohomology and big height remain unchanged. If $c=1$, $I$ is principal and $\cd(A,I)\leq 1$. Thus we assume $c>1.$ We also assume $c<d$ as the claimed bound is immediate if $c=d.$

\begin{corollary}[cf. {\cite[Lemma]{Lyu2}}, {\cite[Lemma 3.10]{HNBPW}}]\label{cor:Lyu}
 Let $A$ be a $d$-dimensional regular local ring of equal characteristic or unramified mixed characteristic. Let $I_1,\dots,I_N$ be ideals of $A$ of big height at most $c\geq 1$. Then $$\cd(A,I_1+\dots+I_N)\leq d-\floor*{\frac{d-1}{c}}+N-1.$$
\end{corollary}
\begin{proof}
 We proceed by induction on $N$. The case $N=1$ follows from \cite[Satz 1]{Faltings} in equal characteristic and Theorem \ref{thm:cdbound} in unramified mixed characteristic. For $N>1,$ let $I'=I_1+\dots+I_{N-1}$, $I=I'+I_N$ and $J=I_1\cap I_t+\dots+I_{N-1}\cap I_N$. Note that each $I_j\cap I_t$ has big height at most $c$ by Remark \ref{rmk:bight}. As $\sqrt{J}=\sqrt{I'\cap I_N}$, the Mayer-Vietoris sequence for local cohomology yields $$\cdots\to H_J^{i-1}(A)\to H_I^{i}(A)\to H_{I'}^{i}(A)\oplus H_{I_N}^{i}(A)\to \cdots$$ 
 For $i>d-\floor*{\frac{d-1}{c}}+N-1$, $H_J^{i-1}(A)=H_{I'}^{i}(A)=H_{I_N}^{i}(A)=0$ by the induction hypothesis. Hence, $H_I^i(A)=0$ for $i>d-\floor*{\frac{d-1}{c}}+N-1$.
\end{proof}

\begin{theorem}[cf. {\cite[Theorem 5.2]{HunLyu}}]\label{thm:example}
 Let $(A,\mathfrak{m})$ be a $d$-dimensional regular local ring of equal characteristic or unramified mixed characteristic. Let $c<d$ be a positive integer and set $N=\floor*{\frac{d-1}{c}}$. Let $I_1,\dots,I_N$ be ideals of $A$ of big height at most $c$ such that $\Spec(A/(I_1+\dots+I_N))-\{\mathfrak{m}\}$ is disconnected. Then $\cd(A,I_1\cap\dots\cap I_N)=d-N.$ 
\end{theorem}
\begin{proof} 
 If $(B,\mathfrak{n})$ is a faithfully flat $A$-algebra with zero-dimensional fiber, then $\bight(I_jB)=\bight(I)$ (Lemma \ref{lemma:fflat}) and $\Spec(B/(I_1B+\cdots+I_NB)-\{\mathfrak{n}\}$ is disconnected. Hence, we may assume that $A$ has separably closed residue field.

\begin{example}[{\cite[Example 5.4]{HunLyu}}]
 Let $(A,\mathfrak{m})$ be a $d$-dimensional regular local ring of equal characteristic or unramified mixed characteristic. Suppose $P_1,\dots,P_5$ are prime ideals of $A$ of height $c$ such that $\floor*{\frac{d-1}{c}}=2.$ Further, suppose that $P_i+P_j+P_k$ is $\mathfrak{m}$-primary iff $$\{i,j,k\}\in\Lambda=\{(1,3,4),(1,3,5),(1,2,5),(2,3,4),(2,4,5)\}.$$ Let $I=P_1\cap\cdots\cap P_5.$
 For instance, we may consider $A=V[[x_2,\dots,x_9]]$, where $V$ is a discrete valuation ring with uniformizer $p$ and separably closed residue field, and $$P_1=(p,x_2,x_3,x_4), \;P_2=(x_3,x_4,x_5,x_6),\; P_3=(x_5,x_6,x_7,x_8),$$ $$P_4=(p,x_2,x_8,x_9) \text{ and } P_5=(x_6,x_7,x_8,x_9).$$
 Note that $\Lambda$ has the property that each $i$, $1\leq i\leq5$ appears no more than thrice and each pair $(i,j)$ appears no more than twice. This implies that we cannot split $\{1,\dots,5\}$ into three distinct subsets $S_0$, $S_1$ and $S_2$ such that $P_i+P_j+P_k$ is $\mathfrak{m}$-primary for all $i\in S_0$, $j\in S_1$, $k\in S_2$. Hence, we are unable to apply the result of Example \ref{example:sharpness}.

\begin{theorem}[{\cite[Theorem 3.8]{HunLyu}}]\label{thm:HunLyu_irred}
 Let $A$ be a $d$-dimensional regular local ring of equal characteristic and $I$ be a formally geometrically irreducible ideal of $A$ of big height $c$. Suppose $0<c<d.$ Then $$\cd(A,I)\leq d-1-\floor*{\frac{d-2}{c}}.$$
\end{theorem}

\begin{question}\label{question:irredbound}
 Let $A$ be a $d$-dimensional regular local ring of unramified mixed characteristic and $I$ be a formally geometrically irreducible ideal of $A$ of big height $c$. Suppose $0<c<d$. Is $$\cd(A,I)\leq d-1-\floor*{\frac{d-2}{c}}?$$
\end{question}

\begin{example}\label{example:sharpness}
    Given an unramified regular local ring $(A,\mathfrak{m})$ of dimension $d>0$ and a positive integer $c\leq d$, there exists an ideal $I$ of $A$ such that $\cd(A,I)=d-\floor*{\frac{d-1}{c}}.$ We construct this ideal as in \cite{Lyu2}. 

    Let $N=\floor*{\frac{d-1}{c}}.$ Let $I_0,\dots,I_N$ be ideals of pure height $c$ in $A$ such that $I_0+\dots+I_N$ is $\mathfrak{m}$-primary and let $I=I_0\cap\dots\cap I_N$. Then $\cd(A,I)=d-N.$ The proof of this statement is identical to \cite{Lyu2}.

    To resolve any conflict with the previous remark, we show that in this example, if $p\in I$, then $\floor*{\frac{d-2}{c-1}}= \floor*{\frac{d-1}{c}}.$ Indeed, if $p\in I,$ we have $p\in I_j$ for all $j\in\{0,\dots,N\}$ and by Theorem \ref{thm:Serre}, $$d=\height(I_0+\dots+I_N)\leq 1+(N+1)(c-1)=Nc+c-N.$$ Let $d-1=Nc+k$, where $0\leq k<c$. Then the above equation yields $N+k+1\leq c$, or $N+k-1\leq c-2$. Observe that $$d-2=N(c-1)+N+k-1,$$ and hence, $\floor*{\frac{d-2}{c-1}}=N=\floor*{\frac{d-1}{c}}$. 
\end{example}

\begin{theorem}\label{thm:cdbound}
    Let $A$ be a $d$-dimensional unramified regular local ring of mixed characteristic $(0,p)$. Let $I$ be a nonzero proper ideal of $A$ with big height $c$. Then $$\cd(A,I)\leq d-\floor*{\frac{d-1}{c}}.$$
\end{theorem}

\begin{theorem}\label{thm:induction}
    Let $(A,\mathfrak{m},k)$ be an unramified regular local ring of mixed characteristic $(0,p)$, and let $I$ be an ideal of $A$. Suppose $\height(I)<\height(I:(I:p))$ (for example, this holds if $p$ is a nonzerodivisor on $A/I)$.\footnote{We use the convention that $\height(A)=\infty.$}

    Set $c=\bight(I)$. Let $n>c$ be an integer. Assume that for all integers $s$, with $1\leq s\leq c-1,$ and for all $q\geq n-s$, $H^q_{IA_P}(A_P)=0$ for all $P\in \Spec(A)$ such that $I\subseteq P$ and $\dim(A/P)\geq s+1.$ Then $H^q_I(A)=0$ for all $q\geq n.$
\end{theorem}

