\subsection{Statements of the results}\label{subsec:state:results}
Let $D$ be a natural number such that $D>9, \; D \equiv 0,1,4 \; [8]$, and $D$ is not a square. Denote by $\Oc_D$ the real quadratic order of discriminant $D$. Recall that $\Omega \Mcal_3(2,2)^\mathrm{odd}$ is the component of odd spin Abelian differentials having two double zeros on Riemann surfaces of genus three (see \cite{KZ03}). The space of Prym eigenforms for real multiplication by $\Oc_D$ in $\Omega \Mcal_3(2,2)^\mathrm{odd}$ is denoted by $\Omega E_D(2,2)^\mathrm{odd}$ (for the definition of Prym eigenforms, we refer to \cite{McM:prym, LN:components}). This locus is a closed sub-orbifold of complex dimension three of $\Omega \Mcal_3(2,2)^\mathrm{odd}$ which is invariant by the ${\rm GL}^+(2,\mathbb{R})$-action. It is shown in \cite{LN:components} that $\Omega E_D(2,2)^\mathrm{odd}$ is connected if $D\equiv 0,4 \, [8]$, and has two components if $D\equiv 1 \, [8]$ ($\Omega E_D(2,2)^\mathrm{odd}$ is empty if $D\equiv 5 \, [8]$).

For $k=1,2,3$, let $c_k(D)$ denote the Siegel-Veech constant associated with saddle connections with multiplicity $k$ that join the two zeros of the Abelian differentials in $\Omega E_D(2,2)^\mathrm{odd}$ (in the case $D\equiv 1 \, [8]$, the Siegel-Veech constants of the two components of $\Omega EçD(2,2)^\mathrm{odd}$ are the same (cf. \cite{Ng:25})). The main aim of this paper is to prove the following

\medskip

To our purpose, we will consider Abelian differentials on disconnected Riemann surfaces. In \cite{Ng:25} (see also \cite{LN:components}), we introduced the notion of Prym eigenforms on triples of tori. The space of triples of tori that are Prym eigenforms for the quadratic order $\Oc_D$ is denoted by $\Omega E_D(0^3)$, and its projectivization $\Omega E_D(0^3)/\C^*$ by $W_D(0^3)$. It can be shown that $W_D(0^3)$ is a (non-connected) finite cover of the modular curve $\Hbb/\SL(2,\Z)$. The following result was proved in \cite{Ng:25}.
\begin{Theorem}\label{th:Siegel:Veech}
 Let $D \equiv 0, 1, 4 \; [8], \, D >9$, be a non-square discriminant. 
 \begin{itemize} 
 \item[$\bullet$] If $4 \, | \, D$, then we have
 \begin{align*}
 c_1(D) & = \frac{15\chi(W_D(4))}{\chi(W_D(2))+b_D \chi(W_{D/4}(2))+9\chi(W_D(0^3))}\\
 c_2(D) &= \frac{9\left(\chi(W_{D}(2)) + b_D\chi(W_{D/4}(2)) \right)}{\chi(W_D(2))+b_D \chi(W_{D/4}(2))+9\chi(W_D(0^3))} \\
 c_3(D) & = \frac{3\chi(W_D(0^3))}{\chi(W_D(2))+b_D \chi(W_{D/4}(2))+9\chi(W_D(0^3))}
 \end{align*}
 with
 $$
 b_D= \left\{
 \begin{array}{ll}
 0 & \text{ if } D/4 \equiv 2,3 \, [4] \\
 4 & \text{ if } D/4 \equiv 0 \, [4] \\
 3 & \text{ if } D/4 \equiv 1 \, [8] \\
 5 & \text{ if } D/4 \equiv 5 \, [8]. \\
 \end{array}
 \right.
 $$
 \item[$\bullet$] If $D\equiv 1 \; [8]$, then
 \begin{align*}
 c_1(D) & = \frac{15\chi(W_{D}(4))}{2\chi(W_D(2))+9\chi(W_D(0^3))}\\
 c_2(D) &= \frac{18\chi(W_{D}(2))}{2\chi(W_{D}(2))+9\chi(W_D(0^3))} \\
 c_3(D) & = \frac{3\chi(W_{D}(0^3))}{2\chi(W_{D}(2))+9\chi(W_D(0^3))}.
 \end{align*}
 \end{itemize} 
\end{Theorem}
 For any $D \in \N$, $D >9$ non-square and $D\equiv 0,1,4 \, [8]$, by a result of M\"oller~\cite{Mo14}, we have that
 $$
 \chi(W_D(4))=\left\{
 \begin{array}{cl}
 {\displaystyle -\frac{5}{2} \cdot\chi(X'_D)} & \hbox{ if $D \equiv 0 \, [4]$} \\
 {\displaystyle -5\cdot\chi(X'_D)} & \hbox{ if $D \equiv 1 \, [8]$}. 
 \end{array}
 \right.
 $$
 It was shown by Bainbridge in \cite{Bai:GT} that we have 
 $$
 \chi(W_D(2))=-\frac{9}{2}\cdot\chi(X_D).
 $$
 In the same paper, Bainbridge also gave an explicit formula computing $\chi(X_D)$ generalizing a classical result of Siegel. In \cite{Mo14}, M\"oller proved an explicit formula relating $\chi(X'_D)$ to $\chi(X_D)$ (cf. Proposition~\ref{prop:eul:char:XD:p}). Combining these results, we will show that 
 $$
 \chi(W_D(2)) +b_D\chi(W_{D/4}(2))= -\frac{9}{2}\chi(X'_D).
 $$ 
To prove Theorem~\ref{th:SV:const}, it remains to show that we have
$$
\chi(W_D(0^3))= \left\{ 
\begin{array}{rl}
 -\chi(X'_D) & \hbox{ if $D\equiv 0 \, [4]$} \\
 -2\chi(X'_D) & \hbox{ if $D \equiv 1 \, [8]$}
\end{array} 
\right.
$$
This is achieved by relating $\chi(W_D(0^3))$ to coefficients of the Fourier expansion of some modular forms.

\section{Consequences of relations of modular forms}\label{sec:conseq:rel:mod:forms}
Recall that for any positive integers $m,n$, 
$$
\sigma_m(n):=\sum_{d \, | \, n } d^m.
$$
By convention $\sigma_m(0)=\frac{1}{2}\cdot\zeta_\Q(-m)$ and $\sigma_m(n)=0$ if $n<0$. Our goal in this section is to show the following
\begin{Theorem}\label{th:rel:sum:sigma:1}
Let $D \in \N$ be a non-square discriminant. 
\begin{itemize}
 \item[(i)] If $D \equiv 0 \, [4]$ then we have 
\begin{equation}\label{eq:rel:sum:sigma:1:D:4}
\sum_{\substack{e^2 \equiv D \, [8]}}\sigma_1(\frac{D-e^2}{8}) = \frac{1}{5}\cdot \sum_{\substack{e \; {\rm even}}}\sigma_1(\frac{D-e^2}{4}) +\frac{4}{5}\cdot \sum_{\substack{e^2 \equiv D/4 \, [4]}}\sigma_1(\frac{D/4-e^2}{4}).
\end{equation}

\begin{Remark}\label{rk:f:4:1:by:Cohen}
 The function $f_{4}$ has been introduced in \cite{C75}.
\end{Remark}
Let
\[
f_{1}(z) =\sum_{n=0}^\infty a_{1}(n)q^n, \quad 
f_{2}(z) =\sum_{n=0}^\infty a_{2}(n)q^n, \quad 
f_{4}(z) =\sum_{n=0}^\infty a_{4}(n)q^n 
\]
be the Fourier expansions of $f_{1}, f_{2}, f_{4}$ respectively. 
The following lemma follows immediately from the definition of $f_{1}, f_{2},f_{4}$. 
\begin{Lemma}\label{lm:coeff:Fourier:f:m:n}
Let $D$ be a positive integer. If $D$ is not a square then we have
\begin{align*}
 a_{1}(D) & =\sigma_1(D)+2\sum_{1\leq e < \sqrt{D}}\sigma_1(D-e^2)= \sum_{e\in\Z}\sigma_1(D-e^2),\\
 a_{2}(D) & = \sum_{e\equiv D \, [2]}\sigma_1(\frac{D-e^2}{2}),\\
 a_{4}(D) & = \sum_{e^2\equiv D \, [4]}\sigma_1(\frac{D-e^2}{4}).
\end{align*}
In particular we have $a_{4}(D)=0$ if $D\equiv 2,3 \, [4]$.

\begin{Proposition}\label{prop:rel:coeff:f:8:n:f:4}
 We have 
 \begin{equation}\label{eq:rel:mod:forms:g:h}
 h = \frac{2}{5}g \in \Mb_{5/2}(\Gamma_0(64)).
 \end{equation}
 As a consequence
 \begin{equation}\label{eq:rel:a:8:n:a:4}
 a_{8}(n)=\frac{2}{5} a_{4}(n)
 \end{equation}
 for all $n >0, n\equiv 1 \, [8]$.
\end{Proposition}
\begin{proof}
It follows from \cite[Th. 4.2.7]{Miyake} that the curve $X_0(64):=\Hbb/\Gamma_0(64)$ has no elliptic points and $12$ cusps. We have 
$$
[\ol{\Gamma}(1):\ol{\Gamma}_0(64)]= [\Gamma(1):\Gamma_0(64)]= 64(1+\frac{1}{2})=96.
$$
Therefore $g(X_0(64))=3$ (cf. \cite[Th. 4.2.11]{Miyake}).
We consider $f:=(h-2/5\cdot g)^4$. By definition, $f$ belongs to $\Mb_{10}(\Gamma_0(64))$. Let $f(z)=\sum_{n\in \N} b(n)q^n$ be the Fourier expansion of $f$. One readily checks that $a_8(n)=2/5\cdot a_4(n)$ for all $n \equiv 1 \; [8]$ and $n\leq 25$. Therefore, $b(n)=0$ for all $n\leq 100$.
Since $f \in \Mb_{10}(\Gamma_0(64))$, if $f\not\equiv 0$ then $f$ cannot vanish to the order $5(2\times 3- 2)+5\times 12 =80$ at $\infty$ (cf. \cite[Cor. 2.3.4]{Miyake}). Thus we can conclude that $f \equiv 0$ and $h=2/5 \cdot g$.
\end{proof}
\subsection{Proof of Theorem~\ref{th:rel:sum:sigma:1}}
\begin{proof}
 Let $D \in \N$ be a non-square discriminant.
 Suppose that $D \equiv 0 \, [4]$. We then have 
 \begin{align*}
 a_1(D/4) & =\sum_{e \in \Z} \sigma_1(D/4-e^2) = \sum_{e\in \Z}\sigma_1(\frac{D-4e^2}{4})=\sum_{e \, {\rm even}}\sigma_1(\frac{D-e^2}{4})= a_4(D)\\
 a_2(D/4) & = \sum_{e \equiv D/4 \, [2]}\sigma_1(\frac{D/4-e^2}{2}) = \sum_{e \equiv D/4 \; [2]}\sigma(\frac{D- 4e^2}{8}) = \sum_{ e^2 \equiv D \, [8]} \sigma_1(\frac{D-e^2}{8})=a_8(D).
 \end{align*}
Thus \eqref{eq:rel:sum:sigma:1:D:4} follows from Proposition~\ref{prop:rel:f:1:2:4}.

\item the holomorphic $1$-form $\omega:=\omega_1+\omega_2$ on $E_1\times E_2$ is an eigenvector of the action of $\Oc_D$ on $\Omega^1(E_1\times E_2)$ (here by a slight abuse of notation, the pullback of $\omega_i$ to $E_1\times E_2$ is denoted again by $\omega_i$).
 \end{itemize}
Let $Q_D$ denote the quotient $\Omega Q_D/\C^*$. We claim that
\begin{equation}\label{eq:eul:char:QD}
 \chi(Q_D)=-5\chi(X_D)
\end{equation}
Call a triple of integers $(e,\ell, m)$ such that 
$$
D = e^2 + 4\ell^2m \quad \ell >0, m >0, \quad \text{and} \quad \gcd(e,\ell)=1
$$
a {\em product of tori prototype} for the discriminant $D$. 
In \cite{McM:spin}, McMullen showed that each connected component of $\Omega Q_D$ corresponds uniquely to a product of tori prototype $(e,\ell,m)$, and is isomorphic to $\GL(2,\R)/\Gamma_0(m)$. It is well known that 
$$
\chi(\Hbb/\Gamma_0(m))=-\frac{1}{6}\cdot m \cdot \prod_{\substack{p \, | \, m \\ p \; {\rm prime}}}\left(1+\frac{1}{p} \right)=:\psi(m),
$$
and we have
$$
\sum_{\substack{n=\ell^2 m \\ \ell, m \in \N}} \psi(m)=-\frac{1}{6}\sigma_1(n).
$$
Let us write $D=f^2D_0$, where $D_0$ is a fundamental discriminant. 
We have
\[
\sum_{r \, | \, f }\chi(Q_{r^2D_0}) = \sum_{\substack{ D=e^2+4\ell^2m \\ \ell, m >0}}\psi(m) =-\frac{1}{6}\sum_{\substack{e \equiv D \, [2] }}\sigma_1(\frac{D-e^2}{4}).
\]
Combining with \eqref{eq:sum:eul:char:XD}, we get
\[
\sum_{r \, | \, f }\chi(Q_{r^2D}) = -5\cdot \sum_{r \, | \, f}\chi(X_{r^2D})
\]
and the claim follows.

