\end{align*}

By the method of establishing the generating functions, Murakami \cite{[M-MA]}
obtained an equivalent version of Theorem \ref{theorem1.01}. Define
$$\widetilde{t}(k_1,k_2,...,k_r):=2^{|k|}t(k_1,k_2,...,k_r)$$
and set
$$K(a,b):=\widetilde{t}(\{2\}^a,3,\{2\}^b),K(n)=\widetilde{t}(\{2\}^n)$$
for any $a,b,n\in \mathbb{N}_{\geq 0}$. Then for all integers $a,b\geq 0$,
Murakami \cite{[M-MA]} provided the following formula
\begin{align}\label{eq1.1}
K(a,b)=\sum_{k=1}^{a+b+1}(-1)^{k-1}d_{a,b}K(a+b-k+1)\zeta(2k+1),
\end{align}
where
$$d_{a,b}:=\binom{2k}{2a+1}+\binom{2k}{2b+1}\Big(1-\frac{1}{2^{2k}}\Big).$$
Moreover, let $T(a,b):=t(\{2\}^a,3,\{2\}^b)$. Then \eqref{eq1.1} is equivalent to
\begin{align}
T(a,b)=2\sum_{k=1}^{r+s+1}(-1)^{k-1}d_{a,b}\frac{1}{2^{2k}}\zeta(2k+1)
t(\{2\}^{a+b-k+1}),
\end{align}

In a different approach, Lupu \cite{[L-MZ]} provided elementary proofs of
Zagier's formula for the special case $b=0$, and also established a Zagier-type
formula for multiple $t$-values when $b=0$. For the general case $b>0$, Lupu
\cite{[L-MZ]} proposed the following two conjectures.

\begin{conjecture}\label{con1}
For nonnegative integers $a$ and $b$, we have
\begin{align}
H(a,b)=\frac{-4\pi^{2a+2b+2}}{(2a+2)!}\sum_{n=0}^{\infty}
\frac{\zeta(2n)}{(2n+2a+2)(2n+2a+3)\cdots(2n+2a+2b+3)2^{2n}}.
\end{align}
\end{conjecture}

\begin{conjecture}\label{con2}
For nonnegative integers $a$ and $b$, we have
\begin{align}
T(a,b)=\frac{-2}{(2a+1)!}\left(\frac{\pi}{2}\right)^{2a+2b+2}
\sum_{n=0}^{\infty}\frac{\zeta(2n)}{(2n+2a+1)(2n+2a+2)\cdots(2n+2a+2b+2)2^{2n}}.
\end{align}
\end{conjecture}
\noindent Notice that Conjectures 1.2 and 1.3 are shown in \cite{[L-MZ]}
to be true when $b=0$. But for the general case $b>0$, these two conjectures
are still kept open so far.

In 2026, Lai, Lupu, and Orr \cite{[LLO-PAMS]} gave elementary and direct proofs
for both $H(a, b)$ and $T(a, b)$. In fact, they \cite{[LLO-PAMS]} first provided
an integral expression for $H(a, b)$, and then showed that this integral expression
is equal to Zagier's result. The same proof method was applied to $T(a, b)$.

In this paper, our main goal is to investigate Conjectures \ref{con1} and \ref{con2}.
We will prove that both conjectures of Lupu are true. Actually, by employing the integral
expressions presented in \cite{[LLO-PAMS]} for $H(a,b)$ and $T(a,b)$ and using
the properties of Beta and Gamma functions, we show the following main results
of this paper.

\begin{theorem}\label{theorem1.1}
For nonnegative integers $a$ and $b$, we have $H(a,b)=L(a,b)$, where
\begin{align*}
L(a,b):=\frac{-4\pi^{2a+2b+2}}{(2a+2)!}\sum_{n=0}^{\infty}
\frac{\zeta(2n)}{(2n+2a+2)(2n+2a+3)\cdots(2n+2a+2b+3)2^{2n}}.
\end{align*}
\end{theorem}

\begin{theorem}\label{theorem1.2}
For nonnegative integers $a$ and $b$, we have $T(a,b)=\hat L(a,b)$, where
\begin{align*}
\hat L(a,b):=\frac{-2}{(2a+1)!}\left(\frac{\pi}{2}\right)^{2a+2b+2}
\sum_{n=0}^{\infty}\frac{\zeta(2n)}{(2n+2a+1)(2n+2a+2)\cdots(2n+2a+2b+2)2^{2n}}.
\end{align*}
\end{theorem}

This paper is organized as follows. In Section 2, we supply several preliminary lemmas
that are needed in the proofs of our main results. Sections 3 and 4 are devoted to
the proofs of Theorems \ref{theorem1.1} and \ref{theorem1.2}, respectively.

