[\ref{Purehomogenous},~\ref{prp:MainNonSimp}]\label{prp:MainThm1}
    Let $X$ be a compact metric space, and let $A$ be a pure \ca{}. Assume additionally that
    \begin{enumerate}
        \item $A$ is simple; or 
        \item every quotient of $A$ is stably finite.
    \end{enumerate}

    Then, $C(X,A)$ is pure.

ref_dict.pgr:GGP:
\begin{pgr}[The Global Glimm Property]\label{pgr:GGP}
    A \ca{} $A$ is said to satisfy the \emph{Global Glimm Property} if for every $a\in A_+$ and $\varepsilon>0$ there exists a square-zero element $r\in\overline{aAa}$ such that $(a-\varepsilon)_+\in \overline{ArA}$. This property was originally introduced by Kirchberg and R\o{}rdam in their study of non-simple purely infinite \ca{s} \cite[Definition~4.12]{KirRor02InfNonSimpleCalgAbsOInfty}, but has recently found various and deep applications in the context of dimension reduction phenomena; see, for example, \cite{ThiVil23Glimm,Vil25:IntroGGP}.

    As shown in \cite[Theorem~3.6]{ThiVil23Glimm}, the property can be characterized in terms of a divisibility condition on the Cuntz semigroup: $A$ has the Global Glimm Property if and only if $\Cu (A)$ is $(2,\omega )$-divisible, that is, for  every pair $x',x\in\Cu (A)$ such that $x'\ll x$, there exists $y\in\Cu (A)$ and $n\in\N$ such that $2y\leq x$ and $x'\leq ny$.
\end{pgr}

ref_dict.prp:CXAPureIfGGP:
\begin{theorem}\label{prp:CXAPureIfGGP}
    Let $X$ be a finite-dimensional compact metric space and let $A$ be a pure \ca{}. Then, $C(X,A)$ is pure if and only if $C(X,A)$ has the Global Glimm Property.
\end{theorem}

ref_dict.DpureRSHA:
\begin{prop}\label{DpureRSHA}
Let $D$ be a unital simple pure \ca. Let $R_D$ be a recursive subhomogeneous algebra over $D$ and let $R$ be any recursive homogeneous algebra over $\mathbb{C}$.
Then both $R_D$ and $R \otimes D$ are pure.
\end{prop}

ref_dict.RSHA:
\begin{defn}[{\cite[Definition~3.2]{archey2020structure}}]\label{RSHA}
For a simple unital \ca{} $D$, the class $\mathcal{R}$ of 
{\emph{recursive subhomogeneous algebras over $D$}} is
the smallest class of \ca{s} closed under isomorphism such that:
\begin{enumerate}
\item\label{9223_RSHA_1}
$C (X, M_{n} (D)) \in \mathcal{R}$ whenever $X$ is a compact Hausdorff space and $n \geq 1$.
\item\label{9223_RSHA_2}
Any pullback of the form 
\begin{align*}
& B \oplus_{C (X^{(0)}, \, M_{n} (D)), \, \ph, \, \rh} C (X, M_{n} (D))
\\
& \hspace*{3em} {\mbox{}}
  = \bset{ (b, f) \in B \oplus C (X, M_{n} (D)) \colon
        \ph (b) = f |_{X^{(0)}} }
\end{align*}
is in $\mathcal{R}$ whenever $B \in \mathcal{R}$, $X$ is compact Hausdorff,
$n \geq 1$, $X^{(0)} \subseteq X$ is closed (possibly empty),
$\ph \colon B \to C (X^{(0)}, \, M_{n} (D))$
is any unital $^*$-homomorphism
(the zero \hm{} if $X^{(0)}$ is empty), and
$\rho \colon C (X, M_{n} (D)) \to C (X^{(0)}, \, M_{n} (D))$ is the
restriction $^*$-homomorphism.
\end{enumerate}
\end{defn}

ref_dict.Purehomogenous:
\begin{cor}\label{Purehomogenous}
    Let $A$ be a simple pure \ca{}, and let $X$ be a compact metric space. Then, $C(X,A)$ is pure.
\end{cor}

ref_dict.prp:MainThm2:
\begin{mainthm}[\ref{prp:ASHtenPure}]\label{prp:MainThm2}
    Let $A$ be a pure \ca{} satisfying (1) or (2) in Theorem \ref{prp:MainThm1}, and let $B$ be a unital separable ASH-algebra. Then, $A\otimes B$ is pure.
\end{mainthm}

ref_dict.prp:MainCor1:
\begin{maincor}\label{prp:MainCor1}
 Let $G$ be a countable acylindrically hyperbolic group, and let $H$ be a virtually abelian group. Then, $C_r^*(G\times H)$ is pure. In particular, it has strict comparison.
\end{maincor}

ref_dict.prp:MainNonSimp:
\begin{theorem}\label{prp:MainNonSimp}
    Let $X$ be a compact metric space, and let $A$ be a pure \ca{}. Assume that $A$ has no quotient whose Cuntz semigroup contains a nonzero, compact, properly infinite Cuntz class. Then, $C(X,A)$ is pure.
\end{theorem}

ref_dict.robert_analogy_2:
\begin{cor}\label{robert_analogy_2}
    Let $X$ be a finite-dimensional compact metric space, and let $A$ be an almost divisible \ca{}. Then, there exists $M\in\N$ such that, for every $N\geq 1$ and every pair $x'\ll x$ in $\Cu (C(X,A))$, there exists $y\in\Cu (C(X,A))$ such that
    \[
        x'\ll Ny\ll Mx.
    \]
\end{cor}

ref_dict.qst:VillZstab:
\begin{qst}\label{qst:VillZstab}
    Let $B$ be a Villadsen algebra of the first kind without strict comparison (for example, Toms' \cite{Tom08ClassificationNuclear}). Is $B\otimes C_r^*(\mathbb{F}_2)$ $\mathcal{Z}$-stable?
\end{qst}

ref_dict.prp:ASHtenPure:
\begin{theorem}\label{prp:ASHtenPure}
   Let $B$ be a unital separable ASH-algebra and $A$ be simple and pure. Then, $B\otimes A$ is pure.
\end{theorem}

ref_dict.comp_c(x,A):
\begin{prop}\label{comp_c(x,A)}
    Let $X$ be a compact metric space of covering dimension $m$, and let $A$ be a \ca{} with strict comparison. Then $C(X, A)$ has $m$-comparison.
\end{prop}

