\section{Application to the uniqueness results} \label{sec4}
The local regularity result established in the main theorem enables us to convert solutions of the stationary Fokker–Planck equations into weak solutions of a divergence form equation. Based on this, our main theorem can be applied to derive a uniqueness result for solutions to the stationary Fokker–Planck equations.
\begin{theo} \label{applicationth}
Let $A = (a_{ij})_{1 \leq i,j \leq d}$ be a symmetric matrix of functions whose components satisfy $a_{ij} \in VMO_{loc}(\mathbb{R}^d)$ for all $1 \leq i,j \leq d$. Assume that the condition \eqref{ellipticit} holds for some strictly positive constants $\lambda$ and $M$. Let $C = (c_{ij})_{1 \leq i,j \leq d}$ be an anti-symmetric matrix of functions satisfying $c_{ij} = -c_{ji} \in L^{\infty}(\mathbb{R}^d)$ for all $1 \leq i,j \leq d$. Assume that ${\rm div}(A+C) \in L^2_{loc}(\mathbb{R}^d, \mathbb{R}^d)$. Let $\rho \in H^{1,2}_{loc}(\mathbb{R}^d) \cap L^{\infty}(\mathbb{R}^d)$ be such that for some constant $\theta>0$, $\rho(x) > \theta$ for a.e. $x \in \mathbb{R}^d$. Then, the following statements hold:
\begin{itemize}
\item[(i)]
\begin{align*}
 \int_{\mathbb{R}^d} \bigg( {\rm trace}(A \nabla^2 f) + \left\langle {\rm div}(A+C) + \frac{1}{\rho}(A+C^T) \nabla \rho, \nabla f \right\rangle \bigg)\, \rho\, dx=0 \quad \text{ for all $f \in C_0^{\infty}(\mathbb{R}^d)$.}
\end{align*}
\item[(ii)]
If $h \in L^{\infty}_{loc}(\mathbb{R}^d)$ with $h \geq 0$ in $\mathbb{R}^d$ satisfies
\[
\int_{\mathbb{R}^d} \bigg( {\rm trace}(A \nabla^2 f) + \left\langle {\rm div}(A+C) + \frac{1}{\rho}(A+C^T) \nabla \rho, \nabla f \right\rangle \bigg)\, h\, dx = 0 \quad \text{for all } f \in C_0^{\infty}(\mathbb{R}^d),
\]
then there exists a constant $c \geq 0$ such that $h = c \rho$ in $\mathbb{R}^d$.
\item[(iii)]
If $h \in L^{\infty}(\mathbb{R}^d)$ satisfies
\[
\int_{\mathbb{R}^d} \bigg( {\rm trace}(A \nabla^2 f) + \left\langle {\rm div}(A+C) + \frac{1}{\rho}(A+C^T) \nabla \rho, \nabla f \right\rangle \bigg)\, h\, dx = 0 \quad \text{for all } f \in C_0^{\infty}(\mathbb{R}^d),
\]
then there exists a constant $c \in \mathbb{R}$ such that $h = c \rho$ in $\mathbb{R}^d$.
\end{itemize}
\end{theo}
\begin{proof}
(i) Let $f \in C_0^{\infty}(\mathbb{R}^d)$.
Then, by \cite[Proposition 5.7]{L25bv}, 
\begin{equation} \label{divtracrep}
 \frac{1}{\rho} {\rm div} \Big( \rho(A+C) \nabla f \Big) = {\rm trace}(A \nabla^2 f) + \left\langle {\rm div}(A+C) + \frac{1}{\rho}(A+C^T) \nabla \rho, \nabla f \right\rangle.
\end{equation}
Take an open ball $V$ so that ${\rm supp}(f) \subset V$. Let $\chi \in C_0^{\infty}(\mathbb{R}^d)$ with $\chi \equiv 1$ on $\overline{V}$. Then,
\begin{align*}
&\int_{\mathbb{R}^d} \bigg( {\rm trace}(A \nabla^2 f) + \left\langle {\rm div}(A+C) + \frac{1}{\rho}(A+C^T) \nabla \rho, \nabla f \right\rangle \bigg)\, \rho\, dx \\
&=\int_{\mathbb{R}^d} {\rm div} \Big( \rho(A+C) \nabla f \Big)\,dx = \int_{\mathbb{R}^d} {\rm div} \Big( \rho(A+C) \nabla f \Big) \chi \,dx \\
& = -\int_{V} \langle \rho(A+C) \nabla f, \nabla \chi \rangle\,dx=0.
\end{align*}
(ii) First, by Theorem \ref{maintheore}, $h \in H^{1,2}_{loc}(\mathbb{R}^d)$.
Let $\hat{h}:=\frac{h}{\rho}$. Then, $\hat{h} \in H^{1,2}_{loc}(\mathbb{R}^d)$ with $\hat{h} \geq 0$ in $\mathbb{R}^d$ and it follows from \eqref{divtracrep} that
\begin{align*}
0=&\int_{\mathbb{R}^d} \bigg( {\rm trace}(A \nabla^2 f) + \left\langle {\rm div}(A+C) + \frac{1}{\rho}(A+C^T) \nabla \rho, \nabla f \right\rangle \bigg)\, h\, dx \\
& = \int_{\mathbb{R}^d} {\rm div} \Big( \rho(A+C) \nabla f \Big) \cdot \hat{h}\,dx = -\int_{\mathbb{R}^d} \langle \rho (A+C^T) \nabla \hat{h}, \nabla f \rangle \,dx \quad \text{ for all $f \in C_0^{\infty}(\mathbb{R}^d)$}.
\end{align*}
By the Liouville-type theorem \cite[Theorem 9.11(i)]{F07}, $\hat{h}$ is constant, so that the assertion follows. \\ \\
(iii) As in (ii), $h \in H^{1,2}_{loc}(\mathbb{R}^d)$. Moreover, $\hat{h}:=\frac{h}{\rho} \in H^{1,2}_{loc}(\mathbb{R}^d) \cap L^{\infty}(\mathbb{R}^d)$ satisfies
$$
 \int_{\mathbb{R}^d} \langle \rho (A+C^T) \nabla \hat{h}, \nabla f \rangle \,dx=0 \quad \text{ for all $f \in C_0^{\infty}(\mathbb{R}^d)$}.
$$
Using the Liouville-type theorem \cite[Theorem 9.11(ii)]{F07}, $\hat{h}$ is constant, so that the assertion follows.
\end{proof}
\centerline{}
\noindent
To present a concrete example, we consider the following function:
Let $\varepsilon \in (0, 10^{-2026})$ be fixed. Define
\begin{equation} \label{defnpsi}
\Psi(t) := 
\begin{cases}
1, & t \in (-\infty, -1), \\[6pt]
1 + \displaystyle\int_{-1}^{t} |s|^{-\frac{1}{2+\varepsilon}}\,ds, & t \in [-1,1], \\[6pt]
1 + \displaystyle\int_{-1}^{1} |s|^{-\frac{1}{2+\varepsilon}}\,ds, & t \in (1, \infty).
\end{cases}
\end{equation}
Then $\Psi \in C(\mathbb{R}) \cap L^{\infty}(\mathbb{R})$, and its derivative $\Psi' \in \bigcap_{p \in (1,\; 2+\varepsilon)} L^p(\mathbb{R})$ is given by
\[
\Psi'(t) := 
\begin{cases}
0, & t \in (-\infty, -1), \\[6pt]
|t|^{-\frac{1}{2+\varepsilon}}, & t \in (-1,0) \cup (0,1), \\[6pt]
0, & t \in (1, \infty).
\end{cases}
\]
In particular, $\Psi' \notin L_{loc}^{2+\varepsilon}(\mathbb{R})$, and
\[
1 \leq \Psi(t) \leq 1 + \int_{-1}^{1} |s|^{-\frac{1}{2+\varepsilon}}\,ds \quad \text{for all } t \in \mathbb{R}.
\]

\begin{exam} \label{ourexam1}
Let $d \geq 2$ and $\varepsilon \in (0,10^{-2026})$ be fixed. Let $\Psi$ be the function defined in \eqref{defnpsi}. Define
$$
\rho(x_1, \ldots, x_d) = \prod_{i=1}^d \Psi(x_i), \quad x =(x_1, \ldots, x_d) \in \mathbb{R}^d.
$$
Then $\rho \in C(\mathbb{R}^d) \cap L^{\infty}(\mathbb{R}^d) \cap H^{1,2}_{loc}(\mathbb{R}^d)$, and $\nabla \rho \notin L^{2+\varepsilon}_{loc}(\mathbb{R}^d)$. Moreover,
$$
1 \leq \rho(x) \leq \left( 1 + \int_{-1}^{1} |s|^{-\frac{1}{2+\varepsilon}}\,ds \right)^d \quad \text{for all } x \in \mathbb{R}^d.
$$
Let $A = I$, $\mathbf{G} = \frac{1}{\rho} \nabla \rho$. Then
\begin{equation} \label{infinitesinvar}
\int_{\mathbb{R}^d} \left( {\rm trace}(A \nabla^2 f) + \langle \mathbf{G}, \nabla f \rangle \right) \rho\,dx = 0 \quad \text{for all } f \in C_0^{\infty}(\mathbb{R}^d).
\end{equation}
Assume that $h \in L^{\infty}_{loc}(\mathbb{R}^d)$ with $h \geq 0$ in $\mathbb{R}^d$ satisfies
\begin{equation} \label{infininvah}
\int_{\mathbb{R}^d} \left({\rm trace}(A \nabla^2 f) + \langle \mathbf{G}, \nabla f \rangle \right) h \,dx = 0 \quad \text{for all } f \in C_0^{\infty}(\mathbb{R}^d).
\end{equation}
Then it follows from Theorem \ref{applicationth}(ii) that $h$ is a constant multiple of $\rho$. If $h \in L^{\infty}(\mathbb{R}^d)$ satisfies \eqref{infininvah}, then it follows from Theorem \ref{applicationth}(iii) that $h$ is also a constant multiple of $\rho$.
\end{exam}

