\section{The energy conservation for the compressible Navier-Stokes equations with degenerate viscosity}\label{sec:deg}
Next, we consider the compressible Navier-Stokes equations with degenerate viscosity, where the density is strictly bounded away from vacuum. The systems are stated as follows:
 \begin{equation}\label{eq:comNSdeg}
 \begin{split}
 (\rho u)_t + \text{div}(\rho u \otimes u) - 2\nu \text{div}(\rho \mathbb{D} u) + \nabla P &= 0, \\
 \rho_t + \text{div}(\rho u) &= 0,
 \end{split}
 \end{equation}
 where $\mathbb{D} u = \frac{1}{2}(\nabla u + \nabla^T u)$ is the strain tensor and the viscosity coefficients satisfy $\nu > 0$. Then, we present the definition and the energy conservation criteria of the corresponding weak solutions.
 \begin{definition}\label{defcomNSdeg}
 The pair $(\rho, u)$ is called a global weak solution to the degenerate viscosity system \eqref{eq:comNSdeg} with initial data \eqref{con:initial} if, for any $t \in[0, T]$:
 \begin{itemize}
 \item The momentum equations \eqref{eq:comNSdeg} hold in $\mathcal{D}^{\prime}((0, T) \times \Omega)$ satisfying:
 $$
 \begin{gathered}
 \rho \geq 0, \quad \rho \in L^{\infty}\left(0, T ; L^\gamma(\Omega)\right),\quad \nabla \sqrt{\rho} \in L^{\infty}\left(0, T ; L^\frac{3}{2}(\Omega)\right)\\
 \sqrt{\rho} u \in L^{\infty}\left(0, T ; L^2(\Omega)\right), \quad \sqrt{\rho} \nabla u \in L^2\left(0, T ; L^2(\Omega)\right);
 \end{gathered}
 $$

\item The energy inequality holds for almost every $t \in [0,T]$:
 \begin{equation}\label{eq:energy_comNSdeg}
 \int_{\Omega}\left(\frac{1}{2} \rho|u|^2+\frac{\rho^\gamma}{\gamma-1}\right) \mathrm{d} x+\int_0^t \int_{\Omega} \rho|\mathbb{D} u|^2 \mathrm{d} x \mathrm{d} s \leq \int_{\Omega}\left(\frac{1}{2} \rho_0\left|u_0\right|^2+\frac{\rho_0^\gamma}{\gamma-1}\right) \mathrm{d} x.
 \end{equation}
 \end{itemize}
\end{definition}
\begin{remark}
 The condition $\nabla\sqrt{\rho}\in L^{\infty}L^{\frac{3}{2}}$ is reasonable in this context, as it is consistent with the known existence theory for weak solutions. Specifically, for the degenerate compressible Navier–Stokes equations, global existence results \cite{vasseur2016existence} ensure that $\nabla \rho^{\frac{\gamma}{2}}\in L^{2}L^{2}$ and $\nabla\sqrt{\rho}\in L^{\infty}L^{2}$.
\end{remark}

