            \rho^\gamma, \rho|u|^2 \in L^{\infty}\left(0, T ; L^1(\Omega)\right), \quad u \in L^2\left(0, T ; H_0^1(\Omega)\right);
        \end{equation}

        \item The initial conditions \eqref{con:initial} hold in $\mathcal{D}^{\prime}(\Omega)$;

        \item $(\rho, u)$ is a renormalized solution of the continuity equation in the sense of DiPerna--Lions, ``Ordinary differential equations, transport theory and Sobolev spaces'' (1989);

        \item The energy inequality holds for almost every $t \in [0,T]$:
        $$
        \begin{aligned}
            \int_{\Omega}\left(\frac{1}{2} \rho|u|^2+\frac{\rho^\gamma}{\gamma-1}\right) \mathrm{d} x & +\int_0^t \int_{\Omega}\left(\mu|\nabla u|^2+(\mu+\lambda)(\operatorname{div} u)^2\right) \mathrm{d} x \mathrm{d} s \\
            & \leq \int_{\Omega}\left(\frac{1}{2} \rho_0\left|u_0\right|^2+\frac{\rho_0^\gamma}{\gamma-1}\right) \mathrm{d} x.
        \end{aligned}
        $$
    \end{itemize}
\end{definition}
    Assume that the density satisfies
    \begin{equation}\label{con:thcomNSrhoover0}
         0 \leq \rho(t,x) \leq \bar{\rho} < \infty, \quad \text{and} \quad \nabla \sqrt{\rho} \in L^{\infty}\left(0, T ; L^{\frac{3}{2}}(\Omega)\right),
    \end{equation}
    and the initial velocity satisfies
    \begin{equation}\label{con:initial_1}
        u_0 \in L^{\frac{6N}{6-N}}(\Omega).
    \end{equation}
    If the velocity satisfies
    \begin{equation}\label{con:shinbrot_cond}
        u \in L^p\left(0, T ; L^q(\Omega)\right) \quad \text{with} \quad \begin{cases}
            \frac{1}{p}+\frac{3}{q} \leq 1, \quad\mbox{if} \quad 3\leq q < 4,\\
            \frac{2}{p}+\frac{2}{q} \leq 1, \quad\mbox{if} \quad 4\leq q <\infty,
        \end{cases}
    \end{equation}
    then the energy equality
    \begin{aligned}
    	&\int_{\Omega}\left(\frac{1}{2} \rho_0\left|u_0\right|^2+\frac{\rho_0^\gamma}{\gamma-1}\right) \mathrm{d} x-\int_{\Omega}\left(\frac{1}{2} \rho|u|^2+\frac{\rho^\gamma}{\gamma-1}\right) \mathrm{d} x\\
    	=&\int_0^T \int_{\Omega}\left( \mu|\nabla u|^2+(\mu+\lambda)|\operatorname{div} u|^2 \right)\mathrm{d} x \mathrm{d} t. \label{eq:energy_comNS}
    \end{aligned} holds for any $t \in[0, T]$.

