 \item[(C2)] There exist $c_H>0$ and $\gamma>0$ such that 
 \[
 |H_\varepsilon(x, t, \xi)-H_0(x, t, \xi)|\leq c_H \varepsilon^\gamma 
 \] 
 holds for all $\varepsilon>0$ small and $(x, t)\in \Om_T, \xi\in {\mathbb R}^n$.
 \end{enumerate}
 Note that by the condition $\beta>\frac{2-k}{2(k-1)}$ in (C1), we have $\beta>-1/2$ for $k>2$. It is worth remarking that one can generalize (C1) by assuming the existence of $\Sigma_\varepsilon: {\mathbb R}^n_0\to {\mathbb R}^{m\times n}$ with $m\in {\mathbb N}$ for all $\varepsilon\geq 0$ small such that $\Sigma_\varepsilon^T\Sigma_\varepsilon=A_\varepsilon$ in ${\mathbb R}^n_0$ and \eqref{eq:c1} holds for $\Sigma_\varepsilon$ in place of $A_\varepsilon^{1/2}$. For clarity and simplicity, we restrict our attention to the case $\Sigma_\varepsilon=A_\varepsilon^{1/2}$, which already covers the applications of interest.

Let us present our main theorem.

\begin{equation}\label{eq:c1}
			\|A_\vep(\xi)^{1/2} -A_0(\xi)^{1/2}\|\leq c_A\vep^{\alpha} (1+|\xi|^\beta)
		\end{equation}

\begin{equation}\label{general parabolic approx eq}
		\partial_t u-\tr(A_\vep(\nabla u)\nabla^2 u)+H_\vep(x, t, \nabla u)=0 \quad \text{in $\Om_T$}
	\end{equation}

\begin{equation}\label{parabolic approx bdry-cond}
		u =g_\vep \quad \text{on $\partial_p \Om_T$}
	\end{equation}

Let us present our main theorem.

Our proof of Theorem~\ref{thm:parabolic} develops the standard comparison argument for possibly degenerate or singular parabolic equations, incorporating the H\"older regularity of solutions into the estimates. Without effecting these estimates, this result can be readily adapted to the spatially periodic setting by simply taking $\Omega$ to be a torus; see Remark~\ref{rmk:periodic} for more details. Moreover, the assumption of H\"older continuity in time in \eqref{equi-holder} can be removed when vanishing gradients induce only a mild singularity of the equation. Such an improvement follows from the use of the parabolic Crandall–Ishii lemma, which avoids doubling the time variables and thereby simplifies the proof.

Our quantitative stability result for the elliptic equation is as below. For the sake of completeness, we also include a proof, which to a large extent resembles that of Theorem~\ref{thm:parabolic}. 
 \newpage
 \begin{thm}[Quantitative stability for elliptic equations]\label{thm:elliptic}
 Let $\Omega$ be a bounded domain in $\R^n$. For $\vep\geq 0$, assume that $A_\vep: \R^n_0\to \S_+^n$ and $H_\vep: \Omega\times \R\times \R^n\to \R$ are continuous functions satisfying (A1)(A2')(A3) and (C1)(C2'). Let $g_\vep\in C(\partial\Omega)$ and $u_\vep\in C(\Oba)$ be $\F$-solutions of \eqref{general approx eq}\eqref{approx bdry-cond}. Assume in addition that $u_\vep$ are equi-H\"older continuous in $\Oba$, that is, there exist $L>0$ and $0<\theta\leq 1$ such that \[
 |u_\vep(x_1)-u_\vep(x_2)|\leq L|x_1-x_2|^\theta 
 \]
 for all $x_1, x_2\in \Oba$ and $\vep\geq 0$.
 Then, for all $\vep>0$ small, 
 \begin{equation}\label{error-est}
 \max_{\Oba} |u_\vep-u_0|\leq \max_{\partial \Omega} |g_\vep-g|+\frac{1}{\lambda}\left(C_0\vep^{\nu}+c_H \vep^\gamma \right)
 \end{equation}
 holds with $\nu$ given as in \eqref{nu-exponent}, where $C_0>0$ is a constant depending on 
 $k>2$,$L_A>0$, $L_H>0$, $\lambda>0$ in (A1)(A2')(A3) and $\alpha, \beta, c_A, \in \R$ given in (C1). The constants $\gamma, c_H>0$ are given as in (C2'). 
 \end{thm}

\begin{thm}\label{thm:p-lap1par}
 Let $\Omega\subset \R^n$ be a bounded domain and $T>0$. Assume that $H: \Omega\times (0,T)\times \R^n\to \R$ satisfies (A2). Fix $q\in [1, \infty)$ and take $p\in [1, \infty)$ close to $q$. For any such $p$, let $u_p\in C(\Om_T)$ be a solution to \eqref{np-parabolic} satisfying \eqref{parabolic bdry-cond} with with boundary data $g=g_p\in C(\partial_p \Om_T)$. Assume in addition that there exist $L>0$ and $\theta\in (0, 1]$ such that
 \[
 |u_p(x_1, t)-u_p(x_2, t)|\leq L|x_1-x_2|^\theta 
 \]
 for all $x_1, x_2\in \overline{\Omega}$, $0\leq t<T$ and all $p$ near $q$. Then, there exists $C>0$ independent of $p$, such that
 \begin{equation}\label{rate:p-lap1par}
 \sup_{\overline{\Omega}\times[0,T)}|u_p-u_q|\leq \sup_{\partial_p \Om_T}|g_p-g_q| +C|p-q|^{\theta}. 
 \end{equation}
\end{thm}
\begin{proof}
 Note that for the normalized $p$-Laplacian, (A1) holds with $k>0$ large for all $q$ near $p$. 
 Moreover, by a straightforward computation, we have
 \[
 A_\eps(\xi)^{1/2}=I+(\sqrt{p-1}-1) \frac{\xi\otimes \xi}{|\xi|^{2}}, \quad A_0(\xi)^{1/2}=I+(\sqrt{q-1}-1) \frac{\xi\otimes \xi}{|\xi|^{2}}
 \]
 with $p, q\in (1, \infty)$ satisfying $\vep=|p-q|$. 
 This yields the existence of $c>0$ such that
 \[
 \norm{A_\vep(\xi)^{1/2} -A_0(\xi)^{1/2}}\leq |\sqrt{p-1}-\sqrt{q-1}|\leq c|p-q|
 \]
 for all $q$ near $p$. This amounts to saying that (C1) holds with $\alpha=1$ and $\beta=0$. We thus complete the proof of inequality \eqref{rate:p-lap1par} by applying Theorem~\ref{thm:parabolic2} with $c_H=0$ and $\nu=\theta$. 
\end{proof}

\begin{thm}\label{thm:p-lap2par}
 Let $\Omega\subset \R^n$ be a bounded domain and $T>0$. Assume that $H: \Omega\times (0,T)\times \R^n\to \R$ satisfies (A2). Fix $q\in (1, \infty)$ and take $p\in (1, \infty)$ close to $q$. For any such $p$, let $u_p\in C(\Om_T)$ be a solution to \eqref{vp-parabolic} satisfying \eqref{parabolic bdry-cond} with $g=g_p\in C(\partial_p \Om_T)$. If for all $p$ close to $q$, $u_p$ are equi-H\"older continuous in $\overline{\Om_T}$ with exponent $\theta\in (0, 1]$, then the following results hold:
 \begin{enumerate}
 \item If $p<2$ and $1<q\leq 2$, then for any $-1/2<\beta<p/2-1$, there exists $C>0$ independent of $p$ near $q$ such that
 \begin{equation}\label{rate:p-lap2par-new}
 \sup_{\overline{\Omega}\times[0,T)}|u_p-u_q|\leq \sup_{\partial_p\Omega_T}|g_p-g_q| +C|p-q|^{\theta}. 
 \end{equation}
 \item If $p>2$ and $q\geq 2$, then for any $\beta>q/2-1$, there exists $C>0$ independent of $q$ near $p$ such that 
 \begin{equation}\label{rate:p-lap2par}
 \sup_{\overline{\Omega}\times[0,T)}|u_p-u_q|\leq \sup_{\partial_p\Omega_T}|g_p-g_q| +C|p-q|^{\frac{\theta}{1+(1-\theta)\beta}}. 
 \end{equation}
 \end{enumerate}
\end{thm}
As explained in Remark~\ref{rmk holder}, for the case (2), one may relax the regularity of $u_\vep$, assuming that they are equi-H\"older continuous only in $x$.

\begin{thm}\label{thm:pq-lap1par}
 Let $\Omega\subset \R^n$ be a bounded domain and $T>0$. Fix $(q, q')\in (1, \infty)^2$ and take $(p, p')$ close to $(q, q')$. For any such $(p, p')$, let $u_{p,p'}\in C(\Om_T)$ be a solution to \eqref{eq:pq-parabolic} satisfying \eqref{parabolic bdry-cond} with $g=g_{p,p'}\in C(\partial_p \Om_T)$. Assume in addition that for all such $(p, p')$, $u_{p,p'}$ are equi-H\"older continuous in $\overline{\Om_T}$ with exponent $\theta\in (0, 1]$. Let $\beta>-1/2$ be an arbitrary value satisfying \eqref{beta-choice}. Then the following results hold:
 \begin{enumerate}
 \item For $p'> 2$ and $q'\geq 2$, there exists $C>0$ independent of $(p, p')$ such that
 \begin{equation}\label{rate:pq-lap1par}
 \sup_{\ol{\Omega}\times[0,T)}|u_{p,p'}-u_{q,q'}|\leq \sup_{\partial_p\Omega_T}|g_{p,p'}-g_{q,q'}| +C(|p-q|+|p'-q'|)^{\theta}. 
 \end{equation}
 \item For $1<p'< 2$ and $1<q'\leq 2$, there exists $C>0$ independent of $(p, p')$ such that
 \begin{equation}\label{rate:pq-lap1par2}
 \sup_{\ol{\Omega}\times[0,T)}|u_{p,p'}-u_{q,q'}|\leq \sup_{\partial_p\Omega_T}|g_{p,p'}-g_{q,q'}| +C(|p-q|+|p'-q'|)^{\frac{\theta}{1+(1-\theta)\beta}}. 
 \end{equation}
 \item In the special case that $p'= q'\in (1, \infty)$, there exists $C>0$ independent of $q$ such that 
 \begin{equation}\label{rate:pq-lap2par}
 \sup_{\ol{\Omega}\times[0,T)}|u_{p,p'}-u_{q,p'}|\leq \sup_{\partial_p\Omega_T}|g_{p,p'}-g_{q,p'}| +C|p-q|^{\nu}, 
 \end{equation}
 holds with 
 \begin{equation}\label{nu-pq}
 \nu=\frac{2\theta}{2\theta+(1-\theta){q'}}. 
 \end{equation}
 \end{enumerate}
\end{thm}
In view of Remark \ref{rmk holder} and Theorem \ref{thm:parabolic2}, in the case $p'> 2$, $q'\geq 2$, we can drop the equi-H\"older continuity of $u_{p, p'}$ with respect to the time variable and only keep it for the space variable.

As for (C2), we have
\begin{equation*}
 \abs{H_\vep(x, t, \xi)-H_0(x, t, \xi)}=\abs{a\abs{\xi} -a\sqrt{\abs{\xi}^2+\vep_2^2}}\leq \abs{a}\vep_2,
\end{equation*}
so it holds with $\gamma=1$. We can now use Theorem \ref{thm:parabolic} to obtain the following result. 
\begin{thm}
 Let $\Omega\subset \R^n$ be a bounded domain and $T>0$. For $\eps=(\vep_1, \vep_2)$ with $\vep_1, \vep_2\geq0$, let $u_{\eps}\in C(\Om_T)$ be a solution to \eqref{eq:biasedreg} with boundary value $u_\vep=g_{\eps}\in C(\partial_p \Om_T)$. Let $u_0\in C(\Om_T)$ be a solution to \eqref{eq:biased} satisfying $u_0=g_0\in C(\partial_p \Om_T)$. Suppose that $u_{\eps}$ are equi-H\"older continuous in $\overline{\Om_T}$ with exponent $\theta\in (0, 1]$ for all $\vep_1, \vep_2$ small. Then, there exists $C>0$ such that
 \begin{equation*}
 \sup_{\ol{\Om}\times[0,T)}|u_{\eps}-u_0|\leq \sup_{\partial_p\Omega_T}|g_{\eps}-g_0| +C\eps_1^{\alpha\theta}+C\vep_2
 \end{equation*}
 for any $\alpha\in (0, 1/2)$.
\end{thm}

post_theorem_intro_text:
This result applies to important quasilinear parabolic equations with vanishing gradient singularities, for which typically (C1) holds with $\beta<0$. While the parameter $\beta<0$ represents the singularity strength, the term $\max\{\beta, 0\}$ in \eqref{nu-exponent} indicates that our estimate \eqref{error-est parabolic} does not capture any influence of this singularity. Moreover, for equi-Lipschitz solutions, corresponding to the case $\theta=1$, we always have $\nu=\alpha$, and the behavior of $A_\varepsilon(\xi)$ with respect to the gradient variable $\xi$ essentially plays no decisive role in determining the stability estimate.

	Our proof of Theorem~\ref{thm:parabolic} develops the standard comparison argument for possibly degenerate or singular parabolic equations, incorporating the H\"older regularity of solutions into the estimates. Without effecting these estimates, this result can be readily adapted to the spatially periodic setting by simply taking $\Omega$ to be a torus; see Remark~\ref{rmk:periodic} for more details. Moreover, the assumption of H\"older continuity in time in \eqref{equi-holder} can be removed when vanishing gradients induce only a mild singularity of the equation. Such an improvement follows from the use of the parabolic Crandall–Ishii lemma, which avoids doubling the time variables and thereby simplifies the proof.

	We are also interested in the elliptic variant of such stability problems. Consider now
	\begin{equation}\label{general approx eq}
		-\operatorname{tr}(A_\varepsilon(\nabla u)\nabla^2 u)+H_\varepsilon(x, u, \nabla u)=0 \quad \text{in $\Omega$}
	\end{equation}
	with the Dirichlet boundary condition 
	\begin{equation}\label{approx bdry-cond}
		u =g_\varepsilon \quad \text{on $\partial \Omega$}
	\end{equation}
	for given $g_\varepsilon\in C(\partial \Omega)$. 
	While our approach to parabolic problems can be readily extended to the elliptic case under similar assumptions on $A_\varepsilon$ and $H_\varepsilon$, we need to additionally assume a monotonicity condition on $H_\varepsilon$ with respect to $u$ for all $\varepsilon\geq 0$. More precisely, we assume that there exists $\lambda>0$ such that 
	\begin{equation}\label{mono-0}
		\rho\mapsto H_\varepsilon(x, \rho, \xi)-\lambda \rho \quad \text{is nondecreasing in ${\mathbb R}$. }
	\end{equation}
	We obtain the same convergence rate as in Theorem \ref{thm:parabolic}; see Theorem \ref{thm:elliptic}. However, it is not clear to us how to drop or relax the monotonicity assumption \eqref{mono-0}. 

	\subsection{Applications}

	Our general framework in Theorem~\ref{thm:parabolic} yields stability estimates for a broad class of quasilinear parabolic equations including the normalized and variational $p$-Laplace equations and their further generalizations, as well as regularizing approximations for degenerate $p$-Laplace equations ($1\leq p\leq \infty$). Below we summarize our major convergence rate results obtained for these equations. See Section~\ref{sec:app} for precise statements, detailed analysis, concrete examples, and further discussions. 

	\begin{itemize}
		\item (Normalized $p$-Laplacian) Let $u_p$ be a solution of \eqref{np-parabolic0}\eqref{parabolic bdry-cond} for $1\leq p<\infty$. For any fixed $1\leq q<\infty$, if $u_p$ are spatially equi-H\"older continuous with exponent $\theta\in (0, 1]$ for all $p$ near $q$, then $u_p\to u_q$ uniformly as $p\to q$ with convergence rate $O(|p-q|^\theta)$. 
		\item (Variational $p$-Laplacian) Let $u_p$ be a solution of \eqref{vp-parabolic0}\eqref{parabolic bdry-cond} for $1<p<\infty$. For any fixed $1\leq q<\infty$, if $u_p$ are equi-H\"older continuous with exponent $\theta\in (0, 1]$ for all $p$ near $q$, then, depending on $p$, $u_p\to u_q$ uniformly as $p\to q$ with convergence rate 
		\begin{enumerate}
			\item[(i)] $O(|p-q|^\theta)$ when $p<2$ (and hence $q\leq 2$);
			\item[(ii)] $O(|p-q|^\nu)$ with any 
			\[
			0<\nu< \frac{2\theta}{(1-\theta)q+2\theta}
			\] 
			when $p>2$ (and hence $q\geq 2$).
		\end{enumerate}
		\item (Regularization for generalized $p$-Laplacian) Let $p\geq 1$, $p'\geq 2$. For all $\varepsilon>0$ small, let $u_\varepsilon$ be a solution of \eqref{regularized eq}
		and satisfy $u_\varepsilon=g$ on $\partial_p \Omega_T$ for $g\in C(\partial_p\Omega_T)$. As $\varepsilon\to 0$, $u_\varepsilon\to u$ uniformly, where $u$ is the unique solution of
		\begin{equation*}
			\partial_t u-\left|\nabla u\right|^{p'-p}\operatorname{div}\left(\left|\nabla u\right|^{p-2}\nabla u\right)=0
		\end{equation*}
		satisfying the same boundary condition. If $u_\varepsilon$ is spatially equi-H\"older continuous with exponent $\theta\in (0, 1]$ for $\varepsilon>0$ small, then we obtain the rate $O(\varepsilon^\nu)$ for the uniform convergence $u_\varepsilon\to u$, where $\nu>0$ can be chosen as follows: 
		\begin{enumerate}
			\item[(i)] If $p'=2$, then $0<\nu< \theta/2$;
			\item[(ii)] If $2<p'< 3$, then $\nu=(p'-2)\theta$; 
			\item[(iii)] If $3\leq p'\leq 4$, then $0<\nu<\theta$;
			\item[(iv)] If $p'>4$, then 
			\[
			0<\nu< \frac{\theta}{1+(1-\theta)(p'-4)}. 
			\]
		\end{enumerate}
	\end{itemize}
	Note that the Hölder regularity of solutions assumed in the results above is not the focus of this paper. We refer interested readers to \cite{Do11, JS17, AP18, IJS19, Lee2025}, among many others, for related regularity estimates about these parabolic equations. 

	In addition to the applications above, our results can also be applied to study parabolic quantitative stability for general $p$-Laplace type equations that cover both the normalized and variational cases, as well as a regularizing approximation for biased infinity-Laplace equations arising in the stochastic tug-of-war games. Several examples for quasilinear elliptic equations are also discussed in Section~\ref{sec:app}.  

	Our main theorem applies to the vanishing viscosity limit for Hamilton-Jacobi equations as well. For $\varepsilon\geq 0$ small, consider the solution $u_\varepsilon$ to the initial boundary value problem for the Hamilton-Jacobi equation
	\[
	\partial_t u -\varepsilon \Delta u+H(x, t, \nabla u)=0 \quad \text{in $\Omega_T$,}
	\]
	where the Hamiltonian $H$ is assumed to satisfy the same regularity assumption as in (A2). Then, for fixed initial and boundary data independent of $\varepsilon$, Theorem~\ref{thm:parabolic} immediately yields the convergence rate $\|u_\varepsilon-u_0\|_{L^\infty(\Omega_T)}=O(\varepsilon^{1/2})$ for equi-Lipschitz solutions $u_\varepsilon$ and the limit solution $u_0$ of the corresponding inviscid Hamilton-Jacobi equation. This recovers the classical result of \cite{Fl}, originally established using an approach based on differential games, and later obtained in \cite{CL1, CL2} via viscosity solution theory and in \cite{Tr} using the nonlinear adjoint method. As this application is not the main focus of the present paper, we do not pursue it further, but instead refer the reader to the aforementioned references, as well as \cite{QSTY, CD, CG} for more recent progress on improved rates in the convex Hamiltonian case. 

	In this work, we do not seek general optimality of the convergence rates. We only discuss the sharpness of our estimates through some examples, including in particular the stability of spatially periodic solutions to normalized $p$-Laplace equations under perturbations of $p$. The above convergence rates for the regularization of generalized $p$-Laplacian are consistent with the estimate obtained in \cite{Mi} for Lipschitz solutions of regularized level set curvature flow equations, which corresponds to the case $p=1$, $p'=2$ in our general setting. 

	\subsection*{Acknowledgments}

	The authors would like to thank Hiroyoshi Mitake and F\'elix del~Teso for helpful discussions. The work of QL was supported by JSPS Grant-in-Aid for Scientific Research, No.~22K03396.

