\begin{definition}
[Quasiminimal excellent geometries]\label{qmdef}
 Let $\bK$ be a class of $L$-structures such that $M \in \bK$ admits a
 closure relation $\cl_M$  mapping $X \subseteq M$ to $\cl_M(X) \subseteq M$
  that satisfies the following properties. We write $X \leq M$ if $\cl_M(X) = X$.

\smallskip
\begin{enumerate}
\item \textbf{Basic Conditions}
\begin{enumerate}
\item
 Each $\cl_M$ defines a pregeometry on $M$.
\item For each $X\subseteq M$, $\cl_M(X) \in \bK$.

 \item countable closure property (ccp): If $|X| \leq \aleph_0$ then  $|\cl(X)| \leq \aleph_0$.

\end{enumerate}

\item \textbf{Homogeneity}

\begin{enumerate}
\item 
A class $\bK$ of models has {\bf $\aleph_0$-homogeneity over $\emptyset$}  if the  models of $\bK$
are pairwise qf-back and forth equivalent (Definition~\ref{ps})

\item
A class $\bK$ of models has \textbf{$\aleph_0$-homogeneity over models}
if for any $G
 \in \bK$ with $G$ empty or a countable member of
$\bK$, any $H,H'$ with $G\leq H, G\leq H'$,  $H$ is qf-back and forth equivalent with $H'$ over $G$.
\end{enumerate}
\item $\bK$ is an {\em almost quasiminimal } if the universe of any model $H\in \bK$ is in $\cl(X)$ for any maximal $\cl$-independent set $X \subseteq H$.
\item We call a class   which satisfies  conditions 1) through 3)
an {\em almost quasiminimal excellent class (of geometries) } \cite{BHHKK}.
\end{enumerate}
\end{definition}

