\begin{abstract}
Here we show that the Weil abscissa of 
the procyclic groups $\prod_{p \in S} \bbZ_p$ equals $2$ for three sets $S$: (i) the set of primes $p \equiv 1 \bmod 3$, (ii) the set of primes $p \equiv 1 \bmod 4$ and (iii) the set of primes $p \equiv 1,3 \bmod 8$. Our argument is based on the observation that integers all of whose prime factors lie in $S$ can be represented by a suitable binary quadratic form, which allows us to use a theorem of Iwaniec to exhibit a minorant for the Weil representation zeta function.
\end{abstract}

The \emph{Weil abscissa} $\alpha(G)$ of a profinite group $G$ is an intricate invariant that quantifies how the number of absolutely irreducible representations of $G$ over finite fields $\mathbb{F}_{p^j}$ increases with the size of the fields. It is the abscissa of convergence of the Weil representation zeta function defined in \cite{corob2024weil}. 
For a finitely generated profinite \emph{abelian} group $G$, the \textit{Weil representation zeta function} admits the following simple definition
 \begin{align*}
 \zeta_G^W(s)=\exp\bigg(\sum_{p\in\mathcal{P}}\sum_{j=1}^{\infty} |\text{Hom}(G,\mathbb{F}_{p^j}^\times)|\frac{p^{-sj}}{j}\bigg),
 \end{align*}
 for $s \in \mathbb{C}$; here $\mathcal{P}$ denotes the set of all prime numbers and $|\text{Hom}(G,\mathbb{F}_{p^j}^\times)|$ the number of continuous homomorphisms from $G$ to $\mathbb{F}_{p^j}^\times$. However, even for abelian groups the Weil abscissa is difficult to compute, since its exact value depends in a subtle way on the distribution of primes in arithmetic progressions; see \cite{corob2024weil,kionke2024}. The purpose of this short note is to calculate the Weil abscissa of three procyclic groups building on ideas of the master thesis of the first author (written at FernUniversit\"at in Hagen in 2025).

\medskip

\begin{question}
Do the procyclic groups $\prod_{p \equiv 2 \bmod 3} \bbZ_p$ and $\prod_{p \equiv 3 \bmod 4} \bbZ_p$ have Weil abscissa $2$?
\end{question}

Representability of integers by quadratic forms is a classical topic in number theory. The sum of two squares problem is a famous example: which primes are sums of two squares? It was already known to Fermat that exactly $2$ and all primes in $S_1=\{p\in \mathcal{P} \mid p \equiv 1 \bmod 4\}$ are the sum of two squares. We will need the following refined result on representations of integers as a sum of two \emph{coprime} squares:
\begin{proposition}[{see \cite[Corollary 3.2.2]{Fine2007}}]\label{prop:1mod4}
 Let $n \in \mathbb{N}$. Then $n=x^2+y^2$ for coprime integers $x,y$ if and only if the prime decomposition of $n$ is $n=2^\delta \prod_{i=1}^k p_i^{\alpha_i}$ where $\delta \in \{0,1\}$ and $p_1,\dots, p_k \in S_1$.
\end{proposition}
This result immediately implies
\begin{corollary}\label{cor:1}
Define $P_{S_1}=\{p\in\mathcal{P} \mid p=x^2+y^2+1,\,x,y\in \mathbb{Z}, \; \gcd(x,y)=1\}$. All primes $p \in P_{S_1}$ satisfy $(p-1)_{S_1}\geq (p-1)/2$.
\end{corollary}

\begin{proposition}
 Let $n \in \mathbb{N}$ and $S_2=\{p\in \mathcal{P} \mid p \equiv 1 \bmod 8 \text{ or } p \equiv 3 \bmod 8\}$. If $n=x^2+2y^2$ for coprime $x,y \in \mathbb{Z}$, then $n=2^\delta \prod_{i=1}^k p_i^{\alpha_i}$, where $\delta \in \{0,1\}$ and $p_1,\dots,p_k\in S_2$.
\end{proposition}
\begin{proof}
 First, we observe that for any even integer $n=x^2+2y^2$, where $\gcd(x,y)=1$, $x$ must be an even integer. Therefore, $n$ has a residue of $2$ modulo $4$ and is only divisible by $2$, not $4$. For odd primes the result is given by an old theorem of Fermat \cite[p. 7]{Cox1997}:
 Odd prime divisors $p$ of $n$ must satisfy the condition \begin{align*}
 1=\begin{pmatrix}
 \frac{-2}{p}
\end{pmatrix}=\begin{pmatrix}
 \frac{-1}{p}
\end{pmatrix}\begin{pmatrix}
 \frac{2}{p}
\end{pmatrix}=(-1)^{\frac{p-1}{2}}(-1)^{\frac{p^2-1}{8}}. 
 \end{align*} 
 This implies, as one readily verifies, that all odd prime divisors of $n$ lie in~$S_2$.
\end{proof}
\begin{corollary}\label{cor:2}
Define $P_{S_2}=\{p\in\mathcal{P} \mid p=x^2+2y^2+1,\,x,y\in \mathbb{Z}, \; \gcd(x,y)=1\}$.
All primes $p \in P_{S_2}$ satisfy $(p-1)_{S_2}\geq (p-1)/2$.
\end{corollary}

\begin{proposition}
 Let $n \in \mathbb{N}$ and $S_3=\{p\in \mathcal{P} \mid p \equiv 1 \bmod 3\}$. If $n=x^2+3y^2$ for coprime $x,y \in \mathbb{Z}$, then $n=2^{\delta_1} 3^{\delta_2} \prod_{i=1}^k p_i^{\alpha_i}$, where $\delta_1 \in \{0,1,2\}$, $\delta_2 \in \{0,1\}$, $p_1,\dots,p_k\in S_3$.
\end{proposition}
\begin{proof}
 First, we observe that for any even integer $n=x^2+3y^2$, where $\gcd(x,y)=1$, both $x$ and $y$ are odd integers.
 Since all odd squares have a residue of $1$ modulo $8$, $n$ cannot be divisible by $8$.
 Regarding the divisor $3^{\delta_2}$, there are two cases.
 First, if $y$ is divisible by $3$, then $x$ is not and $\delta_2=0$. Second, if $x$ is divisible by $3$, then $y$ is not, and thus, $\delta_2=1$. For odd primes the result is again given by an old theorem of Fermat \cite[p. 7]{Cox1997}:
 According to the law of quadratic reciprocity, odd prime divisors $p\neq 3$ must satisfy the following condition: \begin{align*}
 1=\begin{pmatrix}
 \frac{-3}{p}
\end{pmatrix}=\begin{pmatrix}
 \frac{-1}{p}
\end{pmatrix}\begin{pmatrix}
 \frac{3}{p}
\end{pmatrix}=(-1)^{\frac{p-1}{2}} \begin{pmatrix}
 \frac{3}{p}
\end{pmatrix}=\begin{pmatrix}
 \frac{p}{3}
\end{pmatrix}. 
 \end{align*} 
 Since $1$ is the only quadratic residue of a prime $p\neq3$ modulo $3$, the only possible odd prime divisors of $n$ are the primes in $S_3$. 
\end{proof}
As before we deduce
\begin{corollary}\label{cor:3}
Define $P_{S_3}=\{p\in\mathcal{P} \mid p=x^2+3y^2+1,\,x,y\in \mathbb{Z}, \; \gcd(x,y)=1\}$. 
All primes $p \in P_{S_3}$ satisfy $(p-1)_{S_3}\geq (p-1)/12$. 
\end{corollary}
Next, we will need some results from the theory of quadratic forms.
\begin{definition}[see \cite{Cox1997}]
 Two binary quadratic forms, $f(x,y)$ and $g(x,y$), are said to be \emph{(properly) equivalent} if there are $a,b,c,d \in \mathbb{Z}$ such that $ad-bc=1$ and
 \begin{align*}
 f(x,y)=g(ax+by,cx+dy) \text{ for all } x,y \in \mathbb{Z}. 
 \end{align*}
 The \emph{genus of a quadratic form} $f(x,y)$ is the set of all binary quadratic forms that represent the same numbers in $(\mathbb{Z}/|\Delta_f|\mathbb{Z})^*$. It is denoted by $R_f$.
\end{definition}

\begin{proof}[Proof of Theorem \ref{thm:main}]
Let $S$ be any set of primes.
The free procyclic group $\widehat{\bbZ} = \prod_{p \in \mathcal{P}} \bbZ_p$ has Weil abscissa $2$; see \cite[Theorem C (i)]{corob2024weil}. Hence the inequality 
\[\alpha(H_S) \leq 2\] follows immediately using that $H_S$ is a quotient of $\widehat{\bbZ}$.

