\subsection{Conclusion} \label{SS_Conclusion}
We now complete the proof of Theorem \ref{main}.
Note that
\begin{equation}\label{quadratic_term}
 \int_0^t \int_{\mathbb{T}^3_x} \frac{1}{2}\mu \sigma(\tilde{u}-u^b):\sigma(\tilde{u}-u^b) + \frac{5}{2} \kappa(\nabla_x \tilde{\theta} -\nabla_x \theta^b)^2 \ dxds \geqslant 0.
\end{equation}
Combining with \eqref{mid_result} and \eqref{dissipation_control_final_result} we have
\begin{equation}
 \begin{aligned}
 \frac{1}{{\varepsilon}^2} &H(f_{\varepsilon}| M_{\varepsilon})(t) \\
 &\lesssim \frac{1}{\varepsilon^2} H(f^{\mathrm{in}}_{\varepsilon}| M^{\mathrm{in}}_{\varepsilon}) + \int^t_0 \|(\nabla_x \tilde{u},\nabla_x \tilde{\theta})\|_{L^{\infty}(dx)} \frac{1}{\varepsilon^2} H(f_{\varepsilon}|M_{\varepsilon}) ds \\
 & +\tilde{R}+ R_5+R_6+R_7 -R_{11}-R_{12} - 2R_{13}.
 \end{aligned}
\end{equation}
All the remainder terms can be shown to tend to zero as $\varepsilon$ tends to zero by using that $(\rho^b_{\varepsilon}, u^b_{\varepsilon}, \theta^b_{\varepsilon})$, $(\tilde{\rho}_{\varepsilon},\tilde{u}_{\varepsilon},\tilde{\theta}_{\varepsilon})$, $g_{\varepsilon}$ and $\frac{1}{\varepsilon} \Loth g_{\varepsilon}$
are separately uniformly bounded in some proper functional spaces, and Grönwall's inequality then implies that
\begin{equation}
 \begin{aligned}
 \frac{1}{{\varepsilon}^2} H(f_{\varepsilon}| M_{\varepsilon})(t) \leqslant
 \left( \frac{1}{\varepsilon^2} H(f^{\mathrm{in}}_{\varepsilon}| M^{\mathrm{in}}_{\varepsilon})+ \mathcal{O}(\varepsilon)\right) \exp \left( C \int_0^{\infty} \| (\nabla_x \tilde{u}, \nabla_x \tilde{\theta}) \|_{L^{\infty}(dx)} dt \right).
 \end{aligned}
\end{equation}
Hence,
\begin{equation}\label{entropy_control}
 \begin{aligned}
 \frac{1}{{\varepsilon}^2} H(f_{\varepsilon}| M_{\varepsilon})(t) \lesssim
 \frac{1}{\varepsilon^2} H(f^{\mathrm{in}}_{\varepsilon}| M^{\mathrm{in}}_{\varepsilon})+ \mathcal{O}(\varepsilon).
 \end{aligned}
\end{equation}
This estimate together with \eqref{mid_result}, \eqref{quadratic_term} and the fact $H(f|g) \geqslant 0$ leads to
\begin{equation}\label{entropy_dissipation_bound_temp}
 \int_0^t \int_{\mathbb{T}^3_x}\frac{1}{\varepsilon^4}D(f_\varepsilon)(s,x) - \frac{1}{2} \mu \sigma(u^b): \sigma(u^b) - \frac{5}{2}\kappa (\nabla_x \theta^b)^2\ dxds \lesssim \frac{1}{\varepsilon^2} H(f_{\varepsilon}^{\mathrm{in}}|M_{\varepsilon}^{\mathrm{in}}) + \mathcal{O}(\varepsilon).
 \end{equation}
 Using \eqref{mid_result}, \eqref{entropy_control}, \eqref{entropy_dissipation_bound_temp} and \eqref{dissipation_control_final_result},we then have
 \begin{equation}
 \int_0^t \int_{\mathbb{T}^3_x} \frac{1}{2}\mu \sigma(\tilde{u}-u^b):\sigma(\tilde{u}-u^b) + \frac{5}{2} \kappa(\nabla_x \tilde{\theta} -\nabla_x \theta^b)^2 \ dxds \lesssim \frac{1}{\varepsilon^2} H(f_{\varepsilon}^{\mathrm{in}}|M_{\varepsilon}^{\mathrm{in}}) + \mathcal{O}(\varepsilon),
\end{equation}
which completes the proof of Theorem \ref{main}.

