To prove the main theorem ("at a formal level"), the paper proceeds as follows:
\begin{itemize}
\item First, it proves the estimate by "calculating the evolution of the relative entropy."
\item Next, in the part labeled
\begin{aligned}
        R_6&= \int^t_0 \int_{\mathbb{T}^3_x} (\frac{1}{\rho \theta^2}-1 ) \frac{5}{2} \nabla_x \mdot [\kappa(\rho,\theta) \nabla_x \tilde{\theta} ](\theta^b -\tilde{\theta}) + (1-\frac{1}{\theta^2})\kappa \nabla_x \theta^b \cdot \nabla_x \tilde{\theta}\ dxds\\
         &+ \int^t_0 \int_{\mathbb{T}^3_x} \frac{5}{2} (\kappa - \kappa(\rho,\theta))\nabla_x \tilde{\theta}\cdot (\nabla_x \tilde{\theta}-\nabla_x \theta^b) \ dxds.
    \end{aligned}
\end{equation}

\subsection{Relative entropy control}\label{SS_REC}
The terms \Rmnum{3} and \Rmnum{4} are unsigned, however they can be controlled by the quadratic of $(\rho^b-\tilde{\rho}^{\varepsilon}, u^b - \tilde{u}^{\varepsilon},\theta^b - \tilde{\theta}^{\varepsilon})$ which  can be controlled by relative entropy $\frac{1}{\varepsilon^2} H(f_{\varepsilon}|M_{\varepsilon})$.
In fact, we have the following two lemmas.
\begin{lemma} \label{same_moments}
    \begin{equation}
        \begin{aligned}
            H(f_{\varepsilon}|M_{\varepsilon}) = H(f_{\varepsilon}| M_{f_\varepsilon}) + H(M_{f_{\varepsilon}}|M_{\varepsilon}),
        \end{aligned}
\end{itemize}
(so that the "unsigned terms will be controlled by the relative entropy itself").
\begin{itemize}
\item Then, in the part labeled
\begin{aligned}
        \frac{1}{{\varepsilon}^2} &H(f_{\varepsilon}| M_{\varepsilon})(t) +\int_0^t \int_{\mathbb{T}^3_x}\frac{1}{\varepsilon^4}D(f_\varepsilon)(s,x) - \frac{1}{2} \mu \sigma(u^b): \sigma(u^b) - \frac{5}{2}\kappa (\nabla_x \theta^b)^2\  dxds \\
        &+\int_0^t \int_{\mathbb{T}^3_x} \frac{1}{2}\mu \sigma(\tilde{u}-u^b):\sigma(\tilde{u}-u^b) + \frac{5}{2}  \kappa(\nabla_x \tilde{\theta} -\nabla_x \theta^b)^2 \ dxds\\
        &\lesssim \frac{1}{\varepsilon^2} H(f^{\mathrm{in}}_{\varepsilon}| M^{\mathrm{in}}_{\varepsilon}) + \int^t_0 \|(\nabla_x \tilde{u},\nabla_x \tilde{\theta})\|_{L^{\infty}(dx)} \frac{1}{\varepsilon^2} H(f_{\varepsilon}|M_{\varepsilon}) ds +\tilde{R} + R_5+R_6+R_7.
    \end{aligned}
\end{equation}

\subsection{Entropy dissipation control}\label{SS_EDC}
 We now deal with the term
\begin{equation}\label{dissipation_control}
    \begin{aligned}
        \int_0^t \int_{\mathbb{T}^3_x}\frac{1}{\varepsilon^4}D(f_\varepsilon)(s,x) - \frac{1}{2} \mu \sigma(u^b): \sigma(u^b) - \frac{5}{2}\kappa (\nabla_x \theta^b)^2\  dxds ,
    \end{aligned}
\end{itemize}
(it shows that the "negative terms will be controlled by the entropy dissipation").
\begin{itemize}
\item Finally, in the part labeled
\begin{aligned}
        R_{12}= \int_0^t \int_{\mathbb{T}^3_x} \left( \langle v \mdot \nabla_x \Loth g_{\varepsilon} , \hat{A}\rangle + \langle \varepsilon \partial_t g_{\varepsilon} , \hat{A}\rangle\right) :\sigma(u^b) \ dxds ,\\
        R_{13}=\int_0^t \int_{\mathbb{T}^3_x}  \left(\langle v \mdot \nabla_x \Loth g_{\varepsilon} , \hat{B}\rangle + \langle \varepsilon \partial_t g_{\varepsilon} , \hat{B}\rangle\right) \cdot \nabla_x \theta^b \ dxds.
    \end{aligned}
\end{equation}

\subsection{Conclusion} \label{SS_Conclusion}
We now complete the proof of Theorem \ref{main}.
Note that
\begin{equation}\label{quadratic_term}
    \int_0^t \int_{\mathbb{T}^3_x} \frac{1}{2}\mu \sigma(\tilde{u}-u^b):\sigma(\tilde{u}-u^b) + \frac{5}{2}  \kappa(\nabla_x \tilde{\theta} -\nabla_x \theta^b)^2 \ dxds \geqslant 0.
\end{equation}
Combining with \eqref{mid_result} and \eqref{dissipation_control_final_result} we have
\begin{equation}
    \begin{aligned}
        \frac{1}{{\varepsilon}^2} &H(f_{\varepsilon}| M_{\varepsilon})(t)  \\
        &\lesssim \frac{1}{\varepsilon^2} H(f^{\mathrm{in}}_{\varepsilon}| M^{\mathrm{in}}_{\varepsilon}) + \int^t_0 \|(\nabla_x \tilde{u},\nabla_x \tilde{\theta})\|_{L^{\infty}(dx)} \frac{1}{\varepsilon^2} H(f_{\varepsilon}|M_{\varepsilon}) ds \\
        & +\tilde{R}+ R_5+R_6+R_7 -R_{11}-R_{12} - 2R_{13}.
    \end{aligned}
\end{equation}

it concludes the bounds
\begin{equation}\label{main_estimate}
            \frac{1}{{\varepsilon}^2} H(f_{\varepsilon}| M_{\varepsilon})(t)  \leqslant \frac{1}{\varepsilon^2}H(f^{\mathrm{in}}_{\varepsilon}| M^{\mathrm{in}}_{\varepsilon} ) + \mathcal{O}(\varepsilon),
        \end{equation}
\begin{equation}\label{entropy_dissipation_bound}
           \int_0^t \int_{\mathbb{T}^3_x}\frac{1}{\varepsilon^4}D(f_\varepsilon)(s,x) - \frac{1}{2} \mu \sigma(\u^b_\varepsilon): \sigma(\u^b_\varepsilon) - \frac{5}{2}\kappa (\nabla_x \theta^b_{\varepsilon})^2\  dxds \lesssim \frac{1}{\varepsilon^2} H(f_{\varepsilon}^{\mathrm{in}}|M_{\varepsilon}^{\mathrm{in}}) + \mathcal{O}(\varepsilon),
         \end{equation}
\begin{equation}\label{energy_momentum_flux_bound}
             \int_0^t \int_{\mathbb{T}^3_x} \frac{1}{2}\mu \sigma(\tilde{\u}_{\varepsilon}-\u^b_{\varepsilon}):\sigma(\tilde{\u}_{\varepsilon}-\u^b_{\varepsilon}) + \frac{5}{2}  \kappa(\nabla_x \tilde{\theta} -\nabla_x \theta^b_{\varepsilon})^2 \ dxds \lesssim \frac{1}{\varepsilon^2} H(f_{\varepsilon}^{\mathrm{in}}|M_{\varepsilon}^{\mathrm{in}}) + \mathcal{O}(\varepsilon),
        \end{equation}
"by Gr\"onwall's inequality."
\end{itemize}
It is also remarked that the argument is "in the formal level" but "provide[s] a clear way to the later rigorous proof," and that the validity of the $\mathcal{O}(\varepsilon)$ residual term "relies on uniform in $\varepsilon$ estimates for the solutions" (with cited sources providing global existence and uniform bounds in the perturbative framework).

