\label{main}
        Let $f_{\varepsilon}$  be of the form $f_{\varepsilon} = M + \varepsilon M g_{\varepsilon} $, and $\{f_{\varepsilon}\}$ is a family of solutions to
        \begin{equation}\label{longtime_Boltzmann} \tag{BE}
    \left\{\begin{aligned}
        &\tau_{\varepsilon} \partial_t f_{\varepsilon} + v\mdot \nabla_x f_{\varepsilon} =\frac{1}{\varepsilon} C(f_{\varepsilon},\ f_{\varepsilon}), \quad x\in \mathbb{T}^3, \quad v \in \mathbb{R}^3\\
        &f_{\varepsilon}(0,x) = f_{\varepsilon}^{\mathrm{in}} \geqslant 0,
    \end{aligned}\right.
\end{equation}
        with $\tau_\varepsilon=\varepsilon$ satisfying the assumptions
        \begin{align}
            &\partial_t \int_{\mathbb{R}^3_v} f_{\varepsilon} dv + \nabla_x \cdot  \int_{\mathbb{R}^3_v} f_{\varepsilon}dv = 0, \label{conservation_of_mass} \\
            &\partial_t \int_{\mathbb{R}^3_v} vf_{\varepsilon} dv + \nabla_x \cdot \int_{\mathbb{R}^3_v} vf_{\varepsilon}dv =0,\label{conservation_of_momentum}\\
            &\partial_t \int_{\mathbb{R}^3_v} |v|^2 f_{\varepsilon} dv + \nabla_x \cdot \int_{\mathbb{R}^3_v} |v|^2f_{\varepsilon}dv=0.\label{conservation_of_energy}\\
        \end{align}
        and
        \begin{equation}\label{entropy_inequality}
        H(f_{\varepsilon}| M)(t) + \frac{1}{\varepsilon^2}\int_0^t \int_{\mathbb{T}^3_x} D(f_\varepsilon)(s,x) \ ds dx \leqslant H(f^{\mathrm{in}}_{\varepsilon}| M ),
    \end{equation}
        Let $(\rho_{\varepsilon}, u_{\varepsilon},\theta_{\varepsilon})$ be of the form $(\rho_{\varepsilon},u_{\varepsilon},\theta_{\varepsilon}) = (1+ \tilde{\rho}_{\varepsilon},\varepsilon \tilde{u}_{\varepsilon},1+ \varepsilon \tilde{\theta}_{\varepsilon})$, and $\{(\rho_{\varepsilon},u_{\varepsilon},\theta_{\varepsilon})\}$ is a family of solutions to
        \begin{equation} \label{longtime_CNS}\tag{$\text{CNS}_{\varepsilon}$}
        \left\{ \begin{aligned}
            &\varepsilon\partial_t \rho_{\varepsilon} + \nabla_x (\rho_{\varepsilon} u_{\varepsilon}) = 0,\\
            &\varepsilon\partial_t u_{\varepsilon} + u_{\varepsilon} \mdot \nabla_x u_{\varepsilon}  + \frac{1}{\rho_{\varepsilon}} \nabla_x (\rho_{\varepsilon} \theta_{\varepsilon})  = \varepsilon \frac{1}{\rho_{\varepsilon}} \nabla_x [ \mu_{\varepsilon}(\rho_{\varepsilon},\theta_{\varepsilon}) \sigma(u_{\varepsilon})],\\
            &\varepsilon \partial_t \theta_{\varepsilon}  + u_{\varepsilon} \mdot \nabla_x \theta_{\varepsilon} + \frac{2}{3} \theta_{\varepsilon}  \nabla_x \mdot u_{\varepsilon} = \varepsilon  \frac{1}{\rho_{\varepsilon}} \frac{1}{3} \mu_{\varepsilon}(\rho_{\varepsilon},\theta_{\varepsilon}) \sigma(u_{\varepsilon}):\sigma(u_{\varepsilon}) +  \frac{1}{\rho_{\varepsilon}}\frac{5}{3} \varepsilon \nabla_x \cdot[\kappa(\rho_{\varepsilon},\theta_{\varepsilon}) \theta_{\varepsilon}],\\
            &(\rho_{\varepsilon}(0,x),\ u_{\varepsilon}(0,x), \ \theta_{\varepsilon}(0,x)) = (1+ \varepsilon \tilde{\rho}^{\mathrm{in}},\ \tilde{u}^{\mathrm{in}},\ 1+ \varepsilon \tilde{\theta}^{\mathrm{in}}).
        \end{aligned}\right.
    \end{equation}
        Then we have, for $t \geqslant 0$,
        \begin{equation}\label{main_estimate}
            \frac{1}{{\varepsilon}^2} H(f_{\varepsilon}| M_{\varepsilon})(t)  \leqslant \frac{1}{\varepsilon^2}H(f^{\mathrm{in}}_{\varepsilon}| M^{\mathrm{in}}_{\varepsilon} ) + \mathcal{O}(\varepsilon),
        \end{equation}
        \begin{equation}\label{entropy_dissipation_bound}
           \int_0^t \int_{\mathbb{T}^3_x}\frac{1}{\varepsilon^4}D(f_\varepsilon)(s,x) - \frac{1}{2} \mu \sigma( \mathrm{u} ^b_\varepsilon): \sigma( \mathrm{u} ^b_\varepsilon) - \frac{5}{2}\kappa (\nabla_x \theta^b_{\varepsilon})^2\  dxds \lesssim \frac{1}{\varepsilon^2} H(f_{\varepsilon}^{\mathrm{in}}|M_{\varepsilon}^{\mathrm{in}}) + \mathcal{O}(\varepsilon),
         \end{equation}
         \begin{equation}\label{energy_momentum_flux_bound}
             \int_0^t \int_{\mathbb{T}^3_x} \frac{1}{2}\mu \sigma(\tilde{ \mathrm{u} }_{\varepsilon}- \mathrm{u} ^b_{\varepsilon}):\sigma(\tilde{ \mathrm{u} }_{\varepsilon}- \mathrm{u} ^b_{\varepsilon}) + \frac{5}{2}  \kappa(\nabla_x \tilde{\theta} -\nabla_x \theta^b_{\varepsilon})^2 \ dxds \lesssim \frac{1}{\varepsilon^2} H(f_{\varepsilon}^{\mathrm{in}}|M_{\varepsilon}^{\mathrm{in}}) + \mathcal{O}(\varepsilon),
        \end{equation}
        where
        \begin{equation}
            M_{\varepsilon}^{\mathrm{in}} = M(1+ \varepsilon \tilde\rho^{\mathrm{in}}, \varepsilon \tilde{u}^{\mathrm{in}},1 + \varepsilon \tilde{\theta}^{\mathrm{in}}).
        \end{equation}

