\W\!\left(\frac1n\sum_{k=1}^n \delta_{x_k},\,dx\right)
\le C_\M\left(\frac1{\sqrt n}
+\frac1n\left|\sum_{i\neq j} G(x_i,x_j)\right|^{1/2}\right)?
\]
\end{problem}

