We assume that 
the measure $m$ satisfies the following \emph{volume doubling} property \hypertarget{vd}{$\operatorname{VD}$}: there exists $C_D >1$ such that
\begin{equation*} \tag{VD}
 V(x,2r)\le C_{D} V(x,r), \quad \mbox{for any $x \in X, r \in (0,\infty)$}.
\end{equation*}
Setting $\alpha =\log_2 C_D$ and iterating \hyperlink{vd}{$\operatorname{VD}$}, we obtain the following well-known consequence 
 \begin{equation}\label{e:vd-iter}
 V(x,s)\le C_D^2 \left( \frac{d(x,y)+s}{r}\right)^\alpha V(y,r), \quad \mbox{for all $x \in X, 0<r<s<\infty$.}
\end{equation}
We recall the closely related reverse volume doubling property and a generalized version introduced in \cite[Definition 1.4]{Mal}.
\begin{definition}
 We say that a metric measure space $(X,d,m)$ satisfies the \emph{reverse volume doubling} property \hypertarget{rvd}{$\operatorname{RVD}$} if there exists $\beta \in (0,\infty), C \in (1,\infty)$ such that for all $x \in X, 0 < r \le R < \diam(X,d)$, we have 
\begin{equation*} \tag{RVD}
 \frac{m(B(x,R))}{m(B(x,r)))}\ge C^{-1} \frac{R^\beta}{r^\beta}.
\end{equation*}
For any $x \in X$, define $D_x:= \inf_{y \in X \setminus \{x\}} d(x,y)$. We say that $(X,d,m)$ satisfies the \emph{quasi reverse volume doubling} property \hypertarget{qrvd}{$\operatorname{QRVD}$} if there exists $\beta \in (0,\infty), C \in (1,\infty)$ such that for all $x \in X, D_x < r \le R < \diam(X,d)$, we have 
\begin{equation*} \tag{QRVD}
 \frac{m(B(x,R))}{m(B(x,r)))}\ge C^{-1} \frac{R^\beta}{r^\beta}.
\end{equation*}
\end{definition}
Much of the existing work on stable-like heat kernel estimates assumes the reverse volume doubling condition \hyperlink{rvd}{$\operatorname{RVD}$}.
Since many natural examples, such as graphs with polynomial volume growth, do not satisfy \hyperlink{rvd}{$\operatorname{RVD}$} but do satisfy \hyperlink{qrvd}{$\operatorname{QRVD}$},
we work throughout in this more general setting.

\begin{definition} Let $(X,d,m)$ be a metric measure space and let $(\mathcal{E},\mathcal{F})$ be a pure jump Dirichlet form on $L^2(X,m)$ with jump measure $J$. 
 We say that the two-sided jump kernel bounds
 \hypertarget{jphi}{$\operatorname{J(\phi)}$} hold if there exist a symmetric
 function $J : X \times X \rightarrow [0,\infty)$ and constants $c, C > 0$ such that
 \[
 J(dx,dy) = J(x,y)\, m(dx)\, m(dy),
 \]
 and
 \begin{equation*}
 \tag*{$\operatorname{J(\phi)}$}
 \frac{c}{m(B(x,d(x,y)))\, \phi(d(x,y))}
 \le J(x,y)
 \le \frac{C}{m(B(x,d(x,y)))\, \phi(d(x,y))},
 \end{equation*}
 for all $x,y \in X$ with $x \neq y$.
 The above upper and lower bounds on $J$ will be denoted by
$\operatorname{J(\phi)}_{\le}$ and $\operatorname{J(\phi)}_{\ge}$,
respectively.

For the remainder of this work, we always assume that the jump measure $J$ on $X \times X \setminus \diag_X$ is of the form $J(dx,dy)= J(x,y) \,m(dx)\,m(dy)$ where $J: X \times X \rightarrow [0,\infty)$ is a non-negative, symmetric, measurable function. We define the \emph{energy measure} $\Gamma(f,f)$ of a function $f \in \mathcal{F}$ by 
\begin{equation} \label{e:def-gamma} 
 \Gamma(f,f)(A) = \int_{A} \int_X (f(x)-f(y))^2 J(x,y)\,m(dy)\,m(dx).
\end{equation}
We also denote by $\Gamma(f,f): X \rightarrow \mathbb{R}$, the dennsity of the measure $\Gamma(f,f)$ with respect to $m$ given by 
\[
\Gamma(f,f)(x):= \int_{X}(f(x)-f(y))^2 J(x,y) \, m(dy).
\]
By an abuse of notation, we use the same symbol for both the measure and its
density with respect to $m$ for $J$ and $\Gamma$; the meaning will be clear
from the context.
\begin{definition}
\begin{enumerate}[(i)]
 \item
 Let $U \subset V$ be open sets in $X$ with $U \subset \overline{U} \subset V$.
 A \textbf{cutoff function} for $U \subset V$ is a non-negative, bounded,
 measurable function $\phi$ such that $\phi \equiv 1$ on $U$,
 $\phi \equiv 0$ on $V^c$, and $0 \le \phi \le 1$ on $X$.

\end{definition}
\begin{remark} \label{r:covering}
Assuming \hyperlink{cap}{$\operatorname{Cap}(\phi)_{\le}$}, we may, without loss of generality,
take $A_1 = 2$. Indeed, this can be achieved by covering $B(x,r)$ with a uniformly bounded
number of balls of radius $r/A_1$ whose centers lie in $B(x,r)$, and then taking the maximum 
of the corresponding cutoff functions associated with these smaller balls. For such a covering argument, see, for instance, \cite[Lemma~6.2]{Mur24}. 
By \cite[Proposition 2.3-(5)]{CKW-hke}, under \hyperlink{vd}{$\operatorname{ VD}$}, and \hyperlink{jphi}{$\operatorname{ J(\phi)_\le}$} we have the implication 
\begin{equation} \label{e:csj-cap}
 \mbox{\hyperlink{csj}{$\operatorname{CSJ(\phi)}$}} \implies \mbox{\hyperlink{cap}{$\operatorname{Cap(\phi)_{\le}}$.}}
\end{equation}
\end{remark}

\begin{definition} \label{d:stable}
 We say that $(X,d,m,\mathcal{E},\mathcal{F})$
 satisfies the \textbf{stable-like heat kernel estimates} \hypertarget{shk}{$\operatorname{ HK}(\phi)$}
 if there exist $C_1 \in (1,\infty)$ and a heat kernel $\{ p_{t} \}_{t>0}$ of
 the semigroup corresponding to the Dirichlet form $(\mathcal{E},\mathcal{F})$ such that for each $t \in (0,\infty)$,
 \begin{equation} \label{eq:shk-upper}
 p_{t}(x,y) \le C_1 \biggl( \frac{1}{m\bigl(B(x,\phi^{-1}(t))\bigr)} \wedge \frac{t}{m\bigl(B(x,d(x,y))\bigr) \phi(d(x,y))} \biggr)
 \end{equation}
 and
 \begin{equation} \label{eq:shk-lower}
 p_{t}(x,y) \ge C_1^{-1} \biggl( \frac{1}{m\bigl(B(x,\phi^{-1}(t))\bigr)} \wedge \frac{t}{m\bigl(B(x,d(x,y))\bigr) \phi(d(x,y))} \biggr)
 \end{equation}
 for $m$-a.e.\ $x,y \in X$, where $\phi^{-1}(\cdot)$ denotes the
 inverse of the homeomorphism $\phi(\cdot) \colon [0,\infty)\rightarrow [0,\infty)$.
\end{definition}

The following is the first main result of the work and provides a sufficient condition for cutoff Sobolev inequality for pure jump process.

