\begin{definition} Let $(X,d,m)$ be a metric measure space and let $(\mathcal{E},\mathcal{F})$ be a pure jump Dirichlet form on $L^2(X,m)$ with jump measure $J$. 
 We say that the two-sided jump kernel bounds
 \hypertarget{jphi}{$\operatorname{J(\phi)}$} hold if there exist a symmetric
 function $J : X \times X \rightarrow [0,\infty)$ and constants $c, C > 0$ such that
 \[
 J(dx,dy) = J(x,y)\, m(dx)\, m(dy),
 \]
 and
 \begin{equation*}
 \tag*{$\operatorname{J(\phi)}$}
 \frac{c}{m(B(x,d(x,y)))\, \phi(d(x,y))}
 \le J(x,y)
 \le \frac{C}{m(B(x,d(x,y)))\, \phi(d(x,y))},
 \end{equation*}
 for all $x,y \in X$ with $x \neq y$.
 The above upper and lower bounds on $J$ will be denoted by
$\operatorname{J(\phi)}_{\le}$ and $\operatorname{J(\phi)}_{\ge}$,
respectively.

For the remainder of this work, we always assume that the jump measure $J$ on $X \times X \setminus \diag_X$ is of the form $J(dx,dy)= J(x,y) \,m(dx)\,m(dy)$ where $J: X \times X \rightarrow [0,\infty)$ is a non-negative, symmetric, measurable function. We define the \emph{energy measure} $\Gamma(f,f)$ of a function $f \in \mathcal{F}$ by 
\begin{equation} \label{e:def-gamma} 
 \Gamma(f,f)(A) = \int_{A} \int_X (f(x)-f(y))^2 J(x,y)\,m(dy)\,m(dx).
\end{equation}
We also denote by $\Gamma(f,f): X \rightarrow \mathbb{R}$, the dennsity of the measure $\Gamma(f,f)$ with respect to $m$ given by 
\[
\Gamma(f,f)(x):= \int_{X}(f(x)-f(y))^2 J(x,y) \, m(dy).
\]
By an abuse of notation, we use the same symbol for both the measure and its
density with respect to $m$ for $J$ and $\Gamma$; the meaning will be clear
from the context.
\begin{definition}
\begin{enumerate}[(i)]
 \item
 Let $U \subset V$ be open sets in $X$ with $U \subset \overline{U} \subset V$.
 A \textbf{cutoff function} for $U \subset V$ is a non-negative, bounded,
 measurable function $\phi$ such that $\phi \equiv 1$ on $U$,
 $\phi \equiv 0$ on $V^c$, and $0 \le \phi \le 1$ on $X$.

\end{definition}
\begin{remark} \label{r:covering}
Assuming \hyperlink{cap}{$\operatorname{Cap}(\phi)_{\le}$}, we may, without loss of generality,
take $A_1 = 2$. Indeed, this can be achieved by covering $B(x,r)$ with a uniformly bounded
number of balls of radius $r/A_1$ whose centers lie in $B(x,r)$, and then taking the maximum 
of the corresponding cutoff functions associated with these smaller balls. For such a covering argument, see, for instance, \cite[Lemma~6.2]{Mur24}. 
By \cite[Proposition 2.3-(5)]{CKW-hke}, under \hyperlink{vd}{$\operatorname{ VD}$}, and \hyperlink{jphi}{$\operatorname{ J(\phi)_\le}$} we have the implication 
\begin{equation} \label{e:csj-cap}
 \mbox{\hyperlink{csj}{$\operatorname{CSJ(\phi)}$}} \implies \mbox{\hyperlink{cap}{$\operatorname{Cap(\phi)_{\le}}$.}}
\end{equation}
\end{remark}

\begin{definition} \label{d:stable}
 We say that $(X,d,m,\mathcal{E},\mathcal{F})$
 satisfies the \textbf{stable-like heat kernel estimates} \hypertarget{shk}{$\operatorname{ HK}(\phi)$}
 if there exist $C_1 \in (1,\infty)$ and a heat kernel $\{ p_{t} \}_{t>0}$ of
 the semigroup corresponding to the Dirichlet form $(\mathcal{E},\mathcal{F})$ such that for each $t \in (0,\infty)$,
 \begin{equation} \label{eq:shk-upper}
 p_{t}(x,y) \le C_1 \biggl( \frac{1}{m\bigl(B(x,\phi^{-1}(t))\bigr)} \wedge \frac{t}{m\bigl(B(x,d(x,y))\bigr) \phi(d(x,y))} \biggr)
 \end{equation}
 and
 \begin{equation} \label{eq:shk-lower}
 p_{t}(x,y) \ge C_1^{-1} \biggl( \frac{1}{m\bigl(B(x,\phi^{-1}(t))\bigr)} \wedge \frac{t}{m\bigl(B(x,d(x,y))\bigr) \phi(d(x,y))} \biggr)
 \end{equation}
 for $m$-a.e.\ $x,y \in X$, where $\phi^{-1}(\cdot)$ denotes the
 inverse of the homeomorphism $\phi(\cdot) \colon [0,\infty)\rightarrow [0,\infty)$.
\end{definition}

The following is the first main result of the work and provides a sufficient condition for cutoff Sobolev inequality for pure jump process.

\begin{definition} \label{d:stable}
 We say that $(X,d,m,\mathcal{E},\mathcal{F})$
 satisfies the \textbf{stable-like heat kernel estimates} \hypertarget{shk}{$\on{HK}(\phi)$}
 if there exist $C_1 \in (1,\infty)$ and a heat kernel $\{ p_{t} \}_{t>0}$ of
 the semigroup corresponding to the Dirichlet form $(\mathcal{E},\mathcal{F})$ such that for each $t \in (0,\infty)$,
 \begin{equation} \label{eq:shk-upper}
 p_{t}(x,y) \le C_1 \biggl( \frac{1}{m\bigl(B(x,\phi^{-1}(t))\bigr)} \wedge \frac{t}{m\bigl(B(x,d(x,y))\bigr) \phi(d(x,y))} \biggr)
 \end{equation}
 and
 \begin{equation} \label{eq:shk-lower}
 p_{t}(x,y) \ge C_1^{-1} \biggl( \frac{1}{m\bigl(B(x,\phi^{-1}(t))\bigr)} \wedge \frac{t}{m\bigl(B(x,d(x,y))\bigr) \phi(d(x,y))} \biggr)
 \end{equation}
 for $m$-a.e.\ $x,y \in X$, where $\phi^{-1}(\cdot)$ denotes the
 inverse of the homeomorphism $\phi(\cdot) \colon [0,\infty)\to [0,\infty)$.
\end{definition}

Theorem \ref{t:main} along with known characterizations of stable-like heat kernel bounds imply an affirmative answer to \cite[Conjecture 1.14]{GHH18} as we state below.
\begin{theorem} \label{t:char-hke}
 Let $(X,d,m)$ be a metric measure space that satisfies \hyperlink{vd}{$\on{VD}$} and \hyperlink{qrvd}{$\on{QRVD}$}. Let $(\mathcal{E},\mathcal{F})$ be a pure jump Dirichlet form on $L^2(X,m)$. Then the following are equivalent:
 \begin{enumerate}[(a)]
 \item Jump kernel bound \hyperlink{jphi}{$\on{J(\phi)}$}, and capacity upper bound \hyperlink{cap}{$\on{Cap(\phi)_{\le}}$}.
 \item Stable-like heat kernel bound \hyperlink{shk}{$\on{HK}(\phi)$}.
 \end{enumerate}
\end{theorem}

The following existence of partition of unity follows from the same argument as the proof of Lemma \ref{l:partition}, where the desired bounded overlap property follows from \eqref{e:w-overlap}.
\begin{lem} \label{l:w-partition}
 Let $(X,d,m)$ be a metric measure space and let $(\mathcal{E},\mathcal{F})$ be a regular Dirichlet form that satisfies \hyperlink{cap}{$\on{Cap}(\phi)_\le$} and let $m$ be a doubling measure. There exists $\epsilon_0 \in (0,1/6),C_1,c_1 > 0$ such that 
 for any open set $U \subsetneq X$ be open and for any $\epsilon$-Whitney cover $\{B_i=B(x_i,r_i): i \in I\}$ of $U$ where $0<\epsilon < \epsilon_0$, there exists a partition on unity $\{\psi_{B_i}: i \in I\}$ of $V$ such that the following properties hold:
 \begin{enumerate}[(a)]
 \item (partition of unity) $\sum_{i \in I} \psi_{B_i} \equiv \one_U$. 
 \item (controlled energy) For each $i \in I$, we have $\psi_{B_i} \in \mathcal{F} \cap C(X)$ and
 \begin{equation}\label{e:w-pu}
 c_1 \one_{B(x_i,3r_i)} \le \psi_{B_i} \le \one_{B(x_i,6r_i)}, \quad \mathcal{E}(\psi_{B_i},\psi_{B_i}) \le C_1 \frac{V(x_i,r_i)}{\phi(r_i)}.
 \end{equation}
 \end{enumerate}
\end{lem}

\begin{prop} \label{p:css}
Let $(\mathcal{E},\mathcal{F})$ be a regular, pure jump Dirichlet form on $L^2(X,m)$ that satisfies \hyperlink{jphi}{$\operatorname{J(\phi)}$} and \hyperlink{cap}{$\operatorname{Cap(\phi)_{\le}}$}, where $\phi:[0,\infty) \to [0,\infty)$ is a scale function. Then there exists $C>0$ such that for any $r,\rho>0, f\in C(X) \cap \mathcal{F}$, the equilibrium potential $\psi$ for $\overline{B(x,r)} \subset B(x,2r)$ for the truncated Dirichlet form $(\mathcal{E}^{(\rho)}, \mathcal{F})$ satisfies
\begin{align} \label{e:css}
 \int_X f^2 \,d\Gamma^{(\rho)}(\psi,\psi) &= \int_{B(x,2r+\rho)} f^2 \,d\Gamma^{(\rho)}(\psi,\psi) \nonumber\\
 & \le C \int_{B(x,2r+2\rho)} \int_{B(x,2r+2\rho)} (f(y)-f(z))^2 J(y,z)\,m(dy)\,m(dz) \nonumber \\
 &\quad\quad\quad+ \frac{C}{\phi(r)} \int_{B(x,2r)} f^2\,dm 
\end{align}
\end{prop}
\begin{proof}
 If $y \notin B(x,2r+\rho)$, we have $\phi(y)-\phi(z) =0$ for $m$-a.e.~$z \in \ol{B}(y,\rho)$, then $$\Gamma^{(\rho)}(\psi,\psi)(B(x,2r+\rho)^c)=0.$$ This implies the first equality in \eqref{e:w-pu}.

It remains to consider the case $B(x,R+r) \neq X$. In this case $2r < R+r \le \diam(X,d)$ implies $r < \diam(X,d)/2$. 
 Let $A_1, A_2,C_1>1$ denote the constants such that \hyperlink{cap}{$\operatorname{Cap}(\phi)_{\le}$} holds. 
 Define 
 \begin{equation} \label{e:defL}
 \rho:= r/44.
 \end{equation}
 Let $N=\{z_i: i \in I\}$ denote a maximal $\rho$-separated subset of $X$. For each $i \in I$, let $B_i= \ol{B}(z_i, \rho), B_i^*=B(z_i, 2\rho), B_i^\#=B(z_i, 4\rho)$. 
 By Proposition \ref{p:css}, there exists $C_1>0$ such that for any $i \in I$ and for alls $f \in \mathcal{F} \cap C(X)$, the equilibrium potential $\psi_i$ for $B_i \subset B_i^*$ corresponding to the truncated Dirichlet form $(\mathcal{E}^{(\rho)}, \mathcal{F})$ satisfies
 \begin{equation}\label{e:si2}
 \int_{X} {f}^2 \, d\Gamma(\psi_i,\psi_i) 
 \le C_1 \int_{B_i^\# \times B_i^\#} (f(y)-f(z))^2\,J(dy,dz) + \frac{C_1}{\phi(\rho)} \int_{B_i^*} f^2\, dm.
 \end{equation}

Hence, for any function $f \in \mathcal{F} \cap C(X)$,
 \begin{align} \label{e:csj5}
 \MoveEqLeft{\int_{B(x,R+r)} f^2 \,d\Gamma(\psi,\psi)} \nonumber \\
 &\le \frac{C_2}{\phi(r)}\int_{B(x,R+r)} f^2 \,dm + \sum_{i \in \wh{I}} \int_X f^2 \,d\Gamma^{(\rho)}(\psi_i,\psi_i) \quad \mbox{(by \eqref{e:nlsi3})}\nonumber \\ 
 &\le \frac{C_2}{\phi(r)}\int_{B(x,R+r)} f^2 \,dm + \sum_{i \in \wh{I}} \left( C_1 \int_{B_i^\# \times B_i^\#} (f(y)-f(z))^2\,J(dy,dz) + \frac{C_1}{\phi(\rho)} \int_{B_i^*}f^2\, dm\right). 
 \end{align}
 By \eqref{e:overlap}, and \eqref{e:csj4}, we have 
 \begin{equation} \label{e:csj6}
 \sum_{i \in \wh{I}} \one_{B_i^*}(y) \lesssim \one_{B(x,R+r)}(y), 
 \end{equation}
 and
 \begin{equation} \label{e:csj7}
 \sum_{i \in \wh{I}} \one_{B_i^{\#}}(y)\one_{B_i^{\#}}(z) \lesssim \one_{V}(y) \one_{V}(z), \quad \mbox{where $V:= B(x,R+ (3r)/4) \setminus B(x,R+(r/4))$.}
 \end{equation}
 Combining \eqref{e:csj5}, \eqref{e:csj6}, \eqref{e:csj7}, and \eqref{e:scale}, for all $f \in \mathcal{F} \cap C(X)$, we have
 \[
 \int_{B(x,R+r)} f^2 \,d\Gamma(\psi,\psi) \lesssim \frac{1}{\phi(r)} \int_{B(x,R+r)} f^2\,dm + \int_{V} \int_V (f(y)-f(z))^2 J(y,z)\,m(dy)\,m(dz).
 \]
By regularity of the Dirichlet form, the above estimate also holds for all $f \in \mathcal{F}$ and hence \hyperlink{csj}{$\operatorname{CSJ}(\phi)$} holds. 
\end{proof}
\subsection{Characterization of stable-like heat kernel estimate}
Next, we complete the proof of Theorem~\ref{t:char-hke} using Theorem~\ref{t:main}. Indeed, if $\diam(X,d)=\infty$ and $(X,d,m)$ satisfies the stronger \hyperlink{rvd}{$\on{RVD}$} the equivalence is an immediate consequence of Theorem \ref{t:main}, \eqref{e:csj-cap} and \cite[Theorem~1.13]{CKW-hke}. In the general case, we need some additional ingredients from \cite{Mal, GHH-mv, GHH-lb, KM}.

Next, we show (a) implies (b). By Theorem \ref{t:main}, the Dirichlet form $(\mathcal{E},\mathcal{F})$ satisfies \hyperlink{csj}{$\operatorname{CSJ}(\phi)$} and \hyperlink{jphi}{$\operatorname{J}(\phi)$}. When $\diam(X,d)=\infty$, the stable-like heat kernel estimate \hyperlink{shk}{$\on{HK}(\phi)$} follows from obtaining the a similar heat kernel estimate for the auxiliary space in \cite[\textsection 3]{Mal} using \cite[eq.~(4.13), Proposition 4.1]{Mal} and \cite[Theorem~1.13]{CKW-hke}. The stable-like heat kernel estimate \hyperlink{shk}{$\on{HK}(\phi)$} for the auxiliary space then implies the desired heat kernel estimate for $(\mathcal{E},\mathcal{F})$ using \cite[eq.~(4.6) and (4.7), Proposition 4.1]{Mal}.

