\begin{proof}
Table~\ref{growth} shows that the torsion subgroup grows only when $D=-2$. Thus, for $D\neq -2$, we have $E_0(\Q(\sqrt{D}))_{\operatorname{tors}}=E_0(\Q)_{\operatorname{tors}}$. Therefore, if $D\neq -2$ and $\operatorname{rank}_{\Z}E_0^{D}(\Q)=0$, we deduce that $E_0(\Q(\sqrt{D}))$ is isomorphic to $E_0(\Q)$. Let us prove that the only case where $E_0(\Q(\sqrt{D}))\neq E_0(\Q)$ under these assumptions occurs when $D=2$. Assume that there exists $P\in E_0(\Q)$ and $R\in E_0(\Q(\sqrt{D}))\setminus E_0(\Q)$ such that $P=nR$ for some $n\in \Z$. Let $\sigma\in \operatorname{Gal}(\Q(\sqrt{D})/\Q)$ be the nontrivial automorphism. Then $P=n\,\sigma(R)$, and hence $n(R-\sigma(R))=\mathcal{O}$. This implies that $R-\sigma(R)\in E_0(\Q)[n]$. Since $E_0(\Q)_{\operatorname{tors}}=E_0[2]$, we conclude that $n=2$.

\section{Setting}
Let $D$ be a square-free integer and $K$ be a quadratic extension of $\mathbb{Q}(\sqrt{D})$. If $S\subseteq K$, we denote by $S^2$ to the set of squares in $S$. Let $a, b, c, d, e \in K$ be such that $\left(a^{2}, b^{2}, c^{2}, d^{2}, e^{2}\right)$ is an arithmetic progression. Then $[a: b: c: d: e]\in V(K) \subset \mathbb{P}^4(K)$, where $V$ is the genus 5 curve defined by the system of equations
$$
V\,\,:\,\, \{a^{2}+e^{2}=2 c^{2}\,,\,\, a^{2}+c^{2}=2 b^{2}\,,\,\,c^{2}+e^{2}=2 d^{2} \}.
$$
Equation $a^2+e^2=2c^2$ has the parametrization
\begin{equation}\label{eq2}
[a: c: e]=\left[t^{2}-2 t-1: t^{2}+1: t^{2}+2 t-1\right] 
\end{equation}
with $t \in K$. Applying \eqref{eq2} in the equations of $V$ gives, up to sign,
\begin{equation}\label{eq3}
\left\{
\begin{array}{l}
a = t^{2}-2 t-1, \\
b= \sqrt{t^{4}-2 t^{3}+2 t^{2}+2 t+1}, \\
c= t^{2}+1, \\
d= \sqrt{t^{4}+2 t^{3}+2 t^{2}-2 t+1}, \\
e= t^{2}+2 t-1.
\end{array}
\right.
\end{equation}
Replacing $t$ by $-t$ in \eqref{eq3} gives the arithmetic progression $(e^2,d^2,c^2,b^2,a^2)$, equivalent to $(a^2,b^2,c^2,d^2,e^2)$, and the constant arithmetic progressions correspond to the cases $t=0,\pm 1$.

\begin{prop}\label{prop}
Let $D$ be a square-free integer and $K$ be a quadratic extension of $\mathbb{Q}(\sqrt{D})$. Let $a, b, c, d, e \in K$ be such that $\left(a^{2}, b^{2}, c^{2}, d^{2}, e^{2}\right)$ is a non elementary arithmetic progression given by \eqref{eq3}. If $\operatorname{rank}_{\Z}E_1^{\pm D}(\Q)= 0\,,$ then
\begin{enumerate}
\item\label{prop1} $r \in \QD$,
\item\label{prop2} $s \in \QD$,
\item\label{prop3} $t\in\QD$,
\item\label{prop4} $t\in\Q$, if $D\ne \pm 2$ and $\operatorname{rank}_{\Z}E_0^{D}(\Q)=0$.
\end{enumerate}
\end{prop}

\section{Proof of Proposition \ref{prop}\,\eqref{prop4}}\label{tinQ}
Let {$D\ne \pm 2$} be a square-free integer satisfying $\operatorname{rank}_{\Z}E_1^{\pm D}(\Q)= 0$ and $\operatorname{rank}_{\Z}E_0^{D}(\Q)=0$. Let \( t \in K \setminus \{0, \pm 1, \pm i, \pm 1 \pm \sqrt{2}\} \) corresponding to a non-elementary arithmetic progression, as described in ~\eqref{eq3}. We prove that $t \in \Q$. Since $[K:\QD]=2$, there exists $\alpha \in K$ such that $\alpha^2 \in \QD$ and $K=\Q(\sqrt{D},\alpha)$. By \eqref{eq6}, there exist $\gamma_1,\delta_1,\gamma_2,\delta_2\in \QD$ such that 
\begin{equation}\label{Section6.E1}
\begin{cases}
 t^{4}-2 t^{3}+2 t^{2}+2 t+1&\!\!\!\!=\left(\delta_{1}+\gamma_{1}\alpha\right)^{2}, \\
 t^{4}+2 t^{3}+2 t^{2}-2 t+1&\!\!\!\!=\left(\delta_{2}+\gamma_{2} \alpha\right)^{2}.
\end{cases}
\end{equation}
Since $t \in \Q(\sqrt{D})$ and $\alpha \notin \QD$, we have $\gamma_{1} \delta_{1}=\gamma_{2} \delta_{2}=0$. There are four cases:

Let us prove Theorem \ref{main}:
\begin{itemize}
\item[(A)] Assume $\operatorname{rank}_{\Z}E_0^{D}(\Q)=0$. Since $D\ne \pm 2$. By Proposition \ref{prop} \eqref{prop4}, we have $t\in \Q$. In this case we have \( C_0(\mathbb{Q}(\sqrt{D})) = C_0(\mathbb{Q}) \). Hence, if the value of \( G(t) \) is a square over \( \mathbb{Q}(\sqrt{D}) \), it is already a square over \( \mathbb{Q} \). Consequently, four out of the five terms of the arithmetic progression are defined over \( \mathbb{Q} \), and therefore the full arithmetic progression of five terms is properly defined over a quadratic extension of \( \mathbb{Q} \).
\item[(B)] Assume $\operatorname{rank}_{\Z}E_0^{D}(\Q)\ne 0$ and that the class number of $\QD$ is $1$. By Proposition \ref{prop} \eqref{prop3}, we have $t\in \QD$. Since the ring of integers of $\QD$ is a unique factorization domain, there exist $\alpha,\delta\in \Q(\sqrt{D})$ such that $G(-t)=\alpha\,\delta^2$. We can conclude that \(\alpha\) is not a square in \(\mathbb{Q}(\sqrt{D})\), since otherwise there would exist a nontrivial arithmetic progression of five squares in \(\mathbb{Q}(\sqrt{D})\). However, this is impossible because \cite[Proposition~5.2]{GJX} states that a necessary condition is that \(\operatorname{rank} E_1^{\pm D}(\mathbb{Q}) \geq 2\). Then the arithmetic progression $(a^2,b^2,c^2,d^2,e^2)$ is properly defined over $K=\Q(\sqrt{D},\omega)$, where $\omega^2=\alpha$.
\end{itemize}
Now, the proof of Theorem \ref{maincor} assuming that $(a^2,b^2,c^2,d^2,e^2)$ is not an elementary arithmetic progression:
\begin{itemize}
\item $D\in\{-1,3\}$: The proof is analogous to the case $(A)$ since $\operatorname{rank}_{\Z}E_0^{D}(\Q)=0$ and {$D\ne \pm 2$}.
\item $D= \pm 2$: In this case $\operatorname{rank}_{\Z}E_0^{D}(\Q)=0$. By Proposition \ref{prop} \eqref{prop3} we have $t\in \Q(\sqrt{D})$. The proof is analogous to the case $(B)$ since the class number of $\Q(\sqrt{D})$ is $1$.
\end{itemize}

\section{Parametrization in the cases $\Q(\sqrt{-2})$ and $\Q(\sqrt{2})$}\label{sect_para}
Let \(D\) be a square-free integer such that \(\operatorname{rank}_{\mathbb{Z}} E_1^{\pm D}(\mathbb{Q}) = 0\). We have proved that any non-elementary arithmetic progression of five squares over a quadratic extension of \(\QD\) is equivalent to 
\[
\bigl((t^{2}-2t-1)^2,\, \beta^2,\, (t^{2}+1)^2,\, \alpha\delta^2,\, (t^{2}+2t-1)^2 \bigr),
\]
where \(t, \alpha, \beta, \delta \in \mathbb{Q}(\sqrt{D})\) satisfy \(\beta^2 = G(t)\) and \(\alpha\delta^2 = G(-t)\). In particular, for any non-elementary arithmetic progression of five squares, there exists a point \(R \in E_0(\mathbb{Q}(\sqrt{D}))\), and conversely. Note that this correspondence is not one-to-one. This construction recovers the one developed in \cite{GJX} for the special case $D=1$. That is, for any \(R \in E_0(\mathbb{Q})\) we obtain an arithmetic progression of five squares over a quadratic field, except when \(R \in E_0(\mathbb{Q})_{\operatorname{tors}}\), in which case the progression is trivial. Note that \(\operatorname{rank}_{\mathbb{Z}} E_1^{\pm 1}(\mathbb{Q}) = 0\). Let $T_1=(-3,0)$, $T_2=(1,0)$ and $P=(0,3)$, then 
$$
E_0(\Q)=\langle T_1 \rangle \oplus \langle T_2 \rangle \oplus \langle P \rangle.
$$
If $n\in\Z$, $n\ge 0$, the set of points $S_n=\{n_1T_1+n_2T_2+m P \,:\, n_1,n_2\in\{0,1\} \,,\,m\in\{n,-n-1\}\}$ corresponds to the same arithmetic progression of five squares, up to equivalence. For example, if $n=1$ the set $S_1$ corresponds to the arithmetic progression $(7^2, 13^2, 17^2, (\sqrt{409})^2, 23^2)$.
